interface SimulatedOrder {
  orderId: string;
  ownerId: string;
  symbol: string;
  side: "BUY" | "SELL";
  price: number;
  quantity: number;
  timestamp: string;
}

let simulatedBuyBook: SimulatedOrder[] = [
  { orderId: "ord-buy-001", ownerId: "MAURO Lomibao Dar III", symbol: "TWE/USDT", side: "BUY", price: 54.20, quantity: 1000, timestamp: new Date().toISOString() },
