  };
  return res.json({
    success: true,
    source: "DETERMINISTIC_SCHEMA_ENGINE",
    modelUsed: "gemini-3-flash-preview",
    functionCall: fallbackCall,
    functionCalls: [fallbackCall],
    reasoning: `Deterministic multi-tool intent parsed for Token World Exchange ATS (TWE).`,
  });
});

