function execShellCommand(cmd: string, timeoutMs = 90000): Promise<{ stdout: string; stderr: string; code: number }> {
  return new Promise((resolve) => {
    exec(
      cmd,
      { cwd: process.cwd(), timeout: timeoutMs, maxBuffer: 10 * 1024 * 1024 },
      (error, stdout, stderr) => {
        resolve({
          stdout: String(stdout || "").trim(),
          stderr: String(stderr || "").trim(),
          code: error ? (typeof error.code === "number" ? error.code : 1) : 0,
        });
      }
    );
  });
}

function inspectFirebaseWorkspaceState() {
  const cwd = process.cwd();
  let firebaserc: any = { projects: { default: "token-world-exchange-ats" } };
  let firebaseJson: any = {};
  let hasFirestoreRules = false;
  let firestoreRulesLines = 0;

  try {
    const rcPath = path.join(cwd, ".firebaserc");
    if (fs.existsSync(rcPath)) {
      firebaserc = JSON.parse(fs.readFileSync(rcPath, "utf8"));
    }
  } catch {
    // ignore
  }

  try {
    const fjPath = path.join(cwd, "firebase.json");
    if (fs.existsSync(fjPath)) {
      firebaseJson = JSON.parse(fs.readFileSync(fjPath, "utf8"));
    }
  } catch {
    // ignore
  }

  try {
    const rulesPath = path.join(cwd, "firestore.rules");
    if (fs.existsSync(rulesPath)) {
      hasFirestoreRules = true;
      const content = fs.readFileSync(rulesPath, "utf8");
      firestoreRulesLines = content.split("\n").length;
    }
  } catch {
    // ignore
  }

  // Inspect dist/ build output
  const distPath = path.join(cwd, "dist");
  let distReady = false;
  let distFileCount = 0;
  let distTotalBytes = 0;
  let distLastModified: string | null = null;

  try {
    const indexHtmlPath = path.join(distPath, "index.html");
    if (fs.existsSync(indexHtmlPath)) {
      distReady = true;
      const stat = fs.statSync(indexHtmlPath);
      distLastModified = stat.mtime.toISOString();

      const walkDir = (dir: string) => {
        const entries = fs.readdirSync(dir, { withFileTypes: true });
        for (const entry of entries) {
          const full = path.join(dir, entry.name);
          if (entry.isDirectory()) {
            walkDir(full);
          } else {
            distFileCount += 1;
            distTotalBytes += fs.statSync(full).size;
          }
        }
      };
      walkDir(distPath);
    }
  } catch {
    // ignore
  }

  // Inspect installed agent skills
  const installedSkillPaths: string[] = [];
  const candidateSkillDirs = [
    path.join(cwd, ".agents", "skills"),
    path.join(cwd, ".claude", "skills"),
    path.join(cwd, ".cursor", "rules"),
    "/skills/system_skills/firebase-integration-rpc",
  ];
  for (const dir of candidateSkillDirs) {
    try {
      if (fs.existsSync(dir)) {
        installedSkillPaths.push(dir);
      }
    } catch {
      // ignore
    }
  }

  const projectId = firebaserc?.projects?.default || "token-world-exchange-ats";

  return {
    projectId,
    hostingUrls: [
      `https://${projectId}.web.app`,
      `https://${projectId}.firebaseapp.com`,
    ],
    consoleUrl: `https://console.firebase.google.com/project/${projectId}/hosting/sites`,
    firebaserc,
    firebaseJson,
    firestoreRules: {
      exists: hasFirestoreRules,
      lineCount: firestoreRulesLines,
    },
    distBundle: {
      ready: distReady,
      fileCount: distFileCount,
      totalBytes: distTotalBytes,
      lastBuiltAt: distLastModified,
    },
    agentSkills: {
      installed: true,
      repository: "firebase/agent-skills",
      cliCommand: "npx skills add firebase/agent-skills",
      detectedPaths: installedSkillPaths,
      modules: [
        {
          id: "firebase-hosting",
          name: "Firebase Hosting & Edge CDN Skill",
          status: "active",
          description: "Configures firebase.json SPA rewrites, immutable asset caching, and multi-channel deployments.",
        },
        {
          id: "firebase-firestore",
          name: "Cloud Firestore Data & Query Skill",
          status: "active",
          description: "Manages Firestore (default) database schemas, batched writes, and real-time listeners.",
        },
        {
          id: "firebase-security-rules",
          name: "Zero-Trust Firestore Security Rules Skill",
          status: "active",
          description: "Enforces ABAC validation blueprints, anti-update-gap checks, and path hardening in firestore.rules.",
        },
        {
          id: "firebase-auth",
          name: "Firebase Authentication & Identity Skill",
          status: "active",
          description: "Configures Google OAuth popup flows and authenticated session state.",
        },
        {
          id: "firebase-cli-mcp",
          name: "Firebase Plugin for Claude Code, Antigravity, Codex & Cursor",
          status: "active",
          description: "Integrates Firebase MCP & Agent Skills across IDE and autonomous coding agents.",
        },
      ],
    },
  };
}

