import React, { useState, useMemo } from "react";
import { BarChart3, Filter, Table2 } from "lucide-react";
import {
  GeneratedArtEngineAsset,
  calculateStatisticalRarityScores,
} from "../utils/artEngine";

interface ArtEngineRarityDashboardProps {
  assets: GeneratedArtEngineAsset[];
  selectedEdition: number;
  onSelectEdition: (edition: number) => void;
}

type PercentileFilter = "ALL" | "TOP_1" | "TOP_10" | "TOP_25" | "COMMON";

export const ArtEngineRarityDashboard: React.FC<ArtEngineRarityDashboardProps> = ({
  assets,
  selectedEdition,
  onSelectEdition,
}) => {
  const [percentileFilter, setPercentileFilter] = useState<PercentileFilter>("ALL");

  const { enrichedAssets, traitFrequencyTable } = useMemo(
    () => calculateStatisticalRarityScores(assets),
    [assets]
  );

  const filteredAssets = useMemo(() => {
    const total = Math.max(enrichedAssets.length, 1);
    return enrichedAssets.filter((item) => {
      const pct = (item.rarityRank / total) * 100;
      if (percentileFilter === "TOP_1") return item.rarityRank === 1 || pct <= 12.5;
      if (percentileFilter === "TOP_10") return item.rarityRank <= Math.max(1, Math.ceil(total * 0.2));
      if (percentileFilter === "TOP_25") return item.rarityRank <= Math.max(2, Math.ceil(total * 0.35));
      if (percentileFilter === "COMMON") return item.rarityRank > Math.floor(total * 0.4);
      return true;
    });
  }, [enrichedAssets, percentileFilter]);

  return (
    <div className="rounded-xl border border-slate-800 bg-slate-950 p-4 space-y-5">
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-800 pb-3">
        <div className="flex items-center gap-2 text-xs font-mono font-bold text-white">
          <BarChart3 className="w-4 h-4 text-emerald-400" />
          ArtEngineRarityDashboard — Statistical Frequency & Percentile Filter
        </div>
        <span className="text-[11px] font-mono text-sky-300">
          Showing {filteredAssets.length} of {enrichedAssets.length} NFTs
        </span>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
        {/* Rarity Percentile Filtering Sidebar */}
        <div className="lg:col-span-4 rounded-xl border border-slate-800 bg-slate-900/70 p-3.5 space-y-2.5">
          <div className="text-xs font-mono font-bold text-indigo-300 flex items-center gap-1.5">
            <Filter className="w-3.5 h-3.5" />
            Rarity Percentile Filter Sidebar
          </div>
          {[
            { id: "ALL", label: "All Collection Editions (100%)" },
            { id: "TOP_1", label: "Top 1% / Sovereign Mythic (#1 Rank)" },
            { id: "TOP_10", label: "Top 10% / Institutional Apex" },
            { id: "TOP_25", label: "Top 25% / Prime Genesis" },
            { id: "COMMON", label: "Common / Verified Standard Tier" },
          ].map((opt) => (
            <button
              key={opt.id}
              type="button"
              onClick={() => setPercentileFilter(opt.id as PercentileFilter)}
              className={`w-full text-left px-3 py-2 rounded-lg text-xs font-mono transition cursor-pointer border ${
                percentileFilter === opt.id
                  ? "bg-emerald-500/20 border-emerald-400 text-emerald-300 font-bold"
                  : "bg-slate-950/70 border-slate-800 text-slate-300 hover:border-slate-700"
              }`}
            >
              {opt.label}
            </button>
          ))}

          {/* Filtered Editions Quick List */}
          <div className="pt-2 border-t border-slate-800 space-y-1.5 max-h-44 overflow-y-auto">
            {filteredAssets.map((item) => (
              <div
                key={item.edition}
                onClick={() => onSelectEdition(item.edition)}
                className={`flex items-center justify-between px-2.5 py-1.5 rounded text-[11px] font-mono cursor-pointer ${
                  item.edition === selectedEdition
                    ? "bg-indigo-500/25 border border-indigo-400 text-white"
                    : "bg-slate-950/60 text-slate-300 hover:bg-slate-800"
                }`}
              >
                <span>
                  #{item.edition} (Rank #{item.rarityRank})
                </span>
                <span className="text-amber-300">
                  {item.rarityScore} pts • {item.rarityMultiplier}x
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Trait Frequency Bar Chart & Raw Data Table */}
        <div className="lg:col-span-8 space-y-4">
          {/* Visual Bar Chart */}
          <div className="rounded-xl border border-slate-800 bg-slate-900/60 p-3.5 space-y-2">
            <div className="text-xs font-mono font-bold text-white">
              Visual Trait Rarity Distribution Chart
            </div>
            <div className="space-y-2">
              {traitFrequencyTable.slice(0, 8).map((row) => (
                <div key={`${row.layerName}-${row.traitName}`} className="space-y-1">
                  <div className="flex items-center justify-between text-[11px] font-mono">
                    <span className="text-slate-300">
                      {row.layerName} → <strong className="text-white">{row.traitName}</strong>
                    </span>
                    <span className="text-emerald-400">
                      {row.absoluteCount} items ({row.frequencyPct}%)
                    </span>
                  </div>
                  <div className="h-2 w-full rounded-full bg-slate-800 overflow-hidden">
                    <div
                      className="h-full bg-gradient-to-r from-indigo-500 to-emerald-400"
                      style={{ width: `${Math.min(100, row.frequencyPct)}%` }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Raw Data Frequency Table */}
          <div className="rounded-xl border border-slate-800 bg-slate-900/60 overflow-hidden">
            <div className="px-3.5 py-2 border-b border-slate-800 flex items-center justify-between">
              <span className="text-xs font-mono font-bold text-white flex items-center gap-1.5">
                <Table2 className="w-3.5 h-3.5 text-sky-400" />
                Raw Trait Absolute Count & Percentage Frequency Table
              </span>
              <span className="text-[10px] font-mono text-slate-400">
                {traitFrequencyTable.length} Active Traits
              </span>
            </div>
            <div className="overflow-x-auto max-h-56">
              <table className="w-full text-left text-[11px] font-mono">
                <thead className="bg-slate-950 text-slate-400">
                  <tr>
                    <th className="py-2 px-3">Layer Category</th>
                    <th className="py-2 px-3">Trait Asset</th>
                    <th className="py-2 px-3">Count</th>
                    <th className="py-2 px-3">Frequency %</th>
                    <th className="py-2 px-3">Score Impact</th>
                    <th className="py-2 px-3">Multiplier</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800/70">
                  {traitFrequencyTable.map((row) => (
                    <tr
                      key={`tbl-${row.layerName}-${row.traitName}`}
                      className="hover:bg-slate-800/50"
                    >
                      <td className="py-1.5 px-3 text-indigo-300">{row.layerName}</td>
                      <td className="py-1.5 px-3 font-bold text-white">{row.traitName}</td>
                      <td className="py-1.5 px-3 text-emerald-400">{row.absoluteCount}</td>
                      <td className="py-1.5 px-3 text-sky-300">{row.frequencyPct}%</td>
                      <td className="py-1.5 px-3 text-amber-300">
                        +{row.rarityScoreContribution}
                      </td>
                      <td className="py-1.5 px-3 text-purple-300">
                        {row.rarityMultiplierContribution}x
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

