import React, { useState, useEffect } from "react";
import {
  Sparkles,
  Play,
  Layers,
  Terminal,
  FolderTree,
  BookOpen,
  CheckCircle2,
  ShieldCheck,
  Code2,
  Cpu,
  Copy,
  Check,
  KeyRound,
  RefreshCw,
  Download,
  Hash,
  Link2,
  AlertTriangle,
} from "lucide-react";
import { TokenRecord } from "../types/token";
import {
  DEFAULT_TWE_ENV_KEYS,
  TweEnvironmentKeyBundle,
  TweMissingCriticalKeyTelemetryEvent,
  generateCryptographicTweKeyBundle,
  formatEnvFileBlock,
  subscribeToTweEnvTelemetry,
  simulateMissingCriticalKey,
} from "../config/tweEnvironmentKeys";

export const MAX_UINT256_DECIMAL_STR =
  "115792089237316195423570985008687907853269984665640564039457584007913129639935";

interface ArtEngineTriggerProps {
  activeToken?: TokenRecord;
  allTokens?: TokenRecord[];
  onSelectToken?: (token: TokenRecord) => void;
  tweEnvConfig?: TweEnvironmentKeyBundle;
  onUpdateTweEnvConfig?: (next: TweEnvironmentKeyBundle) => void;
}

interface GeneratedSampleItem {
  id: number;
  uint256TokenId?: string;
  uint256Hex?: string;
  tokenSymbol: string;
  dna: string;
  rarityScore?: number;
  rarityMultiplier?: number;
  tokenURI?: string;
  previewDataUri: string;
  metadata: {
    name: string;
    description: string;
    image: string;
    external_url: string;
    dna: string;
    edition: number | string;
    uint256TokenId?: string;
    uint256Hex?: string;
    tokenSymbol: string;
    attributes: Array<{
      trait_type: string;
      value: string | number;
      weight?: number;
      source_file?: string;
    }>;
  };
}

interface TokenEngineResult {
  success: boolean;
  tokenSymbol: string;
  collectionName: string;
  baseUri: string;
  outputPath: string;
  layersPath: string;
  count: number;
  uint256Capacity?: string;
  startTokenIdUint256?: string;
  totalGenerated: number;
  performance?: {
    pluginsLoaded: string[];
    itemsGenerated: number;
    elapsedMs: number;
    throughputPerSec: number;
    cacheEnabled: boolean;
  };
  sampleItems?: GeneratedSampleItem[];
}

const DEFAULT_TWE_ATS_TOKENS: Array<{ symbol: string; name: string }> = [
  { symbol: "TWE", name: "Token World Exchange ATS" },
  { symbol: "TW-EQ", name: "Token World Genesis Equity" },
  { symbol: "TREE3", name: "Tree 3 Institutional Token" },
  { symbol: "TW-TBILL", name: "TWE US Treasury Bill Vault" },
  { symbol: "TW-REIT", name: "TWE Commercial Real Estate REIT" },
  { symbol: "TW-GOLD", name: "TWE Sovereign Gold Bullion" },
  { symbol: "TW-CARBON", name: "TWE Verified Carbon Credit" },
  { symbol: "TW-DEMO", name: "TWE Compliance Sandbox Token" },
];

const LAYER_DIRECTORY_TREE = [
  {
    folder: "1-Background/",
    files: [
      { name: "Blue#60.png", trait: "Blue", weight: 60, color: "bg-sky-500" },
      { name: "Dark_Obsidian#40.png", trait: "Dark_Obsidian", weight: 40, color: "bg-slate-800" },
    ],
  },
  {
    folder: "2-Base_Structure/",
    files: [
      { name: "Platinum_Mesh#50.png", trait: "Platinum_Mesh", weight: 50, color: "bg-slate-300" },
      { name: "Gold_Alloy#50.png", trait: "Gold_Alloy", weight: 50, color: "bg-amber-400" },
    ],
  },
  {
    folder: "3-Accents/",
    files: [
      { name: "Hologram_Lines#70.png", trait: "Hologram_Lines", weight: 70, color: "bg-emerald-400" },
      { name: "Quantum_Seal#30.png", trait: "Quantum_Seal", weight: 30, color: "bg-purple-500" },
    ],
  },
  {
    folder: "4-Compliance_Watermark/",
    files: [
      {
        name: "SEC_TWE_Compliant#100.png",
        trait: "SEC_TWE_Compliant",
        weight: 100,
        color: "bg-cyan-400",
      },
    ],
  },
];

export default function ArtEngineTrigger({
  activeToken,
  allTokens = [],
  onSelectToken,
  tweEnvConfig,
  onUpdateTweEnvConfig,
}: ArtEngineTriggerProps) {
  const [envKeyBundle, setEnvKeyBundle] = useState<TweEnvironmentKeyBundle>(
    tweEnvConfig || DEFAULT_TWE_ENV_KEYS
  );
  const [isRotatingKeys, setIsRotatingKeys] = useState(false);

  useEffect(() => {
    if (tweEnvConfig) {
      setEnvKeyBundle(tweEnvConfig);
    }
  }, [tweEnvConfig]);

  const updateSharedEnvKeyBundle = (
    updater:
      | TweEnvironmentKeyBundle
      | ((prev: TweEnvironmentKeyBundle) => TweEnvironmentKeyBundle)
  ) => {
    setEnvKeyBundle((prev) => {
      const next = typeof updater === "function" ? updater(prev) : updater;
      if (onUpdateTweEnvConfig) {
        onUpdateTweEnvConfig(next);
      }
      return next;
    });
  };

  const [editionSize, setEditionSize] = useState<number>(100);
  const [startTokenIdUint256, setStartTokenIdUint256] = useState<string>("1");
  const [collectionName, setCollectionName] = useState<string>(
    activeToken ? `TWE ${activeToken.symbol} Qualified Asset` : "TWE Qualified Asset"
  );
  const [baseUri, setBaseUri] = useState<string>(
    "ipfs://bafybeigdyrzt5sfp7udm7hu76uh7y26nf3efuylqabf3oclgtqy55fbzdi/"
  );

  const [apiKeyInput, setApiKeyInput] = useState<string>(
    (tweEnvConfig || DEFAULT_TWE_ENV_KEYS).VITE_TWE_DEV_KEY
  );
  const [loading, setLoading] = useState<boolean>(false);
  const [statusMessage, setStatusMessage] = useState<{
    type: "idle" | "success" | "error";
    message: string;
  }>({ type: "idle", message: "" });

  const [engineResult, setEngineResult] = useState<
    | (TokenEngineResult & {
        batchMode?: string;
        tokensProcessed?: number;
        totalAssetsAcrossTokens?: number;
        tokenResults?: TokenEngineResult[];
      })
    | undefined
  >(undefined);

  const [selectedBatchTokenSymbol, setSelectedBatchTokenSymbol] = useState<string>(
    activeToken?.symbol || "TWE"
  );
  const [selectedSampleItem, setSelectedSampleItem] = useState<
    GeneratedSampleItem | undefined
  >(undefined);

  // uint256 On-Demand Synthesizer & Step 4 Exchange Connection State
  const [uint256QueryInput, setUint256QueryInput] = useState<string>(
    MAX_UINT256_DECIMAL_STR
  );
  const [isSynthesizingUint256, setIsSynthesizingUint256] = useState<boolean>(false);
  const [contractAddressInput, setContractAddressInput] = useState<string>(
    activeToken?.contractAddress || "0x742d35Cc6634C0532925a3b844Bc454e4438f44e"
  );
  const [exchangeAddressInput, setExchangeAddressInput] = useState<string>(
    "0x9f8e7d6c5b4a3f2e1d0c9b8a7f6e5d4c3b2a1f0e"
  );
  const [exchangeConnectionResult, setExchangeConnectionResult] = useState<{
    connected: boolean;
    txHash: string;
    crawledEndpoint: string;
    timestamp: string;
  }>({
    connected: false,
    txHash: "",
    crawledEndpoint: "",
    timestamp: "",
  });

  const [activeDocTab, setActiveDocTab] = useState<
    | "console"
    | "uint256_explorer"
    | "step4_exchange"
    | "env_keys"
    | "layers_tree"
    | "architecture_code"
    | "history_docs"
  >("console");
  const [copiedId, setCopiedId] = useState<string>("");

  useEffect(() => {
    if (activeToken?.symbol) {
      setSelectedBatchTokenSymbol(activeToken.symbol);
      setCollectionName(`TWE ${activeToken.symbol} Qualified Asset`);
      if (activeToken.contractAddress) {
        setContractAddressInput(activeToken.contractAddress);
      }
    }
  }, [activeToken?.symbol, activeToken?.contractAddress]);

  const [missingKeyEvents, setMissingKeyEvents] = useState<
    TweMissingCriticalKeyTelemetryEvent[]
  >(DEFAULT_TWE_ENV_KEYS.telemetryEvents || []);

  useEffect(() => {
    return subscribeToTweEnvTelemetry((events) => {
      setMissingKeyEvents(events);
    });
  }, []);

  useEffect(() => {
    fetch("/api/twe/env-keys")
      .then((r) => (r.ok ? r.json() : undefined))
      .then((data) => {
        if (data?.keys) {
          updateSharedEnvKeyBundle((prev) => ({
            ...prev,
            VITE_TWE_DEV_KEY: data.keys.VITE_TWE_DEV_KEY,
            NEXT_PUBLIC_TWE_DEV_KEY: data.keys.NEXT_PUBLIC_TWE_DEV_KEY,
            TWE_ADMIN_SECRET: data.keys.TWE_ADMIN_SECRET,
            VITE_FIREBASE_MEASUREMENT_ID: data.keys.VITE_FIREBASE_MEASUREMENT_ID,
            generatedAt: data.keys.updatedAt || new Date().toISOString(),
            keyId: data.keys.keyId || "TWE-KEYSET-2026-GENESIS",
          }));
          setApiKeyInput(data.keys.VITE_TWE_DEV_KEY);
        }
      })
      .catch(() => {
        // fallback to default keys
      });
  }, []);

  const handleRotateAndSyncKeys = async () => {
    setIsRotatingKeys(true);
    const nextBundle = generateCryptographicTweKeyBundle(
      envKeyBundle.VITE_FIREBASE_MEASUREMENT_ID
    );
    try {
      const res = await fetch("/api/twe/env-keys/rotate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nextBundle),
      });
      if (res.ok) {
        const data = await res.json();
        if (data?.keys) {
          const synced: TweEnvironmentKeyBundle = {
            ...nextBundle,
            VITE_TWE_DEV_KEY: data.keys.VITE_TWE_DEV_KEY,
            NEXT_PUBLIC_TWE_DEV_KEY: data.keys.NEXT_PUBLIC_TWE_DEV_KEY,
            TWE_ADMIN_SECRET: data.keys.TWE_ADMIN_SECRET,
            VITE_FIREBASE_MEASUREMENT_ID: data.keys.VITE_FIREBASE_MEASUREMENT_ID,
            generatedAt: data.keys.updatedAt || nextBundle.generatedAt,
            keyId: data.keys.keyId || nextBundle.keyId,
          };
          updateSharedEnvKeyBundle(synced);
          setApiKeyInput(synced.VITE_TWE_DEV_KEY);
          setIsRotatingKeys(false);
          return;
        }
      }
    } catch {
      // fallback to local bundle
    }
    updateSharedEnvKeyBundle(nextBundle);
    setApiKeyInput(nextBundle.VITE_TWE_DEV_KEY);
    setIsRotatingKeys(false);
  };

  const handleDownloadEnvFile = () => {
    const content = formatEnvFileBlock(envKeyBundle);
    const blob = new Blob([content + "\n"], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "twe-art-engine-env-keys.env";
    a.click();
    URL.revokeObjectURL(url);
  };

  const tokenListForBatch = React.useMemo(() => {
    const mergedMap = new Map<string, { symbol: string; name: string }>();
    DEFAULT_TWE_ATS_TOKENS.forEach((t) => mergedMap.set(t.symbol, t));
    allTokens.forEach((t) => {
      if (t.symbol) {
        mergedMap.set(t.symbol.toUpperCase(), {
          symbol: t.symbol.toUpperCase(),
          name: t.name || t.symbol,
        });
      }
    });
    return Array.from(mergedMap.values());
  }, [allTokens]);

  const executePipeline = async (executeAllTokens: boolean) => {
    setLoading(true);
    setStatusMessage({ type: "idle", message: "" });

    try {
      const response = await fetch("/api/generate", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-twe-api-key": apiKeyInput || envKeyBundle.NEXT_PUBLIC_TWE_DEV_KEY || "",
        },
        body: JSON.stringify({
          editionSize,
          startTokenIdUint256,
          collectionName,
          baseUri,
          tokenSymbol: activeToken?.symbol || selectedBatchTokenSymbol || "TWE",
          executeAllTokens,
          tokens: tokenListForBatch,
        }),
      });

      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "Execution error");

      setEngineResult(data.data);
      setStatusMessage({
        type: "success",
        message: executeAllTokens
          ? `Generated ${data.data?.totalAssetsAcrossTokens || editionSize} items across all ${
              data.data?.tokensProcessed || tokenListForBatch.length
            } tokens (uint256 keyspace active).`
          : `Generated ${editionSize} items successfully (starting at uint256 #${startTokenIdUint256}).`,
      });
      const firstTokenRes = data.data?.tokenResults?.[0] || data.data;
      if (firstTokenRes?.sampleItems?.[0]) {
        setSelectedSampleItem(firstTokenRes.sampleItems[0]);
      }
    } catch (err: any) {
      setStatusMessage({ type: "error", message: err.message || "Generation failed" });
    } finally {
      setLoading(false);
    }
  };

  const handleGenerate = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    await executePipeline(false);
  };

  const handleExecuteAllTweTokens = async () => {
    await executePipeline(true);
  };

  const handleSynthesizeArbitraryUint256 = async (customId?: string) => {
    const targetId = customId ?? uint256QueryInput;
    setIsSynthesizingUint256(true);
    try {
      const params = new URLSearchParams({
        baseUri,
        collectionName,
      });
      const res = await fetch(
        `/api/tokenURI/${encodeURIComponent(selectedBatchTokenSymbol)}/${encodeURIComponent(
          targetId
        )}?${params.toString()}`
      );
      const data = await res.json();
      if (res.ok && data?.asset) {
        setSelectedSampleItem(data.asset);
        setStatusMessage({
          type: "success",
          message: `Synthesized uint256 tokenURI(${targetId.slice(0, 18)}${
            targetId.length > 18 ? "..." : ""
          }) for ${selectedBatchTokenSymbol}.`,
        });
      }
    } catch (err: any) {
      setStatusMessage({
        type: "error",
        message: err?.message || "Failed to synthesize uint256 token",
