{`import { ArtEngine, inputs, generators, renderers, exporters } from "@hashlips-lab/art-engine";
import path from "path";

export async function runArtEngine({
  itemCount = 100,
  layersDir = "./layers",
  outputDir = "./dist/twe_assets",
