{`const handleGenerate = async () => {
  setLoading(true);
  setStatus(null);

  try {
    const response = await fetch('/api/generate', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-twe-api-key': process.env.NEXT_PUBLIC_TWE_DEV_KEY || ''
      },
      body: JSON.stringify({
        editionSize,
        collectionName,
        baseUri: 'ipfs://bafybeic7...'
      })
    });

    const data = await response.json();
    if (!response.ok) throw new Error(data.error);

    setStatus({
      type: 'success',
      message: \`Generated \${editionSize} items successfully.\`
    });
  } catch (err) {
    setStatus({ type: 'error', message: err.message });
  } finally {
    setLoading(false);
  }
};`}
