  isBuy: boolean;
  isSell: boolean;
  isExtreme: boolean; // >80 or <20
  pulseClass: string; // "animate-rsi-buy-intense" | "animate-rsi-buy-subtle" | "animate-rsi-sell-intense" | "animate-rsi-sell-subtle" | ""
  badgeBorderClass: string;
