  // Retry Failed Items
  const handleRetryFailed = () => {
    setQueueItems((prev) =>
      prev.map((q) => (q.status === "failed" ? { ...q, status: "pending", error: undefined } : q))
    );
    addLog("Reset failed queue items to pending status.");
