                <span>Next: Activate Services ({selectedChainIds.size} Chains Selected)</span>
                <ArrowRight className="w-3.5 h-3.5" />
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ===================================================================== */}
      {/* STEP 3: ACTIVATE SERVICES (ALL 15 SERVICES REQUESTED)                 */}
      {/* ===================================================================== */}
      {currentStep === 3 && (
        <div className="space-y-6 animate-fade-in">
