              {generatedTokensCount > 0 && (
                <span className="text-xs font-bold text-emerald-400 bg-emerald-500/10 px-2.5 py-1 rounded border border-emerald-500/30">
                  +{generatedTokensCount.toLocaleString()} Tokens Minted
