import React, { useState, useEffect, useMemo } from "react";
import QRCode from "qrcode";
import {
  QrCode,
  Copy,
  Check,
  Download,
  Share2,
  Smartphone,
  ExternalLink,
  Sparkles,
  ShieldCheck,
} from "lucide-react";

export type QrPayloadMode =
  | "raw_address"
  | "eip681_wallet"
  | "explorer_url"
  | "json_manifest";

export type QrThemePreset = "crisp_white" | "cyber_cyan" | "sovereign_gold";

export type QrAddressTarget = "contract" | "deployer" | "treasury";

export interface ContractAddressQrGeneratorProps {
  contractAddress: string;
  tokenName: string;
  tokenSymbol: string;
  chain: string;
  tokenStandard?: string;
  decimals?: number;
  deployerAddress?: string;
  treasuryAddress?: string;
  explorerUrl?: string;
  compactByDefault?: boolean;
}

const CHAIN_ID_LOOKUP: Record<string, number> = {
  ethereum: 1,
  base: 8453,
  polygon: 137,
  arbitrum: 42161,
  optimism: 10,
  avalanche: 43114,
  bsc: 56,
};

const THEME_PALETTES: Record<
  QrThemePreset,
  { label: string; dark: string; light: string; badge: string }
> = {
  crisp_white: {
    label: "Crisp White (Universal Scan)",
    dark: "#0A0A0C",
    light: "#FFFFFF",
    badge: "bg-white text-black border-zinc-300",
  },
  cyber_cyan: {
    label: "Cyber Cyan",
    dark: "#00F0FF",
    light: "#0A0A0C",
    badge: "bg-cyan-500/15 text-cyan-300 border-cyan-500/40",
  },
  sovereign_gold: {
    label: "Sovereign Gold",
    dark: "#F0D89B",
    light: "#0B0D10",
    badge: "bg-amber-500/15 text-amber-200 border-amber-500/40",
  },
};

export const ContractAddressQrGenerator: React.FC<
  ContractAddressQrGeneratorProps
> = ({
  contractAddress,
  tokenName,
  tokenSymbol,
  chain,
  tokenStandard = "ERC-20",
  decimals = 18,
  deployerAddress,
  treasuryAddress,
  explorerUrl,
  compactByDefault = false,
}) => {
  const [isExpanded, setIsExpanded] = useState<boolean>(!compactByDefault);
  const [payloadMode, setPayloadMode] = useState<QrPayloadMode>("raw_address");
  const [themePreset, setThemePreset] = useState<QrThemePreset>("crisp_white");
  const [addressTarget, setAddressTarget] =
    useState<QrAddressTarget>("contract");
  const [qrDataUrl, setQrDataUrl] = useState<string>("");
  const [copiedState, setCopiedState] = useState<string | null>(null);

  const activeAddress = useMemo(() => {
    if (addressTarget === "deployer" && deployerAddress) {
      return deployerAddress;
    }
    if (addressTarget === "treasury" && treasuryAddress) {
      return treasuryAddress;
    }
    return contractAddress;
  }, [addressTarget, contractAddress, deployerAddress, treasuryAddress]);

  const resolvedExplorerUrl = useMemo(() => {
    if (explorerUrl && addressTarget === "contract") return explorerUrl;
    const normalized = chain.toLowerCase();
    if (normalized === "base") {
      return `https://basescan.org/address/${activeAddress}`;
    }
    if (normalized === "polygon") {
      return `https://polygonscan.com/address/${activeAddress}`;
    }
    if (normalized === "solana") {
      return `https://solscan.io/account/${activeAddress}`;
    }
    return `https://etherscan.io/address/${activeAddress}`;
  }, [explorerUrl, addressTarget, chain, activeAddress]);

  const encodedPayload = useMemo(() => {
    const normalizedChain = chain.toLowerCase();
    const chainId = CHAIN_ID_LOOKUP[normalizedChain];

    switch (payloadMode) {
      case "raw_address":
        return activeAddress;
      case "eip681_wallet":
        if (normalizedChain === "solana") {
          return `solana:${activeAddress}?label=${encodeURIComponent(
            `${tokenName} (${tokenSymbol})`
          )}`;
        }
        if (normalizedChain === "bitcoin") {
          return `bitcoin:${activeAddress}?label=${encodeURIComponent(
            `${tokenName} (${tokenSymbol})`
          )}`;
        }
        return `ethereum:${activeAddress}${chainId ? `@${chainId}` : ""}`;
      case "explorer_url":
        return resolvedExplorerUrl;
      case "json_manifest":
        return JSON.stringify({
          name: tokenName,
          symbol: tokenSymbol,
          chain,
          standard: tokenStandard,
          decimals,
          addressType: addressTarget,
          address: activeAddress,
        });
    }
  }, [
    payloadMode,
    activeAddress,
    chain,
    tokenName,
    tokenSymbol,
    tokenStandard,
    decimals,
    addressTarget,
    resolvedExplorerUrl,
  ]);

  useEffect(() => {
    let isMounted = true;
    const palette = THEME_PALETTES[themePreset];

    QRCode.toDataURL(encodedPayload, {
      errorCorrectionLevel: "H",
      margin: 2,
      width: 320,
      color: {
        dark: palette.dark,
        light: palette.light,
      },
    })
      .then((url) => {
        if (isMounted) setQrDataUrl(url);
      })
      .catch((err) => {
        console.error("Failed to generate contract QR code:", err);
      });

    return () => {
      isMounted = false;
    };
  }, [encodedPayload, themePreset]);

  const handleCopy = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    setCopiedState(label);
    setTimeout(() => setCopiedState(null), 2000);
  };

  const handleDownloadQrPng = () => {
    if (!qrDataUrl) return;
    const link = document.createElement("a");
    link.href = qrDataUrl;
    const safeSym = tokenSymbol.replace(/[^a-zA-Z0-9_-]/g, "") || "TOKEN";
    link.download = `${safeSym}_${chain}_${addressTarget}_QR.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleShareAddress = async () => {
    const shareText = `${tokenName} (${tokenSymbol}) [${chain.toUpperCase()} • ${tokenStandard}]\nContract Address: ${activeAddress}\nExplorer: ${resolvedExplorerUrl}`;
    if (typeof navigator !== "undefined" && typeof navigator.share === "function") {
      try {
        await navigator.share({
          title: `${tokenName} (${tokenSymbol}) Contract Address`,
          text: shareText,
          url: resolvedExplorerUrl,
        });
        return;
      } catch {
        // Fallback to clipboard copy if share sheet dismissed or blocked in iframe
      }
    }
    handleCopy(shareText, "share_card");
  };

  return (
    <div
      id="token-contract-qr-generator"
      className="bg-[#0A0A0C] rounded-lg border border-cyan-500/30 overflow-hidden transition-all"
    >
      {/* Header Bar */}
      <div className="p-3.5 bg-[#12131A] border-b border-[#1F1F23] flex flex-wrap items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <div className="p-1.5 rounded-lg bg-cyan-500/10 border border-cyan-500/30 text-cyan-400">
            <QrCode className="w-4 h-4" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="font-semibold text-white uppercase tracking-wider text-[11px]">
                Contract Address QR Code &amp; Mobile Scanner
              </span>
              <span className="px-2 py-0.5 rounded text-[9px] font-mono bg-emerald-500/10 text-emerald-400 border border-emerald-500/30 flex items-center gap-1">
                <ShieldCheck className="w-2.5 h-2.5" />
                ECC Level H (30%)
              </span>
            </div>
            <p className="text-[10px] text-[#8E9299] font-mono mt-0.5">
              Instant mobile wallet scan, EIP-681 deep-linking, or high-resolution PNG export
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => handleCopy(activeAddress, "raw_addr")}
            className="flex items-center gap-1 px-2.5 py-1 rounded bg-[#16161A] hover:bg-[#1F1F23] border border-[#2A2A32] text-[#E0E0E0] text-[10px] font-mono cursor-pointer transition-colors"
            title="Copy Active Address"
          >
            {copiedState === "raw_addr" ? (
              <>
                <Check className="w-3 h-3 text-emerald-400" />
                <span className="text-emerald-400">Copied Address</span>
              </>
            ) : (
              <>
                <Copy className="w-3 h-3 text-cyan-400" />
                <span>Copy Address</span>
              </>
            )}
          </button>

          <button
            type="button"
            onClick={handleDownloadQrPng}
            className="flex items-center gap-1 px-2.5 py-1 rounded bg-cyan-500/15 hover:bg-cyan-500/25 border border-cyan-500/40 text-cyan-300 text-[10px] font-mono cursor-pointer transition-colors"
            title="Download High-Res QR Code PNG"
          >
            <Download className="w-3 h-3" />
            <span>Download PNG</span>
          </button>

          <button
            type="button"
            onClick={() => setIsExpanded((prev) => !prev)}
            className="px-2.5 py-1 rounded bg-[#16161A] hover:bg-[#1F1F23] border border-[#2A2A32] text-[#8E9299] hover:text-white text-[10px] font-mono cursor-pointer"
          >
            {isExpanded ? "Minimize" : "Expand QR Studio"}
          </button>
        </div>
      </div>

      {isExpanded && (
        <div className="p-4 grid grid-cols-1 md:grid-cols-12 gap-4 items-center">
          {/* Left: Scannable QR Viewport */}
          <div className="md:col-span-5 flex flex-col items-center justify-center bg-[#121318] border border-[#1F1F23] rounded-xl p-4">
            <div className="relative p-2.5 rounded-xl border border-white/10 shadow-xl bg-[#0A0A0C]">
              {qrDataUrl ? (
                <img
                  src={qrDataUrl}
                  alt={`QR Code for ${tokenName} (${tokenSymbol}) ${activeAddress}`}
                  className="w-44 h-44 sm:w-48 sm:h-48 rounded-lg object-contain select-none"
                />
              ) : (
                <div className="w-44 h-44 sm:w-48 sm:h-48 flex items-center justify-center text-[#8E9299] font-mono text-[11px]">
                  Synthesizing QR Matrix…
                </div>
              )}
              <div className="mt-2 flex items-center justify-between text-[10px] font-mono text-[#8E9299] px-1">
                <span className="text-white font-semibold truncate max-w-[110px]">
                  {tokenSymbol} • {chain.toUpperCase()}
                </span>
                <span className="text-cyan-400">
                  {activeAddress.slice(0, 6)}…{activeAddress.slice(-4)}
                </span>
              </div>
            </div>

            <div className="mt-3 flex items-center gap-1.5 text-[10px] font-mono text-[#8E9299]">
              <Smartphone className="w-3.5 h-3.5 text-cyan-400" />
              <span>Scan with MetaMask, Coinbase Wallet, Phantom, or Camera</span>
            </div>
          </div>

          {/* Right: Controls, Payload Inspector & Share */}
          <div className="md:col-span-7 space-y-3.5">
            {/* Address Target Switcher */}
            <div>
              <label className="block text-[10px] font-mono uppercase tracking-wider text-[#8E9299] mb-1.5">
                1. Select Address Target
              </label>
              <div className="grid grid-cols-3 gap-1.5">
                <button
                  type="button"
                  onClick={() => setAddressTarget("contract")}
                  className={`px-2.5 py-1.5 rounded-lg text-[10px] font-mono border text-left transition-all cursor-pointer ${
                    addressTarget === "contract"
                      ? "bg-cyan-500/15 border-cyan-500/50 text-cyan-300 font-semibold"
                      : "bg-[#16161A] border-[#1F1F23] text-[#8E9299] hover:text-white"
                  }`}
                >
                  <div className="truncate">Token Contract</div>
                  <div className="text-[9px] opacity-75 truncate">
                    {contractAddress.slice(0, 8)}…
                  </div>
                </button>

                {deployerAddress && (
                  <button
                    type="button"
                    onClick={() => setAddressTarget("deployer")}
                    className={`px-2.5 py-1.5 rounded-lg text-[10px] font-mono border text-left transition-all cursor-pointer ${
                      addressTarget === "deployer"
                        ? "bg-amber-500/15 border-amber-500/50 text-amber-300 font-semibold"
                        : "bg-[#16161A] border-[#1F1F23] text-[#8E9299] hover:text-white"
                    }`}
                  >
                    <div className="truncate">Deployer Wallet</div>
                    <div className="text-[9px] opacity-75 truncate">
                      {deployerAddress.slice(0, 8)}…
                    </div>
                  </button>
                )}

                {treasuryAddress && (
                  <button
                    type="button"
                    onClick={() => setAddressTarget("treasury")}
                    className={`px-2.5 py-1.5 rounded-lg text-[10px] font-mono border text-left transition-all cursor-pointer ${
                      addressTarget === "treasury"
                        ? "bg-purple-500/15 border-purple-500/50 text-purple-300 font-semibold"
                        : "bg-[#16161A] border-[#1F1F23] text-[#8E9299] hover:text-white"
                    }`}
                  >
                    <div className="truncate">Protocol Treasury</div>
                    <div className="text-[9px] opacity-75 truncate">
                      {treasuryAddress.slice(0, 8)}…
                    </div>
                  </button>
                )}
              </div>
            </div>

            {/* Encoding Format Selector */}
            <div>
              <label className="block text-[10px] font-mono uppercase tracking-wider text-[#8E9299] mb-1.5">
                2. QR Payload Format
              </label>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-1.5">
                {(
                  [
                    ["raw_address", "Raw Address"],
                    ["eip681_wallet", "EIP-681 Wallet URI"],
                    ["explorer_url", "Explorer Link"],
                    ["json_manifest", "JSON Manifest"],
                  ] as [QrPayloadMode, string][]
                ).map(([modeKey, label]) => (
                  <button
                    key={modeKey}
                    type="button"
                    onClick={() => setPayloadMode(modeKey)}
                    className={`px-2.5 py-1.5 rounded-lg text-[10px] font-mono border transition-all cursor-pointer ${
                      payloadMode === modeKey
                        ? "bg-[#F27D26]/20 border-[#F27D26] text-[#F27D26] font-semibold"
                        : "bg-[#16161A] border-[#1F1F23] text-[#8E9299] hover:text-white"
                    }`}
                  >
                    {label}
                  </button>
                ))}
              </div>
            </div>

            {/* Color Palette Selector */}
            <div>
              <label className="block text-[10px] font-mono uppercase tracking-wider text-[#8E9299] mb-1.5">
                3. Scanner Contrast Theme
              </label>
              <div className="grid grid-cols-3 gap-1.5">
                {(Object.keys(THEME_PALETTES) as QrThemePreset[]).map((key) => {
                  const item = THEME_PALETTES[key];
                  return (
                    <button
                      key={key}
                      type="button"
                      onClick={() => setThemePreset(key)}
                      className={`px-2.5 py-1.5 rounded-lg text-[10px] font-mono border transition-all cursor-pointer truncate ${
                        themePreset === key
                          ? item.badge
                          : "bg-[#16161A] border-[#1F1F23] text-[#8E9299] hover:text-white"
                      }`}
                    >
                      {item.label}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Encoded Payload Readout */}
            <div className="bg-[#16161A] p-2.5 rounded-lg border border-[#1F1F23] space-y-1.5">
              <div className="flex items-center justify-between text-[10px] font-mono text-[#8E9299]">
                <span className="flex items-center gap-1 text-cyan-400">
                  <Sparkles className="w-3 h-3" />
                  Encoded QR Data Stream
                </span>
                <button
                  type="button"
                  onClick={() => handleCopy(encodedPayload, "payload")}
                  className="text-[#E0E0E0] hover:text-cyan-300 flex items-center gap-1 cursor-pointer"
                >
                  {copiedState === "payload" ? (
                    <>
                      <Check className="w-3 h-3 text-emerald-400" />
                      <span className="text-emerald-400">Copied Payload</span>
                    </>
                  ) : (
                    <>
                      <Copy className="w-3 h-3" />
                      <span>Copy Payload</span>
                    </>
                  )}
                </button>
              </div>
              <div className="font-mono text-[11px] text-[#00F0FF] break-all bg-[#0A0A0C] p-2 rounded border border-[#1F1F23] max-h-20 overflow-y-auto select-all">
                {encodedPayload}
              </div>
            </div>

            {/* Bottom Action Buttons */}
            <div className="flex flex-wrap items-center gap-2 pt-1">
              <button
                type="button"
                onClick={handleShareAddress}
                className="flex-1 flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg bg-[#F27D26] hover:bg-[#ff8e3c] text-black font-bold text-xs uppercase tracking-wider cursor-pointer transition-all"
              >
                {copiedState === "share_card" ? (
                  <>
                    <Check className="w-3.5 h-3.5" />
                    <span>Share Card Copied to Clipboard!</span>
                  </>
                ) : (
                  <>
                    <Share2 className="w-3.5 h-3.5" />
                    <span>Share Contract Address &amp; Link</span>
                  </>
                )}
              </button>

              <a
                href={resolvedExplorerUrl}
                target="_blank"
                rel="noreferrer"
                className="flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg bg-[#16161A] hover:bg-[#1F1F23] border border-[#2A2A32] text-cyan-300 font-mono text-xs cursor-pointer transition-colors"
              >
                <span>Open Explorer</span>
                <ExternalLink className="w-3.5 h-3.5" />
              </a>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from "react";
import {
  X,
  Binary,
  Cpu,
  Layers,
  FileCode,
  Copy,
  Check,
  Download,
  Search,
  CheckCircle2,
  AlertTriangle,
  ExternalLink,
  ShieldCheck,
  Zap,
  RefreshCw,
  Terminal,
  Activity,
  Code2,
} from "lucide-react";
import { TokenRecord } from "../types";
import {
  decompileContractBytecode,
  DecompiledContractStructure,
} from "../utils/contractDecompiler";

interface ContractDecompilerModalProps {
  isOpen: boolean;
  onClose: () => void;
  token: TokenRecord | null;
}

export const ContractDecompilerModal: React.FC<ContractDecompilerModalProps> = ({
  isOpen,
  onClose,
  token,
}) => {
  const [activeTab, setActiveTab] = useState<"structure" | "opcodes" | "bytecode" | "security_re">("structure");
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [decompileResult, setDecompileResult] = useState<DecompiledContractStructure | null>(null);
  const [opcodeSearch, setOpcodeSearch] = useState<string>("");
  const [copiedKey, setCopiedKey] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen && token) {
      setIsLoading(true);
      setOpcodeSearch("");
      decompileContractBytecode(
        token.contractAddress || "0x0000000000000000000000000000000000000000",
        token.chain || token.network || "Ethereum Mainnet"
      )
        .then((result) => {
          setDecompileResult(result);
        })
        .finally(() => {
          setIsLoading(false);
        });
    }
  }, [isOpen, token]);

  const handleCopy = (text: string, key: string) => {
    navigator.clipboard.writeText(text);
    setCopiedKey(key);
    setTimeout(() => setCopiedKey(null), 2000);
  };

  const handleDownloadSol = () => {
    if (!decompileResult || !token) return;
