// Convert normalized 1000x460 mapX/mapY into geographic [longitude, latitude]
function mapCoordsToLonLat(mapX: number, mapY: number): [number, number] {
  const lon = Math.max(-175, Math.min(178, ((mapX - 500) / 450) * 175));
  const lat = Math.max(-56, Math.min(72, ((235 - mapY) / 195) * 68));
  return [Number(lon.toFixed(2)), Number(lat.toFixed(2))];
}

export const D3GlobalComplianceVelocityMap: React.FC<
  D3GlobalComplianceVelocityMapProps
> = ({
  jurisdictions,
  customActivationPcts,
  selectedContinent,
  selectedRegulatoryBlocks = ["Americas", "EMEA", "APAC", "LATAM"],
  onToggleRegulatoryBlock,
  onResetRegulatoryBlocks,
  selectedCountryIso,
  tierFilter,
  heatmapMetricMode: controlledMetricMode,
  onChangeHeatmapMetricMode,
  onSelectContinent,
  onSelectCountry,
  onUpdateNodeActivationPct,
  onExportJurisdictionSnapshot,
}) => {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const zoomGroupRef = useRef<SVGGElement | null>(null);

  const getRegulatoryBlockForState = (
    j: UnMemberJurisdiction
  ): GeographicalRegulatoryBlock => {
    const latamNorthAmericaIsos = new Set([
      "MX",
      "GT",
      "BZ",
      "HN",
      "SV",
      "NI",
      "CR",
      "PA",
      "CU",
      "DO",
      "HT",
    ]);
    if (
      j.continent === "South America" ||
      latamNorthAmericaIsos.has(j.isoCode)
    ) {
      return "LATAM";
    }
    if (j.continent === "North America") {
      return "Americas";
    }
    if (
      j.continent === "Europe" ||
      j.continent === "Middle East & Africa"
    ) {
      return "EMEA";
    }
    return "APAC";
  };

  const matchesRegulatoryBlocks = (j: UnMemberJurisdiction): boolean => {
    if (!selectedRegulatoryBlocks || selectedRegulatoryBlocks.length === 0) {
      return true;
    }
    return selectedRegulatoryBlocks.includes(getRegulatoryBlockForState(j));
  };

  const [internalMetricMode, setInternalMetricMode] =
    useState<D3HeatmapMetricMode>("ADOPTION_VELOCITY");
  const activeMetricMode: D3HeatmapMetricMode =
    controlledMetricMode ?? internalMetricMode;

  const handleSelectMetricMode = (mode: D3HeatmapMetricMode) => {
    setInternalMetricMode(mode);
    if (onChangeHeatmapMetricMode) {
      onChangeHeatmapMetricMode(mode);
    }
  };

  const [paletteId, setPaletteId] = useState<D3HeatColorPaletteId>(
    "SOVEREIGN_EMERALD_HEAT"
  );
  const [projectionMode, setProjectionMode] =
    useState<D3ProjectionModeId>("NATURAL_EARTH");
  const [showVoronoiHeatCells, setShowVoronoiHeatCells] =
    useState<boolean>(true);
  const [showThermalContours, setShowThermalContours] = useState<boolean>(true);
  const [showSettlementArcs, setShowSettlementArcs] = useState<boolean>(true);
  const [velocityHeatBoost, setVelocityHeatBoost] = useState<number>(0);
  const [hoveredMetric, setHoveredMetric] =
    useState<JurisdictionVelocityMetric | null>(null);
  const [zoomTransformStr, setZoomTransformStr] = useState<string>(
    "translate(0,0) scale(1)"
  );
  const [zoomScale, setZoomScale] = useState<number>(1);

  const width = 1000;
  const height = 480;

  // 1. D3 Sequential Color Scale for Compliance Adoption Velocity vs Regulatory Risk Intensity (0..100)
  const d3HeatColorScale = useMemo(() => {
    if (activeMetricMode === "REGULATORY_RISK_INTENSITY") {
      return d3
        .scaleSequential(
          d3.interpolateRgbBasis([
            "#064E3B", // 0: Low Sovereign Risk Emerald
            "#10B981", // 20: Controlled Risk Mint
            "#FACC15", // 45: Moderate Risk Gold
            "#F97316", // 65: Elevated Risk Orange
            "#E11D48", // 82: High Regulatory Friction Rose
            "#FF1E56", // 100: Critical Geo-Fenced Risk Crimson
          ])
        )
        .domain([0, 100]);
    }
    if (paletteId === "THERMAL_INFERNO") {
      return d3.scaleSequential(d3.interpolateInferno).domain([0, 100]);
    }
    if (paletteId === "TURBO_SPECTRUM") {
      return d3.scaleSequential(d3.interpolateTurbo).domain([0, 100]);
    }
    if (paletteId === "PLASMA_VELOCITY") {
      return d3.scaleSequential(d3.interpolatePlasma).domain([0, 100]);
    }
    // Default: Sovereign Emerald-Amber-Crimson-Cyan Heat Scale
    return d3
      .scaleSequential(
        d3.interpolateRgbBasis([
          "#4C0519", // 0: Deep Restricted Crimson
          "#E11D48", // 25: Restricted Rose
          "#D97706", // 50: Transitional Amber
          "#F59E0B", // 68: Pending KYC Gold
          "#10B981", // 85: Compliant Emerald
          "#00F0FF", // 100: Hyper-Velocity Quantum Cyan
        ])
      )
      .domain([0, 100]);
  }, [paletteId, activeMetricMode]);

  // 2. D3 GeoProjection (Natural Earth I, Equirectangular, or Mercator)
  const projection = useMemo(() => {
    if (projectionMode === "EQUIRECTANGULAR") {
      return d3
        .geoEquirectangular()
        .scale(155)
        .translate([width / 2, height / 2 + 10]);
    }
    if (projectionMode === "MERCATOR") {
      return d3
        .geoMercator()
        .scale(130)
        .translate([width / 2, height / 2 + 35]);
    }
    return d3
      .geoNaturalEarth1()
      .scale(172)
      .translate([width / 2, height / 2 + 12]);
  }, [projectionMode]);

  const geoPathGenerator = useMemo(
    () => d3.geoPath().projection(projection),
    [projection]
  );

  // Graticule path & Sphere outline generated via D3
  const graticulePathD = useMemo(() => {
    const graticule = d3.geoGraticule10();
    return geoPathGenerator(graticule) || "";
  }, [geoPathGenerator]);

  const sphereOutlineD = useMemo(() => {
    return geoPathGenerator({ type: "Sphere" }) || "";
  }, [geoPathGenerator]);

  // 3. Compute D3 Velocity Metrics for all 193 UN Member States
  const velocityMetrics = useMemo<JurisdictionVelocityMetric[]>(() => {
    return jurisdictions.map((j) => {
      const [lon, lat] = mapCoordsToLonLat(j.mapX, j.mapY);
      const projected = projection([lon, lat]) || [j.mapX, j.mapY];

      const customPct = customActivationPcts[j.isoCode];
      const activationPct =
        typeof customPct === "number"
          ? customPct
          : j.nodeStatus === "GEO_FENCED_RESTRICTED"
          ? 25
          : !j.autoKycEnabled
          ? 68
          : 100;

      const complianceBadge: "Fully Compliant" | "Pending KYC" | "Restricted" =
        activationPct < 50
          ? "Restricted"
          : activationPct < 100
          ? "Pending KYC"
          : "Fully Compliant";

      // Calculate authentic Compliance Adoption Velocity Score (0..100)
      const tierBonus =
        j.tier === "TIER_1" ? 14 : j.tier === "TIER_2" ? 10 : 6;
      const kycBonus = j.autoKycEnabled ? 16 : 4;
      const zkBonus = j.zkIdentityEnabled ? 8 : 2;
      const latencyBonus = Math.max(0, Math.min(8, Math.round((45 - j.latencyMs) / 4)));
      const rawScore =
        activationPct * 0.54 +
        tierBonus +
        kycBonus +
        zkBonus +
        latencyBonus +
        velocityHeatBoost;

      const velocityScore = Number(
        Math.max(5, Math.min(100, rawScore)).toFixed(1)
      );

      // Calculate Regulatory Risk Intensity Score (0..100)
      const geoRestrictionPenalty =
        j.nodeStatus === "GEO_FENCED_RESTRICTED"
          ? 44
          : j.nodeStatus === "STAGING_SYNC"
          ? 22
          : 4;
      const kycGapPenalty = j.autoKycEnabled ? 5 : 26;
      const zkGapPenalty = j.zkIdentityEnabled ? 3 : 12;
      const tierFriction =
        j.tier === "TIER_1" ? 6 : j.tier === "TIER_2" ? 13 : 21;
      const activationGap = (100 - activationPct) * 0.42;
      const rawRiskScore =
        geoRestrictionPenalty +
        kycGapPenalty +
        zkGapPenalty +
        tierFriction * 0.5 +
        activationGap -
        velocityHeatBoost * 0.6;
      const riskIntensityScore = Number(
        Math.max(4, Math.min(98, rawRiskScore)).toFixed(1)
      );

      const activeScore =
        activeMetricMode === "REGULATORY_RISK_INTENSITY"
          ? riskIntensityScore
          : velocityScore;

      const thirtyDayDeltaPct = Number(
        (
          (velocityScore * 0.24) +
          (j.tier === "TIER_1" ? 4.2 : j.tier === "TIER_2" ? 3.1 : 1.8)
        ).toFixed(1)
      );

      const heatIntensityLabel: JurisdictionVelocityMetric["heatIntensityLabel"] =
        activeMetricMode === "REGULATORY_RISK_INTENSITY"
          ? riskIntensityScore >= 75
            ? "CRITICAL RISK (75–100)"
            : riskIntensityScore >= 50
            ? "ELEVATED RISK (50–74)"
            : riskIntensityScore >= 25
            ? "MODERATE RISK (25–49)"
            : "LOW SOVEREIGN RISK (0–24)"
          : velocityScore >= 85
          ? "HYPER-VELOCITY (85–100)"
          : velocityScore >= 65
          ? "HIGH ADOPTION (65–84)"
          : velocityScore >= 45
          ? "TRANSITIONAL (45–64)"
          : "RESTRICTED / COLD (0–44)";

      const heatColorHex = d3HeatColorScale(activeScore);
      const isHighActivityTransition = Boolean(
        j.complianceCheckHighlighted ||
          !j.autoKycEnabled ||
          j.nodeStatus === "STAGING_SYNC" ||
          selectedCountryIso === j.isoCode ||
          j.tier === "TIER_1"
      );
      const isRapidStatusShift = Boolean(
        j.complianceCheckHighlighted ||
          selectedCountryIso === j.isoCode ||
          Math.abs(thirtyDayDeltaPct) >= 12 ||
          velocityScore >= 78 ||
          riskIntensityScore >= 68
      );
      const staggerDelayMs = Math.min(
        480,
        Math.round(j.index * (isRapidStatusShift ? 3.5 : 8.5))
      );
      const easingFunctionName = isRapidStatusShift
        ? "pulsate-to-steady-fast (cubic-bezier(0.16, 1, 0.3, 1))"
        : "pulsate-to-steady-standard (cubic-bezier(0.4, 0, 0.2, 1))";

      return {
        jurisdiction: j,
        lon,
        lat,
        projectedX: projected[0],
        projectedY: projected[1],
        activationPct,
        velocityScore,
        riskIntensityScore,
        activeScore,
        thirtyDayDeltaPct,
        heatIntensityLabel,
        heatColorHex,
        complianceBadge,
        isHighActivityTransition,
        isRapidStatusShift,
        staggerDelayMs,
        easingFunctionName,
      };
    });
  }, [
    jurisdictions,
    customActivationPcts,
    projection,
    velocityHeatBoost,
    d3HeatColorScale,
    activeMetricMode,
    selectedCountryIso,
  ]);

  // 4. Compute D3 Voronoi Tessellation Polygons for all 193 States
  const voronoiCells = useMemo(() => {
    const points: [number, number][] = velocityMetrics.map((m) => [
      m.projectedX,
      m.projectedY,
    ]);
    const delaunay = d3.Delaunay.from(points);
    const voronoi = delaunay.voronoi([25, 20, width - 25, height - 20]);
    return velocityMetrics.map((metric, idx) => ({
      metric,
      pathD: voronoi.renderCell(idx),
    }));
  }, [velocityMetrics]);

  // 5. Compute Continent-Level Mean Score for Choropleth Base Fill
  const continentVelocityMap = useMemo(() => {
    const map: Record<
      WorldContinentId,
      { avgScore: number; count: number; color: string }
    > = {
      "North America": { avgScore: 0, count: 0, color: "#1E293B" },
      "South America": { avgScore: 0, count: 0, color: "#1E293B" },
      Europe: { avgScore: 0, count: 0, color: "#1E293B" },
      "Middle East & Africa": { avgScore: 0, count: 0, color: "#1E293B" },
      Asia: { avgScore: 0, count: 0, color: "#1E293B" },
      Oceania: { avgScore: 0, count: 0, color: "#1E293B" },
    };

    velocityMetrics.forEach((m) => {
      const c = m.jurisdiction.continent;
      map[c].avgScore += m.activeScore;
      map[c].count += 1;
    });

    (Object.keys(map) as WorldContinentId[]).forEach((c) => {
      if (map[c].count > 0) {
        map[c].avgScore = Number((map[c].avgScore / map[c].count).toFixed(1));
        map[c].color = d3HeatColorScale(map[c].avgScore);
      }
    });

    return map;
  }, [velocityMetrics, d3HeatColorScale]);

  // 6. Global Aggregate Velocity / Risk Telemetry
  const globalVelocitySummary = useMemo(() => {
    const total = Math.max(1, velocityMetrics.length);
    const meanScore = Number(
      (
        velocityMetrics.reduce((acc, m) => acc + m.activeScore, 0) / total
      ).toFixed(1)
    );
    const hyperCount = velocityMetrics.filter((m) => m.activeScore >= 85).length;
    const highCount = velocityMetrics.filter(
      (m) => m.activeScore >= 65 && m.activeScore < 85
    ).length;
    const transitionalCount = velocityMetrics.filter(
      (m) => m.activeScore >= 45 && m.activeScore < 65
    ).length;
    const coldCount = velocityMetrics.filter((m) => m.activeScore < 45).length;
    return {
      meanScore,
      hyperCount,
      highCount,
      transitionalCount,
      coldCount,
      meanColor: d3HeatColorScale(meanScore),
    };
  }, [velocityMetrics, d3HeatColorScale]);

  // 7. Attach D3 Zoom behavior to SVG
  useEffect(() => {
    if (!svgRef.current) return;
    const svgSelection = d3.select(svgRef.current);
    const zoomBehavior = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([1, 6])
      .translateExtent([
        [0, 0],
        [width, height],
      ])
      .on("zoom", (event) => {
        const { x, y, k } = event.transform;
        setZoomTransformStr(`translate(${x},${y}) scale(${k})`);
        setZoomScale(Number(k.toFixed(2)));
      });

    svgSelection.call(zoomBehavior);
    return () => {
      svgSelection.on(".zoom", null);
    };
  }, []);

  // 7b. D3 Staggered Animated Metric Transition with Faster Pulsate-to-Steady Easing for Rapid Status Shift States
  useEffect(() => {
    if (!svgRef.current) return;
    const svgSelection = d3.select(svgRef.current);

    const d3PulsateToSteadyEase = (isRapidShift: boolean) => (t: number): number => {
      if (t <= 0) return 0;
      if (t >= 1) return 1;
      const decay = isRapidShift ? 6.5 : 4.2;
      const freq = isRapidShift ? 3.5 * Math.PI : 1.8 * Math.PI;
      return Math.max(0, Math.min(1.18, 1 - Math.exp(-decay * t) * Math.cos(freq * t)));
    };

    svgSelection
      .selectAll<SVGPathElement, unknown>(".d3-voronoi-heat-cell")
      .interrupt()
      .attr("fill-opacity", 0.12)
      .transition()
      .delay(function (_, i) {
        const isRapid = d3.select(this).attr("data-rapid-shift") === "true";
        return Math.min(520, i * (isRapid ? 3.5 : 8.5));
      })
      .duration(function () {
        const isRapid = d3.select(this).attr("data-rapid-shift") === "true";
        return isRapid ? 420 : 820;
      })
      .ease(function () {
        const isRapid = d3.select(this).attr("data-rapid-shift") === "true";
        return d3PulsateToSteadyEase(isRapid);
      } as any)
      .attr("fill-opacity", function () {
        const isSel = d3.select(this).attr("data-selected") === "true";
        const isRapid = d3.select(this).attr("data-rapid-shift") === "true";
        return isSel ? "0.72" : isRapid ? "0.48" : "0.38";
      });

    svgSelection
      .selectAll<SVGCircleElement, unknown>(".d3-state-pin-circle")
      .interrupt()
      .transition()
      .delay(function (_, i) {
        const isRapid = d3.select(this).attr("data-rapid-shift") === "true";
        return Math.min(520, i * (isRapid ? 3.5 : 8.5));
      })
      .duration(function () {
        const isRapid = d3.select(this).attr("data-rapid-shift") === "true";
        return isRapid ? 360 : 620;
      })
      .ease(d3.easeCubicOut)
      .attr("r", function () {
        const baseR = Number(d3.select(this).attr("data-pin-r") || 3.5);
        const isRapid = d3.select(this).attr("data-rapid-shift") === "true";
        return baseR * (isRapid ? 1.38 : 1.2);
      })
      .transition()
      .duration(function () {
        const isRapid = d3.select(this).attr("data-rapid-shift") === "true";
        return isRapid ? 280 : 450;
      })
      .ease(d3.easeCubicInOut)
      .attr("r", function () {
        return Number(d3.select(this).attr("data-pin-r") || 3.5);
      });
  }, [activeMetricMode, paletteId]);

  const handleZoomBy = (factor: number) => {
    if (!svgRef.current) return;
    const svgSelection = d3.select(svgRef.current);
    const zoomBehavior = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([1, 6])
      .on("zoom", (event) => {
        const { x, y, k } = event.transform;
        setZoomTransformStr(`translate(${x},${y}) scale(${k})`);
        setZoomScale(Number(k.toFixed(2)));
      });
    svgSelection.transition().duration(250).call(zoomBehavior.scaleBy, factor);
  };

  const handleResetZoom = () => {
    if (!svgRef.current) return;
    setZoomTransformStr("translate(0,0) scale(1)");
    setZoomScale(1);
  };

  // Active inspected jurisdiction metric (hovered or selected or US default)
  const inspectedMetric = useMemo<JurisdictionVelocityMetric>(() => {
    if (hoveredMetric) return hoveredMetric;
    if (selectedCountryIso) {
      const found = velocityMetrics.find(
        (m) => m.jurisdiction.isoCode === selectedCountryIso
      );
      if (found) return found;
    }
    return (
      velocityMetrics.find((m) => m.jurisdiction.isoCode === "US") ||
      velocityMetrics[0]
    );
  }, [hoveredMetric, selectedCountryIso, velocityMetrics]);

  // US Hub Projected Coordinates for T+0 Settlement Arcs
  const usMetric = useMemo(
    () =>
      velocityMetrics.find((m) => m.jurisdiction.isoCode === "US") ||
      velocityMetrics[0],
    [velocityMetrics]
  );

  // Legend Gradient Stops (0, 20, 40, 60, 80, 100)
  const legendStops = useMemo(
    () =>
      [0, 20, 40, 60, 80, 100].map((score) => ({
        score,
        color: d3HeatColorScale(score),
      })),
    [d3HeatColorScale]
  );

  return (
    <div className="rounded-xl border border-slate-800 bg-[#0B0F19] p-5 space-y-4 shadow-2xl">
      {/* Top Header & D3 Controls */}
      <div className="flex flex-col xl:flex-row xl:items-center xl:justify-between gap-3 border-b border-slate-800 pb-3.5">
        <div className="space-y-1">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full bg-amber-500/15 border border-amber-500/40 text-amber-300 font-mono text-[11px] font-bold">
              <Flame className="w-3.5 h-3.5 text-amber-400" />
              D3.JS GLOBAL COMPLIANCE ADOPTION VELOCITY HEATMAP
            </span>
            <span className="px-2.5 py-0.5 rounded-full bg-cyan-500/15 border border-cyan-500/30 text-cyan-300 font-mono text-[11px] font-bold">
              193 UN Member States · Voronoi & Thermal Choropleth
            </span>
            <span
              className="px-2.5 py-0.5 rounded-full font-mono text-[11px] font-bold text-slate-950"
              style={{ backgroundColor: globalVelocitySummary.meanColor }}
            >
              {activeMetricMode === "REGULATORY_RISK_INTENSITY"
                ? `Global Mean Risk Intensity: ${globalVelocitySummary.meanScore} / 100`
                : `Global Mean Velocity: ${globalVelocitySummary.meanScore} / 100`}
            </span>
          </div>
          <h3 className="text-base sm:text-lg font-bold text-white">
            {activeMetricMode === "REGULATORY_RISK_INTENSITY"
              ? "Interactive D3 Geospatial Regulatory Risk Intensity & Sanctions Friction Heatmap"
              : "Interactive D3 Geospatial Rollout Heat Intensity & Adoption Velocity Map"}
          </h3>
        </div>

        {/* Metric Mode Toggle + Projection & Heat Palette Selectors */}
        <div className="flex flex-wrap items-center gap-2 font-mono text-xs">
          <div
            className="inline-flex items-center rounded-lg bg-[#111622] border border-slate-800 p-1 gap-1"
            role="group"
            aria-label="D3 Heatmap Metric Mode"
          >
            <button
              type="button"
              onClick={() => handleSelectMetricMode("ADOPTION_VELOCITY")}
              className={`px-2.5 py-1 rounded text-[11px] font-bold transition cursor-pointer ${
                activeMetricMode === "ADOPTION_VELOCITY"
                  ? "bg-emerald-500 text-slate-950"
                  : "text-slate-300 hover:bg-slate-800"
              }`}
            >
              Adoption Velocity
            </button>
            <button
              type="button"
              onClick={() =>
                handleSelectMetricMode("REGULATORY_RISK_INTENSITY")
              }
              className={`px-2.5 py-1 rounded text-[11px] font-bold transition cursor-pointer ${
                activeMetricMode === "REGULATORY_RISK_INTENSITY"
                  ? "bg-rose-500 text-white"
                  : "text-slate-300 hover:bg-slate-800"
              }`}
            >
              Regulatory Risk Intensity
            </button>
          </div>

          <div className="flex items-center gap-1.5 bg-[#111622] border border-slate-800 rounded-lg px-2.5 py-1">
            <Globe className="w-3.5 h-3.5 text-cyan-400" />
            <span className="text-[11px] text-slate-400">D3 Projection:</span>
            <select
              aria-label="D3 Map Projection"
              value={projectionMode}
              onChange={(e) =>
                setProjectionMode(e.target.value as D3ProjectionModeId)
              }
              className="bg-transparent text-white font-bold focus:outline-none cursor-pointer"
            >
              <option value="NATURAL_EARTH" className="bg-[#0B0F19]">
                d3.geoNaturalEarth1()
              </option>
              <option value="EQUIRECTANGULAR" className="bg-[#0B0F19]">
                d3.geoEquirectangular()
              </option>
              <option value="MERCATOR" className="bg-[#0B0F19]">
                d3.geoMercator()
              </option>
            </select>
          </div>

          <div className="flex items-center gap-1.5 bg-[#111622] border border-slate-800 rounded-lg px-2.5 py-1">
            <Flame className="w-3.5 h-3.5 text-amber-400" />
            <span className="text-[11px] text-slate-400">Heat Scale:</span>
            <select
              aria-label="D3 Heat Color Scale"
              value={paletteId}
              onChange={(e) =>
                setPaletteId(e.target.value as D3HeatColorPaletteId)
              }
              className="bg-transparent text-amber-300 font-bold focus:outline-none cursor-pointer"
            >
              <option value="SOVEREIGN_EMERALD_HEAT" className="bg-[#0B0F19]">
                Sovereign Crimson → Amber → Emerald → Cyan
              </option>
              <option value="THERMAL_INFERNO" className="bg-[#0B0F19]">
                d3.interpolateInferno (Thermal Heat)
              </option>
              <option value="TURBO_SPECTRUM" className="bg-[#0B0F19]">
                d3.interpolateTurbo (Multi-Spectrum)
              </option>
              <option value="PLASMA_VELOCITY" className="bg-[#0B0F19]">
                d3.interpolatePlasma (High-Contrast Plasma)
              </option>
            </select>
          </div>
        </div>
      </div>

      {/* Heat Intensity Summary Cards + Layer Toggles + Velocity Boost Simulator */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-3 items-center">
        <div className="lg:col-span-7 grid grid-cols-2 sm:grid-cols-4 gap-2.5 font-mono text-xs">
          <div className="p-2.5 rounded-lg bg-[#111622] border border-cyan-500/30">
            <div className="text-[10px] text-cyan-300 uppercase">
              Hyper-Velocity (85–100)
            </div>
            <div className="text-base font-bold text-white tabular-nums mt-0.5">
              {globalVelocitySummary.hyperCount}{" "}
              <span className="text-[11px] text-slate-400 font-normal">
                States
              </span>
            </div>
          </div>
          <div className="p-2.5 rounded-lg bg-[#111622] border border-emerald-500/30">
            <div className="text-[10px] text-emerald-300 uppercase">
              High Adoption (65–84)
            </div>
            <div className="text-base font-bold text-white tabular-nums mt-0.5">
              {globalVelocitySummary.highCount}{" "}
              <span className="text-[11px] text-slate-400 font-normal">
                States
              </span>
            </div>
          </div>
          <div className="p-2.5 rounded-lg bg-[#111622] border border-amber-500/30">
            <div className="text-[10px] text-amber-300 uppercase">
              Transitional (45–64)
            </div>
            <div className="text-base font-bold text-white tabular-nums mt-0.5">
              {globalVelocitySummary.transitionalCount}{" "}
              <span className="text-[11px] text-slate-400 font-normal">
                States
              </span>
            </div>
          </div>
          <div className="p-2.5 rounded-lg bg-[#111622] border border-rose-500/30">
            <div className="text-[10px] text-rose-300 uppercase">
              Restricted / Cold (&lt;45)
            </div>
            <div className="text-base font-bold text-white tabular-nums mt-0.5">
              {globalVelocitySummary.coldCount}{" "}
              <span className="text-[11px] text-slate-400 font-normal">
                States
              </span>
            </div>
          </div>
        </div>

        {/* Layer Toggles & Global Velocity Heat Stress-Test Slider */}
        <div className="lg:col-span-5 p-2.5 rounded-lg bg-[#111622] border border-slate-800 flex flex-wrap items-center justify-between gap-2 font-mono text-xs">
          <div className="flex items-center gap-1.5 flex-wrap">
            <button
              type="button"
              onClick={() => setShowVoronoiHeatCells((v) => !v)}
              className={`px-2.5 py-1 rounded border text-[11px] cursor-pointer transition ${
                showVoronoiHeatCells
                  ? "bg-emerald-500/20 border-emerald-500/50 text-emerald-300 font-bold"
                  : "bg-[#0B0F19] border-slate-800 text-slate-400"
              }`}
            >
              Voronoi Heat Cells
            </button>
            <button
              type="button"
              onClick={() => setShowThermalContours((v) => !v)}
              className={`px-2.5 py-1 rounded border text-[11px] cursor-pointer transition ${
                showThermalContours
                  ? "bg-amber-500/20 border-amber-500/50 text-amber-300 font-bold"
                  : "bg-[#0B0F19] border-slate-800 text-slate-400"
              }`}
            >
              Thermal Halos
            </button>
            <button
              type="button"
              onClick={() => setShowSettlementArcs((v) => !v)}
              className={`px-2.5 py-1 rounded border text-[11px] cursor-pointer transition ${
                showSettlementArcs
                  ? "bg-cyan-500/20 border-cyan-500/50 text-cyan-300 font-bold"
                  : "bg-[#0B0F19] border-slate-800 text-slate-400"
              }`}
            >
              T+0 Arcs
            </button>
            {onToggleRegulatoryBlock && (
              <div
                className="flex items-center gap-1 ml-1 pl-2 border-l border-slate-800"
                role="group"
                aria-label="D3 Map Geographical Regulatory Block Chips"
              >
                {(
                  ["Americas", "EMEA", "APAC", "LATAM"] as GeographicalRegulatoryBlock[]
                ).map((block) => {
                  const isActive = selectedRegulatoryBlocks.includes(block);
                  return (
                    <button
                      key={block}
                      type="button"
                      role="checkbox"
                      aria-checked={isActive}
                      onClick={() => onToggleRegulatoryBlock(block)}
                      className={`px-2 py-0.5 rounded border text-[10px] font-mono cursor-pointer transition ${
                        isActive
                          ? "bg-cyan-500/20 border-cyan-400 text-cyan-200 font-bold"
                          : "bg-[#0B0F19] border-slate-800 text-slate-500 hover:text-slate-300"
                      }`}
                    >
                      {block} {isActive ? "✓" : "+"}
                    </button>
                  );
                })}
                {onResetRegulatoryBlocks &&
                  selectedRegulatoryBlocks.length < 4 && (
                    <button
                      type="button"
                      onClick={onResetRegulatoryBlocks}
                      className="px-2 py-0.5 rounded border border-slate-700 bg-slate-800 text-white text-[10px] font-mono cursor-pointer"
                    >
                      All
                    </button>
                  )}
              </div>
            )}
          </div>

          <div className="flex items-center gap-2 w-full sm:w-auto">
            <Sliders className="w-3.5 h-3.5 text-amber-400 shrink-0" />
            <span className="text-[11px] text-slate-400 whitespace-nowrap">
              Heat Shift:
            </span>
            <input
              type="range"
              aria-label="Global Velocity Heat Shift"
              min={-25}
              max={25}
              value={velocityHeatBoost}
              onChange={(e) => setVelocityHeatBoost(Number(e.target.value))}
              className="w-24 accent-amber-500 cursor-pointer"
            />
            <span className="text-[11px] text-amber-300 font-bold tabular-nums w-10 text-right">
              {velocityHeatBoost >= 0
                ? `+${velocityHeatBoost}`
                : velocityHeatBoost}
            </span>
          </div>
        </div>
      </div>

      {/* Main Split View: D3 SVG Global Map (8 Cols) + Live Velocity Heat Inspector (4 Cols) */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-stretch">
        {/* Left 8 Cols: Interactive D3 SVG Canvas */}
        <div className="lg:col-span-8 rounded-xl border border-slate-800 bg-[#060911] relative overflow-hidden flex flex-col justify-between">
          {/* Top D3 Map Toolbar & Continuous Color Scale Bar */}
          <div className="px-4 py-2.5 border-b border-slate-800/80 bg-[#0A0E18] flex flex-wrap items-center justify-between gap-3 text-[11px] font-mono">
            <div className="flex items-center gap-2 flex-wrap">
              <span className="text-slate-400">
                Compliance Velocity Heat Scale (0 → 100):
              </span>
              <div className="flex items-center gap-1">
                <span className="text-[10px] text-rose-400">0</span>
                <div
                  className="w-36 h-2.5 rounded-full border border-slate-700"
                  style={{
                    background: `linear-gradient(90deg, ${legendStops
                      .map((s) => `${s.color} ${s.score}%`)
                      .join(", ")})`,
                  }}
                />
                <span className="text-[10px] text-cyan-300 font-bold">100</span>
              </div>
            </div>

            {/* Zoom Controls */}
            <div className="flex items-center gap-1.5">
              <span className="text-slate-400 mr-1 tabular-nums">
                Zoom: {zoomScale}x
              </span>
              <button
                type="button"
                onClick={() => handleZoomBy(1.35)}
                className="p-1 rounded bg-[#111622] hover:bg-slate-800 border border-slate-700 text-slate-200 cursor-pointer"
                title="Zoom In"
              >
                <ZoomIn className="w-3.5 h-3.5" />
              </button>
              <button
                type="button"
                onClick={() => handleZoomBy(0.75)}
                className="p-1 rounded bg-[#111622] hover:bg-slate-800 border border-slate-700 text-slate-200 cursor-pointer"
                title="Zoom Out"
              >
                <ZoomOut className="w-3.5 h-3.5" />
              </button>
              <button
                type="button"
                onClick={() => {
                  handleResetZoom();
                  onSelectContinent("ALL");
                  onSelectCountry(null);
                }}
                className="px-2 py-1 rounded bg-[#111622] hover:bg-slate-800 border border-slate-700 text-amber-300 flex items-center gap-1 cursor-pointer"
                title="Reset Zoom & Selection"
              >
                <RotateCcw className="w-3 h-3" />
                <span>Reset</span>
              </button>
            </div>
          </div>

          {/* D3 SVG Viewport */}
          <div className="w-full overflow-x-auto relative">
            <svg
              ref={svgRef}
              viewBox={`0 0 ${width} ${height}`}
              className="w-full h-auto min-w-[660px] select-none cursor-grab active:cursor-grabbing"
              role="img"
              aria-label="D3 Global Compliance Adoption Velocity Heatmap across 193 UN Member States"
            >
              <defs>
                {/* SVG ClipPaths for each of the 6 Continental Polygons so Voronoi Cells stay inside landmasses */}
                <clipPath id="d3-continents-master-clip">
                  {CONTINENT_GEOJSON_FEATURES.map((feat) => {
                    const d = geoPathGenerator(feat as any) || "";
                    return <path key={feat.properties.id} d={d} />;
                  })}
                </clipPath>

                {/* Radial Thermal Glow Filter */}
                <filter
                  id="d3-thermal-glow"
                  x="-50%"
                  y="-50%"
                  width="200%"
                  height="200%"
                >
                  <feGaussianBlur stdDeviation="6" result="blur" />
                  <feMerge>
                    <feMergeNode in="blur" />
                    <feMergeNode in="SourceGraphic" />
                  </feMerge>
                </filter>
              </defs>

              <g ref={zoomGroupRef} transform={zoomTransformStr}>
                {/* 1. D3 Sphere Ocean Background */}
                <path
                  d={sphereOutlineD}
                  fill="#050811"
                  stroke="#1E293B"
                  strokeWidth={1.2}
                />

                {/* 2. D3 Graticule 10-degree Grid */}
                <path
                  d={graticulePathD}
                  fill="none"
                  stroke="#1E293B"
                  strokeWidth={0.55}
                  strokeDasharray="2 3"
                  opacity={0.65}
                />

                {/* 3. Continental Choropleth Base Polygons */}
                {CONTINENT_GEOJSON_FEATURES.map((feat) => {
                  const contId = feat.properties.id;
                  const pathD = geoPathGenerator(feat as any) || "";
                  const contStat = continentVelocityMap[contId];
                  const isContSelected = selectedContinent === contId;
                  const centroid = geoPathGenerator.centroid(feat as any);

                  return (
                    <g key={contId}>
                      <path
                        d={pathD}
                        fill={contStat.color}
                        fillOpacity={isContSelected ? 0.34 : 0.18}
                        stroke={isContSelected ? "#38BDF8" : contStat.color}
                        strokeWidth={isContSelected ? 2.2 : 1.1}
                        className="d3-continent-choropleth transition-all duration-500 ease-in-out [transition:fill_550ms_cubic-bezier(0.4,0,0.2,1),stroke_550ms_cubic-bezier(0.4,0,0.2,1),fill-opacity_450ms_ease-in-out] cursor-pointer"
                        onClick={() => {
                          onSelectContinent(
                            isContSelected ? "ALL" : contId
                          );
                          onSelectCountry(null);
                        }}
                      />
                      {!Number.isNaN(centroid[0]) && !Number.isNaN(centroid[1]) && (
                        <text
                          x={centroid[0]}
                          y={centroid[1]}
                          textAnchor="middle"
                          className="fill-slate-300/75 text-[10px] font-mono font-bold pointer-events-none transition-opacity duration-500 ease-in-out"
                        >
                          {feat.properties.name.toUpperCase()} ({contStat.avgScore}%)
                        </text>
                      )}
                    </g>
                  );
                })}

                {/* 4. D3 Voronoi Jurisdiction Territory Heat Cells (Clipped to Continental Landmasses) */}
                {showVoronoiHeatCells && (
                  <g clipPath="url(#d3-continents-master-clip)">
                    {voronoiCells.map(({ metric, pathD }) => {
                      const j = metric.jurisdiction;
                      if (!matchesRegulatoryBlocks(j)) {
                        return null;
                      }
                      if (
                        selectedContinent !== "ALL" &&
                        j.continent !== selectedContinent
                      ) {
                        return null;
                      }
                      if (tierFilter !== "ALL" && j.tier !== tierFilter) {
                        return null;
                      }
                      const isSelected =
                        selectedCountryIso === j.isoCode ||
                        hoveredMetric?.jurisdiction.isoCode === j.isoCode;

                      return (
                        <path
                          key={`voronoi-${j.isoCode}`}
                          d={pathD}
                          data-selected={isSelected ? "true" : "false"}
                          data-rapid-shift={
                            metric.isRapidStatusShift ? "true" : "false"
                          }
                          data-stagger-delay={metric.staggerDelayMs}
                          data-easing={metric.easingFunctionName}
                          fill={metric.heatColorHex}
                          fillOpacity={
                            isSelected
                              ? 0.68
                              : metric.isRapidStatusShift
                              ? 0.48
                              : 0.38
                          }
                          stroke={isSelected ? "#FFFFFF" : "#0B0F19"}
                          strokeWidth={isSelected ? 1.4 : 0.45}
                          style={{
                            animationDelay: `${metric.staggerDelayMs}ms`,
                            transitionDelay: `${Math.min(
                              320,
                              metric.staggerDelayMs
                            )}ms`,
                          }}
                          className={`d3-voronoi-heat-cell cursor-pointer ${
                            metric.isRapidStatusShift
                              ? "animate-d3-pulsate-steady-fast"
                              : "animate-d3-pulsate-steady-standard"
                          } ${
                            metric.isHighActivityTransition
                              ? "animate-d3-voronoi-breathe"
                              : ""
                          }`}
                          onMouseEnter={() => setHoveredMetric(metric)}
                          onMouseLeave={() => setHoveredMetric(null)}
                          onClick={(e) => {
                            e.stopPropagation();
                            onSelectCountry(
                              selectedCountryIso === j.isoCode
                                ? null
                                : j.isoCode
                            );
                          }}
                        />
                      );
                    })}
                  </g>
                )}

                {/* 5. Thermal Heat Contours / Radial Diffusion Halos */}
                {showThermalContours &&
                  velocityMetrics.map((metric) => {
                    const j = metric.jurisdiction;
                    if (!matchesRegulatoryBlocks(j)) {
                      return null;
                    }
                    if (
                      selectedContinent !== "ALL" &&
                      j.continent !== selectedContinent
                    ) {
                      return null;
                    }
                    if (tierFilter !== "ALL" && j.tier !== tierFilter) {
                      return null;
                    }
                    const haloRadius =
                      j.tier === "TIER_1"
                        ? 16
                        : j.tier === "TIER_2"
                        ? 12
                        : 8;
                    return (
                      <circle
                        key={`halo-${j.isoCode}`}
                        cx={metric.projectedX}
                        cy={metric.projectedY}
                        r={haloRadius}
                        fill={metric.heatColorHex}
                        fillOpacity={0.22}
                        filter="url(#d3-thermal-glow)"
                        className="d3-thermal-halo-circle pointer-events-none transition-all duration-500 ease-in-out [transition:fill_550ms_cubic-bezier(0.4,0,0.2,1),r_450ms_ease-in-out]"
                      />
                    );
                  })}

                {/* 6. Cross-Border T+0 Settlement Arcs from US Hub to High-Velocity Tier 1/2 Hubs */}
                {showSettlementArcs &&
                  usMetric &&
                  velocityMetrics
                    .filter(
                      (m) =>
                        matchesRegulatoryBlocks(m.jurisdiction) &&
                        (m.jurisdiction.tier === "TIER_1" ||
                          m.jurisdiction.tier === "TIER_2") &&
                        m.jurisdiction.isoCode !== "US"
                    )
                    .slice(0, 26)
                    .map((target) => {
                      const midX =
                        (usMetric.projectedX + target.projectedX) / 2;
                      const midY =
                        Math.min(usMetric.projectedY, target.projectedY) - 28;
                      return (
                        <path
                          key={`arc-${target.jurisdiction.isoCode}`}
                          d={`M ${usMetric.projectedX},${usMetric.projectedY} Q ${midX},${midY} ${target.projectedX},${target.projectedY}`}
                          fill="none"
                          stroke={target.heatColorHex}
                          strokeWidth={0.85}
                          strokeDasharray="3 3"
                          opacity={0.42}
                          className="pointer-events-none transition-all duration-500 ease-in-out [transition:stroke_550ms_cubic-bezier(0.4,0,0.2,1)]"
                        />
                      );
                    })}

                {/* 7. All 193 UN Member State Interactive Heat Pins */}
                {velocityMetrics.map((metric) => {
                  const j = metric.jurisdiction;
                  if (!matchesRegulatoryBlocks(j)) {
                    return null;
                  }
                  if (
                    selectedContinent !== "ALL" &&
                    j.continent !== selectedContinent
                  ) {
                    return null;
                  }
                  if (tierFilter !== "ALL" && j.tier !== tierFilter) {
                    return null;
                  }
                  const isActive =
                    selectedCountryIso === j.isoCode ||
                    hoveredMetric?.jurisdiction.isoCode === j.isoCode;
                  const pinRadius = isActive
                    ? 6.5
                    : j.tier === "TIER_1"
                    ? 4.4
                    : j.tier === "TIER_2"
                    ? 3.7
                    : 2.8;

                  return (
                    <g
                      key={`pin-${j.isoCode}`}
                      className="cursor-pointer"
                      onMouseEnter={() => setHoveredMetric(metric)}
                      onMouseLeave={() => setHoveredMetric(null)}
                      onClick={(e) => {
                        e.stopPropagation();
                        onSelectCountry(
                          selectedCountryIso === j.isoCode ? null : j.isoCode
                        );
                      }}
                    >
                      {metric.isHighActivityTransition && (
                        <circle
                          cx={metric.projectedX}
                          cy={metric.projectedY}
                          r={pinRadius + 3.2}
                          fill="none"
                          stroke={metric.heatColorHex}
                          strokeWidth={1.15}
                          strokeOpacity={0.65}
                          className="d3-breathing-transition-ring animate-d3-compliance-breathe pointer-events-none"
                        >
                          <animate
                            attributeName="r"
                            values={`${pinRadius + 1.5};${pinRadius + 5.8};${pinRadius + 1.5}`}
                            dur="2.8s"
                            repeatCount="indefinite"
                          />
                          <animate
                            attributeName="stroke-opacity"
                            values="0.72;0.16;0.72"
                            dur="2.8s"
                            repeatCount="indefinite"
                          />
                        </circle>
                      )}
                      {isActive && (
                        <circle
                          cx={metric.projectedX}
                          cy={metric.projectedY}
                          r={11}
                          fill="none"
                          stroke="#FFFFFF"
                          strokeWidth={1.5}
                          className="transition-all duration-300 ease-out"
                        />
                      )}
                      <circle
                        cx={metric.projectedX}
                        cy={metric.projectedY}
                        r={pinRadius}
                        data-pin-r={pinRadius}
                        fill={metric.heatColorHex}
                        stroke="#050811"
                        strokeWidth={1.1}
                        className="d3-state-pin-circle transition-all duration-500 ease-in-out [transition:fill_550ms_cubic-bezier(0.4,0,0.2,1),r_350ms_ease-out]"
                      />
                      {(isActive ||
                        ["US", "GB", "DE", "CH", "JP", "SG", "AE", "BR", "AU", "IN"].includes(
                          j.isoCode
                        )) && (
                        <text
                          x={metric.projectedX}
                          y={metric.projectedY - 7}
                          textAnchor="middle"
                          className={`text-[9px] font-mono font-bold pointer-events-none transition-all duration-300 ${
                            isActive ? "fill-white" : "fill-slate-200"
                          }`}
                        >
                          {j.isoCode} ({metric.activeScore})
                        </text>
                      )}
                    </g>
                  );
                })}
              </g>
            </svg>
          </div>

          {/* Bottom Map Status Bar */}
          <div className="px-4 py-2 border-t border-slate-800/80 bg-[#0A0E18] flex flex-wrap items-center justify-between gap-2 text-[11px] font-mono text-slate-400">
            <span>
              Click any country cell/pin to filter the 193-state matrix or drag/scroll to pan & zoom D3 viewport
            </span>
            <span className="text-emerald-400 font-bold">
              Active D3 Nodes Rendered: {velocityMetrics.length} / 193 UN States
            </span>
          </div>
        </div>

        {/* Right 4 Cols: Live Selected State Velocity Heat Inspector & Controls */}
        <div className="lg:col-span-4 rounded-xl border border-slate-800 bg-[#0F1422] p-4 flex flex-col justify-between space-y-4 font-mono">
          {inspectedMetric && (
            <>
              <div className="space-y-3">
                <div className="flex items-start justify-between gap-2 border-b border-slate-800 pb-3">
                  <div>
                    <div className="flex items-center gap-1.5 flex-wrap">
                      <span
                        className="px-2 py-0.5 rounded text-[10px] font-bold text-slate-950"
                        style={{
                          backgroundColor: inspectedMetric.heatColorHex,
                        }}
                      >
                        {activeMetricMode === "REGULATORY_RISK_INTENSITY"
                          ? `RISK INTENSITY: ${inspectedMetric.riskIntensityScore} / 100`
                          : `VELOCITY SCORE: ${inspectedMetric.velocityScore} / 100`}
                      </span>
                      <span className="px-2 py-0.5 rounded bg-slate-800 text-amber-300 text-[10px] font-bold">
                        ISO: {inspectedMetric.jurisdiction.isoCode} (#
                        {inspectedMetric.jurisdiction.isoNumericCode})
                      </span>
                    </div>
                    <h4 className="text-base font-bold text-white font-sans mt-1.5">
                      {inspectedMetric.jurisdiction.countryName}
                    </h4>
                    <div className="text-[11px] text-slate-400">
                      {inspectedMetric.jurisdiction.continent} ·{" "}
                      {inspectedMetric.jurisdiction.tierLabel}
                    </div>
                  </div>

                  <span
                    className={`px-2 py-1 rounded text-[10px] font-bold border shrink-0 ${
                      inspectedMetric.complianceBadge === "Fully Compliant"
                        ? "bg-emerald-950/90 border-emerald-600/60 text-emerald-300"
                        : inspectedMetric.complianceBadge === "Pending KYC"
                        ? "bg-amber-950/90 border-amber-600/60 text-amber-300"
                        : "bg-rose-950/90 border-rose-600/60 text-rose-300"
                    }`}
                  >
                    {inspectedMetric.complianceBadge}
                  </span>
                </div>

                {/* Heat Intensity Gauge Bar */}
                <div className="p-3 rounded-lg bg-[#090D16] border border-slate-800 space-y-2 text-xs">
                  <div className="flex items-center justify-between">
                    <span className="text-slate-400 text-[11px]">
                      {activeMetricMode === "REGULATORY_RISK_INTENSITY"
                        ? "Regulatory Risk Classification:"
                        : "Heat Intensity Classification:"}
                    </span>
                    <span
                      className="font-bold text-[11px]"
                      style={{ color: inspectedMetric.heatColorHex }}
                    >
                      {inspectedMetric.heatIntensityLabel}
                    </span>
                  </div>

                  <div className="w-full h-2.5 rounded-full bg-slate-900 overflow-hidden border border-slate-800">
                    <div
                      className="h-full transition-all duration-300"
                      style={{
                        width: `${inspectedMetric.activeScore}%`,
                        backgroundColor: inspectedMetric.heatColorHex,
                      }}
                    />
                  </div>

                  <div className="flex items-center justify-between text-[11px] pt-1">
                    <span className="text-slate-400">
                      Velocity: {inspectedMetric.velocityScore}/100 · Risk:{" "}
                      {inspectedMetric.riskIntensityScore}/100
                    </span>
                    <span className="text-sky-400 font-bold tabular-nums">
                      +{inspectedMetric.thirtyDayDeltaPct}% (30d)
                    </span>
                  </div>
                </div>

                {/* Interactive Node Activation Slider to Adjust State Heat Score Live */}
                <div className="p-3 rounded-lg bg-[#090D16] border border-slate-800 space-y-2 text-xs">
                  <div className="flex items-center justify-between">
                    <span className="text-[11px] text-slate-300 font-semibold">
                      Adjust State Node Activation (%):
                    </span>
                    <span className="text-amber-300 font-bold tabular-nums">
                      {inspectedMetric.activationPct}%
                    </span>
                  </div>
                  <input
                    type="range"
                    aria-label={`Adjust Node Activation for ${inspectedMetric.jurisdiction.countryName}`}
                    min={0}
                    max={100}
                    value={inspectedMetric.activationPct}
                    onChange={(e) =>
                      onUpdateNodeActivationPct(
                        inspectedMetric.jurisdiction.isoCode,
                        Number(e.target.value)
                      )
                    }
                    className="w-full accent-emerald-500 cursor-pointer"
                  />
                  <div className="text-[10px] text-slate-400">
                    Dragging updates both the D3 map heat color and the 193-UN-Member-State table snapshot in real time.
                  </div>
                </div>

                {/* Regulatory Authority & Required Docs */}
                <div className="p-3 rounded-lg bg-[#090D16] border border-slate-800 space-y-1.5 text-xs">
                  <div className="text-[10px] text-slate-400 uppercase">
                    Primary Regulator & Framework
                  </div>
                  <div className="text-amber-300 font-semibold">
                    {inspectedMetric.jurisdiction.primaryRegulator}
                  </div>
                  <div className="text-slate-300 text-[11px] leading-relaxed">
                    {inspectedMetric.jurisdiction.regulatoryFramework}
                  </div>
                  <div className="pt-1.5 flex flex-wrap gap-1">
                    {inspectedMetric.jurisdiction.requiredRegulatoryDocs
                      .slice(0, 3)
                      .map((doc) => (
                        <span
                          key={doc}
                          className="px-2 py-0.5 rounded bg-emerald-500/10 border border-emerald-500/30 text-emerald-300 text-[10px]"
                        >
                          ✓ {doc}
                        </span>
                      ))}
                  </div>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="grid grid-cols-2 gap-2 pt-2 border-t border-slate-800 text-xs">
                <button
                  type="button"
                  onClick={() =>
                    onUpdateNodeActivationPct(
                      inspectedMetric.jurisdiction.isoCode,
                      100
                    )
                  }
                  className="py-2 px-3 rounded-lg bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-bold flex items-center justify-center gap-1.5 cursor-pointer"
                >
                  <Zap className="w-3.5 h-3.5" />
                  <span>Max Velocity (100%)</span>
                </button>
                <button
                  type="button"
                  onClick={() =>
                    onExportJurisdictionSnapshot(inspectedMetric.jurisdiction)
                  }
                  className="py-2 px-3 rounded-lg bg-cyan-500/15 hover:bg-cyan-500/25 border border-cyan-500/40 text-cyan-300 font-bold flex items-center justify-center gap-1.5 cursor-pointer"
                >
                  <Download className="w-3.5 h-3.5" />
                  <span>Export Snapshot</span>
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};
export default D3GlobalComplianceVelocityMap;

