  orderId: string;
  ownerId: string;
  symbol: string;
  side: "BUY" | "SELL";
  price: number;
  quantity: number;
  timestamp: string;
}

interface ExecutedTrade {
  tradeId: string;
  buyOrderId: string;
  sellOrderId: string;
  symbol: string;
  price: number;
  quantity: number;
  timestamp: string;
}

interface AnalysisResult {
