        owner=OWNER_NAME,
        moving_average=round(avg_price, 4),
        signal=signal,
        timestamp=datetime.datetime.utcnow().isoformat()
    )

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)`;

