import React, { useState, useEffect, useCallback } from "react";
import {
  Globe,
  Terminal,
  CheckCircle2,
  RefreshCw,
  Copy,
  Check,
  Rocket,
  ShieldCheck,
  ExternalLink,
  Code2,
  Database,
  Play,
  X,
  Key,
  Layers,
} from "lucide-react";
import { ACTIVE_FIREBASE_CONFIG } from "../lib/firebase";

interface AgentSkillModule {
  id: string;
  name: string;
  status: string;
  description: string;
}

interface FirebaseWorkspaceStatus {
  cliVersion: string;
  projectId: string;
  hostingUrls: string[];
  consoleUrl: string;
  firestoreRules: {
    exists: boolean;
    lineCount: number;
  };
  distBundle: {
    ready: boolean;
    fileCount: number;
    totalBytes: number;
    lastBuiltAt: string | null;
  };
  agentSkills: {
    installed: boolean;
    repository: string;
    cliCommand: string;
    detectedPaths: string[];
    modules: AgentSkillModule[];
  };
}

type ConsoleTabId = "skills" | "hosting" | "deploy";
type AgentPlatformId = "other_npx" | "claude_code" | "antigravity" | "cursor" | "codex";

interface AgentPlatformGuide {
  id: AgentPlatformId;
  label: string;
  subtitle: string;
  installCommand: string;
  configPath: string;
  configSnippet: string;
}

const AGENT_PLATFORM_GUIDES: AgentPlatformGuide[] = [
  {
    id: "other_npx",
    label: "Universal Agent Skills (npx)",
    subtitle: "Standard command to install & update firebase/agent-skills across any agent workspace",
    installCommand: "npx skills add firebase/agent-skills",
    configPath: ".agents/skills/firebase-agent-skills/SKILL.md",
    configSnippet: `# Install or update official Firebase Agent Skills
npx skills add firebase/agent-skills

# Verify Firebase CLI & Project Alias
firebase --version
firebase use token-world-exchange-ats`,
  },
  {
    id: "antigravity",
    label: "Antigravity Agent",
    subtitle: "Firebase MCP & Agent Skills plugin configuration for Antigravity",
    installCommand: "npx skills add firebase/agent-skills && npx -y @firebase/mcp@latest",
    configPath: ".agents/skills/firebase-agent-skills/SKILL.md",
    configSnippet: `{
  "mcpServers": {
    "firebase": {
      "command": "npx",
      "args": ["-y", "firebase-tools@latest", "experimental:mcp", "--project", "token-world-exchange-ats"]
    }
  }
}`,
  },
  {
    id: "claude_code",
    label: "Claude Code",
    subtitle: "Install the official Firebase plugin & MCP server in Claude Code",
    installCommand: "claude mcp add firebase -- npx -y firebase-tools@latest experimental:mcp --project token-world-exchange-ats",
    configPath: ".claude/settings.json",
    configSnippet: `# 1. Add Firebase MCP plugin to Claude Code
claude mcp add firebase -- npx -y firebase-tools@latest experimental:mcp --project token-world-exchange-ats

# 2. Install Firebase Agent Skills into workspace
npx skills add firebase/agent-skills`,
  },
  {
    id: "cursor",
    label: "Cursor Agent",
    subtitle: "Configure Firebase plugin in Cursor MCP settings and rules directory",
    installCommand: "npx skills add firebase/agent-skills",
    configPath: ".cursor/mcp.json",
    configSnippet: `{
  "mcpServers": {
    "firebase": {
      "command": "npx",
      "args": ["-y", "firebase-tools@latest", "experimental:mcp", "--project", "token-world-exchange-ats"]
    }
  }
}`,
  },
  {
    id: "codex",
    label: "Codex Agent",
    subtitle: "Enable Firebase Agent Skills and CLI tooling for Codex",
    installCommand: "npx skills add firebase/agent-skills",
    configPath: "AGENTS.md",
    configSnippet: `# Firebase Agent Skills Mandate
Always use Firebase Agent Skills (.agents/skills/firebase-agent-skills) for Firebase Hosting, Firestore, and Security Rules tasks on project token-world-exchange-ats.
Deploy command: npm run firebase:deploy`,
  },
];

interface FirebaseHostingAndSkillsConsoleProps {
  isModal?: boolean;
  onClose?: () => void;
  initialTab?: ConsoleTabId;
}

export const FirebaseHostingAndSkillsConsole: React.FC<FirebaseHostingAndSkillsConsoleProps> = ({
  isModal = false,
  onClose,
  initialTab = "skills",
}) => {
  const [activeTab, setActiveTab] = useState<ConsoleTabId>(initialTab);
  const [selectedAgent, setSelectedAgent] = useState<AgentPlatformId>("other_npx");
  const [status, setStatus] = useState<FirebaseWorkspaceStatus | null>(null);
  const [isLoadingStatus, setIsLoadingStatus] = useState<boolean>(true);
  const [isSyncingSkills, setIsSyncingSkills] = useState<boolean>(false);
  const [isBuilding, setIsBuilding] = useState<boolean>(false);
  const [isDeploying, setIsDeploying] = useState<boolean>(false);
  const [deployTarget, setDeployTarget] = useState<"hosting,firestore:rules" | "hosting" | "firestore:rules">(
    "hosting,firestore:rules"
  );
  const [firebaseToken, setFirebaseToken] = useState<string>("");
  const [consoleOutput, setConsoleOutput] = useState<string>("");
  const [lastActionStatus, setLastActionStatus] = useState<"idle" | "success" | "auth_needed" | "error">("idle");
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const fetchWorkspaceStatus = useCallback(async () => {
    setIsLoadingStatus(true);
    try {
      const res = await fetch("/api/firebase/status");
      if (res.ok) {
        const data = await res.json();
        setStatus(data);
      }
    } catch {
      // ignore network error
    } finally {
      setIsLoadingStatus(false);
    }
  }, []);

  useEffect(() => {
    fetchWorkspaceStatus();
  }, [fetchWorkspaceStatus]);

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleSyncAgentSkills = async () => {
    setIsSyncingSkills(true);
    setConsoleOutput("Running: npx skills add firebase/agent-skills ...\n");
    try {
      const res = await fetch("/api/firebase/skills/sync", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
      });
      const data = await res.json();
      if (data) {
        setStatus(data);
        setLastActionStatus("success");
        setConsoleOutput(
          `[OK] Command: ${data.command}\n${data.output || "Firebase Agent Skills installed and updated."}`
        );
      }
    } catch (err: any) {
      setLastActionStatus("error");
      setConsoleOutput(`Error syncing skills: ${err?.message || String(err)}`);
    } finally {
      setIsSyncingSkills(false);
    }
  };

  const handleRunProductionBuild = async () => {
    setIsBuilding(true);
    setConsoleOutput("Running production Vite build (vite build -> dist/)...\n");
    try {
      const res = await fetch("/api/firebase/hosting/build", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
      });
      const data = await res.json();
      if (data) {
        setStatus(data);
        setLastActionStatus(data.success ? "success" : "error");
        setConsoleOutput(data.output || "Production bundle compiled into dist/");
      }
    } catch (err: any) {
      setLastActionStatus("error");
      setConsoleOutput(`Build error: ${err?.message || String(err)}`);
    } finally {
      setIsBuilding(false);
    }
  };

  const handleDeployToFirebase = async () => {
    setIsDeploying(true);
    setConsoleOutput(
      `Executing: firebase deploy --only ${deployTarget} --project ${ACTIVE_FIREBASE_CONFIG.projectId} ...\n`
    );
    try {
      const res = await fetch("/api/firebase/hosting/deploy", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          target: deployTarget,
          firebaseToken: firebaseToken.trim() || undefined,
        }),
      });
      const data = await res.json();
      if (data) {
        setStatus(data);
        if (data.success) {
          setLastActionStatus("success");
        } else if (data.needsInteractiveAuth) {
          setLastActionStatus("auth_needed");
        } else {
          setLastActionStatus("error");
        }
        setConsoleOutput(data.output || "Deployment command executed.");
      }
    } catch (err: any) {
      setLastActionStatus("error");
      setConsoleOutput(`Deployment error: ${err?.message || String(err)}`);
    } finally {
      setIsDeploying(false);
    }
  };

  const currentGuide =
    AGENT_PLATFORM_GUIDES.find((g) => g.id === selectedAgent) || AGENT_PLATFORM_GUIDES[0];

  const formatBytes = (bytes: number) => {
    if (!bytes || bytes <= 0) return "0 KB";
    const kb = bytes / 1024;
    if (kb < 1024) return `${kb.toFixed(1)} KB`;
    return `${(kb / 1024).toFixed(2)} MB`;
  };

  const content = (
    <div className="bg-slate-900 border border-slate-800 rounded-xl text-slate-100 overflow-hidden shadow-xl">
      {/* Header Bar */}
      <div className="px-6 py-4 border-b border-slate-800 flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-slate-950/70">
        <div>
          <div className="flex items-center gap-2 text-xs text-slate-400 font-mono tabular-nums">
            <span>Firebase Hosting &amp; Agent Skills</span>
            <span aria-hidden="true">·</span>
            <span className="text-emerald-400">Project: {ACTIVE_FIREBASE_CONFIG.projectId}</span>
            <span aria-hidden="true">·</span>
            <span>CLI v{status?.cliVersion || "15.34.2"}</span>
          </div>
          <h2 className="text-lg font-bold text-white mt-0.5 tracking-tight">
            Firebase Web App Hosting &amp; Agent Skills Console
          </h2>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <a
            href={`https://${ACTIVE_FIREBASE_CONFIG.projectId}.web.app`}
            target="_blank"
            rel="noopener noreferrer"
            className="px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 text-xs font-medium transition-colors flex items-center gap-1.5 whitespace-nowrap shrink-0"
          >
            <Globe className="w-3.5 h-3.5 text-cyan-400" />
            <span>{ACTIVE_FIREBASE_CONFIG.projectId}.web.app</span>
            <ExternalLink className="w-3 h-3 text-slate-400" />
          </a>
          {isModal && onClose && (
            <button
              type="button"
              onClick={onClose}
              className="p-2 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition-colors cursor-pointer"
              title="Close console"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="px-6 py-2.5 bg-slate-950/40 border-b border-slate-800 flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-1 p-1 bg-slate-950 border border-slate-800 rounded-lg">
          <button
            type="button"
            onClick={() => setActiveTab("skills")}
            className={`px-3.5 py-1.5 rounded-md text-xs font-semibold transition-colors whitespace-nowrap shrink-0 cursor-pointer ${
              activeTab === "skills"
                ? "bg-emerald-600 text-white"
                : "text-slate-400 hover:text-slate-200"
            }`}
          >
            01. Firebase Agent Skills &amp; Plugins
          </button>
          <button
            type="button"
            onClick={() => setActiveTab("hosting")}
            className={`px-3.5 py-1.5 rounded-md text-xs font-semibold transition-colors whitespace-nowrap shrink-0 cursor-pointer ${
              activeTab === "hosting"
                ? "bg-emerald-600 text-white"
                : "text-slate-400 hover:text-slate-200"
            }`}
          >
            02. Hosting Setup &amp; Build Verification
          </button>
          <button
            type="button"
            onClick={() => setActiveTab("deploy")}
            className={`px-3.5 py-1.5 rounded-md text-xs font-semibold transition-colors whitespace-nowrap shrink-0 cursor-pointer ${
              activeTab === "deploy"
                ? "bg-emerald-600 text-white"
                : "text-slate-400 hover:text-slate-200"
            }`}
          >
            03. Deploy Web App &amp; CI/CD
          </button>
        </div>

        <div className="flex items-center gap-3 text-xs text-slate-400 font-mono tabular-nums">
          <span>
            Skills: <strong className="text-emerald-400">Installed</strong>
          </span>
          <span aria-hidden="true">·</span>
          <span>
            Bundle:{" "}
            <strong className={status?.distBundle?.ready ? "text-emerald-400" : "text-amber-400"}>
              {status?.distBundle?.ready
                ? `Ready (${status.distBundle.fileCount} files · ${formatBytes(status.distBundle.totalBytes)})`
                : "Pending Build"}
            </strong>
          </span>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="p-6 space-y-6">
        {/* TAB 1: FIREBASE AGENT SKILLS & IDE PLUGINS */}
        {activeTab === "skills" && (
          <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-slate-800">
              <div>
                <h3 className="text-base font-semibold text-white">
                  Official Firebase Agent Skills (firebase/agent-skills)
                </h3>
                <p className="text-xs text-slate-400 mt-1">
                  Equips Claude Code, Antigravity, Codex, Cursor, and CLI coding agents with domain-verified Firebase Hosting, Firestore, Auth, and Security Rules workflows.
                </p>
              </div>
              <button
                type="button"
                onClick={handleSyncAgentSkills}
                disabled={isSyncingSkills}
                className="px-4 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold transition-colors flex items-center gap-2 whitespace-nowrap shrink-0 cursor-pointer disabled:opacity-50"
              >
                <RefreshCw className={`w-3.5 h-3.5 ${isSyncingSkills ? "animate-spin" : ""}`} />
                <span>
                  {isSyncingSkills ? "Updating Agent Skills..." : "Run npx skills add firebase/agent-skills"}
                </span>
              </button>
            </div>

            {/* Agent Selector Bar */}
            <div className="space-y-3">
              <div className="text-xs font-medium text-slate-300">
                Select Your Coding Agent Environment:
              </div>
              <div className="flex flex-wrap gap-1.5 p-1 bg-slate-950 border border-slate-800 rounded-lg">
                {AGENT_PLATFORM_GUIDES.map((guide) => (
                  <button
                    key={guide.id}
                    type="button"
                    onClick={() => setSelectedAgent(guide.id)}
                    className={`px-3 py-1.5 rounded-md text-xs font-medium transition-colors whitespace-nowrap shrink-0 cursor-pointer ${
                      selectedAgent === guide.id
                        ? "bg-slate-800 text-white border border-slate-700"
                        : "text-slate-400 hover:text-slate-200"
                    }`}
                  >
                    {guide.label}
                  </button>
                ))}
              </div>

              {/* Selected Agent Plugin / Skill Instructions */}
              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-4">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                  <div>
                    <div className="text-sm font-semibold text-white">{currentGuide.label}</div>
                    <div className="text-xs text-slate-400">{currentGuide.subtitle}</div>
                  </div>
                  <div className="text-xs font-mono text-slate-400">
                    Config: <span className="text-cyan-300">{currentGuide.configPath}</span>
                  </div>
                </div>

                <div className="space-y-1.5">
                  <div className="flex items-center justify-between text-xs text-slate-400">
                    <span>Installation / Plugin Command</span>
                    <button
                      type="button"
                      onClick={() => handleCopy(currentGuide.installCommand, `cmd_${currentGuide.id}`)}
                      className="text-emerald-400 hover:text-emerald-300 flex items-center gap-1 cursor-pointer whitespace-nowrap shrink-0"
                    >
                      {copiedId === `cmd_${currentGuide.id}` ? (
                        <Check className="w-3.5 h-3.5" />
                      ) : (
                        <Copy className="w-3.5 h-3.5" />
                      )}
                      <span>{copiedId === `cmd_${currentGuide.id}` ? "Copied" : "Copy Command"}</span>
                    </button>
                  </div>
                  <pre className="p-3 rounded-lg bg-slate-900 border border-slate-800 text-xs font-mono text-emerald-300 overflow-x-auto">
                    {currentGuide.installCommand}
                  </pre>
                </div>

                <div className="space-y-1.5">
                  <div className="flex items-center justify-between text-xs text-slate-400">
                    <span>Workspace Plugin / Skill Manifest ({currentGuide.configPath})</span>
                    <button
                      type="button"
                      onClick={() => handleCopy(currentGuide.configSnippet, `cfg_${currentGuide.id}`)}
                      className="text-cyan-400 hover:text-cyan-300 flex items-center gap-1 cursor-pointer whitespace-nowrap shrink-0"
                    >
                      {copiedId === `cfg_${currentGuide.id}` ? (
                        <Check className="w-3.5 h-3.5" />
                      ) : (
                        <Copy className="w-3.5 h-3.5" />
                      )}
                      <span>{copiedId === `cfg_${currentGuide.id}` ? "Copied" : "Copy Snippet"}</span>
                    </button>
                  </div>
                  <pre className="p-3 rounded-lg bg-slate-900 border border-slate-800 text-xs font-mono text-slate-300 overflow-x-auto">
                    {currentGuide.configSnippet}
                  </pre>
                </div>
              </div>
            </div>

            {/* Installed Skill Modules Table */}
            <div className="space-y-2">
              <div className="text-xs font-semibold text-slate-300">
                Active Firebase Agent Skill Modules in Workspace
              </div>
              <div className="border border-slate-800 rounded-xl overflow-hidden divide-y divide-slate-800 bg-slate-950">
                {(status?.agentSkills?.modules || []).map((mod) => (
                  <div
                    key={mod.id}
                    className="px-4 py-3 flex flex-col sm:flex-row sm:items-center justify-between gap-2 hover:bg-slate-900/50 transition-colors"
                  >
                    <div>
                      <div className="text-xs font-semibold text-white flex items-center gap-2">
                        <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
                        <span>{mod.name}</span>
                        <span className="text-slate-500 font-mono">({mod.id})</span>
                      </div>
                      <div className="text-xs text-slate-400 mt-0.5 pl-5">{mod.description}</div>
                    </div>
                    <span className="text-xs font-mono text-emerald-400 pl-5 sm:pl-0 whitespace-nowrap shrink-0">
                      Installed &amp; Active
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* TAB 2: HOSTING SETUP & BUILD VERIFICATION */}
        {activeTab === "hosting" && (
          <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-slate-800">
              <div>
                <h3 className="text-base font-semibold text-white">
                  Firebase Hosting Configuration (firebase.json &amp; .firebaserc)
                </h3>
                <p className="text-xs text-slate-400 mt-1">
                  Configured for SPA delivery from <code className="text-cyan-300">dist/</code> with immutable asset caching, security headers, and project alias <code className="text-emerald-300">token-world-exchange-ats</code>.
                </p>
              </div>
              <button
                type="button"
                onClick={handleRunProductionBuild}
                disabled={isBuilding}
                className="px-4 py-2 rounded-lg bg-cyan-600 hover:bg-cyan-500 text-white text-xs font-semibold transition-colors flex items-center gap-2 whitespace-nowrap shrink-0 cursor-pointer disabled:opacity-50"
              >
                <Play className={`w-3.5 h-3.5 ${isBuilding ? "animate-spin" : ""}`} />
                <span>
                  {isBuilding ? "Building Production Bundle..." : "Build Production Bundle (vite build)"}
                </span>
              </button>
            </div>

            {/* Key Configuration Summary Grid */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800">
                <div className="text-xs text-slate-400">Firebase Project ID</div>
                <div className="text-sm font-bold font-mono text-white mt-1 tabular-nums">
                  {ACTIVE_FIREBASE_CONFIG.projectId}
                </div>
                <div className="text-[11px] text-emerald-400 mt-1">Bound in .firebaserc</div>
              </div>

              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800">
                <div className="text-xs text-slate-400">Hosting Public Directory</div>
                <div className="text-sm font-bold font-mono text-white mt-1 tabular-nums">
                  dist/ (SPA Rewrite)
                </div>
                <div className="text-[11px] text-cyan-400 mt-1">
                  {status?.distBundle?.ready
                    ? `${status.distBundle.fileCount} files (${formatBytes(status.distBundle.totalBytes)})`
                    : "Run build to populate"}
                </div>
              </div>

              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800">
                <div className="text-xs text-slate-400">Firestore Security Rules</div>
                <div className="text-sm font-bold font-mono text-white mt-1 tabular-nums">
                  firestore.rules
                </div>
                <div className="text-[11px] text-emerald-400 mt-1 tabular-nums">
                  {status?.firestoreRules?.exists
                    ? `Verified (${status.firestoreRules.lineCount} lines)`
                    : "Configured"}
                </div>
              </div>

              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800">
                <div className="text-xs text-slate-400">GitHub Secret Protection</div>
                <div className="text-sm font-bold font-mono text-emerald-400 mt-1">
                  API Key Hidden
                </div>
                <div className="text-[11px] text-slate-400 mt-1">
                  Excluded via .gitignore &amp; Env
                </div>
              </div>
            </div>

            {/* Inspect firebase.json and .firebaserc */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-2">
                <div className="flex items-center justify-between text-xs">
                  <span className="font-semibold text-white flex items-center gap-1.5">
                    <Code2 className="w-3.5 h-3.5 text-cyan-400" />
                    <span>firebase.json</span>
                  </span>
                  <button
                    type="button"
                    onClick={() =>
                      handleCopy(JSON.stringify(status?.firebaseJson || {}, null, 2), "firebase_json")
                    }
                    className="text-cyan-400 hover:text-cyan-300 flex items-center gap-1 cursor-pointer"
                  >
                    {copiedId === "firebase_json" ? <Check className="w-3.5 h-3.5" /> : <Copy className="w-3.5 h-3.5" />}
                    <span>Copy</span>
                  </button>
                </div>
                <pre className="p-3 rounded-lg bg-slate-900 border border-slate-800 text-[11px] font-mono text-slate-300 overflow-x-auto max-h-56">
                  {JSON.stringify(
                    status?.firebaseJson || {
                      hosting: {
                        public: "dist",
                        cleanUrls: true,
                        rewrites: [{ source: "**", destination: "/index.html" }],
                      },
                      firestore: { rules: "firestore.rules" },
                    },
                    null,
                    2
                  )}
                </pre>
              </div>

              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-2">
                <div className="flex items-center justify-between text-xs">
                  <span className="font-semibold text-white flex items-center gap-1.5">
                    <Layers className="w-3.5 h-3.5 text-emerald-400" />
                    <span>.firebaserc &amp; Package Scripts</span>
                  </span>
                  <button
                    type="button"
                    onClick={() =>
                      handleCopy("npm run firebase:deploy", "pkg_deploy")
                    }
                    className="text-emerald-400 hover:text-emerald-300 flex items-center gap-1 cursor-pointer"
                  >
                    {copiedId === "pkg_deploy" ? <Check className="w-3.5 h-3.5" /> : <Copy className="w-3.5 h-3.5" />}
                    <span>Copy Script</span>
                  </button>
                </div>
                <pre className="p-3 rounded-lg bg-slate-900 border border-slate-800 text-[11px] font-mono text-slate-300 overflow-x-auto max-h-56">
{`// .firebaserc
{
  "projects": {
    "default": "token-world-exchange-ats",
    "production": "token-world-exchange-ats"
  }
}

// npm scripts configured in package.json:
npm run firebase:skills          # npx skills add firebase/agent-skills
npm run firebase:build           # vite build -> dist/
npm run firebase:deploy          # vite build && firebase deploy
npm run firebase:deploy:hosting  # vite build && firebase deploy --only hosting`}
                </pre>
              </div>
            </div>
          </div>
        )}

        {/* TAB 3: DEPLOY WEB APP & CI/CD */}
        {activeTab === "deploy" && (
          <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-slate-800">
              <div>
                <h3 className="text-base font-semibold text-white">
                  Deploy Web App to Firebase Hosting ({ACTIVE_FIREBASE_CONFIG.projectId})
                </h3>
                <p className="text-xs text-slate-400 mt-1">
                  Execute a live deployment to <code className="text-emerald-300">https://{ACTIVE_FIREBASE_CONFIG.projectId}.web.app</code> or use the pre-configured CLI &amp; GitHub Actions workflows.
                </p>
              </div>

              <div className="flex items-center gap-2">
                <select
                  value={deployTarget}
                  onChange={(e) => setDeployTarget(e.target.value as any)}
                  className="bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-xs text-white font-mono focus:outline-none"
                >
                  <option value="hosting,firestore:rules">Target: Hosting + Firestore Rules</option>
                  <option value="hosting">Target: Hosting Only (dist/)</option>
                  <option value="firestore:rules">Target: Firestore Rules Only</option>
                </select>

                <button
                  type="button"
                  onClick={handleDeployToFirebase}
                  disabled={isDeploying}
                  className="px-4 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold transition-colors flex items-center gap-2 whitespace-nowrap shrink-0 cursor-pointer disabled:opacity-50"
                >
                  <Rocket className={`w-3.5 h-3.5 ${isDeploying ? "animate-bounce" : ""}`} />
                  <span>{isDeploying ? "Deploying to Firebase..." : "Deploy Now"}</span>
                </button>
              </div>
            </div>

            {/* Optional CI Token Input for Non-Interactive Container Deploy */}
            <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-3">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                <div className="flex items-center gap-2 text-xs font-semibold text-white">
                  <Key className="w-3.5 h-3.5 text-amber-400" />
                  <span>Optional: Firebase CI Token (for Headless Container Deployment)</span>
                </div>
                <span className="text-[11px] text-slate-400 font-mono">
                  Generate locally via: firebase login:ci
                </span>
              </div>
              <div className="flex flex-col sm:flex-row gap-2">
                <input
                  type="password"
                  value={firebaseToken}
                  onChange={(e) => setFirebaseToken(e.target.value)}
                  placeholder="Paste FIREBASE_TOKEN (1//0g...) to authenticate non-interactive deploy from this container"
                  className="flex-1 bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-xs text-white font-mono focus:outline-none focus:border-emerald-500"
                />
                <button
                  type="button"
                  onClick={() =>
                    handleCopy(
                      `npm run build && firebase deploy --only ${deployTarget} --project ${ACTIVE_FIREBASE_CONFIG.projectId}`,
                      "cli_deploy_cmd"
                    )
                  }
                  className="px-3.5 py-2 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-medium flex items-center gap-1.5 whitespace-nowrap shrink-0 cursor-pointer"
                >
                  {copiedId === "cli_deploy_cmd" ? (
                    <Check className="w-3.5 h-3.5 text-emerald-400" />
                  ) : (
                    <Copy className="w-3.5 h-3.5" />
                  )}
                  <span>Copy CLI Deploy Command</span>
                </button>
              </div>
            </div>

            {/* Terminal & CI/CD Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-2">
                <div className="text-xs font-semibold text-white">
                  Direct Terminal Deployment Workflow
                </div>
                <pre className="p-3 rounded-lg bg-slate-900 border border-slate-800 text-[11px] font-mono text-emerald-300 overflow-x-auto">
{`# 1. Ensure Firebase Agent Skills are up to date
npx skills add firebase/agent-skills

# 2. Authenticate with your Google account (if running locally)
firebase login

# 3. Build production bundle & deploy to token-world-exchange-ats
npm run firebase:deploy`}
                </pre>
              </div>

              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-2">
                <div className="flex items-center justify-between text-xs">
                  <span className="font-semibold text-white">
                    Automated GitHub Actions (.github/workflows/firebase-hosting.yml)
                  </span>
                  <span className="text-emerald-400 font-mono">Configured</span>
                </div>
                <p className="text-xs text-slate-400 leading-relaxed">
                  Automatically runs <code className="text-slate-200">npx skills add firebase/agent-skills</code>, injects <code className="text-slate-200">VITE_FIREBASE_API_KEY</code> from GitHub Actions Secrets, builds <code className="text-slate-200">dist/</code>, and deploys to Firebase Hosting on every push to <code className="text-slate-200">main</code>.
                </p>
                <div className="pt-1 flex items-center gap-3 text-xs font-mono">
                  <a
                    href={`https://console.firebase.google.com/project/${ACTIVE_FIREBASE_CONFIG.projectId}/hosting/sites`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-cyan-400 hover:text-cyan-300 flex items-center gap-1"
                  >
                    <span>Open Firebase Hosting Console</span>
                    <ExternalLink className="w-3 h-3" />
                  </a>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Live Execution Output Log */}
        {consoleOutput && (
          <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-2">
            <div className="flex items-center justify-between text-xs">
              <span className="font-semibold text-slate-300 flex items-center gap-1.5">
                <Terminal className="w-3.5 h-3.5 text-emerald-400" />
                <span>Execution Output</span>
              </span>
              {lastActionStatus === "auth_needed" && (
                <span className="text-amber-400 font-mono">
                  Provide FIREBASE_TOKEN above or run `firebase login` in local terminal
                </span>
              )}
              {lastActionStatus === "success" && (
                <span className="text-emerald-400 font-mono">Completed Successfully</span>
              )}
            </div>
            <pre className="p-3 rounded-lg bg-slate-900 border border-slate-800 text-[11px] font-mono text-slate-300 overflow-x-auto max-h-52 whitespace-pre-wrap">
              {consoleOutput}
            </pre>
          </div>
        )}
      </div>
    </div>
  );

  if (isModal) {
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 backdrop-blur-sm p-4 overflow-y-auto">
        <div className="w-full max-w-5xl my-8">{content}</div>
      </div>
    );
  }

  return content;
};

