                    <div className="text-amber-200 break-all mt-1 text-[11px]">
                      {activeEnvelope.hmacSha512SignatureHex}
                    </div>
                    <div className="text-cyan-400 break-all mt-1 text-[10px]">
                      {activeEnvelope.mlDsa87LatticeAttestation}
                    </div>
                  </div>

                  <div className="p-2.5 rounded bg-[#070B12] border border-slate-800">
                    <div className="text-[10px] text-emerald-400 font-semibold">
                      ✓ In-Enclave AES-256-GCM Decryption Roundtrip Verification
                    </div>
                    <pre className="text-slate-200 text-[11px] mt-1 overflow-x-auto max-h-32">
                      {activeEnvelope.decryptedVerificationRoundtrip}
                    </pre>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* =====================================================================
          TAB 3: ON-CHAIN TWEGesNsaSacredSecurityEnclave.sol CONTRACT
         ===================================================================== */}
      {activeTab === "solidity_enclave_contract" && (
        <div className="p-6 space-y-4">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
            <div>
              <h3 className="text-sm font-bold text-white font-mono">
                contracts/TWEGesNsaSacredSecurityEnclave.sol (Solidity 0.8.26)
              </h3>
              <p className="text-xs text-slate-400">
                On-chain CNSA 2.0 pre-settlement attestation contract binding SHA-384 integrity digests, ML-KEM-1024 shared secrets, and ML-DSA-87 lattice signatures to Token World Exchange ATS® atomic T+0 DvP settlement.
              </p>
            </div>
            <button
              type="button"
              onClick={() => {
                navigator.clipboard.writeText(TWE_GES_NSA_SACRED_GUARD_SOLIDITY);
                notify(
                  "Copied TWEGesNsaSacredSecurityEnclave.sol Solidity 0.8.26 source code to clipboard."
                );
              }}
              className="px-3.5 py-1.5 rounded-lg bg-emerald-500 text-slate-950 font-mono text-xs font-bold cursor-pointer shrink-0"
            >
              Copy Solidity 0.8.26 Contract
            </button>
          </div>

          <pre className="p-4 rounded-lg bg-[#060911] border border-slate-800 text-xs font-mono text-emerald-300 overflow-x-auto leading-relaxed max-h-[520px]">
            {TWE_GES_NSA_SACRED_GUARD_SOLIDITY}
          </pre>
        </div>
      )}
    </section>
  );
};

