            </a>
            <span className="px-3 py-1.5 rounded-lg bg-rose-950/40 border border-rose-500/40 text-rose-300 text-xs font-mono font-bold">
              ENABLE_LIVE_TRADING=false
            </span>
          </div>
        </div>

        {/* Legal & Regulatory Gate Disclosure Banner */}
