import React, { useState, useMemo } from "react";
import {
  UnMemberJurisdiction,
  WorldContinentId,
  GlobalRegulatoryTier,
} from "../utils/tweGlobal193RolloutData";

export interface InteractiveWorldMap193SelectorProps {
  jurisdictions: UnMemberJurisdiction[];
  selectedContinent: "ALL" | WorldContinentId;
  selectedCountryIso: string | null;
  tierFilter: "ALL" | GlobalRegulatoryTier;
  onSelectContinent: (continent: "ALL" | WorldContinentId) => void;
  onSelectCountry: (isoCode: string | null) => void;
  onToggleNodeStatus: (isoCode: string) => void;
  onExecutePromptForCountry: (country: UnMemberJurisdiction) => void;
  onLoadCountryIntoBitmaskEncoder?: (country: UnMemberJurisdiction) => void;
}

interface ContinentSvgPath {
  id: WorldContinentId;
  label: string;
  labelX: number;
  labelY: number;
  path: string;
  summaryFramework: string;
}

const CONTINENT_POLYGONS: ContinentSvgPath[] = [
  {
    id: "North America",
    label: "North America",
    labelX: 205,
    labelY: 155,
    path: "M 95,65 L 245,55 L 315,95 L 290,165 L 255,215 L 235,242 L 195,235 L 155,190 L 115,135 Z",
    summaryFramework: "U.S. SEC Reg ATS (Form ATS-N) · FINRA Rule 4554 · Canada CSA NI 21-101 · CNBV",
  },
  {
    id: "South America",
    label: "South America",
    labelX: 315,
    labelY: 325,
    path: "M 252,245 L 330,255 L 378,305 L 355,385 L 312,442 L 282,425 L 268,340 L 248,280 Z",
    summaryFramework: "Brazil CVM & DREX CBDC · Argentina CNV · Chile CMF Fintech Law · Colombia SFC",
  },
  {
    id: "Europe",
    label: "Europe",
    labelX: 512,
    labelY: 118,
    path: "M 430,72 L 565,65 L 595,115 L 575,168 L 515,174 L 455,168 L 442,125 Z",
    summaryFramework: "EU ESMA MiCA & DLT Pilot Regime (27 States) · UK FCA DSS · Swiss FINMA DLT Act",
  },
  {
    id: "Middle East & Africa",
    label: "Middle East & Africa",
    labelX: 545,
    labelY: 268,
    path: "M 448,178 L 578,175 L 655,195 L 660,242 L 625,310 L 585,392 L 525,395 L 492,315 L 445,255 Z",
    summaryFramework: "UAE ADGM/VARA · Saudi CMA · QFCRA · South Africa FSCA · Nigeria SEC · FATF Ring",
  },
  {
    id: "Asia",
    label: "Asia",
    labelX: 745,
    labelY: 185,
    path: "M 598,75 L 875,82 L 895,185 L 845,278 L 745,288 L 668,242 L 605,172 Z",
    summaryFramework: "Japan FSA FIEA · Singapore MAS SFA · HK SFC VATP · Korea FSC · India SEBI/IFSCA",
  },
  {
    id: "Oceania",
    label: "Oceania",
    labelX: 855,
    labelY: 358,
    path: "M 775,295 L 935,298 L 945,412 L 805,415 L 768,355 Z",
    summaryFramework: "Australia ASIC Digital Asset Facility & eAUD · New Zealand FMA · Pacific FATF Ring",
  },
];

export const InteractiveWorldMap193Selector: React.FC<
  InteractiveWorldMap193SelectorProps
> = ({
  jurisdictions,
  selectedContinent,
  selectedCountryIso,
  tierFilter,
  onSelectContinent,
  onSelectCountry,
  onToggleNodeStatus,
  onExecutePromptForCountry,
  onLoadCountryIntoBitmaskEncoder,
}) => {
  const [hoveredCountry, setHoveredCountry] =
    useState<UnMemberJurisdiction | null>(null);
  const [hoveredContinent, setHoveredContinent] =
    useState<WorldContinentId | null>(null);

  const continentCounts = useMemo(() => {
    const counts: Record<WorldContinentId, number> = {
      "North America": 0,
      "South America": 0,
      Europe: 0,
      "Middle East & Africa": 0,
      Asia: 0,
      Oceania: 0,
    };
    for (const j of jurisdictions) {
      counts[j.continent] = (counts[j.continent] || 0) + 1;
    }
    return counts;
  }, [jurisdictions]);

  const selectedCountryRecord = useMemo(() => {
    if (!selectedCountryIso) return null;
    return jurisdictions.find((j) => j.isoCode === selectedCountryIso) || null;
  }, [jurisdictions, selectedCountryIso]);

  const inspectedCountry = hoveredCountry || selectedCountryRecord;

  const continentSummary = useMemo(() => {
    const scope =
      selectedContinent === "ALL"
        ? jurisdictions
        : jurisdictions.filter((j) => j.continent === selectedContinent);
    const t1 = scope.filter((j) => j.tier === "TIER_1").length;
    const t2 = scope.filter((j) => j.tier === "TIER_2").length;
    const t3 = scope.filter((j) => j.tier === "TIER_3").length;
    const active = scope.filter((j) => j.nodeStatus === "ACTIVE_VALIDATOR").length;
    const meta = CONTINENT_POLYGONS.find((c) => c.id === selectedContinent);
    return {
      total: scope.length,
      t1,
      t2,
      t3,
      active,
      frameworkText:
        meta?.summaryFramework ||
        "Global Multi-Jurisdictional Matrix (SEC/FINRA, ESMA/MiCA, FCA, MAS, FSA, FINMA, VARA, SFC & FATF ZK-Proofs)",
    };
  }, [jurisdictions, selectedContinent]);

  // US Hub coordinates (Los Angeles / NYC primary ATS matching engine)
  const usHubX = 215;
  const usHubY = 165;

  return (
    <div className="rounded-lg border border-slate-800 bg-[#0D121D] p-5 space-y-4">
      {/* Header & Continent Filter Pills */}
      <div className="flex flex-col xl:flex-row xl:items-center xl:justify-between gap-3 border-b border-slate-800 pb-3.5">
        <div>
          <div className="text-xs font-mono text-amber-400">
            Interactive Geospatial Compliance & Node Selector (193 UN Member States)
          </div>
          <h3 className="text-base font-bold text-white mt-0.5">
            Click Any Continent or Individual Country Node to Filter Regulatory Requirements
          </h3>
        </div>

        {/* Continent Selector Buttons */}
        <div className="flex flex-wrap items-center gap-1.5">
          <button
            type="button"
            onClick={() => {
              onSelectContinent("ALL");
              onSelectCountry(null);
            }}
            className={`px-3 py-1.5 rounded-lg text-xs font-mono transition cursor-pointer whitespace-nowrap shrink-0 ${
              selectedContinent === "ALL" && !selectedCountryIso
                ? "bg-amber-500 text-slate-950 font-semibold"
                : "bg-[#111622] text-slate-300 hover:text-white border border-slate-800"
            }`}
          >
            All Continents (193)
          </button>

          {CONTINENT_POLYGONS.map((cont) => {
            const isSelected = selectedContinent === cont.id;
            return (
              <button
                key={cont.id}
                type="button"
                onClick={() => {
                  onSelectContinent(isSelected ? "ALL" : cont.id);
                  onSelectCountry(null);
                }}
                className={`px-2.5 py-1.5 rounded-lg text-xs font-mono transition cursor-pointer whitespace-nowrap shrink-0 ${
                  isSelected
                    ? "bg-cyan-500 text-slate-950 font-semibold"
                    : "bg-[#111622] text-slate-300 hover:text-white border border-slate-800"
                }`}
              >
                {cont.label} ({continentCounts[cont.id]})
              </button>
            );
          })}
        </div>
      </div>

      {/* Main Split View: Interactive SVG World Map (8 Cols) + Live Jurisdiction Requirements Inspector (4 Cols) */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-stretch">
        {/* Left 8 Columns: Interactive SVG World Map Canvas */}
        <div className="lg:col-span-8 rounded-lg border border-slate-800 bg-[#070A11] relative overflow-hidden flex flex-col justify-between">
          {/* Top Map Legend Overlay */}
          <div className="px-4 py-2.5 border-b border-slate-800/80 bg-[#0A0E18] flex flex-wrap items-center justify-between gap-2 text-[11px] font-mono">
            <div className="flex flex-wrap items-center gap-4">
              <span className="text-amber-400">
                ● Tier 1 Major Hub (SEC/MiCA/FCA/MAS/FSA/FINMA)
              </span>
              <span className="text-cyan-400">
                ● Tier 2 Digital Hub (VARA/SFC/CVM/ASIC)
              </span>
              <span className="text-emerald-400">
                ● Tier 3 Global Ring (FATF + ZK-ID)
              </span>
              <span className="text-rose-400">● Geo-Fenced</span>
            </div>

            {(selectedContinent !== "ALL" || selectedCountryIso) && (
              <button
                type="button"
                onClick={() => {
                  onSelectContinent("ALL");
                  onSelectCountry(null);
                }}
                className="text-amber-300 hover:text-white underline cursor-pointer"
              >
                Reset Map Filter
              </button>
            )}
          </div>

          {/* SVG World Map Viewport */}
          <div className="w-full overflow-x-auto">
            <svg
              viewBox="0 0 1000 460"
              className="w-full h-auto min-w-[640px] select-none"
              role="img"
              aria-label="Interactive World Map of 193 UN Member States"
            >
              {/* Subtle Latitude / Longitude Graticule Grid */}
              {[90, 160, 230, 300, 370].map((y) => (
                <line
                  key={`lat-${y}`}
                  x1={40}
                  y1={y}
                  x2={960}
                  y2={y}
                  stroke="#1E293B"
                  strokeWidth={0.75}
                  strokeDasharray="3 3"
                />
              ))}
              {[180, 340, 500, 660, 820].map((x) => (
                <line
                  key={`lon-${x}`}
                  x1={x}
                  y1={30}
                  x2={x}
                  y2={430}
                  stroke="#1E293B"
                  strokeWidth={0.75}
                  strokeDasharray="3 3"
                />
              ))}

              {/* Clickable Continent Polygons */}
              {CONTINENT_POLYGONS.map((cont) => {
                const isActive = selectedContinent === cont.id;
                const isHovered = hoveredContinent === cont.id;
                return (
                  <g
                    key={cont.id}
                    onClick={() => {
                      onSelectContinent(isActive ? "ALL" : cont.id);
                      onSelectCountry(null);
                    }}
                    onMouseEnter={() => setHoveredContinent(cont.id)}
                    onMouseLeave={() => setHoveredContinent(null)}
                    className="cursor-pointer transition-opacity"
                  >
                    <path
                      d={cont.path}
                      fill={
                        isActive
                          ? "rgba(14, 165, 233, 0.22)"
                          : isHovered
                          ? "rgba(245, 158, 11, 0.14)"
                          : "rgba(30, 41, 59, 0.45)"
                      }
                      stroke={
                        isActive
                          ? "#38BDF8"
                          : isHovered
                          ? "#F59E0B"
                          : "#334155"
                      }
                      strokeWidth={isActive ? 2 : 1.2}
                    />
                    <text
                      x={cont.labelX}
                      y={cont.labelY}
                      textAnchor="middle"
                      fill={isActive ? "#38BDF8" : "#64748B"}
                      fontSize={10}
                      fontFamily="monospace"
                      fontWeight="bold"
                      className="pointer-events-none"
                    >
                      {cont.label.toUpperCase()}
                    </text>
                  </g>
                );
              })}

              {/* Settlement Routing Vector from US Primary ATS Hub to Selected Country */}
              {inspectedCountry && inspectedCountry.isoCode !== "US" && (
                <g className="pointer-events-none">
                  <path
                    d={`M ${usHubX},${usHubY} Q ${
                      (usHubX + inspectedCountry.mapX) / 2
                    },${Math.min(usHubY, inspectedCountry.mapY) - 45} ${
                      inspectedCountry.mapX
                    },${inspectedCountry.mapY}`}
                    fill="none"
                    stroke="#F59E0B"
                    strokeWidth={1.5}
                    strokeDasharray="4 4"
                  />
                </g>
              )}

              {/* All 193 UN Member State Interactive Nodes */}
              {jurisdictions.map((country) => {
                const matchesContinent =
                  selectedContinent === "ALL" ||
                  country.continent === selectedContinent;
                const matchesTier =
                  tierFilter === "ALL" || country.tier === tierFilter;
                const isSelected = selectedCountryIso === country.isoCode;
                const isHovered = hoveredCountry?.isoCode === country.isoCode;
                const isDimmed =
                  (!matchesContinent || !matchesTier) &&
                  !isSelected &&
                  !isHovered;

                const fillColor =
                  country.nodeStatus === "GEO_FENCED_RESTRICTED"
                    ? "#F43F5E"
                    : country.tier === "TIER_1"
                    ? "#F59E0B"
                    : country.tier === "TIER_2"
                    ? "#22D3EE"
                    : "#10B981";

                const radius = isSelected
                  ? 6.5
                  : isHovered
                  ? 5.5
                  : country.tier === "TIER_1"
                  ? 4.2
                  : country.tier === "TIER_2"
                  ? 3.6
                  : 2.8;

                return (
                  <g
                    key={country.isoCode}
                    transform={`translate(${country.mapX}, ${country.mapY})`}
                    onClick={(e) => {
                      e.stopPropagation();
                      if (selectedCountryIso === country.isoCode) {
                        onSelectCountry(null);
                      } else {
                        onSelectCountry(country.isoCode);
                        onSelectContinent(country.continent);
                      }
                    }}
                    onMouseEnter={() => setHoveredCountry(country)}
                    onMouseLeave={() => setHoveredCountry(null)}
                    className="cursor-pointer"
                    opacity={isDimmed ? 0.22 : 1}
                  >
                    {isSelected && (
                      <circle
                        r={11}
                        fill="none"
                        stroke="#F59E0B"
                        strokeWidth={1.5}
                      />
                    )}
                    <circle
                      r={radius}
                      fill={fillColor}
                      stroke="#070A11"
                      strokeWidth={1}
                    />
                    {(isSelected ||
                      isHovered ||
                      ["US", "GB", "SG", "JP", "CH", "DE", "AE", "BR", "AU", "ZA"].includes(
                        country.isoCode
                      )) && (
                      <text
                        y={-7}
                        textAnchor="middle"
                        fill={isSelected || isHovered ? "#FFFFFF" : "#CBD5E1"}
                        fontSize={isSelected || isHovered ? 10 : 8.5}
                        fontFamily="monospace"
                        fontWeight="bold"
                        className="pointer-events-none"
                      >
                        {country.isoCode}
                      </text>
                    )}
                  </g>
                );
              })}
            </svg>
          </div>

          {/* Bottom Map Status Bar */}
          <div className="px-4 py-2 border-t border-slate-800/80 bg-[#0A0E18] flex flex-wrap items-center justify-between gap-2 text-[11px] font-mono text-slate-400">
            <div>
              Active Filter:{" "}
              <span className="text-white font-semibold">
                {selectedCountryRecord
                  ? `${selectedCountryRecord.countryName} (${selectedCountryRecord.isoCode}) · ${selectedCountryRecord.continent}`
                  : selectedContinent === "ALL"
                  ? "All 6 Continents (193 UN Member States)"
                  : `${selectedContinent} (${continentSummary.total} UN Member States)`}
              </span>
            </div>
            <div className="tabular-nums">
              {hoveredCountry
                ? `Hover: ${hoveredCountry.countryName} [${hoveredCountry.isoCode}] · ${hoveredCountry.primaryRegulator} · ${hoveredCountry.latencyMs}ms`
                : "Tip: Click any continent polygon or country node pin"}
            </div>
          </div>
        </div>

        {/* Right 4 Columns: Live Regulatory Requirements Inspector */}
        <div className="lg:col-span-4 rounded-lg border border-slate-800 bg-[#111622] p-4 flex flex-col justify-between space-y-4">
          {inspectedCountry ? (
            <div className="space-y-3.5">
              <div className="flex items-start justify-between gap-2 border-b border-slate-800 pb-3">
                <div>
                  <div className="text-[11px] font-mono text-amber-400">
                    Country Regulatory Dossier · UN #{inspectedCountry.index}
                  </div>
                  <h4 className="text-base font-bold text-white mt-0.5">
                    {inspectedCountry.countryName} ({inspectedCountry.isoCode})
                  </h4>
                  <div className="text-xs text-slate-400 mt-0.5">
                    {inspectedCountry.continent} · {inspectedCountry.tierLabel}
                  </div>
                </div>
                {selectedCountryIso && (
                  <button
                    type="button"
                    onClick={() => onSelectCountry(null)}
                    className="px-2 py-1 rounded text-[11px] font-mono bg-slate-800 hover:bg-slate-700 text-slate-300 cursor-pointer"
                  >
                    Clear Pin
                  </button>
                )}
              </div>

              <div className="space-y-2.5 text-xs">
                <div className="p-2.5 rounded bg-[#0A0D14] border border-slate-800">
                  <div className="text-[11px] font-mono text-slate-400">
                    Primary Regulator & Statutory Framework
                  </div>
                  <div className="text-white font-semibold mt-0.5">
                    {inspectedCountry.primaryRegulator}
                  </div>
                  <div className="text-cyan-300 font-mono text-[11px] mt-0.5">
                    {inspectedCountry.regulatoryFramework}
                  </div>
                </div>

                <div className="p-2.5 rounded bg-[#0A0D14] border border-slate-800">
                  <div className="text-[11px] font-mono text-slate-400">
                    Mandatory Onboarding & Compliance Rule
                  </div>
                  <p className="text-slate-200 mt-0.5 leading-relaxed">
                    {inspectedCountry.onboardingComplianceRule}
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-2 font-mono text-[11px]">
                  <div className="p-2.5 rounded bg-[#0A0D14] border border-slate-800">
                    <div className="text-slate-400">Fiat / CBDC Bridge</div>
                    <div className="text-amber-300 font-semibold mt-0.5 truncate">
                      {inspectedCountry.fiatOrCbdcBridge}
                    </div>
                  </div>
                  <div className="p-2.5 rounded bg-[#0A0D14] border border-slate-800">
                    <div className="text-slate-400">ISO-3166 Numeric Slot</div>
                    <div className="text-cyan-300 font-semibold tabular-nums mt-0.5">
                      #{inspectedCountry.isoNumericCode} [Bits 0–15]
                    </div>
                  </div>
                </div>

                {/* Node Status Metadata Card */}
                <div className="p-2.5 rounded bg-[#0A0D14] border border-slate-800 space-y-1.5 font-mono text-[11px]">
                  <div className="flex items-center justify-between text-slate-400 border-b border-slate-800/80 pb-1">
                    <span>Node Status Metadata</span>
                    <span className="text-emerald-400 font-semibold tabular-nums">
                      {inspectedCountry.latencyMs}ms · {inspectedCountry.validatorUptime}
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-slate-400">Validator ID:</span>
                    <span className="text-white font-semibold">{inspectedCountry.nodeId}</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-slate-400">HSM Slot:</span>
                    <span className="text-amber-300">{inspectedCountry.hsmKeySlot}</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-slate-400">Synced Block:</span>
                    <span className="text-cyan-300 tabular-nums">
                      #{inspectedCountry.syncedBlockHeight.toLocaleString()}
                    </span>
                  </div>
                  <div className="text-[10px] text-slate-400 truncate pt-0.5">
                    Enclave: <span className="text-slate-200">{inspectedCountry.azureEnclaveZone}</span>
                  </div>
                </div>
              </div>

              <div className="pt-1.5 space-y-2">
                <button
                  type="button"
                  onClick={() => onToggleNodeStatus(inspectedCountry.isoCode)}
                  className={`w-full py-2 px-3 rounded-lg text-xs font-mono font-semibold transition cursor-pointer ${
                    inspectedCountry.nodeStatus === "ACTIVE_VALIDATOR"
                      ? "bg-emerald-950/90 text-emerald-300 border border-emerald-700/70 hover:bg-emerald-900"
                      : "bg-rose-950/90 text-rose-300 border border-rose-700/70 hover:bg-rose-900"
                  }`}
                >
                  {inspectedCountry.nodeStatus === "ACTIVE_VALIDATOR"
                    ? `Node Status: Active Validator (Click to Geo-Fence ${inspectedCountry.isoCode})`
                    : `Node Status: Geo-Fenced Restricted (Click to Permit ${inspectedCountry.isoCode})`}
                </button>

                <button
                  type="button"
                  onClick={() => onExecutePromptForCountry(inspectedCountry)}
                  className="w-full py-2 px-3 rounded-lg text-xs font-mono font-semibold bg-amber-500 hover:bg-amber-400 text-slate-950 transition cursor-pointer"
                >
                  Execute Compliance Prompt for {inspectedCountry.countryName}
                </button>

                {onLoadCountryIntoBitmaskEncoder && (
                  <button
                    type="button"
                    onClick={() => onLoadCountryIntoBitmaskEncoder(inspectedCountry)}
                    className="w-full py-2 px-3 rounded-lg text-xs font-mono font-semibold bg-cyan-500/20 hover:bg-cyan-500/30 text-cyan-300 border border-cyan-500/40 transition cursor-pointer"
                  >
                    Pack ISO #{inspectedCountry.isoNumericCode} ({inspectedCountry.isoCode}) in TWECommodityEncoder.sol
                  </button>
                )}
              </div>
            </div>
          ) : (
            <div className="space-y-3.5">
              <div className="border-b border-slate-800 pb-3">
                <div className="text-[11px] font-mono text-cyan-400">
                  Continental Regulatory Overview
                </div>
                <h4 className="text-base font-bold text-white mt-0.5">
                  {selectedContinent === "ALL"
                    ? "Global 193-UN-Member-State Rollout"
                    : `${selectedContinent} Regulatory Zone`}
                </h4>
                <p className="text-xs text-slate-400 mt-0.5">
                  Click any country pin on the map to inspect its specific regulator, onboarding rule, and CBDC bridge.
                </p>
              </div>

              <div className="grid grid-cols-2 gap-2.5 text-xs font-mono">
                <div className="p-3 rounded bg-[#0A0D14] border border-slate-800">
                  <div className="text-slate-400">Countries in Scope</div>
                  <div className="text-lg font-bold text-white tabular-nums mt-0.5">
                    {continentSummary.total} States
                  </div>
                </div>
                <div className="p-3 rounded bg-[#0A0D14] border border-slate-800">
                  <div className="text-slate-400">Active Validators</div>
                  <div className="text-lg font-bold text-emerald-400 tabular-nums mt-0.5">
                    {continentSummary.active} / {continentSummary.total}
                  </div>
                </div>
              </div>

              <div className="p-3 rounded bg-[#0A0D14] border border-slate-800 space-y-1.5 text-xs font-mono">
                <div className="text-slate-400">Tier Partitioning in Region:</div>
                <div className="flex items-center justify-between text-amber-300 tabular-nums">
                  <span>Tier 1 Major Hubs:</span>
                  <span>{continentSummary.t1}</span>
                </div>
                <div className="flex items-center justify-between text-cyan-300 tabular-nums">
                  <span>Tier 2 Emerging & Digital Hubs:</span>
                  <span>{continentSummary.t2}</span>
                </div>
                <div className="flex items-center justify-between text-emerald-300 tabular-nums">
                  <span>Tier 3 Global Integration Ring:</span>
                  <span>{continentSummary.t3}</span>
                </div>
              </div>

              <div className="p-3 rounded bg-[#0A0D14] border border-slate-800 space-y-1 text-xs">
                <div className="text-[11px] font-mono text-slate-400">
                  Primary Regional Frameworks:
                </div>
                <p className="text-slate-200 font-mono text-[11px] leading-relaxed">
                  {continentSummary.frameworkText}
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

