                  className="px-3 py-1.5 rounded-lg bg-[#141A2A] hover:bg-[#1E263C] text-slate-300 text-xs flex items-center gap-1.5 transition-colors"
                >
                  {copiedKey === "modal_claims_json" ? (
                    <Check className="w-3.5 h-3.5 text-emerald-400" />
