import React, { useState, useMemo, useEffect } from "react";
import {
  ArrowLeftRight,
  TrendingUp,
  Activity,
  Zap,
  ShieldCheck,
  Sparkles,
  Layers,
  CheckCircle2,
  AlertTriangle,
  BarChart3,
  Scale,
  DollarSign,
  Percent,
  ArrowUpRight,
  Sliders,
} from "lucide-react";
import { TokenRecord } from "../types";
import {
  SettlementAssetSymbol,
  PoolRangeStrategy,
  LiquidityPoolInitParameters,
  calculateOptimalLiquidityPoolParams,
} from "../utils/treasuryCollateralSettlementEngine";
import {
  MARKET_TREND_SCENARIOS,
  RoiTimeHorizon,
} from "./LiquidityPoolRoiProjectionTable";

export interface ComparedPoolConfig {
  tokenId: string;
  quoteAsset: SettlementAssetSymbol;
  feeTier: 500 | 3000 | 10000;
  rangeStrategy: PoolRangeStrategy;
  liquidityPercent: number;
}

interface LiquidityPoolComparePanelProps {
  tokens: TokenRecord[];
  activeToken: TokenRecord | null;
  activeQuoteAsset: SettlementAssetSymbol;
  activeFeeTier: 500 | 3000 | 10000;
  activeRangeStrategy: PoolRangeStrategy;
  activeLiquidityPercent: number;
  slippagePercent: number;
  recipientTreasuryAddress: string;
  onApplyPoolConfigToActive: (config: ComparedPoolConfig) => void;
  onQueueComparedPool?: (
    token: TokenRecord,
    config: ComparedPoolConfig,
    params: LiquidityPoolInitParameters
  ) => void;
  onQueueBothPools?: (
    poolA: {
      token: TokenRecord;
      config: ComparedPoolConfig;
      params: LiquidityPoolInitParameters;
    },
    poolB: {
      token: TokenRecord;
      config: ComparedPoolConfig;
      params: LiquidityPoolInitParameters;
    }
  ) => void;
}

interface ComputedPoolMetrics {
  token: TokenRecord;
  config: ComparedPoolConfig;
  params: LiquidityPoolInitParameters;
  // ROI Metrics for selected scenario & horizon
  dailyVolumeUsd: number;
  annualVolumeUsd: number;
  dailyFeesUsd: number;
  annualFeesUsd: number;
  simpleAprPct: number;
  compoundedApyPct: number;
  impermanentLossPct: number;
  netEffectiveApyPct: number;
  periodYieldUsd: number;
  periodReturnPct: number;
  breakEvenDays: number;
  // Slippage Metrics for selected test trade size
  virtualLiquidityUsd: number;
  priceImpactPct: number;
  totalSlippagePct: number;
  depthConsumedPct: number;
  effectiveExecutionPriceUsd: number;
  maxSafeTradeCollarUsd: number;
  isWithinCollar: boolean;
  slippageStatus: "SAFE" | "MODERATE" | "HIGH" | "CRITICAL";
}

const QUOTE_ASSETS: SettlementAssetSymbol[] = [
  "USDC",
  "USDT",
  "WETH",
  "WBTC",
  "SOL",
];

const FEE_TIERS: { tier: 500 | 3000 | 10000; label: string }[] = [
  { tier: 500, label: "0.05%" },
  { tier: 3000, label: "0.30%" },
  { tier: 10000, label: "1.00%" },
];

const RANGE_STRATEGIES: { key: PoolRangeStrategy; label: string }[] = [
  { key: "NARROW", label: "Narrow (±10%)" },
  { key: "BALANCED", label: "Balanced (±30%)" },
  { key: "WIDE", label: "Wide (±60%)" },
  { key: "FULL_RANGE", label: "Full (0→∞)" },
];

const LIQUIDITY_RATIOS = [1.0, 2.5, 5.0, 8.0];

export const LiquidityPoolComparePanel: React.FC<
  LiquidityPoolComparePanelProps
> = ({
  tokens,
  activeToken,
  activeQuoteAsset,
  activeFeeTier,
  activeRangeStrategy,
  activeLiquidityPercent,
  slippagePercent,
  recipientTreasuryAddress,
  onApplyPoolConfigToActive,
  onQueueComparedPool,
  onQueueBothPools,
}) => {
  // Pool A defaults to the modal's active token/pair
  const [poolAConfig, setPoolAConfig] = useState<ComparedPoolConfig>(() => ({
    tokenId: activeToken?.id || tokens[0]?.id || "",
    quoteAsset: activeQuoteAsset,
    feeTier: activeFeeTier,
    rangeStrategy: activeRangeStrategy,
    liquidityPercent: activeLiquidityPercent,
  }));

  // Pool B defaults to a second distinct token (or distinct quote asset if only 1 token)
  const [poolBConfig, setPoolBConfig] = useState<ComparedPoolConfig>(() => {
    const secondToken =
      tokens.find((t) => t.id !== (activeToken?.id || tokens[0]?.id)) ||
      tokens[0];
    const defaultQuoteB: SettlementAssetSymbol =
      secondToken?.id === (activeToken?.id || tokens[0]?.id)
        ? activeQuoteAsset === "USDC"
          ? "WETH"
          : "USDC"
        : "USDC";

    return {
      tokenId: secondToken?.id || "",
      quoteAsset: defaultQuoteB,
      feeTier: 3000,
      rangeStrategy: "BALANCED",
      liquidityPercent: 5.0,
    };
  });

  // Sync Pool A when user changes active token in the main modal
  useEffect(() => {
    if (activeToken) {
      setPoolAConfig((prev) => ({
        ...prev,
        tokenId: activeToken.id,
        quoteAsset: activeQuoteAsset,
        feeTier: activeFeeTier,
        rangeStrategy: activeRangeStrategy,
        liquidityPercent: activeLiquidityPercent,
      }));
    }
  }, [
    activeToken?.id,
    activeQuoteAsset,
    activeFeeTier,
    activeRangeStrategy,
    activeLiquidityPercent,
  ]);

  // Comparison Controls State
  const [selectedScenarioId, setSelectedScenarioId] =
    useState<string>("benchmark");
  const [selectedHorizon, setSelectedHorizon] = useState<RoiTimeHorizon>("1Y");
  const [isCompounded, setIsCompounded] = useState<boolean>(true);
  const [testTradeSizeUsd, setTestTradeSizeUsd] = useState<number>(100_000);
  const [actionBanner, setActionBanner] = useState<string | null>(null);

  const activeScenario = useMemo(() => {
    return (
      MARKET_TREND_SCENARIOS.find((s) => s.id === selectedScenarioId) ||
      MARKET_TREND_SCENARIOS[1]
    );
  }, [selectedScenarioId]);

  const horizonDays = useMemo(() => {
    return selectedHorizon === "30D"
      ? 30
      : selectedHorizon === "90D"
      ? 90
      : selectedHorizon === "3Y"
      ? 365 * 3
      : 365;
  }, [selectedHorizon]);

  // Helper to compute complete ROI + Slippage metrics for a pool config
  const computePoolMetrics = (
    config: ComparedPoolConfig
  ): ComputedPoolMetrics | null => {
    const token = tokens.find((t) => t.id === config.tokenId) || tokens[0];
    if (!token) return null;

    const params = calculateOptimalLiquidityPoolParams({
      token,
      quoteAsset: config.quoteAsset,
      feeTier: config.feeTier,
      rangeStrategy: config.rangeStrategy,
      customLiquidityPercent: config.liquidityPercent,
      recipientTreasuryAddress,
      slippagePercent,
    });

    const totalDepthUsd = Math.max(1, params.totalInitialLiquidityUsd);
    const feeRate = config.feeTier / 1_000_000;
    const efficiencyMultiplier = params.concentratedCapitalEfficiencyMultiplier;

    // concentrator boost factor on fee capture within active range
    const concentrationCaptureBoost =
      config.rangeStrategy === "NARROW"
        ? 1.45
        : config.rangeStrategy === "BALANCED"
        ? 1.2
        : config.rangeStrategy === "WIDE"
        ? 1.0
        : 0.78;

    const dailyVolumeUsd =
      totalDepthUsd * (activeScenario.turnoverDailyPct / 100);
    const annualVolumeUsd = dailyVolumeUsd * 365;
    const dailyFeesUsd =
      dailyVolumeUsd * feeRate * concentrationCaptureBoost;
    const annualFeesUsd = dailyFeesUsd * 365;

    const simpleAprPct = (annualFeesUsd / totalDepthUsd) * 100;
    const compoundedApyPct =
      (Math.pow(1 + simpleAprPct / 100 / 365, 365) - 1) * 100;
    const grossAnnualRate = isCompounded ? compoundedApyPct : simpleAprPct;

    // Range strategy impacts Impermanent Loss exposure
    const ilMultiplier =
      config.rangeStrategy === "NARROW"
        ? 1.55
        : config.rangeStrategy === "BALANCED"
        ? 1.0
        : config.rangeStrategy === "WIDE"
        ? 0.7
        : 0.45;
    const impermanentLossPct =
      activeScenario.impermanentLossAnnualPct * ilMultiplier;
    const netEffectiveApyPct = Math.max(
      0,
      grossAnnualRate - impermanentLossPct
    );

    const periodRatio = horizonDays / 365;
    const periodYieldUsd = isCompounded
      ? totalDepthUsd * (Math.pow(1 + netEffectiveApyPct / 100, periodRatio) - 1)
      : totalDepthUsd * (netEffectiveApyPct / 100) * periodRatio;
    const periodReturnPct = (periodYieldUsd / totalDepthUsd) * 100;
    const breakEvenDays =
      dailyFeesUsd > 0 ? Math.ceil(totalDepthUsd / dailyFeesUsd) : 9999;

    // Slippage simulation for testTradeSizeUsd
    const virtualLiquidityUsd = totalDepthUsd * efficiencyMultiplier;
    const feePct = config.feeTier / 10000;
    const tradeSize = Math.max(100, testTradeSizeUsd);
    const priceImpactPct =
      (tradeSize / (virtualLiquidityUsd + tradeSize)) * 100 * 1.15;
    const totalSlippagePct = priceImpactPct + feePct;
    const depthConsumedPct = Math.min(100, (tradeSize / totalDepthUsd) * 100);
    const effectiveExecutionPriceUsd =
      params.impliedTokenUnitPriceUsd * (1 + priceImpactPct / 100);
    const isWithinCollar = totalSlippagePct <= slippagePercent;

    let slippageStatus: ComputedPoolMetrics["slippageStatus"] = "SAFE";
    if (totalSlippagePct > 3.0 || depthConsumedPct > 25) {
      slippageStatus = "CRITICAL";
    } else if (totalSlippagePct > 1.5 || depthConsumedPct > 10) {
      slippageStatus = "HIGH";
    } else if (totalSlippagePct > slippagePercent) {
      slippageStatus = "MODERATE";
    }

    const targetMaxImpact = Math.max(0.05, slippagePercent - feePct);
    const ratio = targetMaxImpact / 100;
    const maxSafeTradeCollarUsd = Math.max(
      500,
      Math.round((virtualLiquidityUsd * ratio) / (1 - ratio))
    );

    return {
      token,
      config,
      params,
      dailyVolumeUsd,
      annualVolumeUsd,
      dailyFeesUsd,
      annualFeesUsd,
      simpleAprPct,
      compoundedApyPct,
      impermanentLossPct,
      netEffectiveApyPct,
      periodYieldUsd,
      periodReturnPct,
      breakEvenDays,
      virtualLiquidityUsd,
      priceImpactPct,
      totalSlippagePct,
      depthConsumedPct,
      effectiveExecutionPriceUsd,
      maxSafeTradeCollarUsd,
      isWithinCollar,
      slippageStatus,
    };
  };

  const metricsA = useMemo(
    () => computePoolMetrics(poolAConfig),
    [
      poolAConfig,
      tokens,
      activeScenario,
      horizonDays,
      isCompounded,
      testTradeSizeUsd,
      slippagePercent,
      recipientTreasuryAddress,
    ]
  );

  const metricsB = useMemo(
    () => computePoolMetrics(poolBConfig),
    [
      poolBConfig,
      tokens,
      activeScenario,
      horizonDays,
      isCompounded,
      testTradeSizeUsd,
      slippagePercent,
      recipientTreasuryAddress,
    ]
  );

  if (!metricsA || !metricsB) return null;

  const handleSwapPools = () => {
    const tempA = { ...poolAConfig };
    setPoolAConfig({ ...poolBConfig });
    setPoolBConfig(tempA);
  };

  // Determine comparative advantages
  const apyDiff = metricsA.netEffectiveApyPct - metricsB.netEffectiveApyPct;
  const yieldUsdDiff = metricsA.periodYieldUsd - metricsB.periodYieldUsd;
  const slippageDiff = metricsA.totalSlippagePct - metricsB.totalSlippagePct; // Lower is better
  const depthDiff =
    metricsA.params.totalInitialLiquidityUsd -
    metricsB.params.totalInitialLiquidityUsd;

  const standardizedTradeLadder = [10_000, 50_000, 100_000, 250_000, 500_000, 1_000_000];

  return (
    <div className="rounded-2xl bg-gradient-to-b from-[#111528] via-[#0D1020] to-[#0A0D18] border border-purple-500/35 p-4 sm:p-5 space-y-5 font-mono shadow-2xl">
      {/* =================================================================
          HEADER & GLOBAL COMPARISON CONTROLS
         ================================================================= */}
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#222845] pb-3.5">
        <div className="flex items-center gap-2.5">
          <div className="p-2 rounded-xl bg-purple-500/15 border border-purple-500/40 text-purple-300">
            <Scale className="w-5 h-5" />
          </div>
          <div>
            <div className="flex items-center gap-2 flex-wrap">
              <h3 className="text-sm font-black uppercase tracking-wider text-white">
                Compare Pools: Side-by-Side ROI &amp; Slippage Analyzer
              </h3>
              <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-purple-500/15 text-purple-300 border border-purple-500/30">
                Dual-Pair Pre-Deployment Simulation
              </span>
            </div>
            <p className="text-[11px] text-gray-400 mt-0.5">
              Select two token pairs simultaneously to benchmark projected annual yields, impermanent loss drag, and execution slippage before deployment.
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          <button
            type="button"
            onClick={handleSwapPools}
            className="px-3 py-1.5 rounded-lg bg-[#171C33] hover:bg-[#222949] text-purple-300 hover:text-white border border-purple-500/35 text-xs font-bold transition flex items-center gap-1.5 cursor-pointer"
            title="Swap Pool A and Pool B positions"
          >
            <ArrowLeftRight className="w-3.5 h-3.5" />
            <span>Swap A ↔ B</span>
          </button>

          {onQueueBothPools && (
            <button
              type="button"
              onClick={() => {
                onQueueBothPools(
                  {
                    token: metricsA.token,
                    config: poolAConfig,
                    params: metricsA.params,
                  },
                  {
                    token: metricsB.token,
                    config: poolBConfig,
                    params: metricsB.params,
                  }
                );
                setActionBanner(
                  `Queued both ${metricsA.token.symbol}/${poolAConfig.quoteAsset} and ${metricsB.token.symbol}/${poolBConfig.quoteAsset} into the Multi-Pool Batch Sequence!`
                );
              }}
              className="px-3 py-1.5 rounded-lg bg-gradient-to-r from-purple-500 to-cyan-500 hover:brightness-110 text-black text-xs font-black transition flex items-center gap-1.5 cursor-pointer shadow-md"
              title="Queue both Pool A and Pool B into the Multi-Pool Batch Deployment Sequence"
            >
              <Layers className="w-3.5 h-3.5" />
              <span>Queue Both Pools (A + B)</span>
            </button>
          )}
        </div>
      </div>

      {/* Action Confirmation Notice */}
      {actionBanner && (
        <div className="p-3 rounded-xl bg-emerald-950/40 border border-emerald-500/40 text-xs text-emerald-200 flex items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
            <span>{actionBanner}</span>
          </div>
          <button
            type="button"
            onClick={() => setActionBanner(null)}
            className="text-[11px] text-gray-400 hover:text-white underline cursor-pointer"
          >
            Dismiss
          </button>
        </div>
      )}

      {/* =================================================================
          DUAL POOL SELECTORS: POOL A (LEFT) VS POOL B (RIGHT)
         ================================================================= */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* POOL A CONFIGURATION CARD */}
        <div className="p-4 rounded-xl bg-[#0D1122] border border-[#F27D26]/40 space-y-3">
          <div className="flex items-center justify-between border-b border-[#1D2340] pb-2.5">
            <div className="flex items-center gap-2">
              <span className="px-2 py-0.5 rounded bg-[#F27D26]/20 text-[#F27D26] border border-[#F27D26]/40 text-[10px] font-black uppercase">
                Pool A (Primary)
              </span>
              <span className="text-sm font-black text-white">
                {metricsA.token.symbol}/{poolAConfig.quoteAsset}
              </span>
              <span className="text-[10px] text-gray-400 uppercase">
                ({metricsA.token.chain})
              </span>
            </div>
            <button
              type="button"
              onClick={() => {
                onApplyPoolConfigToActive(poolAConfig);
                setActionBanner(
                  `Applied Pool A (${metricsA.token.symbol}/${poolAConfig.quoteAsset}) as active deployment configuration.`
                );
              }}
              className="px-2.5 py-1 rounded-lg bg-[#F27D26]/20 hover:bg-[#F27D26] text-[#F27D26] hover:text-black border border-[#F27D26]/40 text-[10px] font-bold transition cursor-pointer"
            >
              Load into Active Deployer
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5 text-xs">
            {/* Token A Selector */}
            <div>
              <label className="text-[10px] text-gray-400 uppercase block mb-1">
                Base Token A
              </label>
              <select
                value={poolAConfig.tokenId}
                onChange={(e) =>
                  setPoolAConfig((prev) => ({ ...prev, tokenId: e.target.value }))
                }
                className="w-full p-2 rounded-lg bg-[#151A30] border border-[#293156] text-xs text-white focus:outline-none focus:border-[#F27D26] cursor-pointer"
              >
                {tokens.map((t) => (
                  <option key={`poolA-${t.id}`} value={t.id}>
                    {t.symbol} — {t.name} (${((t.marketCap || 0) / 1e6).toFixed(1)}M)
                  </option>
                ))}
              </select>
            </div>

            {/* Quote Asset A Selector */}
            <div>
              <label className="text-[10px] text-gray-400 uppercase block mb-1">
                Quote Currency A
              </label>
              <div className="grid grid-cols-5 gap-1">
                {QUOTE_ASSETS.map((q) => (
                  <button
                    key={`poolA-q-${q}`}
                    type="button"
                    onClick={() =>
                      setPoolAConfig((prev) => ({ ...prev, quoteAsset: q }))
                    }
                    className={`py-1.5 rounded text-[10px] font-bold transition cursor-pointer ${
                      poolAConfig.quoteAsset === q
                        ? "bg-[#F27D26] text-black"
                        : "bg-[#151A30] text-gray-300 hover:text-white border border-[#262E52]"
                    }`}
                  >
                    {q}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-2 text-xs">
            {/* Fee Tier A */}
            <div>
              <label className="text-[10px] text-gray-400 uppercase block mb-1">
                Fee Tier
              </label>
              <select
                value={poolAConfig.feeTier}
                onChange={(e) =>
                  setPoolAConfig((prev) => ({
                    ...prev,
                    feeTier: Number(e.target.value) as 500 | 3000 | 10000,
                  }))
                }
                className="w-full p-1.5 rounded-lg bg-[#151A30] border border-[#293156] text-[11px] text-white focus:outline-none cursor-pointer"
              >
                {FEE_TIERS.map((f) => (
                  <option key={`poolA-fee-${f.tier}`} value={f.tier}>
                    {f.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Range Strategy A */}
            <div>
              <label className="text-[10px] text-gray-400 uppercase block mb-1">
                Tick Range
              </label>
              <select
                value={poolAConfig.rangeStrategy}
                onChange={(e) =>
                  setPoolAConfig((prev) => ({
                    ...prev,
                    rangeStrategy: e.target.value as PoolRangeStrategy,
                  }))
                }
                className="w-full p-1.5 rounded-lg bg-[#151A30] border border-[#293156] text-[11px] text-white focus:outline-none cursor-pointer"
              >
                {RANGE_STRATEGIES.map((r) => (
                  <option key={`poolA-range-${r.key}`} value={r.key}>
                    {r.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Liquidity Ratio % A */}
            <div>
              <label className="text-[10px] text-gray-400 uppercase block mb-1">
                Depth (% MCap)
              </label>
              <select
                value={poolAConfig.liquidityPercent}
                onChange={(e) =>
                  setPoolAConfig((prev) => ({
                    ...prev,
                    liquidityPercent: Number(e.target.value),
                  }))
                }
                className="w-full p-1.5 rounded-lg bg-[#151A30] border border-[#293156] text-[11px] text-white focus:outline-none cursor-pointer"
              >
                {LIQUIDITY_RATIOS.map((pct) => (
                  <option key={`poolA-pct-${pct}`} value={pct}>
                    {pct}% MCap
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="pt-1 flex items-center justify-between text-[11px] text-gray-400 border-t border-[#1A203A]">
            <span>
              Pool A Depth:{" "}
              <strong className="text-[#F27D26]">
                ${Math.round(metricsA.params.totalInitialLiquidityUsd).toLocaleString()} USD
              </strong>
            </span>
            <span>
              Unit Price:{" "}
              <strong className="text-white">
                ${metricsA.params.impliedTokenUnitPriceUsd.toFixed(4)}
              </strong>
            </span>
          </div>
        </div>

        {/* POOL B CONFIGURATION CARD */}
        <div className="p-4 rounded-xl bg-[#0D1122] border border-cyan-500/40 space-y-3">
          <div className="flex items-center justify-between border-b border-[#1D2340] pb-2.5">
            <div className="flex items-center gap-2">
              <span className="px-2 py-0.5 rounded bg-cyan-500/20 text-cyan-300 border border-cyan-500/40 text-[10px] font-black uppercase">
                Pool B (Challenger)
              </span>
              <span className="text-sm font-black text-white">
                {metricsB.token.symbol}/{poolBConfig.quoteAsset}
              </span>
              <span className="text-[10px] text-gray-400 uppercase">
                ({metricsB.token.chain})
              </span>
            </div>
            <button
              type="button"
              onClick={() => {
                onApplyPoolConfigToActive(poolBConfig);
                setActionBanner(
                  `Applied Pool B (${metricsB.token.symbol}/${poolBConfig.quoteAsset}) as active deployment configuration.`
                );
              }}
              className="px-2.5 py-1 rounded-lg bg-cyan-500/20 hover:bg-cyan-400 text-cyan-300 hover:text-black border border-cyan-500/40 text-[10px] font-bold transition cursor-pointer"
            >
              Load into Active Deployer
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5 text-xs">
            {/* Token B Selector */}
            <div>
              <label className="text-[10px] text-gray-400 uppercase block mb-1">
                Base Token B
              </label>
              <select
                value={poolBConfig.tokenId}
                onChange={(e) =>
                  setPoolBConfig((prev) => ({ ...prev, tokenId: e.target.value }))
                }
                className="w-full p-2 rounded-lg bg-[#151A30] border border-[#293156] text-xs text-white focus:outline-none focus:border-cyan-400 cursor-pointer"
              >
                {tokens.map((t) => (
                  <option key={`poolB-${t.id}`} value={t.id}>
                    {t.symbol} — {t.name} (${((t.marketCap || 0) / 1e6).toFixed(1)}M)
                  </option>
                ))}
              </select>
            </div>

            {/* Quote Asset B Selector */}
            <div>
              <label className="text-[10px] text-gray-400 uppercase block mb-1">
                Quote Currency B
              </label>
              <div className="grid grid-cols-5 gap-1">
                {QUOTE_ASSETS.map((q) => (
                  <button
                    key={`poolB-q-${q}`}
                    type="button"
                    onClick={() =>
                      setPoolBConfig((prev) => ({ ...prev, quoteAsset: q }))
                    }
                    className={`py-1.5 rounded text-[10px] font-bold transition cursor-pointer ${
                      poolBConfig.quoteAsset === q
                        ? "bg-cyan-400 text-black"
                        : "bg-[#151A30] text-gray-300 hover:text-white border border-[#262E52]"
                    }`}
                  >
                    {q}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-2 text-xs">
            {/* Fee Tier B */}
            <div>
              <label className="text-[10px] text-gray-400 uppercase block mb-1">
                Fee Tier
              </label>
              <select
                value={poolBConfig.feeTier}
                onChange={(e) =>
                  setPoolBConfig((prev) => ({
                    ...prev,
                    feeTier: Number(e.target.value) as 500 | 3000 | 10000,
                  }))
                }
                className="w-full p-1.5 rounded-lg bg-[#151A30] border border-[#293156] text-[11px] text-white focus:outline-none cursor-pointer"
              >
                {FEE_TIERS.map((f) => (
                  <option key={`poolB-fee-${f.tier}`} value={f.tier}>
                    {f.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Range Strategy B */}
            <div>
              <label className="text-[10px] text-gray-400 uppercase block mb-1">
                Tick Range
              </label>
              <select
                value={poolBConfig.rangeStrategy}
                onChange={(e) =>
                  setPoolBConfig((prev) => ({
                    ...prev,
                    rangeStrategy: e.target.value as PoolRangeStrategy,
                  }))
                }
                className="w-full p-1.5 rounded-lg bg-[#151A30] border border-[#293156] text-[11px] text-white focus:outline-none cursor-pointer"
              >
                {RANGE_STRATEGIES.map((r) => (
                  <option key={`poolB-range-${r.key}`} value={r.key}>
                    {r.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Liquidity Ratio % B */}
            <div>
              <label className="text-[10px] text-gray-400 uppercase block mb-1">
                Depth (% MCap)
              </label>
              <select
                value={poolBConfig.liquidityPercent}
                onChange={(e) =>
                  setPoolBConfig((prev) => ({
                    ...prev,
                    liquidityPercent: Number(e.target.value),
                  }))
                }
                className="w-full p-1.5 rounded-lg bg-[#151A30] border border-[#293156] text-[11px] text-white focus:outline-none cursor-pointer"
              >
                {LIQUIDITY_RATIOS.map((pct) => (
                  <option key={`poolB-pct-${pct}`} value={pct}>
                    {pct}% MCap
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="pt-1 flex items-center justify-between text-[11px] text-gray-400 border-t border-[#1A203A]">
            <span>
              Pool B Depth:{" "}
              <strong className="text-cyan-300">
                ${Math.round(metricsB.params.totalInitialLiquidityUsd).toLocaleString()} USD
              </strong>
            </span>
            <span>
              Unit Price:{" "}
              <strong className="text-white">
                ${metricsB.params.impliedTokenUnitPriceUsd.toFixed(4)}
              </strong>
            </span>
          </div>
        </div>
      </div>

      {/* =================================================================
          SHARED SIMULATION CONTROLS (MARKET REGIME, HORIZON & STRESS TRADE)
         ================================================================= */}
      <div className="p-3.5 rounded-xl bg-[#0B0E1D] border border-[#212744] flex flex-wrap items-center justify-between gap-3 text-xs">
        {/* Market Regime Selector */}
        <div className="flex items-center gap-2 flex-wrap">
          <span className="text-[10px] text-gray-400 uppercase font-bold">
            Market Trend:
          </span>
          {MARKET_TREND_SCENARIOS.map((sc) => (
            <button
              key={sc.id}
              type="button"
              onClick={() => setSelectedScenarioId(sc.id)}
              className={`px-2.5 py-1 rounded-lg text-[11px] font-bold transition cursor-pointer ${
                selectedScenarioId === sc.id
                  ? "bg-purple-500 text-black shadow"
                  : "bg-[#141930] text-gray-300 hover:text-white border border-[#273056]"
              }`}
            >
              {sc.name.split(" (")[0]} ({sc.turnoverDailyPct}%/d)
            </button>
          ))}
        </div>

        {/* Time Horizon & Trade Size Tester */}
        <div className="flex items-center gap-3 flex-wrap">
          <div className="flex items-center gap-1">
            <span className="text-[10px] text-gray-400 uppercase">Horizon:</span>
            {(["30D", "90D", "1Y", "3Y"] as RoiTimeHorizon[]).map((h) => (
              <button
                key={h}
                type="button"
                onClick={() => setSelectedHorizon(h)}
                className={`px-2 py-0.5 rounded text-[10px] font-bold transition cursor-pointer ${
                  selectedHorizon === h
                    ? "bg-emerald-400 text-black"
                    : "bg-[#151A30] text-gray-400 hover:text-white"
                }`}
              >
                {h}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-1.5">
            <span className="text-[10px] text-gray-400 uppercase">
              Test Swap Order:
            </span>
            {[25_000, 100_000, 250_000, 1_000_000].map((sz) => (
              <button
                key={sz}
                type="button"
                onClick={() => setTestTradeSizeUsd(sz)}
                className={`px-2 py-0.5 rounded text-[10px] font-bold transition cursor-pointer ${
                  testTradeSizeUsd === sz
                    ? "bg-[#F27D26] text-black"
                    : "bg-[#151A30] text-gray-400 hover:text-white"
                }`}
              >
                ${sz >= 1_000_000 ? `${sz / 1_000_000}M` : `${sz / 1000}k`}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* =================================================================
          SIDE-BY-SIDE ROI & SLIPPAGE BENCHMARK MATRIX
         ================================================================= */}
      <div className="overflow-x-auto rounded-xl border border-[#232947] bg-[#090C18]">
        <table className="w-full text-left border-collapse text-xs">
          <thead>
            <tr className="bg-[#12172E] border-b border-[#232947] text-[10px] uppercase text-gray-400">
              <th className="p-3">Performance &amp; Risk Metric</th>
              <th className="p-3 text-[#F27D26]">
                Pool A: {metricsA.token.symbol}/{poolAConfig.quoteAsset} (
                {(poolAConfig.feeTier / 10000).toFixed(2)}%)
              </th>
              <th className="p-3 text-cyan-300">
                Pool B: {metricsB.token.symbol}/{poolBConfig.quoteAsset} (
                {(poolBConfig.feeTier / 10000).toFixed(2)}%)
              </th>
              <th className="p-3 text-right">Comparative Edge</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#181E36]">
            {/* 1. Net Effective Annual APY */}
            <tr className="hover:bg-[#10152B] transition">
              <td className="p-3 font-bold text-white">
                Net Effective Annual APY (Post-IL)
              </td>
              <td className="p-3 font-black text-emerald-400 text-sm">
                +{metricsA.netEffectiveApyPct.toFixed(2)}% APY
                <span className="block text-[10px] text-gray-400 font-normal">
                  Gross: {metricsA.compoundedApyPct.toFixed(2)}% | IL Drag: -
                  {metricsA.impermanentLossPct.toFixed(2)}%
                </span>
              </td>
              <td className="p-3 font-black text-emerald-400 text-sm">
                +{metricsB.netEffectiveApyPct.toFixed(2)}% APY
                <span className="block text-[10px] text-gray-400 font-normal">
                  Gross: {metricsB.compoundedApyPct.toFixed(2)}% | IL Drag: -
                  {metricsB.impermanentLossPct.toFixed(2)}%
                </span>
              </td>
              <td className="p-3 text-right">
                {Math.abs(apyDiff) < 0.05 ? (
                  <span className="px-2 py-0.5 rounded bg-gray-500/20 text-gray-300 text-[10px]">
                    Tied Yield
                  </span>
                ) : apyDiff > 0 ? (
                  <span className="px-2 py-0.5 rounded bg-[#F27D26]/20 text-[#F27D26] border border-[#F27D26]/40 text-[10px] font-bold">
                    Pool A +{apyDiff.toFixed(2)}% APY
                  </span>
                ) : (
                  <span className="px-2 py-0.5 rounded bg-cyan-500/20 text-cyan-300 border border-cyan-500/40 text-[10px] font-bold">
                    Pool B +{Math.abs(apyDiff).toFixed(2)}% APY
                  </span>
                )}
              </td>
            </tr>

            {/* 2. Projected Period Fee Return ($ USD) */}
            <tr className="hover:bg-[#10152B] transition">
              <td className="p-3 font-bold text-white">
                Projected {selectedHorizon} Net Fee Yield ($ USD)
              </td>
              <td className="p-3 font-bold text-white">
                +${Math.round(metricsA.periodYieldUsd).toLocaleString()} USD
                <span className="block text-[10px] text-emerald-400">
                  +{metricsA.periodReturnPct.toFixed(2)}% Capital Return ($
                  {Math.round(metricsA.dailyFeesUsd).toLocaleString()}/day)
                </span>
              </td>
              <td className="p-3 font-bold text-white">
                +${Math.round(metricsB.periodYieldUsd).toLocaleString()} USD
                <span className="block text-[10px] text-emerald-400">
                  +{metricsB.periodReturnPct.toFixed(2)}% Capital Return ($
                  {Math.round(metricsB.dailyFeesUsd).toLocaleString()}/day)
                </span>
              </td>
              <td className="p-3 text-right">
                {yieldUsdDiff >= 0 ? (
                  <span className="px-2 py-0.5 rounded bg-[#F27D26]/20 text-[#F27D26] border border-[#F27D26]/40 text-[10px] font-bold">
                    Pool A +${Math.round(yieldUsdDiff).toLocaleString()}
                  </span>
                ) : (
                  <span className="px-2 py-0.5 rounded bg-cyan-500/20 text-cyan-300 border border-cyan-500/40 text-[10px] font-bold">
                    Pool B +${Math.round(Math.abs(yieldUsdDiff)).toLocaleString()}
                  </span>
                )}
              </td>
            </tr>

            {/* 3. Total Slippage & Price Impact at Test Order Size */}
            <tr className="hover:bg-[#10152B] transition">
              <td className="p-3 font-bold text-white">
                Execution Slippage on ${testTradeSizeUsd.toLocaleString()} Swap
              </td>
              <td className="p-3">
                <div className="flex items-center gap-2">
                  <span
                    className={`font-black text-sm ${
                      metricsA.isWithinCollar
                        ? "text-emerald-400"
                        : "text-amber-400"
                    }`}
                  >
                    {metricsA.totalSlippagePct.toFixed(3)}%
                  </span>
                  <span className="text-[10px] px-1.5 py-0.5 rounded bg-[#181F38] text-gray-300">
                    {metricsA.slippageStatus}
                  </span>
                </div>
                <span className="block text-[10px] text-gray-400">
                  Price Impact: {metricsA.priceImpactPct.toFixed(3)}% | Depth Used:{" "}
                  {metricsA.depthConsumedPct.toFixed(2)}%
                </span>
              </td>
              <td className="p-3">
                <div className="flex items-center gap-2">
                  <span
                    className={`font-black text-sm ${
                      metricsB.isWithinCollar
                        ? "text-emerald-400"
                        : "text-amber-400"
                    }`}
                  >
                    {metricsB.totalSlippagePct.toFixed(3)}%
                  </span>
                  <span className="text-[10px] px-1.5 py-0.5 rounded bg-[#181F38] text-gray-300">
                    {metricsB.slippageStatus}
                  </span>
                </div>
                <span className="block text-[10px] text-gray-400">
                  Price Impact: {metricsB.priceImpactPct.toFixed(3)}% | Depth Used:{" "}
                  {metricsB.depthConsumedPct.toFixed(2)}%
                </span>
              </td>
              <td className="p-3 text-right">
                {Math.abs(slippageDiff) < 0.005 ? (
                  <span className="px-2 py-0.5 rounded bg-gray-500/20 text-gray-300 text-[10px]">
                    Equal Slippage
                  </span>
                ) : slippageDiff < 0 ? (
                  <span className="px-2 py-0.5 rounded bg-[#F27D26]/20 text-[#F27D26] border border-[#F27D26]/40 text-[10px] font-bold">
                    Pool A -{Math.abs(slippageDiff).toFixed(3)}% Lower Slippage
                  </span>
                ) : (
                  <span className="px-2 py-0.5 rounded bg-cyan-500/20 text-cyan-300 border border-cyan-500/40 text-[10px] font-bold">
                    Pool B -{Math.abs(slippageDiff).toFixed(3)}% Lower Slippage
                  </span>
                )}
              </td>
            </tr>

            {/* 4. Max Safe Trade Size within Slippage Collar */}
            <tr className="hover:bg-[#10152B] transition">
              <td className="p-3 font-bold text-white">
                Max Safe Trade Size (≤{slippagePercent}% Slippage Collar)
              </td>
              <td className="p-3 font-bold text-emerald-300">
                ${metricsA.maxSafeTradeCollarUsd.toLocaleString()} USD
                <span className="block text-[10px] text-gray-400 font-normal">
                  Virtual Depth: $
                  {Math.round(metricsA.virtualLiquidityUsd).toLocaleString()} (
                  {metricsA.params.concentratedCapitalEfficiencyMultiplier.toFixed(
                    1
                  )}
                  x V2)
                </span>
              </td>
              <td className="p-3 font-bold text-emerald-300">
                ${metricsB.maxSafeTradeCollarUsd.toLocaleString()} USD
                <span className="block text-[10px] text-gray-400 font-normal">
                  Virtual Depth: $
                  {Math.round(metricsB.virtualLiquidityUsd).toLocaleString()} (
                  {metricsB.params.concentratedCapitalEfficiencyMultiplier.toFixed(
                    1
                  )}
                  x V2)
                </span>
              </td>
              <td className="p-3 text-right">
                {metricsA.maxSafeTradeCollarUsd >=
                metricsB.maxSafeTradeCollarUsd ? (
                  <span className="px-2 py-0.5 rounded bg-[#F27D26]/20 text-[#F27D26] border border-[#F27D26]/40 text-[10px] font-bold">
                    Pool A Deeper Capacity
                  </span>
                ) : (
                  <span className="px-2 py-0.5 rounded bg-cyan-500/20 text-cyan-300 border border-cyan-500/40 text-[10px] font-bold">
                    Pool B Deeper Capacity
                  </span>
                )}
              </td>
            </tr>

            {/* 5. Initial Liquidity Depth & Break-Even Horizon */}
            <tr className="hover:bg-[#10152B] transition">
              <td className="p-3 font-bold text-white">
                Initial TVL Commitment &amp; Fee Payback Horizon
              </td>
              <td className="p-3 text-gray-200">
                <strong>
                  ${Math.round(metricsA.params.totalInitialLiquidityUsd).toLocaleString()}{" "}
                  USD
                </strong>{" "}
                ({poolAConfig.liquidityPercent}% MCap)
                <span className="block text-[10px] text-gray-400">
                  Payback Horizon: ~{metricsA.breakEvenDays.toLocaleString()} days
                </span>
              </td>
              <td className="p-3 text-gray-200">
                <strong>
                  ${Math.round(metricsB.params.totalInitialLiquidityUsd).toLocaleString()}{" "}
                  USD
                </strong>{" "}
                ({poolBConfig.liquidityPercent}% MCap)
                <span className="block text-[10px] text-gray-400">
                  Payback Horizon: ~{metricsB.breakEvenDays.toLocaleString()} days
                </span>
              </td>
              <td className="p-3 text-right">
                {depthDiff >= 0 ? (
                  <span className="text-[10px] text-[#F27D26] font-bold">
                    Pool A +${Math.round(depthDiff).toLocaleString()} TVL
                  </span>
                ) : (
                  <span className="text-[10px] text-cyan-300 font-bold">
                    Pool B +${Math.round(Math.abs(depthDiff)).toLocaleString()} TVL
                  </span>
                )}
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      {/* =================================================================
          VISUAL SLIPPAGE LADDER COMPARISON ACROSS STANDARDIZED TRADE SIZES
         ================================================================= */}
      <div className="p-4 rounded-xl bg-[#0A0D19] border border-[#1E2440] space-y-3">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <BarChart3 className="w-4 h-4 text-purple-400" />
            <span className="text-xs font-bold text-white uppercase">
              Side-by-Side Slippage Curve Across Order Sizes (Lower is Better)
            </span>
          </div>
          <div className="flex items-center gap-4 text-[10px]">
            <span className="flex items-center gap-1.5 text-[#F27D26] font-bold">
              <span className="w-2.5 h-2.5 rounded-sm bg-[#F27D26] inline-block" />
              Pool A ({metricsA.token.symbol}/{poolAConfig.quoteAsset})
            </span>
            <span className="flex items-center gap-1.5 text-cyan-300 font-bold">
              <span className="w-2.5 h-2.5 rounded-sm bg-cyan-400 inline-block" />
              Pool B ({metricsB.token.symbol}/{poolBConfig.quoteAsset})
            </span>
          </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-2.5">
          {standardizedTradeLadder.map((tradeUsd) => {
            const feePctA = poolAConfig.feeTier / 10000;
            const impactA =
              (tradeUsd / (metricsA.virtualLiquidityUsd + tradeUsd)) *
              100 *
              1.15;
            const slipA = impactA + feePctA;

            const feePctB = poolBConfig.feeTier / 10000;
            const impactB =
              (tradeUsd / (metricsB.virtualLiquidityUsd + tradeUsd)) *
              100 *
              1.15;
            const slipB = impactB + feePctB;

            const maxBar = Math.max(slipA, slipB, 0.5);
            const widthA = Math.min(100, Math.max(8, (slipA / maxBar) * 100));
            const widthB = Math.min(100, Math.max(8, (slipB / maxBar) * 100));

            return (
              <div
                key={`ladder-${tradeUsd}`}
                onClick={() => setTestTradeSizeUsd(tradeUsd)}
                className={`p-2.5 rounded-lg border transition cursor-pointer ${
                  testTradeSizeUsd === tradeUsd
                    ? "bg-[#151B34] border-purple-500/60"
                    : "bg-[#0F1325] border-[#1E2542] hover:border-[#2E3862]"
                }`}
              >
                <div className="text-[10px] text-gray-400 font-bold mb-1.5 flex items-center justify-between">
                  <span>
                    ${tradeUsd >= 1_000_000 ? "1.0M" : `${tradeUsd / 1000}k`}
                  </span>
                  <span className="text-[9px] text-gray-500">Swap</span>
                </div>

                {/* Pool A Bar */}
                <div className="space-y-1 mb-1.5">
                  <div className="flex items-center justify-between text-[10px]">
                    <span className="text-[#F27D26] font-bold">A</span>
                    <span className="text-white">{slipA.toFixed(2)}%</span>
                  </div>
                  <div className="w-full h-1.5 rounded-full bg-[#1A2038] overflow-hidden">
                    <div
                      className="h-full bg-[#F27D26] rounded-full"
                      style={{ width: `${widthA}%` }}
                    />
                  </div>
                </div>

                {/* Pool B Bar */}
                <div className="space-y-1">
                  <div className="flex items-center justify-between text-[10px]">
                    <span className="text-cyan-300 font-bold">B</span>
                    <span className="text-white">{slipB.toFixed(2)}%</span>
                  </div>
                  <div className="w-full h-1.5 rounded-full bg-[#1A2038] overflow-hidden">
                    <div
                      className="h-full bg-cyan-400 rounded-full"
                      style={{ width: `${widthB}%` }}
                    />
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

