import React, { useState, useMemo, useEffect } from "react";
import {
  Sparkles,
  CheckCircle2,
  ChevronRight,
  ChevronLeft,
  Coins,
  Wallet,
  Layers,
  DollarSign,
  Zap,
  ShieldCheck,
  ArrowRightLeft,
  RefreshCw,
  Sliders,
  Landmark,
} from "lucide-react";
import { TokenRecord } from "../types";
import {
  SettlementAssetSymbol,
  VERIFIED_MARKET_CONTRACTS,
  VERIFIED_TREASURY_DESTINATIONS,
  LiquidityPoolInitParameters,
  PoolRangeStrategy,
  RealWalletDescriptor,
  RealWalletId,
} from "../utils/treasuryCollateralSettlementEngine";

export type AmmLiquidityProviderId =
  | "uniswap_v3"
  | "aerodrome_cl"
  | "quickswap_v3"
  | "raydium_clmm";

export interface AmmLiquidityProviderOption {
  id: AmmLiquidityProviderId;
  name: string;
  network: "ethereum" | "base" | "polygon" | "solana";
  badge: string;
  recommendedQuote: SettlementAssetSymbol;
  recommendedFeeTier: 500 | 3000 | 10000;
  factoryAddress: string;
  description: string;
}

export const AMM_LIQUIDITY_PROVIDERS: AmmLiquidityProviderOption[] = [
  {
    id: "uniswap_v3",
    name: "Uniswap V3 Concentrated AMM",
    network: "ethereum",
    badge: "EVM Standard · Q64.96",
    recommendedQuote: "USDC",
    recommendedFeeTier: 3000,
    factoryAddress: "0x1F98431c8aD98523631AE4a59f267346ea31F984",
    description:
      "Institutional concentrated liquidity with custom tick ranges and NonfungiblePositionManager NFT custody.",
  },
  {
    id: "aerodrome_cl",
    name: "Aerodrome Slipstream (Base L2)",
    network: "base",
    badge: "Base Mainnet · Chain 8453",
    recommendedQuote: "USDC",
    recommendedFeeTier: 500,
    factoryAddress: "0x5e7BB104d84c7CB9B682AaC2F3d509f5F406809A",
    description:
      "High-velocity Base L2 concentrated liquidity engine settling directly to Base Sovereign Treasury (0x70Ac).",
  },
  {
    id: "quickswap_v3",
    name: "QuickSwap V3 Algebra (Polygon)",
    network: "polygon",
    badge: "Polygon PoS · Chain 137",
    recommendedQuote: "USDT",
    recommendedFeeTier: 3000,
    factoryAddress: "0x411b0fAcC3489691f28ad58c47006AF5E3Ab3A28",
    description:
      "Dynamic fee concentrated liquidity pool on Polygon PoS settling to Polygon Treasury Vault (0xd12A).",
  },
  {
    id: "raydium_clmm",
    name: "Raydium CLMM (Solana SVM)",
    network: "solana",
    badge: "Solana SPL · CLMM",
    recommendedQuote: "SOL",
    recommendedFeeTier: 3000,
    factoryAddress: "CAMMCzo5YL8w4VFF8KVHrK22GGUsp5VTaW7grrKgrWqK",
    description:
      "Ultra-low latency Solana Concentrated Liquidity Market Maker settling to Solana Multi-Sig Treasury (2TTe).",
  },
];

export interface LiquidityPoolQuickStartWizardProps {
  tokens: TokenRecord[];
  activeToken: TokenRecord | null;
  onSelectTokenId: (id: string) => void;
  quoteAsset: SettlementAssetSymbol;
  onSelectQuoteAsset: (asset: SettlementAssetSymbol) => void;
  feeTier: 500 | 3000 | 10000;
  onSelectFeeTier: (tier: 500 | 3000 | 10000) => void;
  rangeStrategy: PoolRangeStrategy;
  onSelectRangeStrategy: (strategy: PoolRangeStrategy) => void;
  liquidityPercent: number;
  onSelectLiquidityPercent: (pct: number) => void;
  customInitialPriceUsd: number | null;
  onChangeCustomInitialPriceUsd: (price: number | null) => void;
  wallets: RealWalletDescriptor[];
  selectedWalletId: RealWalletId;
  onConnectWallet: (walletId: RealWalletId) => void;
  onSelectTreasuryDestination: (presetId: string, address: string) => void;
  poolParams: LiquidityPoolInitParameters | null;
  isExecuting: boolean;
  executionStage: string;
  onConfirmAndInitialize: () => void;
}

export const LiquidityPoolQuickStartWizard: React.FC<
  LiquidityPoolQuickStartWizardProps
> = ({
  tokens,
  activeToken,
  onSelectTokenId,
  quoteAsset,
  onSelectQuoteAsset,
  feeTier,
  onSelectFeeTier,
  rangeStrategy,
  onSelectRangeStrategy,
  liquidityPercent,
  onSelectLiquidityPercent,
  customInitialPriceUsd,
  onChangeCustomInitialPriceUsd,
  wallets,
  selectedWalletId,
  onConnectWallet,
  onSelectTreasuryDestination,
  poolParams,
  isExecuting,
  executionStage,
  onConfirmAndInitialize,
}) => {
  const [wizardStep, setWizardStep] = useState<1 | 2 | 3>(1);
  const [selectedAmmId, setSelectedAmmId] =
    useState<AmmLiquidityProviderId>("uniswap_v3");
  const [priceInputText, setPriceInputText] = useState<string>("");

  // Derive market-cap implied default unit price for reference
  const marketCapDerivedPriceUsd = useMemo(() => {
    if (!activeToken) return 0.05;
    const mcap = Math.max(activeToken.marketCap || 25_000_000, 100_000);
    const tShares =
      parseFloat(String(activeToken.treasuryShares || "500000000").replace(/,/g, "")) ||
      500_000_000;
    const rShares =
      parseFloat(String(activeToken.reserveShares || "500000000").replace(/,/g, "")) ||
      500_000_000;
    const supply = Math.max(tShares + rShares, 1_000_000);
    return Math.max(mcap / supply, 0.0001);
  }, [activeToken]);

  const effectiveUnitPriceUsd =
    customInitialPriceUsd && customInitialPriceUsd > 0
      ? customInitialPriceUsd
      : poolParams?.impliedTokenUnitPriceUsd || marketCapDerivedPriceUsd;

  useEffect(() => {
    if (customInitialPriceUsd === null) {
      setPriceInputText(
        marketCapDerivedPriceUsd < 0.01
          ? marketCapDerivedPriceUsd.toFixed(6)
          : marketCapDerivedPriceUsd.toFixed(4)
      );
    }
  }, [marketCapDerivedPriceUsd, customInitialPriceUsd]);

  // Select AMM provider and automatically sync treasury destination & fee tier
  const handleSelectAmmProvider = (provider: AmmLiquidityProviderOption) => {
    setSelectedAmmId(provider.id);
    onSelectQuoteAsset(provider.recommendedQuote);
    onSelectFeeTier(provider.recommendedFeeTier);

    const matchedTreasury =
      VERIFIED_TREASURY_DESTINATIONS.find(
        (d) => d.network === provider.network
      ) || VERIFIED_TREASURY_DESTINATIONS[0];

    if (matchedTreasury) {
      onSelectTreasuryDestination(matchedTreasury.id, matchedTreasury.address);
    }
  };

  const selectedAmm =
    AMM_LIQUIDITY_PROVIDERS.find((p) => p.id === selectedAmmId) ||
    AMM_LIQUIDITY_PROVIDERS[0];

  const quotePriceUsd =
    VERIFIED_MARKET_CONTRACTS.TOKENS[quoteAsset]?.priceUsd || 1.0;
  const computedQuoteRatio = effectiveUnitPriceUsd / quotePriceUsd;

  return (
    <div className="p-4 rounded-2xl bg-gradient-to-br from-[#12162A] via-[#0E1222] to-[#0B0E1A] border border-[#2C3458] shadow-xl space-y-4 font-mono">
      {/* =================================================================
          WIZARD HEADER & 3-STEP PROGRESS BAR
         ================================================================= */}
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#1F2542] pb-3">
        <div className="flex items-center gap-2.5">
          <div className="p-2 rounded-xl bg-gradient-to-br from-[#F27D26]/25 to-amber-500/10 border border-[#F27D26]/40 text-[#F27D26]">
            <Sparkles className="w-4 h-4" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="text-xs sm:text-sm font-black text-white uppercase tracking-wider">
                Quick-Start Pool Initialization Wizard
              </span>
              <span className="px-2 py-0.5 rounded-full text-[9px] font-bold bg-emerald-500/15 text-emerald-400 border border-emerald-500/30 uppercase">
                Step {wizardStep} of 3
              </span>
            </div>
            <p className="text-[11px] text-gray-400 font-sans mt-0.5">
              Guided 3-step setup: select liquidity provider, pair tokens, and set initial pool price with single-click confirmation.
            </p>
          </div>
        </div>

        {/* Stepper Pills */}
        <div className="flex items-center gap-1.5">
          {[
            { step: 1 as const, label: "1. Provider" },
            { step: 2 as const, label: "2. Pair Tokens" },
            { step: 3 as const, label: "3. Price & Confirm" },
          ].map((item) => {
            const isCurrent = wizardStep === item.step;
            const isDone = wizardStep > item.step;
            return (
              <button
                key={item.step}
                type="button"
                onClick={() => setWizardStep(item.step)}
                className={`px-2.5 py-1 rounded-lg text-[11px] font-bold transition flex items-center gap-1 cursor-pointer ${
                  isCurrent
                    ? "bg-[#F27D26] text-black shadow"
                    : isDone
                    ? "bg-emerald-500/15 text-emerald-300 border border-emerald-500/30"
                    : "bg-[#15192E] text-gray-400 hover:text-white border border-[#252C4A]"
                }`}
              >
                {isDone && <CheckCircle2 className="w-3 h-3 text-emerald-400" />}
                <span>{item.label}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* =================================================================
          STEP 1: SELECT LIQUIDITY PROVIDER (AMM PROTOCOL & WALLET)
         ================================================================= */}
      {wizardStep === 1 && (
        <div className="space-y-4">
          <div className="space-y-2">
            <div className="flex items-center justify-between text-xs">
              <span className="text-amber-400 font-bold uppercase flex items-center gap-1.5">
                <Layers className="w-3.5 h-3.5" />
                <span>Step 1A: Choose Automated Market Maker (Liquidity Provider)</span>
              </span>
              <span className="text-[10px] text-gray-400">
                Auto-aligns fee tier &amp; verified chain treasury
              </span>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
              {AMM_LIQUIDITY_PROVIDERS.map((prov) => {
                const active = selectedAmmId === prov.id;
                return (
                  <button
                    key={prov.id}
                    type="button"
                    onClick={() => handleSelectAmmProvider(prov)}
                    className={`p-3 rounded-xl text-left border transition cursor-pointer flex flex-col justify-between gap-1.5 ${
                      active
                        ? "bg-[#1A203D] border-[#F27D26] shadow-md"
                        : "bg-[#0D101E] hover:bg-[#13182C] border-[#212742]"
                    }`}
                  >
                    <div className="flex items-center justify-between gap-2">
                      <span className="text-xs font-bold text-white">
                        {prov.name}
                      </span>
                      <span
                        className={`px-2 py-0.5 rounded text-[9px] font-bold ${
                          active
                            ? "bg-[#F27D26] text-black"
                            : "bg-[#171C32] text-cyan-400 border border-cyan-500/20"
                        }`}
                      >
                        {prov.badge}
                      </span>
                    </div>
                    <p className="text-[11px] text-gray-400 font-sans leading-snug">
                      {prov.description}
                    </p>
                    <div className="flex items-center justify-between text-[10px] text-gray-400 pt-1 border-t border-[#1D223A]">
                      <span>Default Quote: {prov.recommendedQuote}</span>
                      <span className="text-emerald-400">
                        Fee: {(prov.recommendedFeeTier / 10000).toFixed(2)}%
                      </span>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Signing Wallet Provider */}
          <div className="space-y-2 pt-1">
            <span className="text-xs font-bold text-gray-300 uppercase flex items-center gap-1.5">
              <Wallet className="w-3.5 h-3.5 text-emerald-400" />
              <span>Step 1B: Select Signing Wallet Provider (EIP-6963)</span>
            </span>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-2">
              {wallets.map((w) => {
                const active = selectedWalletId === w.id;
                return (
                  <button
                    key={w.id}
                    type="button"
                    onClick={() => onConnectWallet(w.id)}
                    className={`p-2 rounded-lg text-xs border transition flex flex-col items-center justify-center gap-0.5 cursor-pointer ${
                      active
                        ? "bg-emerald-500/20 border-emerald-400 text-emerald-300 font-bold"
                        : "bg-[#0D101E] hover:bg-[#14192E] border-[#212742] text-gray-300"
                    }`}
                  >
                    <span className="truncate max-w-[95px]">
                      {w.name.split(" ")[0]}
                    </span>
                    <span className="text-[9px] text-gray-400">
                      {w.isDetected ? "Detected" : "Ready"}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          <div className="flex items-center justify-end pt-2">
            <button
              type="button"
              onClick={() => setWizardStep(2)}
              className="px-4 py-2 rounded-xl bg-[#F27D26] hover:bg-[#ff8d38] text-black font-bold text-xs flex items-center gap-1.5 cursor-pointer shadow transition"
            >
              <span>Next: Choose Pair Tokens</span>
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      {/* =================================================================
          STEP 2: CHOOSE THE PAIR TOKENS (BASE TOKEN & QUOTE ASSET)
         ================================================================= */}
      {wizardStep === 2 && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Base Token Selector */}
            <div className="p-3.5 rounded-xl bg-[#0C0F1D] border border-[#222845] space-y-2.5">
              <label className="text-xs font-bold text-[#F27D26] uppercase flex items-center justify-between">
                <span className="flex items-center gap-1.5">
                  <Coins className="w-3.5 h-3.5" />
                  <span>Base Token (Token 0)</span>
                </span>
                <span className="text-[10px] text-gray-400">
                  {tokens.length} Portfolio Tokens
                </span>
              </label>

              <select
                value={activeToken?.id || ""}
                onChange={(e) => {
                  onSelectTokenId(e.target.value);
                  onChangeCustomInitialPriceUsd(null);
                }}
                className="w-full p-2.5 rounded-lg bg-[#14182C] border border-[#2B3254] text-xs text-white font-bold focus:outline-none focus:border-[#F27D26] cursor-pointer"
              >
                {tokens.map((t) => (
                  <option key={t.id} value={t.id}>
                    {t.symbol} — {t.name} ({t.chain.toUpperCase()} · MCap: $
                    {(t.marketCap || 0).toLocaleString()})
                  </option>
                ))}
              </select>

              {activeToken && (
                <div className="p-2.5 rounded-lg bg-[#090B15] border border-[#1B2038] text-[11px] text-gray-300 space-y-1">
                  <div className="flex items-center justify-between">
                    <span className="text-gray-400">Sovereign Market Cap:</span>
                    <strong className="text-emerald-400">
                      ${(activeToken.marketCap || 0).toLocaleString()} USD
                    </strong>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-gray-400">Contract Address:</span>
                    <span className="text-white">
                      {activeToken.contractAddress
                        ? `${activeToken.contractAddress.slice(0, 10)}...${activeToken.contractAddress.slice(-6)}`
                        : "Native Mint"}
                    </span>
                  </div>
                </div>
              )}
            </div>

            {/* Quote Asset Selector */}
            <div className="p-3.5 rounded-xl bg-[#0C0F1D] border border-[#222845] space-y-2.5">
              <label className="text-xs font-bold text-cyan-400 uppercase flex items-center justify-between">
                <span className="flex items-center gap-1.5">
                  <ArrowRightLeft className="w-3.5 h-3.5" />
                  <span>Quote Settlement Currency (Token 1)</span>
                </span>
                <span className="text-[10px] text-gray-400">
                  50/50 Value Parity
                </span>
              </label>

              <div className="grid grid-cols-5 gap-1.5">
                {(
                  ["USDC", "USDT", "WETH", "WBTC", "SOL"] as SettlementAssetSymbol[]
                ).map((sym) => {
                  const active = quoteAsset === sym;
                  const info = VERIFIED_MARKET_CONTRACTS.TOKENS[sym];
                  return (
                    <button
                      key={sym}
                      type="button"
                      onClick={() => onSelectQuoteAsset(sym)}
                      className={`p-2 rounded-lg text-xs font-bold transition flex flex-col items-center justify-center cursor-pointer ${
                        active
                          ? "bg-cyan-400 text-black shadow"
                          : "bg-[#14182C] text-gray-300 hover:text-white border border-[#272E4D]"
                      }`}
                    >
                      <span>{sym}</span>
                      <span className="text-[9px] font-normal opacity-80">
                        ${info.priceUsd.toLocaleString()}
                      </span>
                    </button>
                  );
                })}
              </div>

              <div className="p-2.5 rounded-lg bg-[#090B15] border border-[#1B2038] text-[11px] text-gray-300 flex items-center justify-between">
                <span>Selected Liquidity Pair:</span>
                <strong className="text-white text-xs">
                  {activeToken?.symbol || "TOKEN"} / {quoteAsset} (
                  {(feeTier / 10000).toFixed(2)}% Fee Tier)
                </strong>
              </div>
            </div>
          </div>

          <div className="flex items-center justify-between pt-2">
            <button
              type="button"
              onClick={() => setWizardStep(1)}
              className="px-3.5 py-2 rounded-xl bg-[#161B30] hover:bg-[#1E2542] text-gray-300 hover:text-white border border-[#293152] text-xs font-bold flex items-center gap-1 cursor-pointer transition"
            >
              <ChevronLeft className="w-4 h-4" />
              <span>Back: Provider</span>
            </button>

            <button
              type="button"
              onClick={() => setWizardStep(3)}
              className="px-4 py-2 rounded-xl bg-[#F27D26] hover:bg-[#ff8d38] text-black font-bold text-xs flex items-center gap-1.5 cursor-pointer shadow transition"
            >
              <span>Next: Set Initial Price &amp; Confirm</span>
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      {/* =================================================================
          STEP 3: SET INITIAL POOL PRICE & SINGLE-BUTTON CONFIRMATION
         ================================================================= */}
      {wizardStep === 3 && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Initial Pool Price Configuration */}
            <div className="p-3.5 rounded-xl bg-[#0C0F1D] border border-[#222845] space-y-3">
              <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-emerald-400 uppercase flex items-center gap-1.5">
                  <DollarSign className="w-3.5 h-3.5" />
                  <span>Set Initial Pool Price (USD per {activeToken?.symbol})</span>
                </label>
                <button
                  type="button"
                  onClick={() => {
                    onChangeCustomInitialPriceUsd(null);
                    setPriceInputText(
                      marketCapDerivedPriceUsd < 0.01
                        ? marketCapDerivedPriceUsd.toFixed(6)
                        : marketCapDerivedPriceUsd.toFixed(4)
                    );
                  }}
                  className="text-[10px] text-amber-400 hover:underline cursor-pointer flex items-center gap-1"
                >
                  <RefreshCw className="w-3 h-3" />
                  <span>Reset to MCap Price</span>
                </button>
              </div>

              <div className="flex items-center gap-2">
                <div className="flex-1 flex items-center px-3 py-2 rounded-lg bg-[#14182C] border border-[#2B3254] focus-within:border-emerald-400">
                  <span className="text-gray-400 text-xs mr-1.5">$</span>
                  <input
                    type="number"
                    step="any"
                    min="0.000001"
                    value={priceInputText}
                    onChange={(e) => {
                      setPriceInputText(e.target.value);
                      const parsed = parseFloat(e.target.value);
                      if (!Number.isNaN(parsed) && parsed > 0) {
                        onChangeCustomInitialPriceUsd(parsed);
                      }
                    }}
                    className="w-full bg-transparent border-none text-sm font-black text-white focus:outline-none"
                    placeholder="0.0500"
                  />
                  <span className="text-[10px] text-gray-400 ml-2">
                    USD / {activeToken?.symbol}
                  </span>
                </div>
              </div>

              {/* Quick Price Multiplier Presets relative to Market Cap Derived Price */}
              <div className="flex items-center justify-between gap-1.5 text-[10px]">
                <span className="text-gray-400">Price Multipliers:</span>
                <div className="flex items-center gap-1">
                  {[
                    { label: "0.5x MCap", mult: 0.5 },
                    { label: "1.0x Parity", mult: 1.0 },
                    { label: "1.5x Premium", mult: 1.5 },
                    { label: "2.0x Launch", mult: 2.0 },
                  ].map((preset) => {
                    const targetPrice = Number(
                      (marketCapDerivedPriceUsd * preset.mult).toFixed(6)
                    );
                    return (
                      <button
                        key={preset.label}
                        type="button"
                        onClick={() => {
                          onChangeCustomInitialPriceUsd(
                            preset.mult === 1.0 ? null : targetPrice
                          );
                          setPriceInputText(
                            targetPrice < 0.01
                              ? targetPrice.toFixed(6)
                              : targetPrice.toFixed(4)
                          );
                        }}
                        className="px-2 py-0.5 rounded bg-[#161B30] hover:bg-[#222A4A] text-gray-300 hover:text-white border border-[#272F4F] cursor-pointer transition"
                      >
                        {preset.label}
                      </button>
                    );
                  })}
                </div>
              </div>

              <div className="p-2.5 rounded-lg bg-[#090B15] border border-[#1B2038] text-[11px] flex items-center justify-between">
                <span className="text-gray-400">Implied Exchange Ratio:</span>
                <strong className="text-cyan-300">
                  1 {activeToken?.symbol} ={" "}
                  {computedQuoteRatio < 0.0001
                    ? computedQuoteRatio.toExponential(3)
                    : computedQuoteRatio.toFixed(6)}{" "}
                  {quoteAsset}
                </strong>
              </div>
            </div>

            {/* Wizard Summary & Single-Confirmation Card */}
            <div className="p-3.5 rounded-xl bg-[#0C0F1D] border border-emerald-500/30 flex flex-col justify-between space-y-3">
              <div className="space-y-1.5">
                <div className="flex items-center justify-between text-xs">
                  <span className="font-bold text-white uppercase flex items-center gap-1.5">
                    <ShieldCheck className="w-4 h-4 text-emerald-400" />
                    <span>Ready for 1-Click Initialization</span>
                  </span>
                  <span className="text-[10px] text-emerald-400 font-bold">
                    {selectedAmm.name.split(" ")[0]}
                  </span>
                </div>

                {poolParams && (
                  <div className="grid grid-cols-2 gap-2 pt-1 text-[11px]">
                    <div className="p-2 rounded bg-[#090B15] border border-[#1B2038]">
                      <span className="text-[9px] text-gray-400 uppercase block">
                        Initial Pool Depth
                      </span>
                      <strong className="text-emerald-400">
                        ${Math.round(poolParams.totalInitialLiquidityUsd).toLocaleString()} USD
                      </strong>
                    </div>
                    <div className="p-2 rounded bg-[#090B15] border border-[#1B2038]">
                      <span className="text-[9px] text-gray-400 uppercase block">
                        Inventory Split
                      </span>
                      <strong className="text-white truncate block">
                        {poolParams.baseTokenAmountFormatted} {activeToken?.symbol} +{" "}
                        {poolParams.quoteAssetAmountFormatted} {quoteAsset}
                      </strong>
                    </div>
                  </div>
                )}
              </div>

              {/* Single Confirmation Button */}
              <div className="flex items-center justify-between gap-2 pt-1">
                <button
                  type="button"
                  onClick={() => setWizardStep(2)}
                  className="px-3 py-2.5 rounded-xl bg-[#161B30] hover:bg-[#1E2542] text-gray-300 hover:text-white border border-[#293152] text-xs font-bold flex items-center gap-1 cursor-pointer transition"
                >
                  <ChevronLeft className="w-3.5 h-3.5" />
                  <span>Back</span>
                </button>

                <button
                  type="button"
                  onClick={onConfirmAndInitialize}
                  disabled={isExecuting || !poolParams}
                  className="flex-1 py-2.5 px-4 rounded-xl bg-gradient-to-r from-emerald-500 via-[#F27D26] to-amber-500 hover:brightness-110 text-black font-black text-xs shadow-lg transition flex items-center justify-center gap-2 cursor-pointer disabled:opacity-50"
                >
                  {isExecuting ? (
                    <>
                      <RefreshCw className="w-4 h-4 animate-spin text-black" />
                      <span>{executionStage || "Initializing Pool..."}</span>
                    </>
                  ) : (
                    <>
                      <Zap className="w-4 h-4 text-black" />
                      <span>
                        Confirm &amp; Initialize {activeToken?.symbol}/{quoteAsset} Pool
                      </span>
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

