} from "recharts";
import { TokenRecord } from "../types";
import { TweEnvironmentKeyBundle } from "../config/tweEnvironmentKeys";
import {
  MAURO_SOVEREIGN_POSSESSION_UUID,
  MAURO_SOVEREIGN_OWNER,
  MAURO_UINT256_MAX_FORMATTED,
  MAURO_BOUND_ENV_KEYS,
} from "../utils/mauroSovereignWealthPossession";
import { RsiDynamicSignalPanel } from "./RsiDynamicSignalPanel";
import { MauroSovereignWealthPossessionsHub } from "./MauroSovereignWealthPossessionsHub";
import { MauroGoddessNftFrontPage } from "./MauroGoddessNftFrontPage";
import { TweCompleteMasterArchiveDownloadHub } from "./TweCompleteMasterArchiveDownloadHub";
import { ProjectArchive } from "./twe/ProjectArchive";
import { ReferenceStudio } from "./twe/ReferenceStudio";
import { TWEWorkspace } from "./twe/TWEWorkspace";

export type ManusPrimaryNavId =
  | "Projects"
  | "TWEAtlas"
  | "SessionSandbox"
  | "SourcesStudio"
  | "ProjectArchive"
  | "Gallery"
  | "Skills"
  | "Codes";

export type SandboxViewportMode =
  | "live-browser"
  | "vscode-editor"
  | "mobile-frame"
  | "artifact-preview";

export interface ManusSubTaskItem {
  id: string;
  title: string;
  moduleTag: string;
  status: "Completed" | "Active" | "Queued";
  durationMs: number;
  connector: "Drive" | "Gmail" | "Stripe" | "TWE-Enclave";
  detail: string;
}

export interface ManusActivityFeedEntry {
  id: string;
  actorName: string;
  actorHandle: string;
  avatarBg: string;
  avatarInitials: string;
  timestampLabel: string;
  actionSnippet: string;
  subAttribution?: {
    actor: string;
    verb: string;
    target: string;
    connector: "Drive" | "Gmail" | "Stripe" | "TWE";
  };
  badgeText: string;
}

export interface ManusTweWorkspaceRedesignProps {
  tokens: TokenRecord[];
  tweEnvConfig: TweEnvironmentKeyBundle;
  metaMaskAccount?: string | null;
  isMetaMaskConnected?: boolean;
  onGenerate100?: () => void;
  onSelectToken: (token: TokenRecord) => void;
  onTradeToken?: (token: TokenRecord, mode: "swap" | "sell") => void;
  onOpenSwap?: (token?: TokenRecord, mode?: "swap" | "sell") => void;
  onAddTokenToPortfolio: (token: TokenRecord) => void;
  onSendToRemix: (code: string, name: string) => void;
  onNavigateToClassicTab: (tabId: string) => void;
  onSwitchToClassicFullView: () => void;
  onOpenMetaMaskSync: () => void;
}

export const ManusTweWorkspaceRedesign: React.FC<ManusTweWorkspaceRedesignProps> = ({
  tokens,
  tweEnvConfig,
  metaMaskAccount,
  isMetaMaskConnected,
  onGenerate100,
  onSelectToken,
  onTradeToken,
  onOpenSwap,
  onAddTokenToPortfolio,
  onSendToRemix,
  onNavigateToClassicTab,
  onSwitchToClassicFullView,
  onOpenMetaMaskSync,
}) => {
  // Navigation & Surface Mode State
  const [activeNav, setActiveNav] = useState<ManusPrimaryNavId>("Projects");
  const [isObsidianDark, setIsObsidianDark] = useState<boolean>(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState<boolean>(false);
  const [selectedProjectSlug, setSelectedProjectSlug] = useState<string>("twe-core-agent");
  const [projectsExpanded, setProjectsExpanded] = useState<boolean>(true);
  const [newsExpanded, setNewsExpanded] = useState<boolean>(true);
  const [connectorsExpanded, setConnectorsExpanded] = useState<boolean>(true);

  // Split-Pane Session Sandbox (manus.im/app/L2s2pha43DT4TyygVztES4) State
  const [sandboxViewportMode, setSandboxViewportMode] =
    useState<SandboxViewportMode>("live-browser");
  const [sessionExecStatus, setSessionExecStatus] = useState<
    "Running" | "Completed" | "Waiting for User Input"
  >("Running");
  const [manualSandboxControl, setManualSandboxControl] = useState<boolean>(false);
  const [selectedSandboxFile, setSelectedSandboxFile] = useState<
    "ProjectArchive.tsx" | "ReferenceStudio.tsx" | "RsiDynamicSignalPanel.tsx"
  >("ReferenceStudio.tsx");

  // Center Column: Task Composer ("What can I do for you?")
  const [composerPrompt, setComposerPrompt] = useState<string>("");
  const [isVoiceListening, setIsVoiceListening] = useState<boolean>(false);
  const [isExecutingPrompt, setIsExecutingPrompt] = useState<boolean>(false);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  // Dual Multi-Agent Task Node Toggles
  const [agentNode1Active, setAgentNode1Active] = useState<boolean>(true);
  const [agentNode2Active, setAgentNode2Active] = useState<boolean>(true);

  // Interactive Console / Terminal Logs inside Status Cards
  const [terminalNode1Logs, setTerminalNode1Logs] = useState<string[]>([
    "[09:41:02] TWE-AGENT-01 :: Initializing incoming transaction token parser...",
    `[09:41:04] PARSED :: Token Inventory (${tokens.length || 102} active contracts verified)`,
    `[09:41:06] VAULT-CHECK :: UUID ${MAURO_SOVEREIGN_POSSESSION_UUID} (${MAURO_SOVEREIGN_OWNER})`,
    `[09:41:08] UINT256-MAX :: ${MAURO_UINT256_MAX_FORMATTED.slice(0, 38)}... verified`,
    "[09:41:10] STATUS :: matching wallet validations -> EIP-55 & CNSA-2.0 PASS",
  ]);

  const [terminalNode2Logs, setTerminalNode2Logs] = useState<string[]>([
    "[09:41:03] TWE-AGENT-02 :: Connecting Drive -> Gmail -> Stripe -> TWE ATS CLOB...",
    `[09:41:05] KEY-BIND :: ${MAURO_BOUND_ENV_KEYS.NEXT_PUBLIC_TWE_DEV_KEY.slice(0, 24)}...`,
    `[09:41:07] ANALYTICS :: Firebase Measurement ID ${MAURO_BOUND_ENV_KEYS.VITE_FIREBASE_MEASUREMENT_ID}`,
    "[09:41:09] EXCHANGE-SYNC :: Updating exchange rates across 193 UN Member States",
    "[09:41:12] READY :: Atomic DvP T+0 Settlement & RSI Signal Stream active",
  ]);

  // Step-by-Step Sub-task Timeline
  const [subTasks, setSubTasks] = useState<ManusSubTaskItem[]>([
    {
      id: "subtask-1",
      title: "matching wallet validations",
      moduleTag: "EIP-55 · MetaMask · Sovereign Vault",
      status: "Completed",
      durationMs: 142,
      connector: "TWE-Enclave",
      detail: `Validated ${MAURO_SOVEREIGN_OWNER} primary deployer & ${MAURO_SOVEREIGN_POSSESSION_UUID} possession credentials.`,
    },
    {
      id: "subtask-2",
      title: "parsing incoming transaction token list",
      moduleTag: `${tokens.length || 102} Tokens · ERC-20 / ERC-3643 / SPL`,
      status: "Completed",
      durationMs: 218,
      connector: "Drive",
      detail: `Indexed ${tokens.length || 102} live token contracts and synchronized Drive/Keep metadata manifests.`,
    },
    {
      id: "subtask-3",
      title: "updating exchange rates",
      moduleTag: "TWE ATS CLOB · Uniswap · 14-Period RSI",
      status: "Active",
      durationMs: 85,
      connector: "Stripe",
      detail:
        "Streaming real-time market cap fluctuations, NBBO spreads, and Wilder's RSI Buy/Sell triggers.",
    },
    {
      id: "subtask-4",
      title: "indexing Project Archive & Sources Studio",
      moduleTag: "L2s2pha43DT4TyygVztES4 · DRKqxy5haFhuVB96KsQTYx",
      status: "Completed",
      durationMs: 164,
      connector: "Gmail",
      detail:
        "Compiled TWE_SESSION_ARCHIVE.md, 4-page PDF implementation plan extract, and browser-local SHA-256 studio.",
    },
  ]);

  // Right Column: Collaboration & Activity Feed ("Operations & Activity Feed")
  const [activityFeed, setActivityFeed] = useState<ManusActivityFeedEntry[]>([
    {
      id: "act-1",
      actorName: "Mauro Dar",
      actorHandle: "@maurodar08",
      avatarBg: "bg-blue-600 text-white",
      avatarInitials: "MD",
      timestampLabel: "Just now",
      actionSnippet:
        "Synchronized Manus Session L2s2pha43DT4TyygVztES4 Split-Pane Cloud Sandbox, Project Archive, and Sources & Studio.",
      subAttribution: {
        actor: "Davin",
        verb: "initiated",
        target: "matching wallet validations across Drive & TWE Vault",
        connector: "Drive",
      },
      badgeText: "Sovereign Owner",
    },
    {
      id: "act-2",
      actorName: "Emsi Collaborator",
      actorHandle: "@emsi",
      avatarBg: "bg-emerald-600 text-white",
      avatarInitials: "EM",
      timestampLabel: "2m ago",
      actionSnippet:
        "Collaborator @emsi verified multi-agent connector corridor (Google Drive → Gmail → Stripe → TWE ATS).",
      subAttribution: {
        actor: "Amned",
        verb: "synchronized",
        target: "Stripe settlement webhook & token liquidity rates",
        connector: "Stripe",
      },
      badgeText: "Core Sync",
    },
    {
      id: "act-3",
      actorName: "Jasved Engine",
      actorHandle: "@jasved",
      avatarBg: "bg-slate-800 text-white",
      avatarInitials: "JV",
      timestampLabel: "6m ago",
      actionSnippet:
        "Completed automated audit of af230af8-bf63-4308-968a-9962ed14e565 (Treasures, Wealth, Asset).",
      subAttribution: {
        actor: "Jasved",
        verb: "archived",
        target:
          "115,792,089,237,316,195,423,570,985,008,687,907,853,269,984,665,640,564,039,457,584,007,913,129,639,935 units",
        connector: "Gmail",
      },
      badgeText: "Verified",
    },
  ]);

  const [notificationInput, setNotificationInput] = useState<string>("");
  const [copiedLinkId, setCopiedLinkId] = useState<string | null>(null);
  const [tickCounter, setTickCounter] = useState<number>(0);

  // Live tick for Analytics Widget Column
  useEffect(() => {
    if (!agentNode1Active && !agentNode2Active) return;
    const timer = setInterval(() => {
      setTickCounter((prev) => prev + 1);
    }, 3500);
    return () => clearInterval(timer);
  }, [agentNode1Active, agentNode2Active]);

  // Dynamic Analytics Data for the 3 Manus Analytics Cards
  const analyticsSeries = useMemo(() => {
    const basePoints = 12;
    const executionRateData = [];
    const apiHitChartData = [];
    const totalApiHits = 148920 + tickCounter * 37;

    for (let i = 0; i < basePoints; i++) {
      const phase = (i + tickCounter) * 0.65;
      const execRate = Math.min(
        99.9,
        Math.max(91.5, Number((96.2 + Math.sin(phase) * 2.8).toFixed(1)))
      );
      const apiHits = Math.round(1150 + Math.cos(phase * 0.9) * 340 + i * 28);
      executionRateData.push({
        time: `${i * 5}m`,
        rate: execRate,
      });
      apiHitChartData.push({
        time: `${i * 5}m`,
        hits: apiHits,
        validated: Math.round(apiHits * 0.94),
      });
    }

    return {
      executionRateData,
      apiHitChartData,
      currentExecutionRate:
        executionRateData[executionRateData.length - 1]?.rate || 98.4,
      currentApiHitsPerSec:
        apiHitChartData[apiHitChartData.length - 1]?.hits || 1420,
      totalApiHits,
    };
  }, [tickCounter]);

  const handleCopyUrl = (url: string, id: string) => {
    navigator.clipboard?.writeText(url);
    setCopiedLinkId(id);
    setTimeout(() => setCopiedLinkId(null), 2000);
  };

  const handleTriggerTrade = (token: TokenRecord, mode: "swap" | "sell") => {
    if (onTradeToken) {
      onTradeToken(token, mode);
    } else if (onOpenSwap) {
      onOpenSwap(token, mode);
    }
  };

  // Execute a task from the Core Task Composer ("What can I do for you?")
  const handleComposerSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = composerPrompt.trim();
    if (!trimmed) return;

    setIsExecutingPrompt(true);
    const timeStr = new Date().toTimeString().slice(0, 8);

    setTerminalNode1Logs((prev) => [
      ...prev.slice(-8),
      `[${timeStr}] USER-TASK :: "${trimmed}"`,
      `[${timeStr}] PARSING :: Executing matching wallet validations & token scan...`,
    ]);
    setTerminalNode2Logs((prev) => [
      ...prev.slice(-8),
      `[${timeStr}] AGENT-DISPATCH :: Routing task across Drive -> Gmail -> Stripe -> TWE...`,
      `[${timeStr}] COMPLETED :: Updated exchange rates & verified ${tokens.length} tokens.`,
    ]);

    setSubTasks((prev) => [
      {
        id: `subtask-${Date.now()}`,
        title: trimmed.toLowerCase(),
        moduleTag: "Manus TWE Agent · Live Execution",
        status: "Completed",
        durationMs: 112,
        connector: "TWE-Enclave",
        detail: `Executed conversational task against ${tokens.length} tokens and Sovereign Vault ${MAURO_SOVEREIGN_POSSESSION_UUID}.`,
      },
      ...prev.map((item) =>
        item.status === "Active" ? { ...item, status: "Completed" as const } : item
      ),
    ]);

    setActivityFeed((prev) => [
      {
        id: `act-${Date.now()}`,
        actorName: "Mauro Dar",
        actorHandle: "@maurodar08",
        avatarBg: "bg-blue-600 text-white",
        avatarInitials: "MD",
        timestampLabel: "Just now",
        actionSnippet: `User initiated task: ${trimmed}`,
        subAttribution: {
          actor: "Davin",
          verb: "executed",
          target: `automated pipeline for "${trimmed.slice(0, 36)}"`,
          connector: "TWE",
        },
        badgeText: "Live Task",
      },
      ...prev,
    ]);

    const lower = trimmed.toLowerCase();
    if ((lower.includes("generate") || lower.includes("mint")) && onGenerate100) {
      onGenerate100();
    } else if (lower.includes("archive") || lower.includes("pdf")) {
      setActiveNav("ProjectArchive");
    } else if (lower.includes("studio") || lower.includes("sha-256") || lower.includes("calldata")) {
      setActiveNav("SourcesStudio");
    } else if (lower.includes("sandbox") || lower.includes("l2s2")) {
      setActiveNav("SessionSandbox");
    }

    setComposerPrompt("");
    setTimeout(() => setIsExecutingPrompt(false), 400);
  };

  const handleRunQuickTask = (taskLabel: string) => {
    setComposerPrompt(taskLabel);
    const timeStr = new Date().toTimeString().slice(0, 8);
    setTerminalNode1Logs((prev) => [
      ...prev.slice(-8),
      `[${timeStr}] QUICK-ACTION :: ${taskLabel}`,
      `[${timeStr}] OK :: Synchronized ${tokens.length} token records with zero errors.`,
    ]);
    setActivityFeed((prev) => [
      {
        id: `act-${Date.now()}`,
        actorName: "Mauro Dar",
        actorHandle: "@maurodar08",
        avatarBg: "bg-blue-600 text-white",
        avatarInitials: "MD",
        timestampLabel: "Just now",
        actionSnippet: `User initiated task: ${taskLabel}`,
        subAttribution: {
          actor: "Amned",
          verb: "validated",
          target: taskLabel,
          connector: "Drive",
        },
        badgeText: "Executed",
      },
      ...prev,
    ]);
  };

  const handleSendNotification = (e: React.FormEvent) => {
    e.preventDefault();
    const msg = notificationInput.trim();
    if (!msg) return;

    setActivityFeed((prev) => [
      {
        id: `notif-${Date.now()}`,
        actorName: "Mauro Dar",
