import React, { useState } from "react";
import {
  ShieldCheck,
  Download,
  Check,
  ExternalLink,
  Copy,
  Layers,
  Award,
  Wallet,
  Eye,
  Heart,
} from "lucide-react";
import heroEmbraceImg from "../assets/images/nft_hero_mauro_goddess_embrace_1794160128696.jpg";
import genesisPortraitImg from "../assets/images/nft_genesis_card_mauro_goddess_hug_1794160129824.jpg";
import sacredMedallionImg from "../assets/images/nft_collection_sacred_unity_medallion_1794160131016.jpg";

export interface NftEditionItem {
  id: string;
  tokenId: string;
  title: string;
  subtitle: string;
  category: string;
  standard: "ERC-721 (1-of-1 Genesis)" | "ERC-721 Sovereign" | "ERC-1155 Open Vault";
  chain: "Ethereum Mainnet" | "Arbitrum One" | "Base L2";
  priceEth: number;
  priceUsd: number;
  royaltyBps: number;
  totalSupply: number;
  mintedCount: number;
  imageSrc: string;
  aspectLabel: string;
  inscription: string;
  attributes: Array<{ trait_type: string; value: string }>;
}

const MAURO_GODDESS_NFT_COLLECTION: NftEditionItem[] = [
  {
    id: "genesis-embrace-01",
