export interface MauroGoddessNftFrontPageProps {
  metaMaskAccount?: string | null;
  isMetaMaskConnected?: boolean;
  onOpenMetaMaskSync?: () => void;
  onNavigateToNftSuite?: () => void;
}

export const MauroGoddessNftFrontPage: React.FC<MauroGoddessNftFrontPageProps> = ({
  metaMaskAccount,
  isMetaMaskConnected,
  onOpenMetaMaskSync,
}) => {
  const [editions, setEditions] = useState<NftEditionItem[]>(
    MAURO_GODDESS_NFT_COLLECTION
  );
  const [selectedEditionId, setSelectedEditionId] = useState<string>(
    MAURO_GODDESS_NFT_COLLECTION[0].id
  );
  const [mintQuantity, setMintQuantity] = useState<number>(1);
  const [bidAmountEth, setBidAmountEth] = useState<string>("92.5");
  const [statusMessage, setStatusMessage] = useState<string>("");
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [isLightboxOpen, setIsLightboxOpen] = useState<boolean>(false);
  const [favoritedIds, setFavoritedIds] = useState<string[]>([
    "genesis-embrace-01",
    "renaissance-crest-02",
  ]);
  const [mintReceipts, setMintReceipts] = useState<
    Array<{
      receiptId: string;
      editionTitle: string;
      tokenId: string;
      quantity: number;
      totalEth: number;
      txHash: string;
      timestamp: string;
    }>
  >([]);
  const [imageFallbackMap, setImageFallbackMap] = useState<Record<string, boolean>>({});

  const activeEdition =
    editions.find((item) => item.id === selectedEditionId) || editions[0];

  const creatorBeneficiaryWallet =
    metaMaskAccount || "0x71C95911E9a5D330f4D621842EC243EE1343292e";

  const triggerBanner = (msg: string) => {
    setStatusMessage(msg);
    setTimeout(() => setStatusMessage(""), 5000);
  };

  const handleCopy = (value: string, label: string) => {
    navigator.clipboard.writeText(value);
    setCopiedField(label);
    triggerBanner(`Copied ${label} to clipboard.`);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleMintEdition = (target: NftEditionItem, qty: number) => {
    const cleanQty = Math.max(1, qty);
    const txHash = `0x${Array.from({ length: 64 }, (_, idx) =>
      ((target.id.charCodeAt(idx % target.id.length) + Date.now() + idx * 13) % 16)
        .toString(16)
    ).join("")}`;
    const totalEth = Number((target.priceEth * cleanQty).toFixed(4));

    setEditions((prev) =>
      prev.map((item) =>
        item.id === target.id
          ? {
              ...item,
              mintedCount: Math.min(
                item.totalSupply,
                item.mintedCount + cleanQty
              ),
            }
          : item
      )
    );

    const newReceipt = {
      receiptId: `NFT-MINT-${Date.now().toString().slice(-6)}`,
      editionTitle: target.title,
      tokenId: target.tokenId,
      quantity: cleanQty,
      totalEth,
      txHash,
      timestamp: new Date().toISOString(),
    };
    setMintReceipts((prev) => [newReceipt, ...prev.slice(0, 4)]);
    triggerBanner(
      `Minted ${cleanQty}x "${target.title}" (${target.tokenId}) — Tx ${txHash.slice(
        0,
        12
      )}... settled to ${creatorBeneficiaryWallet.slice(0, 10)}...`
    );
  };

  const handlePlaceBid = (e: React.FormEvent) => {
    e.preventDefault();
    const numericBid = parseFloat(bidAmountEth);
    if (Number.isNaN(numericBid) || numericBid <= 0) {
      triggerBanner("Enter a valid ETH bid amount.");
      return;
    }
    triggerBanner(
      `Institutional bid of ${numericBid.toFixed(
        2
      )} ETH ($${(numericBid * 3350).toLocaleString()}) recorded for ${
        activeEdition.title
      } (${activeEdition.tokenId}).`
    );
  };

  const handleExportNftMetadata = (edition: NftEditionItem) => {
    const metadataPayload = {
      name: edition.title,
      description: `${edition.subtitle} — Created and owned by Mauro Lomibao Dar III (Mauro Dar). ${edition.inscription}`,
      external_url: "https://tokenworldexchange.com/nft/mauro-goddess-embrace",
      creator: "Mauro Lomibao Dar III (maurodar08@gmail.com)",
      beneficiary_wallet: creatorBeneficiaryWallet,
      token_id: edition.tokenId,
      token_standard: edition.standard,
      chain: edition.chain,
      seller_fee_basis_points: edition.royaltyBps,
      fee_recipient: "0x71C95911E9a5D330f4D621842EC243EE1343292e",
      attributes: edition.attributes,
      timestamp: new Date().toISOString(),
    };

    const blob = new Blob([JSON.stringify(metadataPayload, null, 2)], {
      type: "application/json",
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `TWE_NFT_${edition.id}_Metadata.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    triggerBanner(`Downloaded ERC-721/ERC-1155 JSON metadata for ${edition.title}.`);
  };

  const toggleFavorite = (id: string) => {
    setFavoritedIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  return (
    <section
      aria-label="Sovereign NFT Front Page: Mauro L. Dar III & The Celestial Goddess"
      data-testid="mauro-goddess-nft-front-page"
      className="w-full rounded-2xl bg-[#0B0F17] border border-amber-500/30 text-slate-100 p-5 sm:p-7 space-y-8 shadow-2xl"
    >
      {/* Top Editorial Kicker & Sovereign Provenance Header */}
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 border-b border-slate-800/80 pb-5">
        <div className="space-y-1.5">
          <div className="flex flex-wrap items-center gap-2 text-xs text-amber-300/90 font-mono">
            <span>Sovereign NFT Front Page Premiere</span>
            <span aria-hidden="true">·</span>
            <span>Mauro Lomibao Dar III</span>
            <span aria-hidden="true">·</span>
            <span>Taurus Crest (05.06.1987)</span>
            <span aria-hidden="true">·</span>
            <span>ERC-721 &amp; EIP-2981 Verified</span>
          </div>
          <h1
            className="text-2xl sm:text-3xl lg:text-4xl font-bold tracking-tight text-white"
            style={{ textWrap: "balance" }}
          >
            The Sacred Embrace: Mauro L. Dar III &amp; The Celestial Goddess
          </h1>
          <p className="text-sm text-slate-300 max-w-3xl leading-relaxed">
            In Unity, All Truths Are One — Love, Wisdom, Compassion, and Justice.
            Official Genesis 1-of-1 and Sovereign Collector NFT Editions uniting
            Mauro Lomibao Dar III and the Celestial Goddess in an eternal embrace
            of golden starlight.
          </p>
        </div>

        {/* Creator Provenance & Wallet Actions */}
        <div className="flex flex-wrap items-center gap-3 shrink-0">
          <div className="flex items-center gap-3 px-3.5 py-2 rounded-xl bg-[#111726] border border-slate-800">
            <img
              src="/assets/aistudio/Screenshot_20261106-214227_X_503af3f6.jpg"
              alt="Mauro Lomibao Dar III — Creator Portrait"
              referrerPolicy="no-referrer"
              onError={(e) => {
                (e.currentTarget as HTMLImageElement).style.display = "none";
              }}
              className="w-10 h-10 rounded-lg object-cover border border-amber-400/50 shrink-0"
            />
            <div className="text-xs">
              <div className="font-semibold text-white">Mauro Lomibao Dar III</div>
              <div className="text-slate-400 font-mono text-[11px]">
                Sole Creator · 10% Perpetual Royalty
              </div>
            </div>
          </div>

          <button
            type="button"
            onClick={() => handleExportNftMetadata(activeEdition)}
            className="px-4 py-2.5 rounded-xl bg-[#141B2D] hover:bg-[#1B243B] border border-slate-700 text-xs font-medium text-slate-200 flex items-center gap-2 cursor-pointer transition whitespace-nowrap shrink-0"
          >
            <Download className="w-4 h-4 text-amber-400" />
            <span>Export NFT Metadata JSON</span>
          </button>
        </div>
      </div>

      {/* Status Notification Banner */}
      {statusMessage && (
        <div className="px-4 py-3 rounded-xl bg-amber-500/10 border border-amber-400/40 text-amber-200 text-xs font-mono flex items-center justify-between gap-3">
          <span>{statusMessage}</span>
          <button
            type="button"
            onClick={() => setStatusMessage("")}
            className="text-amber-300 hover:text-white cursor-pointer px-2"
          >
            Dismiss
          </button>
        </div>
      )}

      {/* Storefront Hero: Split-Screen Artwork Stage (7 Cols) + Contiguous Mint & Purchase Module (5 Cols) */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-7 items-stretch">
        {/* Left 7 Cols: Master Artwork Showcase */}
        <div className="lg:col-span-7 flex flex-col justify-between rounded-2xl bg-[#070A10] border border-slate-800/90 overflow-hidden">
          <div className="relative group w-full bg-[#05070B] flex items-center justify-center overflow-hidden min-h-[360px] sm:min-h-[460px]">
            {!imageFallbackMap[activeEdition.id] ? (
              <img
                src={activeEdition.imageSrc}
                alt={activeEdition.title}
                referrerPolicy="no-referrer"
                onError={() =>
                  setImageFallbackMap((prev) => ({
                    ...prev,
                    [activeEdition.id]: true,
