                onClick={() => setIsLightboxOpen(true)}
                className="w-full h-full max-h-[540px] object-contain cursor-zoom-in transition-transform duration-300 group-hover:scale-[1.01]"
              />
            ) : (
              <div className="p-12 text-center space-y-2">
                <Award className="w-12 h-12 text-amber-400 mx-auto" />
                <div className="text-base font-bold text-white">
                  {activeEdition.title}
                </div>
                <div className="text-xs text-slate-400">
                  {activeEdition.inscription}
                </div>
              </div>
            )}

            {/* Measured Scrim Overlay at Bottom of Artwork */}
            <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/90 via-black/55 to-transparent p-5 flex flex-col sm:flex-row sm:items-end justify-between gap-3">
              <div className="space-y-1">
                <div className="flex items-center gap-2 text-xs text-amber-300 font-mono">
                  <span>{activeEdition.tokenId}</span>
                  <span aria-hidden="true">·</span>
                  <span>{activeEdition.category}</span>
                  <span aria-hidden="true">·</span>
                  <span>{activeEdition.aspectLabel}</span>
                </div>
                <h2 className="text-lg sm:text-xl font-bold text-white">
                  {activeEdition.title}
                </h2>
                <p className="text-xs text-slate-300">{activeEdition.subtitle}</p>
              </div>

              <div className="flex items-center gap-2 shrink-0">
                <button
                  type="button"
                  onClick={() => toggleFavorite(activeEdition.id)}
                  className="px-3 py-1.5 rounded-lg bg-black/70 hover:bg-black/90 border border-slate-700 text-xs text-slate-200 flex items-center gap-1.5 cursor-pointer transition whitespace-nowrap shrink-0"
                >
                  <Heart
                    className={`w-3.5 h-3.5 ${
                      favoritedIds.includes(activeEdition.id)
                        ? "fill-rose-500 text-rose-500"
                        : "text-slate-300"
                    }`}
                  />
                  <span>
                    {favoritedIds.includes(activeEdition.id) ? "Saved" : "Save"}
                  </span>
                </button>
                <button
                  type="button"
                  onClick={() => setIsLightboxOpen(true)}
                  className="px-3 py-1.5 rounded-lg bg-black/70 hover:bg-black/90 border border-slate-700 text-xs text-slate-200 flex items-center gap-1.5 cursor-pointer transition whitespace-nowrap shrink-0"
                >
                  <Eye className="w-3.5 h-3.5 text-amber-400" />
                  <span>Inspect 8K Canvas</span>
                </button>
              </div>
            </div>
          </div>

          {/* Thumbnail Edition Switcher Strip */}
          <div className="p-4 bg-[#0D1320] border-t border-slate-800/80 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div className="flex items-center gap-3 overflow-x-auto w-full sm:w-auto pb-1 sm:pb-0">
              {editions.map((ed) => {
                const isSelected = ed.id === activeEdition.id;
                return (
                  <button
                    key={ed.id}
                    type="button"
                    data-testid={`select-nft-edition-${ed.id}`}
                    onClick={() => setSelectedEditionId(ed.id)}
                    className={`flex items-center gap-2.5 p-1.5 pr-3 rounded-xl border text-left transition cursor-pointer shrink-0 ${
                      isSelected
                        ? "bg-amber-500/15 border-amber-400 text-white"
                        : "bg-[#090D16] border-slate-800 text-slate-400 hover:border-slate-700 hover:text-slate-200"
                    }`}
                  >
                    <img
                      src={ed.imageSrc}
                      alt={ed.title}
                      referrerPolicy="no-referrer"
                      className="w-11 h-11 rounded-lg object-cover shrink-0"
                    />
                    <div>
                      <div className="text-xs font-semibold text-white whitespace-nowrap">
                        {ed.tokenId} · {ed.aspectLabel}
                      </div>
                      <div className="text-[11px] font-mono text-amber-300 tabular-nums">
                        {ed.priceEth.toFixed(1)} ETH
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>

            <div className="text-[11px] font-mono text-slate-400">
              Inscription: <span className="text-slate-200">TAURUS-1987-05-06</span>
            </div>
          </div>
        </div>

        {/* Right 5 Cols: Contiguous NFT Purchase, Mint & Royalty Module */}
        <div className="lg:col-span-5 rounded-2xl bg-[#101624] border border-slate-800 p-5 sm:p-6 flex flex-col justify-between space-y-6">
          <div className="space-y-5">
            {/* Edition Metadata & Standard */}
            <div className="flex flex-wrap items-center justify-between gap-2 text-xs text-slate-400 font-mono border-b border-slate-800 pb-3">
              <span>{activeEdition.standard}</span>
              <span aria-hidden="true">·</span>
              <span className="text-cyan-300">{activeEdition.chain}</span>
              <span aria-hidden="true">·</span>
              <span className="text-amber-300 tabular-nums">
                Minted: {activeEdition.mintedCount} / {activeEdition.totalSupply}
              </span>
            </div>

            {/* Valuation & Royalty Block */}
            <div className="grid grid-cols-2 gap-4 pt-1">
              <div>
                <div className="text-xs text-slate-400">Current Acquisition Price</div>
                <div className="text-2xl sm:text-3xl font-bold text-white font-mono tabular-nums mt-1">
                  {activeEdition.priceEth.toFixed(2)} ETH
                </div>
                <div className="text-xs text-slate-400 font-mono tabular-nums mt-0.5">
                  ${activeEdition.priceUsd.toLocaleString()} USD Equivalent
                </div>
              </div>

              <div>
                <div className="text-xs text-slate-400">Creator Royalty (EIP-2981)</div>
                <div className="text-2xl sm:text-3xl font-bold text-amber-400 font-mono tabular-nums mt-1">
                  {(activeEdition.royaltyBps / 100).toFixed(1)}%
                </div>
                <div className="text-xs text-slate-400 font-mono mt-0.5">
                  Direct to Mauro L. Dar III
                </div>
              </div>
            </div>

            {/* Quantity Stepper & Primary Mint CTA */}
            <div className="space-y-3 pt-2 border-t border-slate-800">
              <div className="flex items-center justify-between text-xs">
                <span className="text-slate-300 font-medium">
                  Edition Quantity
                </span>
                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={() => setMintQuantity((q) => Math.max(1, q - 1))}
                    className="w-8 h-8 rounded-lg bg-[#0B0F17] border border-slate-700 text-white font-mono cursor-pointer hover:bg-slate-800"
                  >
                    -
                  </button>
                  <span className="w-8 text-center font-mono font-bold text-white tabular-nums">
                    {mintQuantity}
                  </span>
                  <button
                    type="button"
                    onClick={() =>
                      setMintQuantity((q) =>
                        Math.min(Math.max(1, activeEdition.totalSupply), q + 1)
                      )
                    }
                    className="w-8 h-8 rounded-lg bg-[#0B0F17] border border-slate-700 text-white font-mono cursor-pointer hover:bg-slate-800"
                  >
