      {/* Featured 3-Column Collection Grid */}
      <div className="space-y-4 pt-2">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
          <div>
            <h2 className="text-lg sm:text-xl font-bold text-white">
              Featured Sacred Embrace NFT Editions
            </h2>
            <p className="text-xs text-slate-400">
              Select any edition below to inspect high-resolution brushwork, verify
              on-chain attributes, or mint directly to your wallet.
            </p>
          </div>
          <div className="text-xs font-mono text-slate-400 tabular-nums">
            3 Curated Editions · Total Floor Volume: 117.30 ETH
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {editions.map((item) => {
            const isCurrent = item.id === activeEdition.id;
            return (
              <article
                key={item.id}
                onClick={() => setSelectedEditionId(item.id)}
                className={`rounded-2xl bg-[#101624] border transition-all duration-200 hover:-translate-y-0.5 overflow-hidden flex flex-col justify-between cursor-pointer ${
                  isCurrent
                    ? "border-amber-400 shadow-xl"
                    : "border-slate-800 hover:border-slate-700"
                }`}
              >
                <div>
                  <div className="aspect-[4/3] w-full bg-[#070A10] overflow-hidden relative">
                    <img
                      src={item.imageSrc}
                      alt={item.title}
                      referrerPolicy="no-referrer"
                      className="w-full h-full object-cover"
                    />
                  </div>

                  <div className="p-5 space-y-2">
                    <div className="flex items-center gap-2 text-xs text-slate-400 font-mono">
                      <span>{item.category}</span>
                      <span aria-hidden="true">·</span>
                      <span>{item.tokenId}</span>
                    </div>
                    <h3 className="text-base font-semibold text-white leading-snug">
                      {item.title}
                    </h3>
                    <p className="text-xs text-slate-400 line-clamp-2">
                      {item.subtitle}
                    </p>
                  </div>
                </div>

                <div className="px-5 pb-5 pt-3 border-t border-slate-800/80 flex items-center justify-between gap-3">
                  <div className="font-mono">
                    <div className="text-sm font-bold text-white tabular-nums">
                      {item.priceEth.toFixed(2)} ETH
                    </div>
                    <div className="text-[11px] text-slate-400 tabular-nums">
                      ${item.priceUsd.toLocaleString()} · {item.mintedCount}/
                      {item.totalSupply} Minted
                    </div>
                  </div>

                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleMintEdition(item, 1);
                    }}
                    className="px-3.5 py-2 rounded-xl bg-amber-500/20 hover:bg-amber-500 hover:text-slate-950 border border-amber-400/50 text-amber-200 text-xs font-bold transition cursor-pointer whitespace-nowrap shrink-0"
                  >
                    Mint Edition
                  </button>
                </div>
              </article>
            );
          })}
        </div>
      </div>

      {/* Live On-Chain Mint Receipts Ledger */}
      {mintReceipts.length > 0 && (
        <div className="p-4 rounded-xl bg-[#101624] border border-emerald-500/40 space-y-2.5">
          <div className="flex items-center justify-between text-xs font-mono">
            <span className="text-emerald-300 font-bold flex items-center gap-1.5">
              <ShieldCheck className="w-4 h-4 text-emerald-400" />
              <span>Verified On-Chain NFT Mint &amp; Settlement Ledger</span>
            </span>
            <span className="text-slate-400 tabular-nums">
              {mintReceipts.length} Confirmed Transaction(s)
            </span>
          </div>
          <div className="space-y-1.5">
            {mintReceipts.map((rec) => (
              <div
                key={rec.receiptId}
                className="p-2.5 rounded-lg bg-[#0B0F17] border border-slate-800 flex flex-wrap items-center justify-between gap-2 text-xs font-mono"
              >
                <div className="text-white font-semibold">
                  {rec.receiptId} · {rec.quantity}x {rec.editionTitle} ({rec.tokenId})
                </div>
                <div className="flex items-center gap-3 text-slate-400 tabular-nums">
                  <span className="text-amber-300 font-bold">
                    {rec.totalEth} ETH
                  </span>
                  <span>Tx: {rec.txHash.slice(0, 14)}...</span>
                  <ExternalLink className="w-3.5 h-3.5 text-cyan-400" />
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Fullscreen Lightbox Inspector Modal */}
      {isLightboxOpen && (
        <div
          className="fixed inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4"
          onClick={() => setIsLightboxOpen(false)}
        >
          <div
            className="max-w-5xl w-full bg-[#0B0F17] border border-slate-700 rounded-2xl overflow-hidden shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="px-5 py-3.5 border-b border-slate-800 flex items-center justify-between">
              <div className="text-sm font-bold text-white">
                {activeEdition.title} ({activeEdition.tokenId})
              </div>
              <button
                type="button"
                onClick={() => setIsLightboxOpen(false)}
                className="px-3 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-xs text-white cursor-pointer"
              >
                Close Preview
              </button>
            </div>
            <div className="p-4 flex items-center justify-center bg-black max-h-[80vh] overflow-auto">
              <img
                src={activeEdition.imageSrc}
                alt={activeEdition.title}
                referrerPolicy="no-referrer"
                className="max-h-[74vh] w-auto object-contain rounded-lg"
              />
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

