import React, { useState, useEffect } from "react";
import {
  Crown,
  ShieldCheck,
  Coins,
  Gem,
  Landmark,
  Copy,
  Check,
  Plus,
  Download,
  Code2,
  Key,
  Sparkles,
  ExternalLink,
  Layers,
  Lock,
  CheckCircle2,
  FileJson,
  ArrowUpRight,
} from "lucide-react";
import { TokenRecord, ChainType } from "../types";
import { TweEnvironmentKeyBundle } from "../config/tweEnvironmentKeys";
import {
  MAURO_SOVEREIGN_POSSESSION_UUID,
  MAURO_SOVEREIGN_OWNER,
  MAURO_UINT256_MAX_FORMATTED,
  MAURO_UINT256_MAX_RAW,
  MAURO_UINT256_MAX_HEX,
  MAURO_BOUND_ENV_KEYS,
  SovereignPossessionPillar,
  SovereignWealthPossessionRecord,
  getMauroWealthPossessions,
  saveMauroWealthPossessions,
  createMauroWealthPossessionRecord,
  generateMauroPossessionSolidityContract,
  formatBigUintStringWithCommas,
} from "../utils/mauroSovereignWealthPossession";

interface MauroSovereignWealthPossessionsHubProps {
  tokens: TokenRecord[];
  tweEnvConfig: TweEnvironmentKeyBundle;
  onAddTokenToPortfolio?: (token: TokenRecord) => void;
  onSelectToken?: (token: TokenRecord) => void;
  onSendToRemix?: (solidityCode: string, contractName: string) => void;
  onNavigateToTab?: (tab: string) => void;
}

export const MauroSovereignWealthPossessionsHub: React.FC<
  MauroSovereignWealthPossessionsHubProps
> = ({
  tweEnvConfig,
  onAddTokenToPortfolio,
  onSelectToken,
  onSendToRemix,
  onNavigateToTab,
}) => {
  const [possessions, setPossessions] = useState<SovereignWealthPossessionRecord[]>(() =>
    getMauroWealthPossessions()
  );
  const [selectedPossessionId, setSelectedPossessionId] = useState<string>(
    MAURO_SOVEREIGN_POSSESSION_UUID
  );
  const [activePillarFilter, setActivePillarFilter] = useState<
    "ALL" | SovereignPossessionPillar
  >("ALL");
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showSolidityPreview, setShowSolidityPreview] = useState<boolean>(false);
  const [isCreatorModalOpen, setIsCreatorModalOpen] = useState<boolean>(false);
  const [showAdminSecret, setShowAdminSecret] = useState<boolean>(false);
  const [statusBanner, setStatusBanner] = useState<string | null>(null);

  // New Asset & Wealth Possession creation form state
  const [newTitle, setNewTitle] = useState<string>(
    "Mauro Dar Sovereign Treasures, Wealth & Asset Reserve Vault"
  );
  const [newSymbol, setNewSymbol] = useState<string>("TWA-MDAR");
  const [newOwner, setNewOwner] = useState<string>(MAURO_SOVEREIGN_OWNER);
  const [newUuid, setNewUuid] = useState<string>(MAURO_SOVEREIGN_POSSESSION_UUID);
  const [newQuantityRaw, setNewQuantityRaw] = useState<string>(MAURO_UINT256_MAX_RAW);
  const [newChain, setNewChain] = useState<ChainType>("ethereum");
  const [newPillars, setNewPillars] = useState<SovereignPossessionPillar[]>([
    "Treasures",
    "Wealth",
    "Asset",
  ]);
  const [newCollateralDesc, setNewCollateralDesc] = useState<string>(
    "Omniversal Sovereign Treasures, Wealth & Asset Possession backed by 2^256 - 1 uint256 units on Token World Exchange ATS®."
  );

  // Sync with backend API ledger on mount
  useEffect(() => {
    fetch("/api/twe/wealth-possessions")
      .then((res) => (res.ok ? res.json() : null))
      .then((data) => {
        if (data && Array.isArray(data.possessions) && data.possessions.length > 0) {
          setPossessions((prev) => {
            const byId = new Map<string, SovereignWealthPossessionRecord>();
            prev.forEach((p) => byId.set(p.id, p));
            data.possessions.forEach((p: SovereignWealthPossessionRecord) => {
              if (!byId.has(p.id)) {
                byId.set(p.id, p);
              }
            });
            const merged = Array.from(byId.values());
            saveMauroWealthPossessions(merged);
            return merged;
          });
        }
      })
      .catch(() => {
        // Fallback to localStorage ledger
      });
  }, []);

  const handleCopy = (text: string, label: string) => {
    navigator.clipboard?.writeText(text).catch(() => {});
    setCopiedField(label);
    setTimeout(() => setCopiedField(null), 2200);
  };

  const filteredPossessions = possessions.filter((item) => {
    if (activePillarFilter === "ALL") return true;
    return item.pillars.includes(activePillarFilter);
  });

  const activePossession =
    possessions.find((p) => p.id === selectedPossessionId) || possessions[0];

  const handleToggleNewPillar = (pillar: SovereignPossessionPillar) => {
    setNewPillars((prev) => {
      if (prev.includes(pillar)) {
        if (prev.length === 1) return prev; // Keep at least one classification
        return prev.filter((p) => p !== pillar);
      }
      return [...prev, pillar];
    });
  };

  const handleCreatePossession = async (e: React.FormEvent) => {
    e.preventDefault();
    const { possession, tokenRecord } = createMauroWealthPossessionRecord({
      title: newTitle,
      symbol: newSymbol,
      owner: newOwner,
      possessionUuid:
        possessions.some((p) => p.id === newUuid)
          ? `${MAURO_SOVEREIGN_POSSESSION_UUID}-${Date.now().toString(16).slice(-4)}`
          : newUuid,
      pillars: newPillars,
      quantityRaw: newQuantityRaw,
      chain: newChain,
      collateralDescription: newCollateralDesc,
      nextPublicTweDevKey:
        tweEnvConfig?.NEXT_PUBLIC_TWE_DEV_KEY ||
        MAURO_BOUND_ENV_KEYS.NEXT_PUBLIC_TWE_DEV_KEY,
      firebaseMeasurementId:
        tweEnvConfig?.VITE_FIREBASE_MEASUREMENT_ID ||
        MAURO_BOUND_ENV_KEYS.VITE_FIREBASE_MEASUREMENT_ID,
      tweAdminSecret:
        tweEnvConfig?.TWE_ADMIN_SECRET || MAURO_BOUND_ENV_KEYS.TWE_ADMIN_SECRET,
    });

    const updated = [possession, ...possessions];
    setPossessions(updated);
    saveMauroWealthPossessions(updated);
    setSelectedPossessionId(possession.id);

    if (onAddTokenToPortfolio) {
      onAddTokenToPortfolio(tokenRecord);
    }

    // Persist to backend API ledger as well
    try {
      await fetch("/api/twe/wealth-possessions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ possession }),
      });
    } catch {
      // Local ledger already updated
    }

    setIsCreatorModalOpen(false);
    setStatusBanner(
      `Minted & Registered "${possession.title}" (${possession.symbol}) for Owner ${possession.owner} with ${possession.quantityFormatted} units (${possession.possessionUuid}).`
    );
    setTimeout(() => setStatusBanner(null), 7000);
  };

  const handleDownloadPossessionCertificate = (
    target: SovereignWealthPossessionRecord
  ) => {
    const certificatePayload = {
      certificateType:
        "TOKEN_WORLD_EXCHANGE_ATS_SOVEREIGN_TREASURES_WEALTH_ASSET_POSSESSION_DEED",
      possessionUuid: target.possessionUuid,
      owner: target.owner,
      ownerLegalIdentity: target.ownerLegalIdentity,
      ownerEmail: target.ownerEmail,
      ownerWalletAddress: target.ownerWalletAddress,
      classifications: target.pillars,
      quantityFormatted: target.quantityFormatted,
      quantityRawUint256: target.quantityRawUint256,
      quantityHexUint256: target.quantityHexUint256,
      mathematicalFormula: "2^256 - 1 (MAX_UINT256)",
      environmentCredentials: {
        NEXT_PUBLIC_TWE_DEV_KEY: MAURO_BOUND_ENV_KEYS.NEXT_PUBLIC_TWE_DEV_KEY,
        VITE_FIREBASE_MEASUREMENT_ID: MAURO_BOUND_ENV_KEYS.VITE_FIREBASE_MEASUREMENT_ID,
        TWE_ADMIN_SECRET: MAURO_BOUND_ENV_KEYS.TWE_ADMIN_SECRET,
      },
      onChainSpecifications: {
        chain: target.chain,
        networkId: target.networkId,
        contractAddress: target.contractAddress,
        treasuryVaultAddress: target.treasuryVaultAddress,
        tokenStandard: target.tokenStandard,
        cusip: target.cusip,
        isin: target.isin,
        secFileNumber: target.secFileNumber,
        finraCrd: target.finraCrd,
        dtccFastId: target.dtccFastId,
        txHash: target.txHash,
      },
      solidityContractCode: generateMauroPossessionSolidityContract(target),
      issuedAt: new Date().toISOString(),
    };

    const blob = new Blob([JSON.stringify(certificatePayload, null, 2)], {
      type: "application/json",
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `Mauro_Dar_Sovereign_Possession_${target.possessionUuid}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const envBlockString = [
    `NEXT_PUBLIC_TWE_DEV_KEY="${MAURO_BOUND_ENV_KEYS.NEXT_PUBLIC_TWE_DEV_KEY}"`,
    `VITE_FIREBASE_MEASUREMENT_ID="${MAURO_BOUND_ENV_KEYS.VITE_FIREBASE_MEASUREMENT_ID}"`,
    `TWE_SOVEREIGN_POSSESSION_ID="${MAURO_SOVEREIGN_POSSESSION_UUID}"`,
    `TWE_SOVEREIGN_POSSESSION_CLASSES="Treasures, Wealth, Asset"`,
    `TWE_ADMIN_SECRET="${MAURO_BOUND_ENV_KEYS.TWE_ADMIN_SECRET}"`,
    `TWE_SOVEREIGN_POSSESSION_OWNER="${MAURO_SOVEREIGN_OWNER}"`,
    `TWE_SOVEREIGN_POSSESSION_BALANCE="${MAURO_UINT256_MAX_FORMATTED}"`,
  ].join("\n");

  return (
    <section
      id="mauro-sovereign-wealth-possessions-hub"
      data-testid="mauro-sovereign-wealth-possessions-hub"
      className="max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8"
    >
      <div className="rounded-2xl bg-gradient-to-br from-[#0B0F17] via-[#0F1420] to-[#0A131A] border border-amber-500/40 shadow-[0_0_50px_rgba(245,158,11,0.12)] overflow-hidden">
        {/* Top Sovereign Status Ribbon */}
        <div className="px-5 py-3 bg-gradient-to-r from-amber-500/20 via-emerald-500/15 to-cyan-500/20 border-b border-amber-500/30 flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2.5">
            <span className="inline-flex items-center justify-center w-7 h-7 rounded-lg bg-amber-500/20 border border-amber-400/50 text-amber-300">
              <Crown className="w-4 h-4" />
            </span>
            <div>
              <div className="flex items-center gap-2 flex-wrap">
                <span className="text-xs font-mono font-bold uppercase tracking-wider text-amber-300">
                  SOVEREIGN TREASURES, WEALTH & ASSET POSSESSIONS LEDGER
                </span>
                <span className="px-2 py-0.5 rounded bg-emerald-500/20 border border-emerald-500/40 text-[10px] font-mono font-bold text-emerald-300">
                  OWNER: {MAURO_SOVEREIGN_OWNER.toUpperCase()}
                </span>
                <span className="px-2 py-0.5 rounded bg-amber-500/20 border border-amber-500/40 text-[10px] font-mono font-bold text-amber-200">
                  UUID: {MAURO_SOVEREIGN_POSSESSION_UUID}
                </span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2 flex-wrap">
            <button
              type="button"
              data-testid="open-create-wealth-possession-modal-btn"
              onClick={() => setIsCreatorModalOpen(true)}
              className="px-3.5 py-1.5 rounded-lg bg-gradient-to-r from-amber-500 to-emerald-500 hover:from-amber-400 hover:to-emerald-400 text-slate-950 font-mono font-bold text-xs flex items-center gap-1.5 shadow-md cursor-pointer transition-all"
            >
              <Plus className="w-3.5 h-3.5" />
              Create / Mint Asset & Wealth Possession
            </button>
            <button
              type="button"
              onClick={() => handleDownloadPossessionCertificate(activePossession)}
              className="px-3 py-1.5 rounded-lg bg-slate-900/90 hover:bg-slate-800 border border-amber-500/40 text-amber-200 font-mono text-xs flex items-center gap-1.5 cursor-pointer transition-colors"
            >
              <Download className="w-3.5 h-3.5 text-amber-400" />
              Export Possession Deed (.JSON)
            </button>
          </div>
        </div>

        {/* Status Notification Banner */}
        {statusBanner && (
          <div className="mx-5 mt-4 p-3 rounded-xl bg-emerald-950/70 border border-emerald-500/50 text-emerald-200 text-xs font-mono flex items-center justify-between gap-3">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
              <span>{statusBanner}</span>
            </div>
            <button
              type="button"
              onClick={() => setStatusBanner(null)}
              className="text-emerald-400 hover:text-white px-2 cursor-pointer"
            >
              ✕
            </button>
          </div>
        )}

        <div className="p-5 sm:p-6 space-y-6">
          {/* Primary Hero Card: Exact 78-Digit MAX_UINT256 Balance & Owner Identity */}
          <div className="p-5 rounded-2xl bg-gradient-to-r from-slate-950 via-[#111827] to-slate-950 border border-amber-500/40 relative overflow-hidden">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-center">
              <div className="lg:col-span-8 space-y-3">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="px-2.5 py-1 rounded-md bg-amber-500/20 border border-amber-500/40 text-amber-300 text-xs font-mono font-bold flex items-center gap-1.5">
                    <Gem className="w-3.5 h-3.5" />
                    Treasures
                  </span>
                  <span className="px-2.5 py-1 rounded-md bg-emerald-500/20 border border-emerald-500/40 text-emerald-300 text-xs font-mono font-bold flex items-center gap-1.5">
                    <Coins className="w-3.5 h-3.5" />
                    Wealth
                  </span>
                  <span className="px-2.5 py-1 rounded-md bg-cyan-500/20 border border-cyan-500/40 text-cyan-300 text-xs font-mono font-bold flex items-center gap-1.5">
                    <Landmark className="w-3.5 h-3.5" />
                    Asset
                  </span>
                  <span className="px-2.5 py-1 rounded-md bg-purple-500/20 border border-purple-500/40 text-purple-300 text-xs font-mono font-bold">
                    2²⁵⁶ - 1 (MAX_UINT256)
                  </span>
                </div>

                <div>
                  <div className="text-[11px] font-mono uppercase tracking-widest text-slate-400">
                    TOTAL VERIFIED SOVEREIGN ASSET & WEALTH POSSESSION UNITS (78 DECIMAL DIGITS)
                  </div>
                  <div
                    data-testid="mauro-dar-uint256-max-balance"
                    className="mt-1.5 p-3.5 rounded-xl bg-black/70 border border-amber-500/50 font-mono text-sm sm:text-base md:text-lg font-black text-amber-300 break-all leading-relaxed tabular-nums tracking-tight shadow-inner"
                  >
                    {MAURO_UINT256_MAX_FORMATTED}
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5 pt-1">
                  <div className="p-2.5 rounded-lg bg-slate-900/90 border border-slate-800">
                    <div className="text-[10px] font-mono text-slate-400 uppercase">
                      Sole Registered Owner
                    </div>
                    <div
                      data-testid="mauro-dar-possession-owner"
                      className="text-sm font-mono font-bold text-white mt-0.5 flex items-center gap-1.5"
                    >
                      <ShieldCheck className="w-4 h-4 text-emerald-400 shrink-0" />
                      {MAURO_SOVEREIGN_OWNER}
                    </div>
                    <div className="text-[10px] font-mono text-slate-400 mt-0.5">
                      Mauro Lomibao Dar III • maurodar08@gmail.com
                    </div>
                  </div>

                  <div className="p-2.5 rounded-lg bg-slate-900/90 border border-slate-800">
                    <div className="text-[10px] font-mono text-slate-400 uppercase flex items-center justify-between">
                      <span>Possession Vault UUID</span>
                      <button
                        type="button"
                        onClick={() =>
                          handleCopy(MAURO_SOVEREIGN_POSSESSION_UUID, "uuid")
                        }
                        className="text-amber-400 hover:text-amber-300 flex items-center gap-1 cursor-pointer"
                      >
                        {copiedField === "uuid" ? (
                          <Check className="w-3 h-3 text-emerald-400" />
                        ) : (
                          <Copy className="w-3 h-3" />
                        )}
                        <span>{copiedField === "uuid" ? "Copied" : "Copy"}</span>
                      </button>
                    </div>
                    <div
                      data-testid="mauro-dar-possession-uuid"
                      className="text-xs font-mono font-bold text-amber-300 mt-1 break-all"
                    >
                      {MAURO_SOVEREIGN_POSSESSION_UUID}
                    </div>
                  </div>

                  <div className="p-2.5 rounded-lg bg-slate-900/90 border border-slate-800">
                    <div className="text-[10px] font-mono text-slate-400 uppercase flex items-center justify-between">
                      <span>256-Bit Hexadecimal Proof</span>
                      <button
                        type="button"
                        onClick={() => handleCopy(MAURO_UINT256_MAX_HEX, "hex")}
                        className="text-cyan-400 hover:text-cyan-300 flex items-center gap-1 cursor-pointer"
                      >
                        {copiedField === "hex" ? (
                          <Check className="w-3 h-3 text-emerald-400" />
                        ) : (
                          <Copy className="w-3 h-3" />
                        )}
                        <span>{copiedField === "hex" ? "Copied" : "Copy"}</span>
                      </button>
                    </div>
                    <div className="text-[11px] font-mono font-bold text-cyan-300 mt-1 truncate">
                      {MAURO_UINT256_MAX_HEX}
                    </div>
                    <div className="text-[10px] font-mono text-slate-400 mt-0.5">
                      64× &apos;f&apos; nibbles • type(uint256).max
                    </div>
                  </div>
                </div>
              </div>

              {/* Right Column: Bound Environment Keys & Enclave Verification */}
              <div className="lg:col-span-4 p-4 rounded-xl bg-slate-900/95 border border-emerald-500/30 space-y-3">
