                      </button>
                    </div>
                    <div
                      data-testid="bound-twe-admin-secret"
                      className="text-emerald-300 font-bold break-all mt-0.5"
                    >
                      {showAdminSecret
                        ? MAURO_BOUND_ENV_KEYS.TWE_ADMIN_SECRET
                        : "twe_live_sk_admin_9f8e7d6c••••••••••••••••••••_2026"}
                    </div>
                  </div>
                </div>

                <div className="pt-1 flex flex-wrap gap-2">
                  <button
                    type="button"
                    onClick={() =>
                      handleCopy(MAURO_UINT256_MAX_FORMATTED, "formatted_balance")
                    }
                    className="flex-1 py-1.5 px-2.5 rounded-lg bg-amber-500/20 hover:bg-amber-500/30 border border-amber-500/40 text-amber-200 font-mono text-[11px] font-bold flex items-center justify-center gap-1.5 cursor-pointer"
                  >
                    {copiedField === "formatted_balance" ? (
                      <Check className="w-3.5 h-3.5 text-emerald-400" />
