                  {onSendToRemix && (
                    <button
                      type="button"
                      onClick={() =>
                        onSendToRemix(
                          generateMauroPossessionSolidityContract(activePossession),
                          `${activePossession.symbol.replace(/[^a-zA-Z0-9]/g, "")}PossessionVault.sol`
