      </div>

      {/* Interactive Modal to Create / Mint New Sovereign Asset & Wealth Possession */}
      {isCreatorModalOpen && (
        <div
          data-testid="create-wealth-possession-modal"
          className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto"
        >
          <div className="bg-[#0D111A] border border-amber-500/50 rounded-2xl max-w-2xl w-full p-6 space-y-5 shadow-2xl">
            <div className="flex items-center justify-between border-b border-slate-800 pb-3">
              <div className="flex items-center gap-2.5">
                <Crown className="w-5 h-5 text-amber-400" />
                <div>
                  <h3 className="text-base font-bold text-white font-mono">
                    Create New Sovereign Asset & Wealth Possession
                  </h3>
                  <p className="text-xs text-slate-400 font-mono">
                    Owner: {MAURO_SOVEREIGN_OWNER} • UUID: {MAURO_SOVEREIGN_POSSESSION_UUID}
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setIsCreatorModalOpen(false)}
                className="text-slate-400 hover:text-white px-2 py-1 rounded cursor-pointer"
              >
                ✕
              </button>
            </div>

            <form onSubmit={handleCreatePossession} className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-mono text-slate-300 mb-1">
                    Possession Title
