                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-mono text-slate-300 mb-1">
                    Ticker Symbol
                  </label>
                  <input
                    type="text"
                    value={newSymbol}
                    onChange={(e) => setNewSymbol(e.target.value)}
                    className="w-full px-3 py-2 rounded-lg bg-slate-950 border border-slate-700 text-xs font-mono text-amber-300 font-bold"
                    required
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div>
                  <label className="block text-xs font-mono text-slate-300 mb-1">
                    Registered Owner
                  </label>
                  <input
                    type="text"
                    value={newOwner}
                    onChange={(e) => setNewOwner(e.target.value)}
                    className="w-full px-3 py-2 rounded-lg bg-slate-950 border border-slate-700 text-xs font-mono text-emerald-300 font-bold"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-mono text-slate-300 mb-1">
                    Possession UUID
                  </label>
                  <input
                    type="text"
                    value={newUuid}
                    onChange={(e) => setNewUuid(e.target.value)}
                    className="w-full px-3 py-2 rounded-lg bg-slate-950 border border-slate-700 text-xs font-mono text-slate-200"
                  />
                </div>
                <div>
                  <label className="block text-xs font-mono text-slate-300 mb-1">
                    Target Blockchain Network
                  </label>
                  <select
                    value={newChain}
                    onChange={(e) => setNewChain(e.target.value as ChainType)}
                    className="w-full px-3 py-2 rounded-lg bg-slate-950 border border-slate-700 text-xs font-mono text-white"
                  >
                    <option value="ethereum">Ethereum Mainnet (Chain 1)</option>
                    <option value="base">Base Mainnet (Chain 8453)</option>
                    <option value="polygon">Polygon PoS (Chain 137)</option>
                    <option value="arbitrum">Arbitrum One (Chain 42161)</option>
                    <option value="solana">Solana Mainnet-Beta (SPL)</option>
                  </select>
                </div>
              </div>

              <div>
                <div className="flex items-center justify-between mb-1">
                  <label className="text-xs font-mono text-slate-300">
                    Possession Classifications (Select Pillars)
                  </label>
                </div>
                <div className="flex items-center gap-2">
                  {(["Treasures", "Wealth", "Asset"] as SovereignPossessionPillar[]).map(
                    (pillar) => {
                      const active = newPillars.includes(pillar);
                      return (
                        <button
                          key={pillar}
                          type="button"
                          onClick={() => handleToggleNewPillar(pillar)}
                          className={`px-3 py-1.5 rounded-lg text-xs font-mono font-bold border cursor-pointer ${
                            active
                              ? "bg-amber-500/25 border-amber-400 text-amber-200"
                              : "bg-slate-900 border-slate-800 text-slate-400"
                          }`}
                        >
                          {active ? "✓ " : ""}
                          {pillar}
                        </button>
                      );
                    }
                  )}
                </div>
              </div>

              <div>
                <div className="flex items-center justify-between mb-1">
                  <label className="text-xs font-mono text-slate-300">
                    Possession Quantity (uint256 Raw or Formatted)
                  </label>
                  <button
                    type="button"
                    onClick={() => setNewQuantityRaw(MAURO_UINT256_MAX_RAW)}
                    className="text-[11px] font-mono text-amber-400 hover:underline cursor-pointer"
                  >
                    Set to 2²⁵⁶ - 1 (MAX_UINT256)
                  </button>
                </div>
                <textarea
                  rows={2}
                  value={newQuantityRaw}
                  onChange={(e) => setNewQuantityRaw(e.target.value)}
                  className="w-full px-3 py-2 rounded-lg bg-slate-950 border border-amber-500/50 text-xs font-mono text-amber-300 font-bold break-all"
                  required
                />
                <div className="text-[11px] font-mono text-slate-400 mt-1 break-all">
                  Formatted:{" "}
                  <span className="text-emerald-300">
                    {formatBigUintStringWithCommas(newQuantityRaw)}
                  </span>
                </div>
              </div>

              <div>
                <label className="block text-xs font-mono text-slate-300 mb-1">
                  Collateral & Sovereign Backing Specification
                </label>
                <input
                  type="text"
                  value={newCollateralDesc}
                  onChange={(e) => setNewCollateralDesc(e.target.value)}
                  className="w-full px-3 py-2 rounded-lg bg-slate-950 border border-slate-700 text-xs font-mono text-slate-200"
                />
              </div>

              <div className="flex items-center justify-end gap-2 pt-2 border-t border-slate-800">
                <button
                  type="button"
                  onClick={() => setIsCreatorModalOpen(false)}
                  className="px-4 py-2 rounded-lg bg-slate-800 hover:bg-slate-700 text-xs font-mono text-slate-300 cursor-pointer"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  data-testid="submit-create-wealth-possession-btn"
                  className="px-4 py-2 rounded-lg bg-gradient-to-r from-amber-500 to-emerald-500 hover:from-amber-400 hover:to-emerald-400 text-slate-950 font-mono font-bold text-xs cursor-pointer shadow-lg"
                >
                  Mint & Register Sovereign Possession
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </section>
  );
};

