import React, { useState } from "react";
import { 
  Mail, 
  Send, 
  Copy, 
  Check, 
  ExternalLink, 
  MessageSquare, 
  X, 
  ShieldCheck, 
  Sparkles, 
  MapPin, 
  User, 
  CheckCircle2,
  Share2
} from "lucide-react";

interface MessageCreatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  defaultTopic?: string;
}

const TOPIC_PRESETS = [
  {
    id: "general",
    label: "General Inquiry",
    subject: "Inquiry: Token World Exchange ATS®",
    body: "Hello Mauro,\n\nI am contacting you regarding the Token World Exchange ATS® platform.\n\nBest regards,\n[Your Name]"
  },
  {
    id: "licensing",
    label: "Token Licensing & ATS Listing",
    subject: "Token Licensing & Listing Request - Token World Exchange",
    body: "Hello Mauro,\n\nWe would like to discuss token licensing and listing opportunities on Token World Exchange ATS®.\n\nProject details:\n\nLooking forward to hearing from you,\n[Your Name]"
  },
  {
    id: "institutional",
    label: "Institutional Liquidity & Clearing",
    subject: "Institutional Liquidity & Clearing Inquiry",
    body: "Hello Mauro,\n\nWe are interested in discussing institutional liquidity provider arrangements and Rule 15c3-5 compliant routing.\n\nOrganization:\nContact info:\n\nRegards,\n[Your Name]"
  },
  {
    id: "partnership",
    label: "Web3 & Foundry Partnership",
    subject: "Web3 Partnership Opportunity - Mauro Dar",
    body: "Hi Mauro,\n\nI reviewed your Token World Exchange ATS® and synthetic foundry architecture and would love to connect on a collaboration.\n\nDetails:\n\nCheers,\n[Your Name]"
  }
];

export const MessageCreatorModal: React.FC<MessageCreatorModalProps> = ({
  isOpen,
  onClose,
  defaultTopic = "general"
}) => {
  const creatorEmail = "maurodar08@gmail.com";
  const twitterHandle = "maurodar08";
  const twitterProfileUrl = "https://x.com/maurodar08";
  const twitterAltUrl = "https://twitter.com/maurodar08";

  const [selectedTopic, setSelectedTopic] = useState(
    TOPIC_PRESETS.find((t) => t.id === defaultTopic) || TOPIC_PRESETS[0]
  );
  const [senderName, setSenderName] = useState("");
  const [senderEmail, setSenderEmail] = useState("");
  const [customSubject, setCustomSubject] = useState(selectedTopic.subject);
  const [customBody, setCustomBody] = useState(selectedTopic.body);
  const [copiedType, setCopiedType] = useState<"email" | "twitter" | "message" | null>(null);

  if (!isOpen) return null;

  const handleTopicChange = (topicId: string) => {
    const t = TOPIC_PRESETS.find((item) => item.id === topicId);
    if (t) {
      setSelectedTopic(t);
      setCustomSubject(t.subject);
      setCustomBody(t.body);
    }
  };

  const handleCopy = (text: string, type: "email" | "twitter" | "message") => {
    navigator.clipboard.writeText(text);
    setCopiedType(type);
    setTimeout(() => setCopiedType(null), 2500);
  };

  const mailtoHref = `mailto:${creatorEmail}?subject=${encodeURIComponent(
    customSubject
  )}&body=${encodeURIComponent(
    customBody + (senderName || senderEmail ? `\n\nSent by: ${senderName} (${senderEmail})` : "")
  )}`;

  const tweetIntentHref = `https://x.com/intent/tweet?text=${encodeURIComponent(
    `@${twitterHandle} Hello Mauro! Regarding Token World Exchange ATS®: `
  )}`;

  return (
    <div 
      className="fixed inset-0 z-50 bg-black/80 backdrop-blur-md flex items-center justify-center p-3 sm:p-5 overflow-y-auto animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div 
        className="w-full max-w-2xl bg-gradient-to-b from-[#161622] via-[#101018] to-[#0A0A10] border border-amber-500/40 rounded-2xl shadow-2xl p-5 sm:p-7 relative my-auto space-y-6 text-white"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Close Button */}
        <button
          type="button"
          onClick={onClose}
          className="absolute top-4 right-4 p-2 rounded-xl bg-[#1C1C28] hover:bg-[#28283A] text-gray-400 hover:text-white border border-[#2B2B3E] transition cursor-pointer"
          title="Close Dialog"
        >
          <X className="w-4 h-4" />
        </button>

        {/* Modal Header */}
        <div className="flex items-start gap-4 pr-10">
          <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-amber-500 via-orange-500 to-amber-700 p-0.5 shadow-[0_0_20px_rgba(242,125,38,0.4)] flex-shrink-0">
            <div className="w-full h-full bg-[#12121A] rounded-[14px] flex items-center justify-center">
              <Mail className="w-7 h-7 text-amber-400" />
            </div>
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-mono uppercase tracking-widest px-2 py-0.5 rounded bg-amber-500/20 text-amber-300 border border-amber-500/30 font-bold">
                Direct Communications
              </span>
              <span className="text-[10px] font-mono text-emerald-400 flex items-center gap-1 font-semibold">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
                Active Inbox
              </span>
            </div>
            <h3 className="text-xl sm:text-2xl font-black text-white tracking-tight mt-1">
              Message Mauro Lomibao Dar III
            </h3>
            <p className="text-xs text-gray-300 font-mono mt-0.5">
              Creator &amp; Sole Owner &bull; Token World Exchange ATS®
            </p>
          </div>
        </div>

        {/* Quick Contact Cards Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
          {/* Email Channel Card */}
          <div className="rounded-xl bg-[#13131D] border border-amber-500/30 p-4 space-y-3 relative overflow-hidden group hover:border-amber-400/60 transition-all">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <div className="p-2 rounded-lg bg-amber-500/20 text-amber-300 border border-amber-500/30">
                  <Mail className="w-4 h-4" />
                </div>
                <div>
                  <span className="text-[11px] font-mono text-gray-400 block uppercase font-bold">Email Address</span>
                  <span className="text-sm font-mono font-bold text-amber-300 select-all">{creatorEmail}</span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-2 pt-1">
              <a
                href={`mailto:${creatorEmail}`}
                className="flex-1 inline-flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg bg-amber-500 hover:bg-amber-400 text-black text-xs font-bold transition shadow cursor-pointer active:scale-95"
              >
                <Send className="w-3.5 h-3.5" />
                <span>Open Mail App</span>
              </a>
              <button
                type="button"
                onClick={() => handleCopy(creatorEmail, "email")}
                className="px-3 py-2 rounded-lg bg-[#1C1C28] hover:bg-[#28283A] border border-[#2F2F42] text-xs font-mono text-gray-200 transition cursor-pointer flex items-center gap-1 active:scale-95"
                title="Copy Email Address"
              >
                {copiedType === "email" ? (
                  <>
                    <Check className="w-3.5 h-3.5 text-emerald-400" />
                    <span className="text-emerald-300 font-bold">Copied</span>
                  </>
                ) : (
