        </div>

        {/* Interactive Quick Compose Form */}
        <div className="rounded-xl bg-[#0E0E14] border border-[#232332] p-4 space-y-3.5">
          <div className="flex items-center justify-between">
            <span className="text-xs font-mono font-bold text-amber-300 uppercase tracking-wide flex items-center gap-1.5">
              <MessageSquare className="w-3.5 h-3.5 text-amber-400" />
              Quick Compose Draft Generator
