            <span className="text-[11px] font-mono text-gray-400">Pre-populates your email client</span>
          </div>

          {/* Topic Pills */}
          <div className="flex flex-wrap gap-1.5">
            {TOPIC_PRESETS.map((topic) => (
              <button
                key={topic.id}
