                onClick={() => handleTopicChange(topic.id)}
                className={`px-2.5 py-1 rounded-lg text-xs font-mono font-semibold transition cursor-pointer ${
                  selectedTopic.id === topic.id
                    ? "bg-amber-500 text-black shadow-sm"
                    : "bg-[#181822] text-gray-300 hover:text-white border border-[#262636] hover:border-amber-500/40"
                }`}
              >
                {topic.label}
              </button>
            ))}
          </div>

          {/* Sender inputs (optional) */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs font-mono">
            <div>
              <label className="block text-[11px] text-gray-400 mb-1">Your Name (Optional)</label>
              <input
                type="text"
                placeholder="e.g. Satoshi Nakamoto"
                value={senderName}
                onChange={(e) => setSenderName(e.target.value)}
                className="w-full bg-[#14141E] border border-[#2B2B3E] rounded-lg px-3 py-2 text-white placeholder-gray-500 focus:outline-none focus:border-amber-400 transition"
              />
