                className="w-full bg-[#14141E] border border-[#2B2B3E] rounded-lg px-3 py-2 text-white placeholder-gray-500 focus:outline-none focus:border-amber-400 transition"
              />
            </div>
          </div>

          {/* Subject & Body */}
          <div className="space-y-2 text-xs font-mono">
            <div>
              <label className="block text-[11px] text-gray-400 mb-1">Email Subject Line</label>
              <input
                type="text"
                value={customSubject}
                onChange={(e) => setCustomSubject(e.target.value)}
                className="w-full bg-[#14141E] border border-[#2B2B3E] rounded-lg px-3 py-2 text-white placeholder-gray-500 focus:outline-none focus:border-amber-400 transition"
              />
            </div>
            <div>
              <label className="block text-[11px] text-gray-400 mb-1">Message Draft Body</label>
              <textarea
                rows={4}
                value={customBody}
                onChange={(e) => setCustomBody(e.target.value)}
                className="w-full bg-[#14141E] border border-[#2B2B3E] rounded-lg px-3 py-2 text-white placeholder-gray-500 focus:outline-none focus:border-amber-400 transition font-mono leading-relaxed"
              />
            </div>
          </div>

          {/* Dispatch Actions */}
          <div className="flex flex-wrap items-center justify-between gap-2 pt-2 border-t border-[#1C1C28]">
            <button
              type="button"
              onClick={() => handleCopy(`${customSubject}\n\n${customBody}`, "message")}
              className="px-3 py-2 rounded-lg bg-[#181822] hover:bg-[#222230] border border-[#2B2B3E] text-xs font-mono text-gray-300 transition cursor-pointer flex items-center gap-1.5"
            >
              {copiedType === "message" ? (
                <>
                  <Check className="w-3.5 h-3.5 text-emerald-400" />
                  <span className="text-emerald-300 font-bold">Draft Copied</span>
                </>
              ) : (
                <>
                  <Copy className="w-3.5 h-3.5 text-gray-400" />
                  <span>Copy Subject &amp; Draft</span>
                </>
              )}
