            <a
              href={mailtoHref}
              className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-black text-xs font-bold font-mono transition shadow-[0_0_15px_rgba(242,125,38,0.3)] cursor-pointer active:scale-95"
            >
              <Send className="w-3.5 h-3.5" />
              <span>Launch Mail Client to Send</span>
            </a>
          </div>
        </div>

        {/* Physical Address & Ownership Footer */}
        <div className="pt-2 border-t border-[#1C1C28] flex flex-col sm:flex-row items-center justify-between gap-2 text-[11px] font-mono text-gray-400">
          <div className="flex items-center gap-1.5">
            <MapPin className="w-3.5 h-3.5 text-amber-400 flex-shrink-0" />
            <span>945 Westholme Ave. Los Angeles, CA 90024</span>
          </div>
          <div className="flex items-center gap-1.5 text-amber-300/80">
            <ShieldCheck className="w-3.5 h-3.5 text-emerald-400" />
            <span>Sole Proprietor: Mauro Lomibao Dar III</span>
          </div>
        </div>
      </div>
    </div>
  );
};

