import React, { useState } from 'react';
import {
  Wrench,
  Play,
  Layers,
  Activity,
  ShieldCheck,
  Wallet,
  FileCode2,
  CheckCircle2,
  Sparkles,
  Terminal,
  RefreshCw,
  Zap,
} from 'lucide-react';

export interface MultiToolExecutionResult {
  toolName: string;
  status: 'EXECUTED' | 'VERIFIED';
  latencyMs: number;
  summary: string;
  payload: Record<string, unknown>;
}

interface MultiToolsCommandHubProps {
  activeSymbol?: string;
  onSelectSymbol?: (symbol: string) => void;
  onOpenArtEngine?: () => void;
}

const MULTI_TOOL_DEFINITIONS = [
  {
    id: 'ats_orderbook_matching_tool',
    label: 'TWE ATS CLOB L2/L3 Matching Tool',
    category: 'ATS Venue & Liquidity',
    description: 'Queries & matches live institutional bids/asks on Token World Exchange ATS (TWE) with zero null states.',
    icon: Activity,
  },
  {
    id: 'hashlips_art_engine_2_tool',
