    category: 'Multi-Chain Treasury',
    description: 'Synchronizes EVM / Solana / Bitcoin balances and routes atomic RWA-to-USDC settlements.',
    icon: Wallet,
  },
  {
    id: 'solidity_contract_deployer_tool',
    label: 'OpenZeppelin ERC-721 / ERC-3643 Deployer',
