                  </>
                )}
              </button>
            )}
          </div>
        </div>

        {/* Mobile Dropdown Menu for Small Screens */}
        {isMobileMenuOpen && (
          <div className="sm:hidden border-t border-[#1F1F23] py-3 space-y-1 max-h-[70vh] overflow-y-auto">
