            {/* Mobile Direct Contact Mauro Banner */}
            <div className="pt-2 px-1 border-t border-[#1F1F23]">
              <div className="p-2.5 rounded-xl bg-gradient-to-r from-[#181824] to-[#12121A] border border-amber-500/30 space-y-2">
                <div className="flex items-center justify-between">
