                  <span className="text-[10px] font-mono text-gray-400">LA CA 90024</span>
                </div>
                <div className="flex items-center gap-2">
                  <a
                    href="mailto:maurodar08@gmail.com"
                    className="flex-1 inline-flex items-center justify-center gap-1.5 py-1.5 rounded-lg bg-cyan-950/40 border border-cyan-500/40 text-cyan-300 text-xs font-mono font-bold"
                  >
                    <Mail className="w-3.5 h-3.5" />
                    <span>Email Mauro</span>
                  </a>
                  <a
                    href="https://x.com/maurodar08"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex-1 inline-flex items-center justify-center gap-1.5 py-1.5 rounded-lg bg-blue-950/40 border border-blue-500/40 text-blue-300 text-xs font-mono font-bold"
                  >
                    <span>Twitter @maurodar08</span>
                  </a>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </header>
  );
};

