                    <label className="text-[10px] text-gray-400 block mb-1">
                      Your TWE Token Holding: <strong>{tweHoldingTokens.toLocaleString()} TWE</strong>
                    </label>
                    <input
                      type="range"
                      min="0"
                      max="300000"
                      step="5000"
