                    <div className="pt-2 border-t border-[#1E1E2C] flex items-center justify-between gap-2">
                      {userVote ? (
                        <div className="w-full py-1.5 text-center rounded bg-[#161622] text-amber-400 font-bold text-xs border border-amber-500/30">
