          <span>&bull; NYSE &amp; SEC Regulation ATS Dual-Listing Engine</span>
        </div>
        <div>
          <span>Sole Owner &amp; Creator: Mauro Lomibao Dar III &bull; maurodar08@gmail.com</span>
        </div>
      </div>
    </div>
  );
};

