            </span>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
            {(Object.keys(MARKET_TREND_CONFIGS) as MarketTrendScenario[]).map((key) => {
              const cfg = MARKET_TREND_CONFIGS[key];
              const isSelected = activeScenario === key;
              return (
                <button
                  key={key}
