    { id: "privacy_zk", label: "Privacy & ZK" },
    { id: "technical", label: "Checksum & Technical" },
    { id: "scripts", label: "Developer Scripts" },
    { id: "narratives", label: "2026 Narratives" },
    { id: "market_sim", label: "Market Simulation" },
