import React, { useState, useEffect, useMemo } from "react";
import {
  ShieldCheck,
  ShieldAlert,
  FileCheck,
  Download,
  Search,
  UserCheck,
  AlertTriangle,
  Lock,
  Building2,
  FileText,
  Sliders,
  CheckCircle2,
  XCircle,
  ExternalLink,
  RefreshCw,
  Plus,
  X,
  FileSpreadsheet,
  Flame,
  Zap,
  Volume2,
  VolumeX,
} from "lucide-react";
import {
  ResponsiveContainer,
  BarChart,
  ComposedChart,
  Bar,
  Line,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  Cell,
} from "recharts";
import { TokenRecord } from "../types";
import { OWNER_PROFILE } from "../utils/atsVenueData";
import {
  INITIAL_193_UN_JURISDICTIONS,
  UnMemberJurisdiction,
  WorldContinentId,
} from "../utils/tweGlobal193RolloutData";
import { TopBookSpoofingHeatmap } from "./TopBookSpoofingHeatmap";
import {
  SpoofingAlert,
  SpoofingAlertNotificationLog,
} from "./SpoofingAlertNotificationLog";
import {
  secRule15c35RiskEngine,
  CollarBreachRecord,
  HaltStateInfo,
} from "../utils/complianceRiskEngine";

export interface KycRecord {
  id: string;
  legalName: string;
  entityType: "INDIVIDUAL" | "INSTITUTION" | "SOVEREIGN_FUND" | "FAMILY_OFFICE";
  tier: "TIER_1_RETAIL" | "TIER_2_INSTITUTIONAL" | "TIER_3_SOVEREIGN";
  jurisdiction: string;
  walletAddress: string;
  status: "VERIFIED" | "PENDING_REVIEW" | "SANCTION_FLAGGED";
  dailyLimitUsd: number;
  submittedAt: number;
  approvedAt?: number;
  secAccreditedStatus: "REG_D_506C" | "RULE_144A_QIB" | "REG_S_OFFSHORE";
}

export interface AmlAlert {
  id: string;
  timestamp: number;
  walletAddress: string;
  transactionAmountUsd: number;
  riskScore: number;
  alertType: "STRUCTURING_DETECTION" | "VELOCITY_BURST" | "SANCTION_PROXIMITY" | "FAT_FINGER_VIOLATION";
  status: "ACTIVE_FLAG" | "CLEARED" | "SAR_FILED";
  details: string;
}

interface RegulatoryComplianceDashboardProps {
  tokens?: TokenRecord[];
  onNavigateToTab?: (tab: string) => void;
}

export const RegulatoryComplianceDashboard: React.FC<RegulatoryComplianceDashboardProps> = ({
  tokens = [],
  onNavigateToTab,
}) => {
  const [activeTab, setActiveTab] = useState<
    "SPOOFING_HEATMAP" | "SPOOFING_ALERTS" | "KYC" | "AML" | "SEC_15C3_5" | "AUDIT_REPORTS"
  >("SPOOFING_HEATMAP");

  // 193-UN-Member-State Compliance Dataset & Interactive Recharts BarChart State
  const [un193States, setUn193States] = useState<UnMemberJurisdiction[]>(
    () => INITIAL_193_UN_JURISDICTIONS
  );
  const [unChartAxisMode, setUnChartAxisMode] = useState<
    "CONTINENT" | "TIER" | "DIRECT_COMPARISON"
  >("CONTINENT");
  const [selectedAuditBarFilter, setSelectedAuditBarFilter] = useState<
    "ALL" | "Fully Compliant" | "Pending KYC"
  >("ALL");
  const [selectedAuditRegionFilter, setSelectedAuditRegionFilter] =
    useState<string>("ALL");

  // Compliance Adoption Velocity Percentage-Based Threshold Alert Configuration State
  const [isVelocityThresholdModalOpen, setIsVelocityThresholdModalOpen] =
    useState<boolean>(false);
  const [velocityThresholdTargetPct, setVelocityThresholdTargetPct] =
    useState<number>(75);
  const [criticalVelocityFloorPct, setCriticalVelocityFloorPct] =
    useState<number>(50);
  const [velocityAlertWarningEnabled, setVelocityAlertWarningEnabled] =
    useState<boolean>(true);
  const [tierSpecificThresholdsEnabled, setTierSpecificThresholdsEnabled] =
    useState<boolean>(false);
  const [tierThresholdsPct, setTierThresholdsPct] = useState<{
    TIER_1: number;
    TIER_2: number;
    TIER_3: number;
  }>({
    TIER_1: 85,
    TIER_2: 75,
    TIER_3: 65,
  });
  const [customStateVelocityBoosts, setCustomStateVelocityBoosts] = useState<
    Record<string, number>
  >({});

  const getUnStateComplianceStatus = (
    j: UnMemberJurisdiction
  ): "Fully Compliant" | "Pending KYC" => {
    return j.autoKycEnabled && j.nodeStatus === "ACTIVE_VALIDATOR"
      ? "Fully Compliant"
      : "Pending KYC";
  };

  // Compute each UN member state's Compliance Adoption Velocity (0% to 100%)
  const getStateAdoptionVelocityPct = (j: UnMemberJurisdiction): number => {
    if (typeof customStateVelocityBoosts[j.isoCode] === "number") {
      return customStateVelocityBoosts[j.isoCode];
    }
    const activationBase =
      j.nodeStatus === "ACTIVE_VALIDATOR"
        ? 100
        : j.nodeStatus === "STAGING_SYNC"
        ? 64
        : 28;
    const kycScore = j.autoKycEnabled ? 100 : 42;
    const tierScore = j.tier === "TIER_1" ? 96 : j.tier === "TIER_2" ? 82 : 66;
    const zkScore = j.zkIdentityEnabled ? 95 : 50;
    const latencyScore = Math.max(20, Math.min(100, 115 - j.latencyMs * 1.2));
    const weighted =
      activationBase * 0.45 +
      kycScore * 0.25 +
      tierScore * 0.12 +
      zkScore * 0.1 +
      latencyScore * 0.08;
    return Number(Math.max(5, Math.min(100, weighted)).toFixed(1));
  };

  const getEffectiveTargetThresholdPct = (j: UnMemberJurisdiction): number => {
    if (tierSpecificThresholdsEnabled) {
      return tierThresholdsPct[j.tier] ?? velocityThresholdTargetPct;
    }
    return velocityThresholdTargetPct;
  };

  const belowThresholdAlerts = useMemo(() => {
    return un193States
      .map((j) => {
        const velocityPct = getStateAdoptionVelocityPct(j);
        const targetPct = getEffectiveTargetThresholdPct(j);
        const deficitPct = Number((targetPct - velocityPct).toFixed(1));
        const isBelowTarget = velocityPct < targetPct;
        const severity: "CRITICAL_BREACH" | "BELOW_TARGET_WARNING" | "COMPLIANT" =
          velocityPct < criticalVelocityFloorPct
            ? "CRITICAL_BREACH"
            : isBelowTarget
            ? "BELOW_TARGET_WARNING"
            : "COMPLIANT";
        return {
          jurisdiction: j,
          velocityPct,
          targetPct,
          deficitPct,
          isBelowTarget,
          severity,
        };
      })
      .filter((item) => item.isBelowTarget)
      .sort((a, b) => b.deficitPct - a.deficitPct);
  }, [
    un193States,
    velocityThresholdTargetPct,
    criticalVelocityFloorPct,
    tierSpecificThresholdsEnabled,
    tierThresholdsPct,
    customStateVelocityBoosts,
  ]);

  const handleRemediateLaggingState = (isoCode: string, targetPct: number) => {
    const boosted = Math.min(100, Math.max(targetPct + 4, 88));
    setCustomStateVelocityBoosts((prev) => ({
      ...prev,
      [isoCode]: boosted,
    }));
    setUn193States((prev) =>
      prev.map((j) =>
        j.isoCode === isoCode
          ? { ...j, autoKycEnabled: true, nodeStatus: "ACTIVE_VALIDATOR" }
          : j
      )
    );
    showToast(
      `Remediated ${isoCode} compliance adoption velocity to ${boosted}% (above ${targetPct}% threshold).`
    );
  };

  const handleBulkRemediateTopLaggingStates = (count: number = 15) => {
    const targets = belowThresholdAlerts.slice(0, count);
    if (targets.length === 0) return;
    const nextBoosts: Record<string, number> = { ...customStateVelocityBoosts };
    const targetIsos = new Set<string>();
    targets.forEach((t) => {
      targetIsos.add(t.jurisdiction.isoCode);
      nextBoosts[t.jurisdiction.isoCode] = Math.min(100, Math.max(t.targetPct + 5, 90));
    });
    setCustomStateVelocityBoosts(nextBoosts);
    setUn193States((prev) =>
      prev.map((j) =>
        targetIsos.has(j.isoCode)
          ? { ...j, autoKycEnabled: true, nodeStatus: "ACTIVE_VALIDATOR" }
          : j
      )
    );
    showToast(
      `Boosted ${targets.length} lagging UN Member States above the ${velocityThresholdTargetPct}% compliance adoption velocity threshold.`
    );
  };

  const un193AuditTotals = useMemo(() => {
