              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-2.5">
                <div className="flex flex-wrap items-center justify-between gap-2 font-mono">
                  <span className="text-amber-300 font-bold">
                    Live Impact: {belowThresholdAlerts.length} / {un193States.length} States Flagged
                  </span>
                  <label className="flex items-center gap-2 text-[11px] text-slate-300 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={velocityAlertWarningEnabled}
                      onChange={(e) =>
                        setVelocityAlertWarningEnabled(e.target.checked)
                      }
                      className="accent-amber-500"
                    />
                    <span>Show UI Warning Banner</span>
                  </label>
                </div>

                <div className="max-h-40 overflow-y-auto divide-y divide-slate-800/70 font-mono text-[11px]">
                  {belowThresholdAlerts.slice(0, 12).map((item) => (
                    <div
                      key={item.jurisdiction.isoCode}
                      className="py-1.5 flex items-center justify-between gap-2"
                    >
                      <div className="truncate">
                        <span className="text-white font-bold">
                          {item.jurisdiction.countryName} ({item.jurisdiction.isoCode})
                        </span>{" "}
                        <span className="text-slate-400">
                          · {item.jurisdiction.continent} · {item.jurisdiction.tier}
                        </span>
                      </div>
                      <div className="flex items-center gap-2 shrink-0 tabular-nums">
                        <span
                          className={
                            item.severity === "CRITICAL_BREACH"
                              ? "text-rose-400 font-bold"
                              : "text-amber-300 font-bold"
                          }
                        >
                          {item.velocityPct}% / {item.targetPct}%
                        </span>
                        <button
                          type="button"
                          onClick={() =>
                            handleRemediateLaggingState(
                              item.jurisdiction.isoCode,
                              item.targetPct
                            )
                          }
                          className="px-2 py-0.5 rounded bg-emerald-600/30 hover:bg-emerald-600 text-emerald-200 hover:text-white border border-emerald-500/40 cursor-pointer transition"
                        >
                          Boost
                        </button>
                      </div>
                    </div>
                  ))}
                  {belowThresholdAlerts.length === 0 && (
                    <div className="py-3 text-center text-emerald-400">
                      All 193 UN Member States meet or exceed the {velocityThresholdTargetPct}% adoption velocity threshold.
                    </div>
                  )}
                </div>
              </div>
            </div>

            <div className="flex flex-wrap items-center justify-between gap-3 pt-2 border-t border-slate-800">
              <button
                type="button"
                onClick={() => {
                  setCustomStateVelocityBoosts({});
                  setVelocityThresholdTargetPct(75);
                  setCriticalVelocityFloorPct(50);
                  setTierSpecificThresholdsEnabled(false);
                  setVelocityAlertWarningEnabled(true);
                  showToast("Reset compliance adoption velocity thresholds to 75% baseline.");
                }}
                className="px-3 py-2 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-mono cursor-pointer"
              >
                Reset Defaults (75%)
              </button>

              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => setIsVelocityThresholdModalOpen(false)}
                  className="px-4 py-2 rounded-lg bg-amber-500 hover:bg-amber-400 text-slate-950 font-bold text-xs cursor-pointer transition"
                >
                  Save &amp; Apply Threshold ({velocityThresholdTargetPct}%)
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

