import React, { useState, useEffect, useMemo, useRef } from "react";
import {
  Activity,
  ArrowUpRight,
  ArrowDownRight,
  TrendingUp,
  TrendingDown,
  AlertTriangle,
  CheckCircle2,
  Filter,
  Play,
  Pause,
  RefreshCw,
  Sliders,
  Sparkles,
  Zap,
  Info,
  ChevronDown,
  ChevronUp,
  Search,
  LineChart as LineChartIcon,
} from "lucide-react";
import {
  ResponsiveContainer,
  LineChart,
  Line,
  YAxis,
  Tooltip,
  ReferenceLine,
} from "recharts";
import { TokenRecord } from "../types";

export interface RsiSparklinePoint {
  hour: string;
  rsi: number;
  price?: number;
}

export interface RsiDynamicSignalPanelProps {
  tokens: TokenRecord[];
  onSelectToken?: (token: TokenRecord) => void;
  onTradeToken?: (token: TokenRecord, mode: "buy" | "sell") => void;
}

export type RsiSignalType = "STRONG_BUY" | "BUY" | "NEUTRAL" | "SELL" | "STRONG_SELL";

export interface TokenRsiState {
  token: TokenRecord;
  currentPrice: number;
  currentMcap: number;
  priceHistory: number[]; // 14 period rolling prices
  rsi: number;
  rsiChange: number; // Delta compared to previous interval
  rsi24hHistory: RsiSparklinePoint[]; // 24-hour hourly RSI movement points
  signal: RsiSignalType;
  signalStrength: number; // 0 - 100%
  overboughtThreshold: number;
  oversoldThreshold: number;
  volatility24h: number;
  lastUpdated: number;
}

export const RsiDynamicSignalPanel: React.FC<RsiDynamicSignalPanelProps> = ({
  tokens,
  onSelectToken,
  onTradeToken,
}) => {
  const [isLiveMonitoring, setIsLiveMonitoring] = useState<boolean>(true);
  const [signalFilter, setSignalFilter] = useState<"ALL" | "BUY" | "SELL" | "NEUTRAL">("ALL");
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [overboughtThreshold, setOverboughtThreshold] = useState<number>(70);
  const [oversoldThreshold, setOversoldThreshold] = useState<number>(30);
  const [isConfigOpen, setIsConfigOpen] = useState<boolean>(false);
  const [tickIntervalMs, setTickIntervalMs] = useState<number>(3000); // 3 sec tick
  const [isAudioAlertEnabled, setIsAudioAlertEnabled] = useState<boolean>(false);

  // Keep a map of historical price simulations keyed by tokenId
  const [priceHistoryMap, setPriceHistoryMap] = useState<Record<string, number[]>>({});

  // Seed initial 14-period price history for all tokens based on initial marketCap and priceUsd
  useEffect(() => {
    if (!tokens || tokens.length === 0) return;

    setPriceHistoryMap((prev) => {
      const nextMap = { ...prev };
      let changed = false;

      tokens.forEach((token) => {
        if (!nextMap[token.id]) {
          changed = true;
          const basePrice = token.priceUsd && token.priceUsd > 0 ? token.priceUsd : 1.0;
          // Generate 14 past pseudo-historical points with realistic random walk
          const history: number[] = [];
          let p = basePrice * 0.95;
          for (let i = 0; i < 14; i++) {
            const delta = (Math.sin(i * 1.5 + token.id.charCodeAt(0)) * 0.04) + ((Math.random() - 0.48) * 0.03);
            p = Math.max(0.000001, p * (1 + delta));
            history.push(p);
          }
          // The 14th is the current base price
          history.push(basePrice);
          nextMap[token.id] = history.slice(-14);
        }
      });

      return changed ? nextMap : prev;
    });
  }, [tokens]);

  // Real-time market cap fluctuation simulation loop
  useEffect(() => {
    if (!isLiveMonitoring || tokens.length === 0) return;

    const interval = setInterval(() => {
      setPriceHistoryMap((prev) => {
        const updated = { ...prev };
        let anyUpdated = false;

        tokens.forEach((token) => {
          const hist = updated[token.id] || [token.priceUsd || 1.0];
          const lastPrice = hist[hist.length - 1];

          // Simulate organic fluctuation using pseudo-random Gaussian walk scaled by token security/holder stats
          const volatilityFactor = (token.securityScore && token.securityScore < 80 ? 0.045 : 0.02);
          const fluctuation = (Math.random() - 0.495) * volatilityFactor;
          const newPrice = Math.max(0.000001, lastPrice * (1 + fluctuation));

          const newHist = [...hist.slice(-13), newPrice]; // keep last 14 periods
          updated[token.id] = newHist;
          anyUpdated = true;
        });

        return anyUpdated ? updated : prev;
      });
    }, tickIntervalMs);

    return () => clearInterval(interval);
  }, [isLiveMonitoring, tokens, tickIntervalMs]);

  // Calculate standard Wilder's RSI (14 periods) from price fluctuations
  const calculateRsi = (prices: number[]): number => {
    if (!prices || prices.length < 2) return 50;

    let gains = 0;
    let losses = 0;

    for (let i = 1; i < prices.length; i++) {
      const diff = prices[i] - prices[i - 1];
      if (diff >= 0) {
        gains += diff;
      } else {
        losses += Math.abs(diff);
      }
    }

    const periodCount = prices.length - 1;
    if (periodCount === 0) return 50;

    const avgGain = gains / periodCount;
    const avgLoss = losses / periodCount;

    if (avgLoss === 0) {
      return avgGain === 0 ? 50 : 100;
    }

    const rs = avgGain / avgLoss;
    const rsi = 100 - 100 / (1 + rs);
    return Math.min(100, Math.max(0, parseFloat(rsi.toFixed(1))));
  };

  // Build reactive signal telemetry list
  const rsiRecords: TokenRsiState[] = useMemo(() => {
    return tokens.map((token) => {
      const hist = priceHistoryMap[token.id] || [token.priceUsd || 1.0];
      const currentPrice = hist[hist.length - 1] || token.priceUsd || 1.0;
      const initialPrice = hist[0] || currentPrice;
      const rsi = calculateRsi(hist);

      // Previous period RSI for delta
      const prevHist = hist.slice(0, -1);
      const prevRsi = prevHist.length > 2 ? calculateRsi(prevHist) : rsi;
      const rsiChange = parseFloat((rsi - prevRsi).toFixed(1));

      // Market cap dynamic adjustment based on price fluctuation ratio
      const priceRatio = currentPrice / (token.priceUsd || currentPrice || 1.0);
      const currentMcap = Math.round((token.marketCap || 1000000) * priceRatio);

      // Determine Buy / Sell Signal
      let signal: RsiSignalType = "NEUTRAL";
      let strength = 50;

      if (rsi <= oversoldThreshold) {
        if (rsi <= oversoldThreshold - 10) {
          signal = "STRONG_BUY";
          strength = Math.min(99, Math.round(75 + (oversoldThreshold - rsi) * 2));
        } else {
          signal = "BUY";
          strength = Math.min(85, Math.round(55 + (oversoldThreshold - rsi) * 1.5));
        }
      } else if (rsi >= overboughtThreshold) {
        if (rsi >= overboughtThreshold + 10) {
          signal = "STRONG_SELL";
          strength = Math.min(99, Math.round(75 + (rsi - overboughtThreshold) * 2));
        } else {
          signal = "SELL";
          strength = Math.min(85, Math.round(55 + (rsi - overboughtThreshold) * 1.5));
        }
      } else {
        signal = "NEUTRAL";
        strength = Math.round(Math.abs(50 - rsi) * 2);
      }

      // Generate 24-hour historical RSI sparkline trajectory (24 hourly checkpoints culminating in current RSI)
      const seedVal = (token.id.split("").reduce((acc, char) => acc + char.charCodeAt(0), 0) % 50) + 25;
      const rsi24hHistory: RsiSparklinePoint[] = [];
      const baseHour = new Date().getHours();

      for (let h = 23; h >= 0; h--) {
        const hourLabel = `${(baseHour - h + 24) % 24}:00`;
        if (h === 0) {
          // Current real-time RSI
          rsi24hHistory.push({ hour: "Now", rsi });
        } else {
          // Simulated 24-hour path with sinusoidal momentum wave terminating at current RSI
          const progress = (24 - h) / 24;
          const wave = Math.sin(progress * Math.PI * 3 + seedVal) * 16;
          const drift = seedVal + (rsi - seedVal) * progress;
          const calculatedPoint = Math.min(95, Math.max(10, Math.round(drift + wave)));
          rsi24hHistory.push({ hour: hourLabel, rsi: calculatedPoint });
        }
      }

      // Volatility calculation (standard deviation over mean)
      const mean = hist.reduce((a, b) => a + b, 0) / hist.length;
      const variance = hist.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / hist.length;
      const volatility24h = parseFloat(((Math.sqrt(variance) / (mean || 1)) * 100).toFixed(2));

      return {
        token,
        currentPrice,
        currentMcap,
        priceHistory: hist,
        rsi,
        rsiChange,
        rsi24hHistory,
        signal,
        signalStrength: strength,
        overboughtThreshold,
        oversoldThreshold,
        volatility24h,
        lastUpdated: Date.now(),
      };
    });
  }, [tokens, priceHistoryMap, overboughtThreshold, oversoldThreshold]);

  // Aggregate telemetry
  const summaryCounts = useMemo(() => {
    let strongBuy = 0;
    let buy = 0;
    let neutral = 0;
    let sell = 0;
    let strongSell = 0;

    rsiRecords.forEach((r) => {
      if (r.signal === "STRONG_BUY") strongBuy++;
      else if (r.signal === "BUY") buy++;
      else if (r.signal === "NEUTRAL") neutral++;
      else if (r.signal === "SELL") sell++;
      else if (r.signal === "STRONG_SELL") strongSell++;
    });

    return {
      strongBuy,
      buy,
      neutral,
      sell,
      strongSell,
      totalBuy: strongBuy + buy,
      totalSell: strongSell + sell,
      totalTokens: rsiRecords.length,
    };
  }, [rsiRecords]);

  // Filtered list
  const filteredRecords = useMemo(() => {
    return rsiRecords.filter((record) => {
      // Filter by signal
      if (signalFilter === "BUY" && !record.signal.includes("BUY")) return false;
      if (signalFilter === "SELL" && !record.signal.includes("SELL")) return false;
      if (signalFilter === "NEUTRAL" && record.signal !== "NEUTRAL") return false;

      // Filter by search
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        const matchesName = record.token.name.toLowerCase().includes(q);
        const matchesSymbol = record.token.symbol.toLowerCase().includes(q);
        const matchesAddress = record.token.contractAddress?.toLowerCase().includes(q);
        return matchesName || matchesSymbol || matchesAddress;
      }

      return true;
    });
  }, [rsiRecords, signalFilter, searchQuery]);

  return (
    <div
      data-testid="rsi-dynamic-signal-panel"
      className="w-full rounded-2xl bg-gradient-to-b from-[#0F141F] via-[#0B0F19] to-[#080B12] border border-cyan-500/30 p-4 sm:p-6 shadow-2xl relative overflow-hidden"
    >
      {/* Background ambient pulse */}
      <div className="absolute top-0 right-0 w-80 h-80 bg-cyan-500/5 rounded-full blur-3xl pointer-events-none" />
      <div className="absolute bottom-0 left-0 w-80 h-80 bg-purple-500/5 rounded-full blur-3xl pointer-events-none" />

      {/* Header Bar */}
      <div className="relative z-10 flex flex-col md:flex-row items-start md:items-center justify-between gap-4 border-b border-slate-800/80 pb-4">
        <div className="space-y-1">
          <div className="flex items-center gap-2 flex-wrap">
            <div className="p-2 rounded-xl bg-cyan-500/15 border border-cyan-500/40 text-cyan-300">
              <Activity className="w-5 h-5 animate-pulse" />
            </div>
            <h2 className="text-lg sm:text-xl font-black text-white tracking-tight flex items-center gap-2 font-mono">
              <span>RSI Dynamic Signal Panel</span>
              <span className="text-[10px] uppercase font-bold tracking-wider px-2 py-0.5 rounded-full bg-cyan-500/20 text-cyan-300 border border-cyan-500/40">
                14-Period RSI
              </span>
              {isLiveMonitoring && (
                <span className="inline-flex items-center gap-1 text-[10px] font-mono font-bold text-emerald-400 bg-emerald-500/10 border border-emerald-500/30 px-2 py-0.5 rounded-full">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-ping" />
                  Live Sim Active
                </span>
              )}
            </h2>
          </div>
          <p className="text-xs text-slate-400 max-w-2xl font-mono">
            Monitors real-time market cap fluctuations, calculates Wilder&apos;s Relative Strength Index, and flags algorithmic Buy/Sell trigger signals.
          </p>
        </div>

        {/* Controls */}
        <div className="flex flex-wrap items-center gap-2 self-stretch md:self-auto justify-end">
          <button
            type="button"
            data-testid="toggle-rsi-monitoring-btn"
            onClick={() => setIsLiveMonitoring((prev) => !prev)}
            className={`px-3 py-1.5 rounded-lg text-xs font-mono font-bold flex items-center gap-1.5 transition cursor-pointer border ${
              isLiveMonitoring
                ? "bg-amber-500/20 text-amber-300 border-amber-500/40 hover:bg-amber-500/30"
                : "bg-emerald-500/20 text-emerald-300 border-emerald-500/40 hover:bg-emerald-500/30"
            }`}
          >
            {isLiveMonitoring ? <Pause className="w-3.5 h-3.5" /> : <Play className="w-3.5 h-3.5" />}
            <span>{isLiveMonitoring ? "Pause Simulation" : "Resume Live Tick"}</span>
          </button>

          <button
            type="button"
            data-testid="toggle-rsi-config-btn"
            onClick={() => setIsConfigOpen((prev) => !prev)}
            className="px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 text-xs font-mono font-bold flex items-center gap-1.5 transition cursor-pointer"
          >
            <Sliders className="w-3.5 h-3.5 text-cyan-400" />
            <span>Config Limits</span>
            {isConfigOpen ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
          </button>
        </div>
      </div>

      {/* Threshold Configuration Drawer */}
      {isConfigOpen && (
        <div className="mt-4 p-4 rounded-xl bg-slate-900/90 border border-cyan-500/30 grid grid-cols-1 sm:grid-cols-3 gap-4 text-xs font-mono text-slate-200">
          <div>
            <label className="block text-[11px] text-emerald-400 font-bold mb-1">
              Oversold Floor (Buy Signal Target): &le; {oversoldThreshold}
            </label>
            <input
              type="range"
              min="15"
              max="45"
              step="1"
              value={oversoldThreshold}
              onChange={(e) => setOversoldThreshold(Number(e.target.value))}
              className="w-full accent-emerald-500 cursor-pointer"
            />
            <div className="flex justify-between text-[10px] text-slate-500 mt-0.5">
              <span>15 (Extreme Deep Value)</span>
              <span>45 (Early Rebound)</span>
            </div>
          </div>

          <div>
            <label className="block text-[11px] text-rose-400 font-bold mb-1">
              Overbought Ceiling (Sell Signal Target): &ge; {overboughtThreshold}
            </label>
            <input
              type="range"
              min="55"
              max="85"
              step="1"
              value={overboughtThreshold}
              onChange={(e) => setOverboughtThreshold(Number(e.target.value))}
              className="w-full accent-rose-500 cursor-pointer"
            />
            <div className="flex justify-between text-[10px] text-slate-500 mt-0.5">
              <span>55 (Conservative Take-Profit)</span>
              <span>85 (Extreme Overbought)</span>
            </div>
          </div>

          <div>
            <label className="block text-[11px] text-cyan-400 font-bold mb-1">
              Fluctuation Tick Speed: {(tickIntervalMs / 1000).toFixed(1)}s
            </label>
            <input
              type="range"
              min="1000"
              max="10000"
              step="500"
              value={tickIntervalMs}
              onChange={(e) => setTickIntervalMs(Number(e.target.value))}
              className="w-full accent-cyan-500 cursor-pointer"
            />
            <div className="flex justify-between text-[10px] text-slate-500 mt-0.5">
              <span>1.0s (High-Frequency)</span>
              <span>10.0s (Slow-Motion)</span>
            </div>
          </div>
        </div>
      )}

      {/* Aggregate Telemetry Strip */}
      <div className="grid grid-cols-2 sm:grid-cols-5 gap-2.5 mt-4">
        <div className="p-3 rounded-xl bg-slate-900/70 border border-slate-800 flex flex-col justify-between">
          <span className="text-[10px] font-mono uppercase text-slate-400 font-bold">Monitored Tokens</span>
          <span className="text-xl font-bold font-mono text-white mt-1 tabular-nums">
            {summaryCounts.totalTokens}
          </span>
          <span className="text-[10px] font-mono text-cyan-400 mt-0.5">Active Portfolio</span>
        </div>

        <div className="p-3 rounded-xl bg-emerald-950/30 border border-emerald-500/30 flex flex-col justify-between">
          <div className="flex items-center justify-between">
            <span className="text-[10px] font-mono uppercase text-emerald-400 font-bold">Buy Signals</span>
            <span className="text-[10px] font-mono px-1.5 py-0.2 rounded bg-emerald-500/20 text-emerald-300">
              RSI &le; {oversoldThreshold}
            </span>
          </div>
          <span className="text-xl font-bold font-mono text-emerald-400 mt-1 tabular-nums">
            {summaryCounts.totalBuy}
          </span>
          <span className="text-[10px] font-mono text-emerald-300/80 mt-0.5">
            {summaryCounts.strongBuy} Strong · {summaryCounts.buy} Moderate
          </span>
        </div>

        <div className="p-3 rounded-xl bg-rose-950/30 border border-rose-500/30 flex flex-col justify-between">
          <div className="flex items-center justify-between">
            <span className="text-[10px] font-mono uppercase text-rose-400 font-bold">Sell Signals</span>
            <span className="text-[10px] font-mono px-1.5 py-0.2 rounded bg-rose-500/20 text-rose-300">
              RSI &ge; {overboughtThreshold}
            </span>
          </div>
          <span className="text-xl font-bold font-mono text-rose-400 mt-1 tabular-nums">
            {summaryCounts.totalSell}
          </span>
          <span className="text-[10px] font-mono text-rose-300/80 mt-0.5">
            {summaryCounts.strongSell} Strong · {summaryCounts.sell} Moderate
          </span>
        </div>

        <div className="p-3 rounded-xl bg-slate-900/70 border border-slate-800 flex flex-col justify-between">
          <span className="text-[10px] font-mono uppercase text-slate-400 font-bold">Neutral Zone</span>
          <span className="text-xl font-bold font-mono text-slate-300 mt-1 tabular-nums">
            {summaryCounts.neutral}
          </span>
          <span className="text-[10px] font-mono text-slate-400 mt-0.5">
            {oversoldThreshold} &lt; RSI &lt; {overboughtThreshold}
          </span>
        </div>

        <div className="p-3 rounded-xl bg-slate-900/70 border border-slate-800 flex flex-col justify-between col-span-2 sm:col-span-1">
          <span className="text-[10px] font-mono uppercase text-slate-400 font-bold">Market Sentiment</span>
          <div className="flex items-center gap-1.5 mt-1">
            {summaryCounts.totalBuy > summaryCounts.totalSell ? (
              <span className="text-sm font-bold font-mono text-emerald-400 flex items-center gap-1">
                <TrendingUp className="w-4 h-4" /> Oversold Rebound
              </span>
            ) : summaryCounts.totalSell > summaryCounts.totalBuy ? (
              <span className="text-sm font-bold font-mono text-rose-400 flex items-center gap-1">
                <TrendingDown className="w-4 h-4" /> Overheated Pullback
              </span>
            ) : (
              <span className="text-sm font-bold font-mono text-slate-300 flex items-center gap-1">
                Balanced Range
              </span>
            )}
          </div>
          <span className="text-[10px] font-mono text-slate-500 mt-0.5">Dynamic Equilibrium</span>
        </div>
      </div>

      {/* Filter and Search Bar */}
      <div className="mt-4 flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0">
          {(["ALL", "BUY", "SELL", "NEUTRAL"] as const).map((filter) => {
            const isActive = signalFilter === filter;
            return (
              <button
                key={filter}
                type="button"
                onClick={() => setSignalFilter(filter)}
                className={`px-3 py-1 rounded-lg text-xs font-mono font-bold transition cursor-pointer border whitespace-nowrap ${
                  isActive
                    ? filter === "BUY"
                      ? "bg-emerald-500/20 text-emerald-300 border-emerald-500/50"
                      : filter === "SELL"
                      ? "bg-rose-500/20 text-rose-300 border-rose-500/50"
                      : filter === "NEUTRAL"
                      ? "bg-slate-700 text-white border-slate-600"
                      : "bg-cyan-500/20 text-cyan-300 border-cyan-500/50"
                    : "bg-slate-900/60 text-slate-400 border-slate-800 hover:text-white"
                }`}
              >
                {filter === "ALL" && `All Signals (${summaryCounts.totalTokens})`}
                {filter === "BUY" && `Buy Alerts (${summaryCounts.totalBuy})`}
                {filter === "SELL" && `Sell Alerts (${summaryCounts.totalSell})`}
                {filter === "NEUTRAL" && `Neutral (${summaryCounts.neutral})`}
              </button>
            );
          })}
        </div>

        <div className="relative min-w-[220px]">
          <Search className="w-3.5 h-3.5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Filter token name, symbol..."
            className="w-full pl-9 pr-3 py-1.5 rounded-lg bg-slate-900 border border-slate-800 text-xs font-mono text-white placeholder-slate-500 focus:outline-none focus:border-cyan-400"
          />
        </div>
      </div>

      {/* Signal Cards Table */}
      <div className="mt-4 overflow-x-auto border border-slate-800/80 rounded-xl bg-slate-950/40">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="border-b border-slate-800/80 bg-slate-900/50 text-[11px] font-mono text-slate-400 uppercase tracking-wider">
              <th className="py-2.5 px-3">Asset & Token</th>
              <th className="py-2.5 px-3">Simulated Price</th>
              <th className="py-2.5 px-3">Dynamic Market Cap</th>
              <th className="py-2.5 px-3">RSI (14) Indicator</th>
              <th className="py-2.5 px-3 min-w-[130px]">24h RSI Trend (Recharts)</th>
              <th className="py-2.5 px-3 text-center">Trigger Signal</th>
              <th className="py-2.5 px-3 text-right">Instant Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/50 text-xs font-mono">
            {filteredRecords.length === 0 ? (
              <tr>
                <td colSpan={6} className="text-center py-8 text-slate-500 font-mono">
                  No tokens matching signal filter &quot;{signalFilter}&quot;
                </td>
              </tr>
            ) : (
              filteredRecords.map((item) => {
                const isBuy = item.signal.includes("BUY");
                const isSell = item.signal.includes("SELL");

                return (
                  <tr
                    key={item.token.id}
                    className={`hover:bg-slate-900/40 transition cursor-pointer ${
                      item.signal === "STRONG_BUY"
                        ? "bg-emerald-950/15"
                        : item.signal === "STRONG_SELL"
                        ? "bg-rose-950/15"
                        : ""
                    }`}
                    onClick={() => onSelectToken?.(item.token)}
                  >
                    {/* Token Info */}
                    <td className="py-2.5 px-3">
                      <div className="flex items-center gap-2">
                        {item.token.imageUrl ? (
                          <img
                            src={item.token.imageUrl}
                            alt={item.token.symbol}
                            className="w-7 h-7 rounded-full object-cover bg-slate-800 border border-slate-700"
                          />
                        ) : (
                          <div className="w-7 h-7 rounded-full bg-slate-800 border border-slate-700 flex items-center justify-center font-bold text-slate-300 text-[10px]">
                            {item.token.symbol.slice(0, 3)}
                          </div>
                        )}
                        <div>
                          <div className="font-bold text-white flex items-center gap-1.5">
                            <span>{item.token.symbol}</span>
                            <span className="text-[10px] text-slate-400 font-normal truncate max-w-[120px]">
                              {item.token.name}
                            </span>
                          </div>
                          <div className="text-[10px] text-slate-500 uppercase">
                            {item.token.chain} · {item.token.tokenStandard}
                          </div>
                        </div>
                      </div>
                    </td>

                    {/* Price with trend */}
                    <td className="py-2.5 px-3 font-mono tabular-nums">
                      <div className="text-white font-bold">
                        ${item.currentPrice < 0.01 ? item.currentPrice.toExponential(3) : item.currentPrice.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 4 })}
                      </div>
                      <div className={`text-[10px] flex items-center gap-0.5 ${item.rsiChange >= 0 ? "text-emerald-400" : "text-rose-400"}`}>
                        {item.rsiChange >= 0 ? "+" : ""}{item.rsiChange} pts
                      </div>
                    </td>

                    {/* Simulated Market Cap */}
                    <td className="py-2.5 px-3 font-mono tabular-nums text-slate-300">
                      ${item.currentMcap.toLocaleString()}
                    </td>

                    {/* RSI Bar Gauge */}
                    <td className="py-2.5 px-3 min-w-[160px]">
                      <div className="flex items-center justify-between text-[11px] font-bold mb-1">
                        <span
                          className={`tabular-nums ${
                            isBuy
                              ? "text-emerald-400"
                              : isSell
                              ? "text-rose-400"
                              : "text-slate-300"
                          }`}
                        >
                          RSI: {item.rsi}
                        </span>
                        <span className="text-[10px] text-slate-500">
                          {item.rsi <= oversoldThreshold
                            ? "Oversold"
                            : item.rsi >= overboughtThreshold
                            ? "Overbought"
                            : "Normal"}
                        </span>
                      </div>

                      {/* Visual RSI Gauge Bar */}
                      <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden relative">
                        {/* Target Zones Background Guide */}
                        <div
                          className="absolute top-0 bottom-0 bg-emerald-500/30"
                          style={{ left: "0%", width: `${oversoldThreshold}%` }}
                        />
                        <div
                          className="absolute top-0 bottom-0 bg-rose-500/30"
                          style={{ left: `${overboughtThreshold}%`, right: "0%" }}
                        />

                        {/* Current RSI Level Indicator */}
                        <div
                          className={`h-full rounded-full transition-all duration-500 ${
                            isBuy
                              ? "bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,0.8)]"
                              : isSell
                              ? "bg-rose-400 shadow-[0_0_8px_rgba(251,113,133,0.8)]"
                              : "bg-cyan-400"
                          }`}
                          style={{ width: `${item.rsi}%` }}
                        />
                      </div>
                    </td>

                    {/* 24-Hour RSI Movement Recharts Sparkline */}
                    <td className="py-2.5 px-3 min-w-[130px]">
                      <div className="w-28 sm:w-32 h-10 bg-slate-900/80 rounded border border-slate-800/80 p-0.5 relative flex items-center justify-center">
                        <ResponsiveContainer width="100%" height="100%">
                          <LineChart data={item.rsi24hHistory} margin={{ top: 2, right: 2, left: 2, bottom: 2 }}>
                            <YAxis domain={[0, 100]} hide />
                            <ReferenceLine y={oversoldThreshold} stroke="#10B981" strokeDasharray="2 2" strokeOpacity={0.6} />
                            <ReferenceLine y={overboughtThreshold} stroke="#F43F5E" strokeDasharray="2 2" strokeOpacity={0.6} />
                            <Tooltip
                              content={({ active, payload }) => {
                                if (active && payload && payload.length) {
                                  const pt = payload[0].payload as RsiSparklinePoint;
                                  return (
                                    <div className="p-1 rounded bg-slate-950/95 border border-slate-700 text-[10px] font-mono text-white shadow-lg pointer-events-none z-30">
                                      <span className="text-slate-400">{pt.hour}: </span>
                                      <span className="font-bold text-cyan-300">RSI {pt.rsi}</span>
                                    </div>
                                  );
                                }
                                return null;
                              }}
                            />
                            <Line
                              type="monotone"
                              dataKey="rsi"
                              stroke={isBuy ? "#10B981" : isSell ? "#F43F5E" : "#06B6D4"}
                              strokeWidth={1.8}
                              dot={false}
                              isAnimationActive={false}
                            />
                          </LineChart>
                        </ResponsiveContainer>
                        <span className="absolute bottom-0.5 right-1 text-[8px] font-mono text-slate-500 uppercase">
                          24h
                        </span>
                      </div>
                    </td>

                    {/* Signal Badge */}
                    <td className="py-2.5 px-3 text-center">
                      <span
                        className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-md text-[11px] font-bold font-mono tracking-tight shadow-sm ${
                          item.signal === "STRONG_BUY"
                            ? "bg-emerald-500 text-slate-950 border border-emerald-400 shadow-emerald-500/20 animate-pulse"
                            : item.signal === "BUY"
                            ? "bg-emerald-500/20 text-emerald-300 border border-emerald-500/40"
                            : item.signal === "STRONG_SELL"
                            ? "bg-rose-500 text-white border border-rose-400 shadow-rose-500/20 animate-pulse"
                            : item.signal === "SELL"
                            ? "bg-rose-500/20 text-rose-300 border border-rose-500/40"
                            : "bg-slate-800 text-slate-300 border border-slate-700"
                        }`}
                      >
                        {item.signal === "STRONG_BUY" && <ArrowUpRight className="w-3.5 h-3.5 stroke-[3]" />}
                        {item.signal === "BUY" && <TrendingUp className="w-3.5 h-3.5" />}
                        {item.signal === "NEUTRAL" && <CheckCircle2 className="w-3 h-3 text-slate-400" />}
                        {item.signal === "SELL" && <TrendingDown className="w-3.5 h-3.5" />}
                        {item.signal === "STRONG_SELL" && <ArrowDownRight className="w-3.5 h-3.5 stroke-[3]" />}
                        <span>{item.signal.replace("_", " ")}</span>
                      </span>
                    </td>

                    {/* Action Button */}
                    <td className="py-2.5 px-3 text-right">
                      {isBuy ? (
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            onTradeToken?.(item.token, "buy");
                          }}
                          className="px-2.5 py-1 rounded bg-emerald-500 hover:bg-emerald-400 text-slate-950 text-xs font-mono font-bold transition cursor-pointer shadow-sm"
                        >
                          Buy Alert
                        </button>
                      ) : isSell ? (
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            onTradeToken?.(item.token, "sell");
                          }}
                          className="px-2.5 py-1 rounded bg-rose-500 hover:bg-rose-400 text-white text-xs font-mono font-bold transition cursor-pointer shadow-sm"
                        >
                          Sell Alert
                        </button>
                      ) : (
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            onSelectToken?.(item.token);
                          }}
                          className="px-2.5 py-1 rounded bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-mono transition cursor-pointer"
                        >
                          Inspect
                        </button>
                      )}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

