export const ThirdwebAllInOneNftMarketplaceHub: React.FC<
  ThirdwebAllInOneNftMarketplaceHubProps
> = ({ token, assets, ipfsManifest, onDeployNftToAts }) => {
  const [activeTab, setActiveTab] = useState<
    "marketplace_roof" | "uint256_tokenomics" | "thirdweb_v5_code"
  >("marketplace_roof");

  // uint256 Batch & Tokenomics State
  const [batchStartUint256, setBatchStartUint256] = useState<string>("1");
  const [mintPriceEth, setMintPriceEth] = useState<number>(0.08);
  const [royaltyBps, setRoyaltyBps] = useState<number>(500); // 5.00%
  const [baseStakingApy, setBaseStakingApy] = useState<number>(18.5);
  const [erc404TokensPerNft, setErc404TokensPerNft] = useState<number>(1000);
  const [bondingCurveType, setBondingCurveType] = useState<
    "WINNER_TAKES_ALL" | "EXPONENTIAL" | "LINEAR"
  >("WINNER_TAKES_ALL");
  const [thirdwebContractPreset, setThirdwebContractPreset] = useState<
    "ERC721Drop" | "ERC1155Drop" | "MarketplaceV3" | "ERC404Hybrid"
  >("ERC721Drop");

  const [copiedKey, setCopiedKey] = useState<string>("");
  const [syncStatusBanner, setSyncStatusBanner] = useState<string>("");
  const [sweptEditions, setSweptEditions] = useState<number[]>([]);
  const [listedMarketplaces, setListedMarketplaces] = useState<string[]>(
    ALL_IN_ONE_MARKETPLACES.map((m) => m.id)
  );

  const ethUsdBenchmark = 2780;
  const { enrichedAssets } = useMemo(
    () => calculateStatisticalRarityScores(assets),
    [assets]
  );

  // Compute full uint256 per-batch Tokenomics for every NFT in the batch
  const batchTokenomics = useMemo(() => {
    const baseUsd = Math.max(Number(token.price || 100), mintPriceEth * ethUsdBenchmark);
    const items = enrichedAssets.map((item, idx) => {
      let startBig = 1n;
      try {
        startBig = BigInt(batchStartUint256 || "1");
      } catch {
        startBig = 1n;
      }
      const uint256Id = (startBig + BigInt(idx)).toString(10);
      const curveFactor =
        bondingCurveType === "WINNER_TAKES_ALL"
          ? item.rarityRank === 1
            ? 3.25
            : 1 + (item.rarityMultiplier - 1) * 1.35
          : bondingCurveType === "EXPONENTIAL"
          ? Math.pow(1.06, idx) * item.rarityMultiplier
          : (1 + idx * 0.04) * item.rarityMultiplier;

      const valuationUsd = Number((baseUsd * curveFactor).toFixed(2));
      const valuationEth = Number((valuationUsd / ethUsdBenchmark).toFixed(4));
      const stakingApyPct = Number((baseStakingApy * item.rarityMultiplier).toFixed(2));
      const creatorRoyaltyUsd = Number(((valuationUsd * royaltyBps) / 10000).toFixed(2));

      return {
        ...item,
        uint256Id,
        valuationUsd,
        valuationEth,
        stakingApyPct,
        creatorRoyaltyUsd,
        erc404BackedUnits: erc404TokensPerNft,
      };
    });

    const totalBatchMarketCapUsd = items.reduce((sum, i) => sum + i.valuationUsd, 0);
    const jackpotPoolUsd = Number((totalBatchMarketCapUsd * 0.15).toFixed(2));
    const avgApy =
      items.reduce((sum, i) => sum + i.stakingApyPct, 0) / Math.max(items.length, 1);

    return {
      items,
      totalBatchMarketCapUsd: Number(totalBatchMarketCapUsd.toFixed(2)),
      jackpotPoolUsd,
      avgApy: Number(avgApy.toFixed(2)),
    };
  }, [
    enrichedAssets,
    batchStartUint256,
    mintPriceEth,
    royaltyBps,
    baseStakingApy,
    erc404TokensPerNft,
    bondingCurveType,
    token.price,
  ]);

  const thirdwebSdkCode = useMemo(() => {
    const cleanSym = token.symbol.toUpperCase();
    return `/**
 * HashLips Art Engine 2.0 + Thirdweb v5 SDK + All-in-One Marketplace Aggregator
 * Token: ${token.name} (${cleanSym}) | Contract Preset: ${thirdwebContractPreset}
 * Unbounded uint256 Keyspace (0 .. ${MAX_UINT256_DECIMAL_STR})
 */
import { createThirdwebClient, getContract, sendTransaction } from "thirdweb";
import { defineChain } from "thirdweb/chains";
import { deployERC721Contract } from "thirdweb/deploys";
import { lazyMint, setClaimConditions, claimTo } from "thirdweb/extensions/erc721";
import { createListing, buyFromListing, makeOffer } from "thirdweb/extensions/marketplace";
import { ethers } from "ethers";

// 1. Initialize Thirdweb v5 Client
export const client = createThirdwebClient({
  clientId: process.env.NEXT_PUBLIC_TWE_DEV_KEY || "twe_live_pk_9f8e7d6c5b4a3f2e1d0c9b8a7f6e5d4c_2026",
});

// 2. Deploy Thirdweb ${thirdwebContractPreset} with EIP-2981 Royalties & IPFS BaseURI
export async function deployAndLazyMintUint256Batch(account) {
  const contractAddress = await deployERC721Contract({
    client,
    chain: defineChain(1),
    account,
    type: "${thirdwebContractPreset === "ERC721Drop" ? "DropERC721" : "TokenERC721"}",
    params: {
      name: "${token.name} — TWE Winner-Takes-All Collection",
      symbol: "${cleanSym}",
      royaltyRecipient: "${token.deployerAddress || "0x742d35Cc6634C0532925a3b844Bc454e4438f44e"}",
      royaltyBps: BigInt(${royaltyBps}), // ${(royaltyBps / 100).toFixed(2)}% Creator Royalty
      contractURI: "${ipfsManifest.baseTokenURI}contract.json",
    },
  });

  const nftContract = getContract({
    client,
    chain: defineChain(1),
    address: contractAddress,
  });

  // 3. Lazy-Mint HashLips Art Engine 2.0 uint256 Batch (Starting at uint256 #${batchStartUint256})
  const lazyMintTx = lazyMint({
    contract: nftContract,
    nfts: [
      {
        name: "${token.name} #${batchStartUint256}",
        description: "Generated by HashLips Art Engine 2.0 & Thirdweb v5 SDK",
        image: "${ipfsManifest.imagesFolderUri}1.png",
        attributes: [
          { trait_type: "Exchange", value: "Token World Exchange ATS" },
          { trait_type: "Bonding Curve", value: "${bondingCurveType}" },
          { trait_type: "ERC-404 Backing", value: "${erc404TokensPerNft} ${cleanSym}" }
        ],
      },
    ],
  });
  await sendTransaction({ transaction: lazyMintTx, account });

  // 4. Configure Free-For-All Public Claim Conditions
  const claimTx = setClaimConditions({
    contract: nftContract,
    phases: [
      {
        maxClaimableSupply: BigInt("${MAX_UINT256_DECIMAL_STR}"),
        maxClaimablePerWallet: BigInt(100),
        currencyAddress: "0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE",
        price: ${mintPriceEth},
        startTime: new Date(),
      },
    ],
  });
  await sendTransaction({ transaction: claimTx, account });

  return { contractAddress, baseTokenURI: "${ipfsManifest.baseTokenURI}" };
}

// 5. All-In-One Roof Multi-Marketplace Operator Approval (TWE ATS, Thirdweb, OpenSea, Blur, Magic Eden, Rarible, Zora)
export async function approveAllMarketplacesUnderOneRoof(signer, nftContractAddress) {
  const operators = [
    "0x9f8e7d6c5b4a3f2e1d0c9b8a7f6e5d4c3b2a1f0e", // Token World Exchange ATS
    "0x3dWebV5MarketplaceRouter0000000000000001", // Thirdweb MarketplaceV3
    "0x0000000000000068F116a894984e2DB1123eB395", // OpenSea Seaport 1.6
    "0x000000000000Ad05Ccc4F10045630fb830B95127", // Blur Blend Router
    "0x9757F2d2b135150BBeb65308D4a91804107cd8D6", // Rarible v2 TransferProxy
    "0x777777C338d93e2C7adf08D102d45CA7CC4Ed021", // Zora Universal Minter
  ];
  const abi = ["function setApprovalForAll(address operator, bool approved) external"];
  const contract = new ethers.Contract(nftContractAddress, abi, signer);

  const receipts = [];
  for (const op of operators) {
    const tx = await contract.setApprovalForAll(op, true);
    const receipt = await tx.wait();
    receipts.push({ operator: op, txHash: receipt.hash });
  }
  return receipts;
}`;
  }, [
    token.symbol,
    token.name,
    token.deployerAddress,
    thirdwebContractPreset,
    royaltyBps,
    ipfsManifest.baseTokenURI,
    ipfsManifest.imagesFolderUri,
    batchStartUint256,
    bondingCurveType,
    erc404TokensPerNft,
    mintPriceEth,
  ]);

  const handleBroadcastAllMarketplaces = async () => {
    setListedMarketplaces(ALL_IN_ONE_MARKETPLACES.map((m) => m.id));
    emitArtEngineLog(
      "AllInOneMarketplace",
      `Broadcasted ${batchTokenomics.items.length} ${token.symbol} uint256 NFTs across all 8 marketplaces under one roof (Total Market Cap: $${batchTokenomics.totalBatchMarketCapUsd.toLocaleString()}).`,
      "SUCCESS",
      100
    );
    setSyncStatusBanner(
      `LIVE ACROSS ALL 8 MARKETPLACES: Listed ${batchTokenomics.items.length} ${token.symbol} uint256 NFTs (TWE ATS, Thirdweb V3, OpenSea Seaport 1.6, Blur, Magic Eden, Rarible, Zora & Tensor) • Batch Cap: $${batchTokenomics.totalBatchMarketCapUsd.toLocaleString()}`
    );
  };

  const handleWinnerTakesAllSweep = (edition?: number) => {
    const targetEditions = edition
      ? [edition]
      : batchTokenomics.items.map((i) => i.edition);
    setSweptEditions((prev) => Array.from(new Set([...prev, ...targetEditions])));

    const firstItem =
      batchTokenomics.items.find((i) => i.edition === (edition || 1)) ||
      batchTokenomics.items[0];
    if (onDeployNftToAts && firstItem) {
      onDeployNftToAts({
        symbol: token.symbol,
        edition: firstItem.edition,
        baseTokenURI: ipfsManifest.baseTokenURI,
        tokenURI: firstItem.ipfsMetadataUri,
        contractStandard: "ERC-721",
        priceUsd: firstItem.valuationUsd,
      });
    }

    emitArtEngineLog(
      "WinnerTakesAllRouter",
      edition
        ? `Executed Free-For-All instant mint & settlement for ${token.symbol} Edition #${edition} ($${firstItem?.valuationUsd.toLocaleString()}).`
        : `Executed Winner-Takes-All floor sweep across all ${batchTokenomics.items.length} ${token.symbol} editions ($${batchTokenomics.totalBatchMarketCapUsd.toLocaleString()}).`,
      "SUCCESS",
      100
    );
    setSyncStatusBanner(
      edition
        ? `EXECUTED: ${token.symbol} Edition #${edition} settled via All-in-One Aggregator at $${firstItem?.valuationUsd.toLocaleString()} (${firstItem?.stakingApyPct}% APY Staking Activated).`
        : `WINNER-TAKES-ALL SWEEP COMPLETED: All ${batchTokenomics.items.length} ${token.symbol} uint256 NFTs swept & settled ($${batchTokenomics.totalBatchMarketCapUsd.toLocaleString()} Volume + $${batchTokenomics.jackpotPoolUsd.toLocaleString()} Reward Pool).`
    );
  };

  const handleCopy = (id: string, text: string) => {
    navigator.clipboard.writeText(text);
    setCopiedKey(id);
    setTimeout(() => setCopiedKey(""), 1800);
  };

  const handleDownloadFullstackSdkFile = () => {
    const blob = new Blob([thirdwebSdkCode], { type: "text/typescript;charset=utf-8" });
