import { useState, useMemo, useRef, useEffect } from "react";
import { motion, AnimatePresence, type Variants } from "motion/react";
import {
  TokenRecord,
  ChainType,
  NarrativeCategory,
  LaunchStatus,
  TokenStandard,
  Web3Genre,
  resolveTokenGenre,
  GENRE_DEFINITIONS,
} from "../types";
import {
  ALL_NARRATIVES,
  ALL_GENRES,
  simulateTokenOrganicEvolution,
  type MarketEvolutionOptions,
  type TokenEvolutionResult,
  NARRATIVE_TAGS_MAP,
