      onBulkUpdate(ids, { isDeployed: false });
    } else if (onBatchUpdateTokens) {
      const idSet = new Set(ids);
      const updated = tokens.map((t) =>
        idSet.has(t.id) ? { ...t, isDeployed: false } : t
