import {
  Archive,
  ArrowDown,
  ArrowUp,
  Check,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  ChevronUp,
  CircleAlert,
  Coins,
  Copy,
  Gem,
  Pencil,
  Plus,
  QrCode,
  Search,
  Star,
  Trash2,
  X,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState, type FormEvent } from "react";
import { startLogin } from "@/const";
import { trpc, type AssetSortField, type AssetSortOrder } from "@/lib/trpc";
import { ContractAddressQrGenerator } from "../ContractAddressQrGenerator";
import {
  BatchHeaderProgressBar,
  INITIAL_BATCH_PROGRESS,
  TableHeaderProgressRow,
  type BatchOperationKind,
  type BatchProgressState,
} from "./BatchProgressIndicator";
import type { AssetKind } from "./types";

const KIND_LABEL: Record<AssetKind, string> = {
  token: "Token",
  nft_collection: "NFT collection",
  nft_item: "NFT item",
  commodity_reference: "Commodity reference",
  currency_reference: "Currency reference",
  other: "Asset reference",
};
const KINDS = Object.keys(KIND_LABEL) as AssetKind[];
const PAGE_SIZE_OPTIONS = [5, 10, 25, 50] as const;
const DEFAULT_PAGE_SIZE = 10;
const MAX_PAGE_COUNT = Math.floor(1_000_000 / DEFAULT_PAGE_SIZE) + 1;

export type SortColumn = AssetSortField;
export type SortDirection = AssetSortOrder;

type AssetReference = {
  id: number;
  kind: AssetKind;
  name: string;
  symbol: string | null;
  description: string | null;
  chain: string | null;
  standard: string | null;
  contractAddress: string | null;
  status?: string;
  sourceName?: string | null;
  isWatchlisted?: boolean;
  metadata?: Record<string, unknown>;
  createdAt?: string | Date;
};

export function AssetWorkspace({
  authenticated,
  title,
  kinds,
  createKind,
  watchlistOnly = false,
}: {
  authenticated: boolean;
  title: string;
  kinds?: AssetKind[];
  createKind?: AssetKind;
  watchlistOnly?: boolean;
}) {
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState<number>(DEFAULT_PAGE_SIZE);
  const [sortBy, setSortBy] = useState<SortColumn>("name");
  const [sortOrder, setSortOrder] = useState<SortDirection>("asc");
  const [modalOpen, setModalOpen] = useState(false);
  const [editingAsset, setEditingAsset] = useState<AssetReference | null>(null);
  const [qrAsset, setQrAsset] = useState<AssetReference | null>(null);
  const [pendingDeleteAsset, setPendingDeleteAsset] = useState<AssetReference | null>(
    null
  );
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const [confirmBatchDelete, setConfirmBatchDelete] = useState(false);
  const [batchProgress, setBatchProgress] = useState<BatchProgressState>(
    INITIAL_BATCH_PROGRESS
  );
  const selectedRecordsMapRef = useRef<Map<number, AssetReference>>(new Map());
  const dismissTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [kindFilter, setKindFilter] = useState<AssetKind | "all">(
    kinds?.length === 1 ? kinds[0] : "all"
  );
  const kind = kindFilter === "all" ? undefined : kindFilter;

  useEffect(() => {
    return () => {
      if (dismissTimerRef.current) {
        clearTimeout(dismissTimerRef.current);
      }
    };
  }, []);

  const handleSortColumn = (column: SortColumn) => {
    if (sortBy === column) {
      setSortOrder((prev) => (prev === "asc" ? "desc" : "asc"));
    } else {
      setSortBy(column);
      setSortOrder("asc");
    }
    setPage(0);
  };

  const query = trpc.twe.assets.list.useQuery(
    {
      kind,
      kinds: kind ? undefined : kinds,
      search,
      watchlistedOnly: watchlistOnly,
      sortBy,
      sortOrder,
      limit: pageSize,
      offset: page * pageSize,
    },
    { enabled: authenticated, retry: false }
  );

  const utils = trpc.useUtils();
  const refresh = async () =>
    Promise.all([
      utils.twe.assets.list.invalidate(),
      utils.twe.overview.invalidate(),
    ]);

  const create = trpc.twe.assets.create.useMutation({
    onSuccess: async () => {
      await refresh();
      setModalOpen(false);
      setEditingAsset(null);
      setPage(0);
    },
  });

  const update = trpc.twe.assets.update.useMutation({
    onSuccess: async () => {
      await refresh();
      setModalOpen(false);
      setEditingAsset(null);
    },
  });

  const remove = trpc.twe.assets.remove.useMutation({
    onSuccess: async () => {
      await refresh();
      setPendingDeleteAsset(null);
      setPage(0);
    },
  });

  const toggleWatch = trpc.twe.assets.toggleWatchlist.useMutation({
    onSuccess: refresh,
  });

  const batchCreate = trpc.twe.assets.create.useMutation();
  const batchRemove = trpc.twe.assets.remove.useMutation();

  const rawAssets = (query.data?.items ?? []) as AssetReference[];
  const assets = useMemo(() => {
    const dir = sortOrder === "desc" ? -1 : 1;
    return [...rawAssets].sort((a, b) => {
      const valA =
        sortBy === "name"
          ? a.name ?? ""
          : sortBy === "kind"
          ? KIND_LABEL[a.kind] ?? a.kind ?? ""
          : a.chain ?? "";
      const valB =
        sortBy === "name"
          ? b.name ?? ""
          : sortBy === "kind"
          ? KIND_LABEL[b.kind] ?? b.kind ?? ""
          : b.chain ?? "";
      const cmp = valA.localeCompare(valB, undefined, { sensitivity: "base" });
      if (cmp !== 0) return cmp * dir;
      return (a.id - b.id) * dir;
    });
  }, [rawAssets, sortBy, sortOrder]);
  const total = query.data?.total ?? 0;
  const pageCount = Math.min(
    MAX_PAGE_COUNT,
    Math.max(1, Math.ceil(total / pageSize))
  );
  const safePage = Math.min(page, pageCount - 1);
  const visiblePageNumbers = useMemo(() => {
    const windowSize = 5;
    let start = Math.max(0, safePage - Math.floor(windowSize / 2));
    const end = Math.min(pageCount, start + windowSize);
    if (end - start < windowSize) {
      start = Math.max(0, end - windowSize);
    }
    const pages: number[] = [];
    for (let i = start; i < end; i++) {
      pages.push(i);
    }
    return pages;
  }, [safePage, pageCount]);

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const name = String(form.get("name") ?? "").trim();
    const symbol = String(form.get("symbol") ?? "").trim() || null;
    const description = String(form.get("description") ?? "").trim();
    const chain = String(form.get("chain") ?? "").trim() || null;
    const standard = String(form.get("standard") ?? "").trim() || null;
    const contractAddress =
      String(form.get("contractAddress") ?? "").trim() || null;

    if (editingAsset) {
      await update.mutateAsync({
        id: editingAsset.id,
        patch: { name, symbol, description, chain, standard, contractAddress },
      });
      return;
    }

    await create.mutateAsync({
      kind: String(form.get("kind") ?? createKind ?? "token") as AssetKind,
      name,
      symbol,
      description,
      chain,
      standard,
      contractAddress,
    });
    event.currentTarget.reset();
  };

  const deleteAsset = (asset: AssetReference) => {
    setPendingDeleteAsset(asset);
  };

  const pageIds = useMemo(() => assets.map((item) => item.id), [assets]);
  const allPageSelected =
    pageIds.length > 0 && pageIds.every((id) => selectedIds.includes(id));

  useEffect(() => {
    for (const item of assets) {
      if (selectedIds.includes(item.id)) {
        selectedRecordsMapRef.current.set(item.id, item);
      }
    }
  }, [assets, selectedIds]);

  const toggleSelectRow = (id: number) => {
    setConfirmBatchDelete(false);
    const match = assets.find((item) => item.id === id);
    if (selectedIds.includes(id)) {
      selectedRecordsMapRef.current.delete(id);
    } else if (match) {
      selectedRecordsMapRef.current.set(id, match);
    }
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const toggleSelectPage = () => {
    setConfirmBatchDelete(false);
    if (allPageSelected) {
      for (const id of pageIds) {
        selectedRecordsMapRef.current.delete(id);
      }
      setSelectedIds((prev) => prev.filter((id) => !pageIds.includes(id)));
    } else {
      for (const item of assets) {
        selectedRecordsMapRef.current.set(item.id, item);
      }
      setSelectedIds((prev) => Array.from(new Set([...prev, ...pageIds])));
    }
  };

  const isBatchRunning =
    batchProgress.visible && batchProgress.status === "running";

  const runBatchOperation = async (operation: BatchOperationKind) => {
    const selectedSet = new Set(selectedIds);
    const currentById = new Map(assets.map((item) => [item.id, item]));
    const targets = selectedIds
      .map((id) => currentById.get(id) ?? selectedRecordsMapRef.current.get(id))
      .filter((item): item is AssetReference => Boolean(item));

    if (targets.length === 0 || isBatchRunning) {
      return;
    }

    if (dismissTimerRef.current) {
      clearTimeout(dismissTimerRef.current);
      dismissTimerRef.current = null;
    }

    setConfirmBatchDelete(false);
    setBatchProgress({
      visible: true,
      operation,
      processed: 0,
      total: targets.length,
      currentLabel: targets[0]?.name ?? "",
      status: "running",
    });

    let completedCount = 0;
    try {
      for (const item of targets) {
        setBatchProgress((prev) => ({
          ...prev,
          currentLabel: item.name,
        }));

        if (operation === "duplicate") {
          await batchCreate.mutateAsync({
            kind: item.kind,
            name: `${item.name} (Copy)`,
            symbol: item.symbol ? `${item.symbol}-COPY` : null,
            description: item.description ?? "",
            chain: item.chain ?? null,
            standard: item.standard ?? null,
            contractAddress: item.contractAddress ?? null,
            metadata: {
              ...(item.metadata ?? {}),
              duplicatedFromId: item.id,
            },
          });
        } else {
          await batchRemove.mutateAsync({ id: item.id });
        }

        completedCount += 1;
        setBatchProgress({
          visible: true,
          operation,
          processed: completedCount,
          total: targets.length,
          currentLabel: item.name,
          status: "running",
        });

        await new Promise((resolve) => setTimeout(resolve, 160));
      }

      await refresh();

      for (const id of selectedSet) {
        selectedRecordsMapRef.current.delete(id);
      }
      setSelectedIds((prev) => prev.filter((id) => !selectedSet.has(id)));
      setBatchProgress({
        visible: true,
        operation,
        processed: completedCount,
        total: targets.length,
        currentLabel: `${completedCount} record${completedCount === 1 ? "" : "s"} finalized`,
        status: "completed",
      });

      dismissTimerRef.current = setTimeout(() => {
        setBatchProgress((prev) => ({ ...prev, visible: false }));
      }, 3200);
    } catch (err) {
      setBatchProgress({
        visible: true,
        operation,
        processed: completedCount,
        total: targets.length,
        currentLabel: "Operation halted",
        status: "error",
        errorMessage:
          err instanceof Error ? err.message : "Batch operation failed",
      });
    }
  };

  const icon = title.toLowerCase().includes("nft") ? (
    <Gem size={17} />
  ) : (
    <Coins size={17} />
  );

  return (
    <>
      <section className="twe-panel twe-panel-pad">
        <div className="twe-between" style={{ flexWrap: "wrap" }}>
          <div className="twe-row">
            <span className="twe-module-icon" style={{ margin: 0 }}>
              {icon}
            </span>
            <div>
              <div className="twe-panel-title">{title}</div>
              <div style={{ color: "#7d848e", fontSize: 10, marginTop: 4 }}>
                {watchlistOnly
                  ? "Saved to your personal watchlist"
                  : "Records owned by your account"}
              </div>
            </div>
          </div>
          <div className="twe-row" style={{ flexWrap: "wrap" }}>
            {selectedIds.length > 0 && (
              <>
                <span className="twe-tag gold">
                  {selectedIds.length} selected
                </span>
                <button
                  type="button"
                  className="twe-btn secondary"
                  style={{ minHeight: 32, padding: "0 10px" }}
                  disabled={!authenticated || isBatchRunning}
                  onClick={() => void runBatchOperation("duplicate")}
                  title="Duplicate selected records"
                >
                  <Copy size={12} /> Duplicate ({selectedIds.length})
                </button>
                {confirmBatchDelete ? (
                  <>
                    <button
                      type="button"
                      className="twe-btn danger"
                      style={{ minHeight: 32, padding: "0 10px" }}
                      disabled={!authenticated || isBatchRunning}
                      onClick={() => void runBatchOperation("delete")}
                    >
                      <Trash2 size={12} /> Confirm Delete ({selectedIds.length})
                    </button>
                    <button
                      type="button"
                      className="twe-btn ghost"
                      style={{ minHeight: 32, padding: "0 8px" }}
                      disabled={isBatchRunning}
                      onClick={() => setConfirmBatchDelete(false)}
                    >
                      Cancel
                    </button>
                  </>
                ) : (
                  <button
                    type="button"
                    className="twe-btn danger"
                    style={{ minHeight: 32, padding: "0 10px" }}
                    disabled={!authenticated || isBatchRunning}
                    onClick={() => setConfirmBatchDelete(true)}
                    title="Delete selected records"
                  >
                    <Trash2 size={12} /> Delete ({selectedIds.length})
                  </button>
                )}
              </>
            )}
            <button
              className="twe-btn"
              disabled={!authenticated || isBatchRunning}
              onClick={() => {
                setEditingAsset(null);
                setModalOpen(true);
              }}
            >
              <Plus size={14} /> New record
            </button>
          </div>
        </div>

        <div style={{ marginTop: 12 }}>
          <BatchHeaderProgressBar
            progress={batchProgress}
            onDismiss={() =>
              setBatchProgress((prev) => ({ ...prev, visible: false }))
            }
          />
        </div>

        <div className="twe-toolbar">
          <label className="twe-search">
            <Search size={14} />
            <input
              className="twe-input"
              placeholder="Search your records…"
              value={search}
              onChange={(event) => {
                setSearch(event.target.value);
                setPage(0);
              }}
            />
          </label>
          <div className="twe-row" style={{ flexWrap: "wrap" }}>
            <span className="twe-tag">
              <Archive size={11} /> {total} records
            </span>
            <span className="twe-tag gold" title="Click Name, Kind, or Chain table headers to sort">
              {sortOrder === "asc" ? <ArrowUp size={11} /> : <ArrowDown size={11} />}
              Sorted by {sortBy === "name" ? "Name" : sortBy === "kind" ? "Kind" : "Chain"} (
              {sortOrder.toUpperCase()})
            </span>
            {!createKind && (
              <label className="twe-row" style={{ gap: 6 }}>
                <span className="twe-panel-kicker">TYPE</span>
                <select
                  className="twe-select"
                  style={{ width: 180, minHeight: 34 }}
                  value={kindFilter}
                  onChange={(event) => {
                    setKindFilter(event.target.value as AssetKind | "all");
                    setPage(0);
                  }}
                >
                  <option value="all">All types</option>
                  {(kinds ?? KINDS).map((value) => (
                    <option key={value} value={value}>
                      {KIND_LABEL[value]}
                    </option>
                  ))}
                </select>
                <ChevronDown
                  size={12}
                  style={{
                    marginLeft: -28,
                    pointerEvents: "none",
                    color: "#9a9da2",
                  }}
                />
              </label>
            )}
          </div>
        </div>

        {pendingDeleteAsset && (
          <div
            className="twe-status-banner"
            style={{
              marginTop: 12,
              marginBottom: 12,
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <div>
              <strong>
                Remove “{pendingDeleteAsset.name}” from your private records?
              </strong>
              <p>This cannot be undone.</p>
            </div>
            <div className="twe-row">
              <button
                type="button"
                className="twe-btn secondary"
                onClick={() => setPendingDeleteAsset(null)}
              >
                Cancel
              </button>
              <button
                type="button"
                className="twe-btn"
                disabled={remove.isPending}
                onClick={() => remove.mutate({ id: pendingDeleteAsset.id })}
              >
                Confirm remove
              </button>
            </div>
          </div>
        )}

        {!authenticated ? (
          <div className="twe-empty">
            <div className="twe-empty-icon">
              <CircleAlert size={20} />
            </div>
            <strong>Sign in to access saved records</strong>
            <p>
              TWE does not create a temporary or sample account. Sign in with your
              real account to add or view your private workspace records.
            </p>
            <button
              className="twe-btn"
              style={{ marginTop: 14 }}
              onClick={() => startLogin()}
            >
              Sign in securely
            </button>
          </div>
        ) : query.isLoading ? (
          <div className="twe-empty">
            <span>Loading your records…</span>
          </div>
        ) : query.error ? (
          <div className="twe-empty">
            <div className="twe-alert">{query.error.message}</div>
          </div>
        ) : !assets.length ? (
          <div className="twe-empty">
            <div className="twe-empty-icon">{icon}</div>
            <strong>
              {watchlistOnly ? "Your watchlist is empty" : "No records yet"}
            </strong>
            <p>
              {watchlistOnly
                ? "Star a saved record to place it in your watchlist. No external account or balance is implied."
                : "Create a record or import an authorized source. Token references stay unverified until checked against an actual provider."}
            </p>
            {!watchlistOnly && authenticated && (
              <button
                className="twe-btn secondary"
                style={{ marginTop: 14 }}
                onClick={() => {
                  setEditingAsset(null);
                  setModalOpen(true);
                }}
              >
                <Plus size={13} /> Create first record
              </button>
            )}
          </div>
        ) : (
          <div className="twe-table-wrap">
            <table className="twe-table">
              <thead>
                <tr>
                  <th style={{ width: 38, textAlign: "center" }}>
                    <input
                      type="checkbox"
                      className="twe-checkbox"
                      checked={allPageSelected}
                      disabled={assets.length === 0 || isBatchRunning}
                      onChange={toggleSelectPage}
                      aria-label="Select all records on current page"
                      title="Select all records on current page"
                    />
                  </th>
                  <th
                    aria-sort={
                      sortBy === "name"
                        ? sortOrder === "asc"
                          ? "ascending"
                          : "descending"
                        : "none"
                    }
                  >
                    <button
                      type="button"
                      className={`twe-sort-btn ${sortBy === "name" ? "active" : ""}`}
                      onClick={() => handleSortColumn("name")}
                      title="Sort by Name"
                    >
                      <span>Name</span>
                      <span
                        style={{
                          display: "inline-flex",
                          flexDirection: "column",
                          lineHeight: 0,
                          marginLeft: 2,
                        }}
                        aria-hidden="true"
                      >
                        <ChevronUp
                          size={11}
                          style={{
                            marginBottom: -3,
                            color:
                              sortBy === "name" && sortOrder === "asc"
                                ? "var(--twe-gold-bright)"
                                : "currentColor",
                            opacity:
                              sortBy === "name" && sortOrder === "asc" ? 1 : 0.38,
                          }}
                        />
                        <ChevronDown
                          size={11}
                          style={{
                            color:
                              sortBy === "name" && sortOrder === "desc"
                                ? "var(--twe-gold-bright)"
                                : "currentColor",
                            opacity:
                              sortBy === "name" && sortOrder === "desc" ? 1 : 0.38,
                          }}
                        />
                      </span>
                    </button>
                  </th>
                  <th
                    aria-sort={
                      sortBy === "kind"
                        ? sortOrder === "asc"
                          ? "ascending"
                          : "descending"
                        : "none"
                    }
                  >
                    <button
                      type="button"
                      className={`twe-sort-btn ${sortBy === "kind" ? "active" : ""}`}
                      onClick={() => handleSortColumn("kind")}
                      title="Sort by Kind"
                    >
                      <span>Kind</span>
                      <span
                        style={{
                          display: "inline-flex",
                          flexDirection: "column",
                          lineHeight: 0,
                          marginLeft: 2,
                        }}
                        aria-hidden="true"
                      >
                        <ChevronUp
                          size={11}
                          style={{
                            marginBottom: -3,
                            color:
                              sortBy === "kind" && sortOrder === "asc"
                                ? "var(--twe-gold-bright)"
                                : "currentColor",
                            opacity:
                              sortBy === "kind" && sortOrder === "asc" ? 1 : 0.38,
                          }}
                        />
                        <ChevronDown
                          size={11}
                          style={{
                            color:
                              sortBy === "kind" && sortOrder === "desc"
                                ? "var(--twe-gold-bright)"
                                : "currentColor",
                            opacity:
                              sortBy === "kind" && sortOrder === "desc" ? 1 : 0.38,
                          }}
                        />
                      </span>
                    </button>
                  </th>
                  <th
                    aria-sort={
                      sortBy === "chain"
                        ? sortOrder === "asc"
                          ? "ascending"
                          : "descending"
                        : "none"
                    }
                  >
                    <button
                      type="button"
                      className={`twe-sort-btn ${sortBy === "chain" ? "active" : ""}`}
                      onClick={() => handleSortColumn("chain")}
                      title="Sort by Chain"
                    >
                      <span>Chain</span>
                      <span
                        style={{
                          display: "inline-flex",
                          flexDirection: "column",
                          lineHeight: 0,
                          marginLeft: 2,
                        }}
                        aria-hidden="true"
                      >
                        <ChevronUp
                          size={11}
                          style={{
                            marginBottom: -3,
                            color:
                              sortBy === "chain" && sortOrder === "asc"
                                ? "var(--twe-gold-bright)"
                                : "currentColor",
                            opacity:
                              sortBy === "chain" && sortOrder === "asc" ? 1 : 0.38,
                          }}
                        />
                        <ChevronDown
                          size={11}
                          style={{
                            color:
                              sortBy === "chain" && sortOrder === "desc"
                                ? "var(--twe-gold-bright)"
                                : "currentColor",
                            opacity:
                              sortBy === "chain" && sortOrder === "desc" ? 1 : 0.38,
