          }}
        >
          <section
            className="twe-modal"
            role="dialog"
            aria-modal="true"
            aria-labelledby="asset-form-title"
          >
            <div className="twe-modal-head">
              <div>
                <h2 id="asset-form-title">
                  {editingAsset ? "Edit an asset record" : "Create an asset record"}
                </h2>
                <p>
                  {editingAsset
                    ? "Changes are saved to your account."
                    : "Saved to your account. This does not issue, mint, list, or deploy an asset."}
                </p>
              </div>
              <button
                className="twe-btn ghost"
                aria-label="Close"
                onClick={() => {
                  setModalOpen(false);
                  setEditingAsset(null);
                }}
              >
                <X size={17} />
              </button>
            </div>
            <form
              key={editingAsset?.id ?? "new-asset"}
              onSubmit={(event) => void submit(event)}
            >
              <div className="twe-form-grid">
                {!editingAsset && (!createKind || (kinds?.length ?? 0) > 1) && (
                  <div className="twe-field">
                    <label htmlFor="asset-kind">Record type</label>
                    <select
                      id="asset-kind"
                      className="twe-select"
                      name="kind"
                      defaultValue={
                        createKind ?? (kindFilter === "all" ? "token" : kindFilter)
                      }
                    >
                      {(kinds ?? KINDS).map((value) => (
                        <option key={value} value={value}>
                          {KIND_LABEL[value]}
                        </option>
                      ))}
                    </select>
                  </div>
                )}
                <div className={`twe-field ${createKind ? "full" : ""}`}>
                  <label htmlFor="asset-name">Name *</label>
                  <input
                    className="twe-input"
                    id="asset-name"
                    name="name"
                    maxLength={160}
                    placeholder="Asset or collection name"
                    defaultValue={editingAsset?.name ?? ""}
                    required
                  />
                </div>
                <div className="twe-field">
                  <label htmlFor="asset-symbol">Symbol / ticker</label>
                  <input
                    className="twe-input"
                    id="asset-symbol"
                    name="symbol"
                    maxLength={24}
                    placeholder="Optional"
                    defaultValue={editingAsset?.symbol ?? ""}
                  />
                </div>
                <div className="twe-field">
                  <label htmlFor="asset-chain">Network / chain</label>
                  <input
                    className="twe-input"
                    id="asset-chain"
                    name="chain"
                    maxLength={80}
                    placeholder="For example, Ethereum"
                    defaultValue={editingAsset?.chain ?? ""}
                  />
                </div>
                <div className="twe-field">
                  <label htmlFor="asset-standard">Standard</label>
                  <input
                    className="twe-input"
                    id="asset-standard"
                    name="standard"
                    maxLength={60}
                    placeholder="For example, ERC-20 / ERC-721"
                    defaultValue={editingAsset?.standard ?? ""}
                  />
                </div>
                <div className="twe-field full">
                  <label htmlFor="asset-contract">
                    Contract / external identifier
                  </label>
                  <input
                    className="twe-input"
                    id="asset-contract"
                    name="contractAddress"
                    maxLength={255}
                    placeholder="Optional; saved as unverified text"
                    defaultValue={editingAsset?.contractAddress ?? ""}
                  />
                </div>
                <div className="twe-field full">
                  <label htmlFor="asset-description">Description</label>
                  <textarea
                    className="twe-textarea"
                    id="asset-description"
                    name="description"
                    maxLength={4000}
                    placeholder="Describe the record and its source or intended use."
                    defaultValue={editingAsset?.description ?? ""}
                  />
                </div>
              </div>
              {create.error && (
                <div className="twe-alert" style={{ marginTop: 12 }}>
                  {create.error.message}
                </div>
              )}
              {update.error && (
                <div className="twe-alert" style={{ marginTop: 12 }}>
                  {update.error.message}
                </div>
              )}
              {remove.error && (
                <div className="twe-alert" style={{ marginTop: 12 }}>
                  {remove.error.message}
                </div>
              )}
              <div
                className="twe-row"
                style={{ justifyContent: "flex-end", marginTop: 18 }}
              >
                <button
                  className="twe-btn secondary"
                  type="button"
                  onClick={() => {
                    setModalOpen(false);
                    setEditingAsset(null);
                  }}
                >
                  Cancel
                </button>
                <button
                  className="twe-btn"
                  type="submit"
                  disabled={create.isPending || update.isPending}
                >
                  {create.isPending || update.isPending
                    ? "Saving…"
                    : editingAsset
                      ? "Save changes"
                      : "Save record"}
                </button>
              </div>
            </form>
          </section>
        </div>
      )}

      {qrAsset && (
        <div
          className="twe-modal-backdrop"
          role="presentation"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget) {
              setQrAsset(null);
            }
          }}
        >
          <section
            className="twe-modal"
            role="dialog"
            aria-modal="true"
            aria-labelledby="asset-qr-title"
          >
            <div className="twe-modal-head">
              <div>
                <h2 id="asset-qr-title">
                  {qrAsset.name} ({qrAsset.symbol || "ASSET"}) · Contract QR
                </h2>
                <p>
                  Scan or share this contract/reference address across mobile
                  wallets and block explorers.
                </p>
              </div>
              <button
                className="twe-btn ghost"
                aria-label="Close QR dialog"
                onClick={() => setQrAsset(null)}
              >
                <X size={17} />
              </button>
            </div>
            <ContractAddressQrGenerator
              contractAddress={
                qrAsset.contractAddress ||
                `TWE-${String(qrAsset.id).padStart(6, "0")}`
              }
              tokenName={qrAsset.name}
              tokenSymbol={qrAsset.symbol || "TWE"}
              chain={qrAsset.chain || "ethereum"}
              tokenStandard={qrAsset.standard || "ERC-20"}
            />
          </section>
        </div>
      )}
    </>
  );
}

