function triggerClientDownload(filename: string, content: string, mime = "application/json") {
  const blob = new Blob([content], { type: `${mime};charset=utf-8` });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

export const CmdtxNftLayerValuationCodex: React.FC = () => {
  const [activeSubTab, setActiveSubTab] = useState<
    | "layers_ipfs"
    | "metadata_openzeppelin"
    | "valuation_barriers"
    | "src_html_framework"
    | "prompts_links_codex"
  >("layers_ipfs");

  const [selectedLayerIds, setSelectedLayerIds] = useState<string[]>(
    CMDTX_HASHLIPS_LAYERS.map((l) => l.id)
  );
  const [editionId, setEditionId] = useState<number>(1);
  const [lotQuantity, setLotQuantity] = useState<number>(12);
  const [royaltyBps, setRoyaltyBps] = useState<number>(500); // 5.00%
  const [activeBarrierFilter, setActiveBarrierFilter] = useState<string>("ALL");
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [qrContractTarget, setQrContractTarget] = useState<CmdtxLayerSpec | null>(null);

  const selectedLayers = useMemo(
    () => CMDTX_HASHLIPS_LAYERS.filter((l) => selectedLayerIds.includes(l.id)),
    [selectedLayerIds]
  );

  const toggleLayer = (id: string) => {
    setSelectedLayerIds((prev) =>
      prev.includes(id) ? (prev.length > 1 ? prev.filter((item) => item !== id) : prev) : [...prev, id]
    );
  };

  const copyText = (key: string, value: string) => {
    navigator.clipboard.writeText(value);
    setCopiedId(key);
    setTimeout(() => setCopiedId(null), 1800);
  };

  // Marketplace valuation and semi-fungible balance math
  const valuationSummary = useMemo(() => {
    const totalRawKg = selectedLayers.reduce((acc, l) => acc + l.rawMaterialWeightKg, 0);
    const totalRefinedUnits = selectedLayers.reduce((acc, l) => acc + l.refinedUnitsPerLot, 0);
    const compositeSemiFungibleRatio =
      totalRawKg > 0 ? Number((totalRefinedUnits / totalRawKg).toFixed(2)) : 1;
    const baseStackValue = selectedLayers.reduce((acc, l) => acc + l.baseUnitValuationUsd, 0);
    const rarityMultiplier = selectedLayers.reduce(
      (acc, l) => acc + (1000 - l.rarityWeightPermille) / 500,
      1
    );
    const singleNftValuation = Math.round(baseStackValue * (compositeSemiFungibleRatio / 2.5) * (rarityMultiplier / 2));
    const totalLotValuation = singleNftValuation * lotQuantity;
    const creatorRoyaltyUsd = Math.round((totalLotValuation * royaltyBps) / 10000);

    return {
      totalRawKg,
      totalRefinedUnits,
      compositeSemiFungibleRatio,
      baseStackValue,
      rarityMultiplier: Number(rarityMultiplier.toFixed(2)),
      singleNftValuation,
      totalLotValuation,
