export const FeatureHub: React.FC<FeatureHubProps> = ({
  section,
  tokens = [],
  onSelectToken = (_token: TokenRecord) => {},
  onTradeToken = (_token: TokenRecord, _mode: "swap" | "sell") => {},
  onNavigateToClassicTab,
}) => {
  const sectionSpecs: Record<
    FeatureSectionKey,
    {
      kicker: string;
      title: string;
      statusNote: string;
      items: { title: string; detail: string; status: string }[];
      classicTabId: string;
      classicTabLabel: string;
    }
  > = {
    market: {
      kicker: "MARKETS · CONNECTION STATUS & RSI TELEMETRY",
      title: "Market & Exchange Readiness + 24h RSI Signal Stream",
      statusNote:
        "External exchange providers require explicit configuration. Below is your deterministic 14-period Wilder's RSI Dynamic Signal Panel with 24-hour Recharts sparklines.",
