        {
          title: "Order Execution & CLOB",
          detail: "Named exchange/broker routing and settlement adapter",
          status: "Workbench Mode",
        },
        {
          title: "14-Period Wilder's RSI Stream",
          detail: "24-hour historical RSI sparkline and Buy/Sell zone monitoring",
          status: "Active Locally",
        },
        {
          title: "Constant-Product AMM Simulator",
          detail: "x · y = k reserve slippage and LP share calculator",
