        },
      ],
      classicTabId: "twe_ats_terminal",
      classicTabLabel: "Launch Full TWE ATS® Matching Terminal",
    },
    deploy: {
      kicker: "BUILD · CONTRACT TOOLS & CALLDATA AUDIT",
      title: "Deploy & Registry Readiness",
      statusNote:
        "Prepare metadata drafts, inspect raw hexadecimal calldata (0xa9059cbb), and verify contract parameters before signing.",
