  const current = sectionSpecs[section];
  const IconMap = {
    market: BarChart3,
    deploy: Blocks,
    security: ShieldCheck,
    compliance: FileCheck2,
    chains: Network,
    ai: Palette,
  };
  const SectionIcon = IconMap[section];

  return (
    <div style={{ display: "grid", gap: 16 }}>
      <section className="twe-panel twe-panel-pad">
        <div className="twe-panel-head" style={{ flexWrap: "wrap" }}>
