              </div>
              <span style={{ color: "var(--twe-muted)", fontSize: 11, marginTop: 4 }}>
                {item.detail}
              </span>
            </div>
          ))}
        </div>
      </section>

      {section === "market" && (
        <RsiDynamicSignalPanel
          tokens={tokens}
          onSelectToken={onSelectToken}
          onTradeToken={(token, mode) =>
            onTradeToken(token, mode === "buy" ? "swap" : "sell")
          }
        />
      )}

      {(section === "compliance" || section === "security") && (
        <ComplianceHub />
      )}

      {(section === "market" ||
        section === "deploy" ||
        section === "security" ||
        section === "compliance") && <TweAtsCompilerBarriersRebateHub />}

      {(section === "ai" || section === "deploy") && (
        <CmdtxNftLayerValuationCodex />
      )}

      {section === "ai" && <FourTokenSystemsPlatform />}

      {(section === "ai" || section === "deploy" || section === "security") && (
        <ReferenceStudio isDarkTheme={true} />
      )}

      {section === "compliance" && <ProjectArchive isDarkTheme={true} />}
    </div>
  );
};

