                  <div className="twe-mono" style={{ fontSize: 10, color: "var(--twe-muted)" }}>
                    Target: {ev.targetId} · Actor: {ev.actorId} ·{" "}
                    {new Date(ev.createdAt).toLocaleTimeString()}
                  </div>
                </div>
              ))}
            </div>
          </section>
        </div>
      )}
    </div>
  );
};

