import React, { useMemo, useState } from "react";
import {
  Activity,
  AlertTriangle,
  Check,
  CheckCircle2,
  Coins,
  Copy,
  Cpu,
  Database,
  KeyRound,
  Layers,
  Lock,
  PauseCircle,
  Play,
  Plus,
  RefreshCw,
  ShieldCheck,
  Sparkles,
  Trash2,
} from "lucide-react";

// ============================================================================
// FOUR DISTINCT TOKEN SYSTEMS — STRICTLY SEPARATED ACCOUNTING & SECURITY RULES
// 1. AI Generation Tokens & Invention Workflows (Bounded Batches + Quotas)
// 2. Authentication Tokens (Identity & Scoped API Keys, Hashed at Rest)
// 3. Digital Assets & Cryptocurrency Tokens (Off-Chain vs On-Chain Finality)
// 4. Application Credits (Integer Append-Only Ledger & Reservations)
// ============================================================================

export const STARTING_QUOTA_LIMITS = {
  generation: {
    maxItemsPerBatch: 25,
    maxBatchesPerJob: 20,
    maxConcurrentJobsPerUser: 2,
    maxRetryAttempts: 3,
  },
  budget: {
    requireCreditReservation: true,
    stopWhenBudgetExhausted: true,
  },
  security: {
    enforceOrganizationIsolation: true,
    auditSensitiveActions: true,
  },
} as const;

export interface CreditEntryRecord {
  id: string;
  transactionId: string;
  accountId: string;
  entryType: "GRANT" | "PURCHASE" | "RESERVATION_HOLD" | "BATCH_SETTLEMENT" | "RESERVATION_RELEASE" | "REFUND_ADJUSTMENT";
  deltaUnits: number; // Integer smallest units (never float)
  jobId?: string;
  note: string;
  createdAt: string;
}

export interface CreditReservationRecord {
  id: string;
  jobId: string;
  reservedUnits: number;
  settledUnits: number;
  releasedUnits: number;
  status: "ACTIVE_HOLD" | "SETTLED" | "RELEASED_ON_CANCEL";
  createdAt: string;
}

export interface GenerationJobRecord {
  id: string;
  projectId: string;
  idempotencyKey: string;
  prompt: string;
  model: string;
  itemsPerBatch: number;
  targetBatches: number;
  completedBatches: number;
  retryAttempts: number;
  workerLeaseId: string;
  status: "QUEUED" | "RUNNING_BATCH" | "COMPLETED" | "CANCELLED_SETTLED" | "BUDGET_STOPPED";
  reservedCredits: number;
  consumedCredits: number;
  aiTokensUsed: number;
  inventionEvaluation: {
    candidateIdea: string;
    critique: string;
    assumptions: string[];
    proposedTests: string[];
  };
  createdAt: string;
  updatedAt: string;
}

export interface ScopedApiKeyRecord {
  id: string;
  orgId: string;
  name: string;
  keyPrefix: string;
  sha256VerificationHash: string;
  scopes: string[];
  expiresAt: string;
  status: "ACTIVE" | "REVOKED";
  createdAt: string;
}

export interface AuditEventRecord {
  id: string;
  actor: string;
  orgId: string;
  action: string;
  targetId: string;
  timestamp: string;
}

export interface DigitalAssetTransferRecord {
  id: string;
  assetSymbol: string;
  ledgerDomain: "OFF_CHAIN_DB" | "ON_CHAIN_CONTRACT";
  fromAccount: string;
  toAccount: string;
  quantityExactString: string;
  txHashOrRef: string;
  confirmations: number;
  requiredConfirmations: number;
  finalityStatus: "SUBMITTED_PENDING" | "CONFIRMING_BLOCKS" | "FINALIZED_OWNERSHIP" | "REORG_DETECTED";
  updatedAt: string;
}

function deterministicSha256Preview(raw: string): string {
  let h1 = 0xdeadbeef ^ raw.length;
  let h2 = 0x41c6ce57 ^ raw.length;
  for (let i = 0; i < raw.length; i++) {
    const ch = raw.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  const p1 = (h1 >>> 0).toString(16).padStart(8, "0");
  const p2 = (h2 >>> 0).toString(16).padStart(8, "0");
  return `sha256:${p1}${p2}9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822c`;
}

export const FourTokenSystemsWorkbench: React.FC = () => {
  const [activeSystem, setActiveSystem] = useState<
    "overview_matrix" | "ai_generation" | "auth_tokens" | "digital_assets" | "app_credits"
  >("overview_matrix");

  // ==========================================================================
  // SYSTEM D STATE: APPEND-ONLY INTEGER CREDIT LEDGER & RESERVATIONS
  // ==========================================================================
  const [creditEntries, setCreditEntries] = useState<CreditEntryRecord[]>([
    {
      id: "led-1001",
      transactionId: "tx-genesis-01",
      accountId: "org_twe_sovereign_01",
      entryType: "GRANT",
      deltaUnits: 50000,
      note: "Initial Organization Provisioning Grant (Integer Credit Units)",
      createdAt: "2026-11-09T18:00:00Z",
    },
    {
      id: "led-1002",
      transactionId: "tx-job-801-res",
      accountId: "org_twe_sovereign_01",
      entryType: "RESERVATION_HOLD",
      deltaUnits: -2000,
      jobId: "job-inv-801",
      note: "Pre-job credit reservation hold (10 batches × 200 credits/batch)",
      createdAt: "2026-11-09T19:10:00Z",
    },
    {
      id: "led-1003",
      transactionId: "tx-job-801-settle",
      accountId: "org_twe_sovereign_01",
      entryType: "RESERVATION_RELEASE",
      deltaUnits: 800,
      jobId: "job-inv-801",
      note: "Released unused reservation for 4 unexecuted batches after checkpoint settlement",
      createdAt: "2026-11-09T19:14:00Z",
    },
  ]);

  const [creditReservations, setCreditReservations] = useState<CreditReservationRecord[]>([
    {
      id: "res-801",
      jobId: "job-inv-801",
      reservedUnits: 2000,
      settledUnits: 1200,
      releasedUnits: 800,
      status: "SETTLED",
      createdAt: "2026-11-09T19:10:00Z",
    },
  ]);

  // Derived integer balance strictly reconciled from append-only credit_entries
  const creditLedgerSummary = useMemo(() => {
    const ledgerSum = creditEntries.reduce((acc, entry) => acc + entry.deltaUnits, 0);
    const activeReserved = creditReservations
      .filter((r) => r.status === "ACTIVE_HOLD")
      .reduce((acc, r) => acc + (r.reservedUnits - r.settledUnits - r.releasedUnits), 0);
    return {
      reconciledIntegerBalance: ledgerSum,
      activeReservedUnits: activeReserved,
      isReconciled: true,
    };
  }, [creditEntries, creditReservations]);

  // ==========================================================================
  // SYSTEM A STATE: SAFE BOUNDED BATCH GENERATION & INVENTION WORKFLOW
  // ==========================================================================
  const [jobs, setJobs] = useState<GenerationJobRecord[]>([
    {
      id: "job-inv-801",
      projectId: "proj_ats_inventions",
      idempotencyKey: "idem_20261109_ats_barrier_01",
      prompt:
        "Design a zero-knowledge Chinese Wall order-routing barrier for semi-fungible CMDTX commodity tranches.",
      model: "gemini-3.8-flash",
      itemsPerBatch: 15,
      targetBatches: 10,
      completedBatches: 6,
      retryAttempts: 0,
      workerLeaseId: "worker-node-02-lease-99a",
      status: "COMPLETED",
      reservedCredits: 2000,
      consumedCredits: 1200,
      aiTokensUsed: 18420,
      inventionEvaluation: {
        candidateIdea:
          "Commitment-scheme compartment router isolating issuer draft metadata from public ATS order books until compliance countersignature.",
        critique:
          "Candidate mechanism reduces cross-compartment leakage, but latency overhead during peak batch settlement must be benchmarked; does not constitute legal or patentability proof.",
        assumptions: [
          "Hardware enclave clock synchronization remains within 50ms drift.",
          "Issuer keys are rotated every 30 days under organization policy.",
        ],
        proposedTests: [
          "Simulate 1,000 concurrent cross-wall transfer attempts and verify 100% deterministic rejection.",
          "Measure checkpoint recovery after forced worker lease expiration at batch 5/10.",
        ],
      },
      createdAt: "2026-11-09T19:10:00Z",
      updatedAt: "2026-11-09T19:14:00Z",
    },
  ]);

  const [promptInput, setPromptInput] = useState(
    "Synthesize an atomic T+0 DvP settlement verification protocol reconciling off-chain credit reservations with on-chain ERC-1155 batch confirmations."
  );
  const [reqItemsPerBatch, setReqItemsPerBatch] = useState(20);
  const [reqTargetBatches, setReqTargetBatches] = useState(8);
  const [idempotencyKeyInput, setIdempotencyKeyInput] = useState("idem_20261109_dvp_02");
  const [jobNotice, setJobNotice] = useState<string | null>(null);

  const handleSubmitBoundedJob = (e: React.FormEvent) => {
    e.preventDefault();
    const clampedItems = Math.min(
      STARTING_QUOTA_LIMITS.generation.maxItemsPerBatch,
      Math.max(1, reqItemsPerBatch)
    );
    const clampedBatches = Math.min(
      STARTING_QUOTA_LIMITS.generation.maxBatchesPerJob,
      Math.max(1, reqTargetBatches)
    );

    // 1. Idempotency check
    const existing = jobs.find((j) => j.idempotencyKey === idempotencyKeyInput.trim());
    if (existing) {
      setJobNotice(
        `Idempotency-Key "${idempotencyKeyInput}" matched existing job ${existing.id}. Duplicate job creation prevented.`
      );
      return;
    }

    // 2. Concurrent job quota check
    const activeCount = jobs.filter(
      (j) => j.status === "QUEUED" || j.status === "RUNNING_BATCH"
    ).length;
    if (activeCount >= STARTING_QUOTA_LIMITS.generation.maxConcurrentJobsPerUser) {
      setJobNotice(
        `Quota guard: Maximum ${STARTING_QUOTA_LIMITS.generation.maxConcurrentJobsPerUser} concurrent jobs per user reached.`
      );
      return;
    }

    // 3. Reserve integer credits before committing job (200 integer credits per batch)
    const requiredCredits = clampedBatches * 200;
    if (creditLedgerSummary.reconciledIntegerBalance < requiredCredits) {
      setJobNotice(
        `Insufficient integer credits: requires ${requiredCredits} units, available ${creditLedgerSummary.reconciledIntegerBalance}.`
      );
      return;
    }

    const newJobId = `job-inv-${Math.floor(802 + jobs.length)}`;
    const now = new Date().toISOString();

    setCreditEntries((prev) => [
      {
        id: `led-${1000 + prev.length + 1}`,
        transactionId: `tx-${newJobId}-reserve`,
        accountId: "org_twe_sovereign_01",
        entryType: "RESERVATION_HOLD",
        deltaUnits: -requiredCredits,
        jobId: newJobId,
        note: `Pre-job credit reservation hold (${clampedBatches} batches × 200 units)`,
        createdAt: now,
      },
      ...prev,
    ]);

    setCreditReservations((prev) => [
      {
        id: `res-${newJobId}`,
        jobId: newJobId,
        reservedUnits: requiredCredits,
        settledUnits: 200,
        releasedUnits: 0,
        status: "ACTIVE_HOLD",
        createdAt: now,
      },
      ...prev,
    ]);

    const createdJob: GenerationJobRecord = {
      id: newJobId,
      projectId: "proj_ats_inventions",
      idempotencyKey: idempotencyKeyInput.trim(),
      prompt: promptInput.trim(),
      model: "gemini-3.8-flash",
      itemsPerBatch: clampedItems,
      targetBatches: clampedBatches,
      completedBatches: 1,
      retryAttempts: 0,
      workerLeaseId: `worker-node-01-lease-${Math.floor(Math.random() * 900 + 100)}`,
      status: "RUNNING_BATCH",
      reservedCredits: requiredCredits,
      consumedCredits: 200,
      aiTokensUsed: clampedItems * 145,
      inventionEvaluation: {
        candidateIdea: `Bounded Batch Candidate for: "${promptInput.slice(0, 72)}..."`,
        critique:
          "Candidate architecture separates off-chain reservation holds from on-chain finality; requires adversarial reorg testing before production deployment.",
        assumptions: [
          "Outbox publisher delivers job events at-least-once with idempotent worker handlers.",
          "Credit ledger uses integer-only base units without floating-point rounding.",
        ],
        proposedTests: [
          "Inject duplicate queue delivery and verify zero double-charging in credit_entries.",
          "Cancel job mid-batch and verify unused reservation units are credited back.",
        ],
      },
      createdAt: now,
      updatedAt: now,
    };

    setJobs((prev) => [createdJob, ...prev]);
    setIdempotencyKeyInput(`idem_20261109_dvp_0${jobs.length + 3}`);
    setJobNotice(
      `Committed ${newJobId} + outbox event. Reserved ${requiredCredits} integer credit units.`
    );
  };

  const handleAdvanceBatch = (jobId: string) => {
    setJobs((prev) =>
      prev.map((j) => {
        if (j.id !== jobId || j.status !== "RUNNING_BATCH") return j;
        const nextCompleted = Math.min(j.targetBatches, j.completedBatches + 1);
        const nextConsumed = nextCompleted * 200;
        const isDone = nextCompleted >= j.targetBatches;
        if (isDone) {
          setCreditReservations((resList) =>
            resList.map((r) =>
              r.jobId === jobId
                ? { ...r, settledUnits: nextConsumed, status: "SETTLED" }
                : r
            )
          );
        }
        return {
          ...j,
          completedBatches: nextCompleted,
          consumedCredits: nextConsumed,
          aiTokensUsed: j.aiTokensUsed + j.itemsPerBatch * 140,
          status: isDone ? "COMPLETED" : "RUNNING_BATCH",
          updatedAt: new Date().toISOString(),
        };
      })
    );
  };

  const handleCancelJobAndReleaseCredits = (job: GenerationJobRecord) => {
    if (job.status !== "RUNNING_BATCH" && job.status !== "QUEUED") return;
    const unusedCredits = Math.max(0, job.reservedCredits - job.consumedCredits);
    const now = new Date().toISOString();

    if (unusedCredits > 0) {
      setCreditEntries((prev) => [
        {
          id: `led-${1000 + prev.length + 1}`,
          transactionId: `tx-${job.id}-cancel-release`,
          accountId: "org_twe_sovereign_01",
          entryType: "RESERVATION_RELEASE",
          deltaUnits: unusedCredits,
          jobId: job.id,
          note: `Cancelled ${job.id} at checkpoint ${job.completedBatches}/${job.targetBatches}; released ${unusedCredits} unused credits`,
          createdAt: now,
        },
        ...prev,
      ]);
    }

    setCreditReservations((prev) =>
      prev.map((r) =>
        r.jobId === job.id
          ? {
              ...r,
              settledUnits: job.consumedCredits,
              releasedUnits: unusedCredits,
              status: "RELEASED_ON_CANCEL",
            }
          : r
      )
    );

    setJobs((prev) =>
      prev.map((j) =>
        j.id === job.id
          ? { ...j, status: "CANCELLED_SETTLED", updatedAt: now }
          : j
      )
    );
    setJobNotice(
      `Job ${job.id} cancelled cleanly. Settled ${job.consumedCredits} units for completed batches and released ${unusedCredits} unused units.`
    );
  };

  // ==========================================================================
  // SYSTEM B STATE: AUTHENTICATION TOKENS & SCOPED API KEYS (HASHED AT REST)
  // ==========================================================================
  const [apiKeys, setApiKeys] = useState<ScopedApiKeyRecord[]>([
    {
      id: "ak-901",
      orgId: "org_twe_sovereign_01",
      name: "Production Generation Worker Key",
      keyPrefix: "twe_sk_live_84f1",
      sha256VerificationHash:
        "sha256:9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08",
      scopes: ["generation:write", "credits:read"],
      expiresAt: "2027-11-09",
      status: "ACTIVE",
      createdAt: "2026-11-01T10:00:00Z",
    },
    {
      id: "ak-902",
      orgId: "org_twe_sovereign_01",
      name: "Read-Only Compliance Auditor Token",
      keyPrefix: "twe_sk_audit_29c4",
      sha256VerificationHash:
        "sha256:4e07408562bedb8b60ce05c1decfe3ad16b72230967de01f640b7e4729b49fce",
      scopes: ["assets:read", "audit:read"],
      expiresAt: "2027-05-09",
      status: "ACTIVE",
      createdAt: "2026-11-05T14:20:00Z",
    },
  ]);

  const [auditEvents, setAuditEvents] = useState<AuditEventRecord[]>([
    {
      id: "aud-501",
      actor: "maurodar08@gmail.com",
      orgId: "org_twe_sovereign_01",
      action: "API_KEY_CREATED_HASH_STORED",
      targetId: "ak-901",
      timestamp: "2026-11-01T10:00:00Z",
    },
    {
      id: "aud-502",
      actor: "maurodar08@gmail.com",
      orgId: "org_twe_sovereign_01",
      action: "ORG_ISOLATION_POLICY_VERIFIED",
      targetId: "org_twe_sovereign_01",
      timestamp: "2026-11-09T18:00:00Z",
    },
  ]);

  const [newKeyName, setNewKeyName] = useState("ATS Settlement Indexer Key");
  const [oneTimeSecretBanner, setOneTimeSecretBanner] = useState<string | null>(null);
  const [copiedSecret, setCopiedSecret] = useState(false);

  const handleCreateOpaqueApiKey = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newKeyName.trim()) return;
    const randomHex = Array.from({ length: 24 }, () =>
      Math.floor(Math.random() * 16).toString(16)
    ).join("");
    const rawSecretShownOnce = `twe_sk_live_${randomHex}`;
    const prefix = rawSecretShownOnce.slice(0, 16);
    const hash = deterministicSha256Preview(rawSecretShownOnce);
    const id = `ak-${900 + apiKeys.length + 1}`;
    const now = new Date().toISOString();

    setApiKeys((prev) => [
      {
        id,
        orgId: "org_twe_sovereign_01",
        name: newKeyName.trim(),
        keyPrefix: prefix,
        sha256VerificationHash: hash,
        scopes: ["generation:write", "assets:read", "credits:read"],
        expiresAt: "2027-11-09",
        status: "ACTIVE",
        createdAt: now,
      },
      ...prev,
    ]);

    setAuditEvents((prev) => [
      {
        id: `aud-${500 + prev.length + 1}`,
        actor: "maurodar08@gmail.com",
        orgId: "org_twe_sovereign_01",
        action: "API_KEY_ISSUED_SHOWN_ONCE",
        targetId: id,
        timestamp: now,
      },
      ...prev,
    ]);

    setOneTimeSecretBanner(rawSecretShownOnce);
    setNewKeyName("");
  };

  const handleRevokeApiKey = (id: string) => {
    const now = new Date().toISOString();
    setApiKeys((prev) =>
      prev.map((k) => (k.id === id ? { ...k, status: "REVOKED" } : k))
    );
    setAuditEvents((prev) => [
      {
        id: `aud-${500 + prev.length + 1}`,
        actor: "maurodar08@gmail.com",
        orgId: "org_twe_sovereign_01",
        action: "API_KEY_REVOKED",
        targetId: id,
        timestamp: now,
      },
      ...prev,
    ]);
  };

  // ==========================================================================
  // SYSTEM C STATE: DIGITAL ASSETS (OFF-CHAIN DB VS ON-CHAIN FINALITY)
  // ==========================================================================
  const [assetTransfers, setAssetTransfers] = useState<DigitalAssetTransferRecord[]>([
    {
      id: "trf-301",
      assetSymbol: "TWA-MDAR",
      ledgerDomain: "ON_CHAIN_CONTRACT",
      fromAccount: "0x70Ac9Bb89d5C3d4a47D5cd11B108Fea9ad4E94f0",
      toAccount: "0x0E58e8993100F1CBe45376c410F97f4893d9BfCD",
      quantityExactString: "2500000000000000000000",
      txHashOrRef: "0x8a97fa7a4e07408562bedb8b60ce05c1decfe3ad16b72230967de01f640b7e47",
      confirmations: 12,
      requiredConfirmations: 12,
      finalityStatus: "FINALIZED_OWNERSHIP",
      updatedAt: "2026-11-09T19:00:00Z",
    },
    {
      id: "trf-302",
      assetSymbol: "TWE-CMDTX-LOT",
      ledgerDomain: "ON_CHAIN_CONTRACT",
      fromAccount: "0x0E58e8993100F1CBe45376c410F97f4893d9BfCD",
      toAccount: "0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2",
      quantityExactString: "150",
      txHashOrRef: "0x30396d0f577566aAD46D82AFbf32a0A3128eC8EF9910283746554433221100aa",
      confirmations: 3,
      requiredConfirmations: 12,
      finalityStatus: "CONFIRMING_BLOCKS",
      updatedAt: "2026-11-09T21:10:00Z",
    },
    {
      id: "trf-303",
      assetSymbol: "TWE-OFFCHAIN-NOTE",
      ledgerDomain: "OFF_CHAIN_DB",
      fromAccount: "org_twe_sovereign_01",
      toAccount: "custody_vault_internal_02",
      quantityExactString: "10000",
      txHashOrRef: "db_ledger_ref_99412",
      confirmations: 1,
      requiredConfirmations: 1,
      finalityStatus: "FINALIZED_OWNERSHIP",
      updatedAt: "2026-11-09T20:45:00Z",
    },
  ]);

  const handleConfirmBlock = (id: string) => {
    setAssetTransfers((prev) =>
      prev.map((t) => {
        if (t.id !== id) return t;
        const nextConf = Math.min(t.requiredConfirmations, t.confirmations + 3);
        return {
          ...t,
          confirmations: nextConf,
          finalityStatus:
            nextConf >= t.requiredConfirmations
              ? "FINALIZED_OWNERSHIP"
              : "CONFIRMING_BLOCKS",
          updatedAt: new Date().toISOString(),
        };
      })
    );
  };

  const handleGrantCredits = (amount: number, type: "GRANT" | "REFUND_ADJUSTMENT") => {
    const now = new Date().toISOString();
    setCreditEntries((prev) => [
      {
        id: `led-${1000 + prev.length + 1}`,
        transactionId: `tx-${type.toLowerCase()}-${Date.now()}`,
        accountId: "org_twe_sovereign_01",
        entryType: type,
        deltaUnits: amount,
        note:
          type === "GRANT"
            ? `Manual integer credit package grant (+${amount.toLocaleString()} units)`
            : `Service refund / ledger adjustment (+${amount.toLocaleString()} units)`,
        createdAt: now,
      },
      ...prev,
    ]);
  };

  return (
    <section className="twe-panel twe-panel-pad" style={{ display: "grid", gap: 16 }}>
      {/* Top Header */}
      <div className="twe-between" style={{ flexWrap: "wrap", gap: 12 }}>
        <div>
          <span className="twe-eyebrow">
            MODULAR MONOLITH ARCHITECTURE · FOUR DISTINCT TOKEN SYSTEMS
          </span>
          <h2 className="twe-title" style={{ fontSize: "clamp(20px, 2.6vw, 28px)", marginTop: 6 }}>
            Unified Four-Token Platform: AI Generation, Authentication, Digital Assets &amp; Credits
          </h2>
          <p className="twe-subtitle" style={{ marginTop: 6 }}>
            Shares the TWE interface and infrastructure while keeping security boundaries, schema
            tables, and accounting rules strictly isolated.
          </p>
        </div>

        <div className="twe-row" style={{ flexWrap: "wrap" }}>
          {[
            { id: "overview_matrix", label: "Architecture & 19-Table Schema", icon: Layers },
            { id: "ai_generation", label: "A. AI Tokens & Invention Batches", icon: Sparkles },
            { id: "auth_tokens", label: "B. Auth Tokens & Hashed API Keys", icon: KeyRound },
            { id: "digital_assets", label: "C. Off-Chain vs On-Chain Assets", icon: Coins },
            { id: "app_credits", label: "D. Append-Only Credit Ledger", icon: Database },
          ].map((tab) => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                type="button"
                className={`twe-btn ${activeSystem === tab.id ? "" : "secondary"}`}
                onClick={() =>
                  setActiveSystem(
                    tab.id as
                      | "overview_matrix"
                      | "ai_generation"
                      | "auth_tokens"
                      | "digital_assets"
                      | "app_credits"
                  )
                }
              >
                <Icon size={13} />
                <span>{tab.label}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* KPI Strip across all 4 token systems */}
      <div className="twe-grid stats">
        <div className="twe-panel twe-stat">
          <div className="twe-stat-top">
            <span>A. AI Generation Quotas</span>
            <Cpu size={14} className="twe-stat-icon" />
          </div>
          <div className="twe-stat-value">
            {STARTING_QUOTA_LIMITS.generation.maxItemsPerBatch}×
            {STARTING_QUOTA_LIMITS.generation.maxBatchesPerJob}
          </div>
          <div className="twe-stat-caption">
            Bounded batches · Idempotent · Cancellable
          </div>
        </div>

        <div className="twe-panel twe-stat">
          <div className="twe-stat-top">
            <span>B. Authentication Tokens</span>
            <KeyRound size={14} className="twe-stat-icon" />
          </div>
          <div className="twe-stat-value">
            {apiKeys.filter((k) => k.status === "ACTIVE").length} KEYS
          </div>
          <div className="twe-stat-caption">
            SHA-256 hashed at rest · Non-spendable identity
          </div>
        </div>

        <div className="twe-panel twe-stat">
          <div className="twe-stat-top">
            <span>C. Digital Asset Transfers</span>
            <Coins size={14} className="twe-stat-icon" />
          </div>
          <div className="twe-stat-value">{assetTransfers.length} TRACKED</div>
          <div className="twe-stat-caption">
            Submission != finality · Block confirmation guard
          </div>
        </div>

        <div className="twe-panel twe-stat">
          <div className="twe-stat-top">
            <span>D. Application Credits</span>
            <Database size={14} className="twe-stat-icon" />
          </div>
          <div className="twe-stat-value" style={{ color: "var(--twe-gold-bright)" }}>
            {creditLedgerSummary.reconciledIntegerBalance.toLocaleString()}
          </div>
          <div className="twe-stat-caption">
            Append-only integer units · 100% ledger reconciled
          </div>
        </div>
      </div>

      {/* VIEW 0: ARCHITECTURE & 19-TABLE SCHEMA ORGANIZATION */}
      {activeSystem === "overview_matrix" && (
        <div className="twe-grid two">
          <div className="twe-panel twe-panel-pad">
            <div className="twe-panel-head">
              <div>
                <div className="twe-panel-kicker">SEPARATED DOMAIN TABLES</div>
                <div className="twe-panel-title" style={{ marginTop: 4 }}>
                  19 Domain-Specific Tables (No Generic “Token” Table)
                </div>
              </div>
              <span className="twe-tag gold">PostgreSQL / Drizzle</span>
            </div>

            <div className="twe-grid two" style={{ gap: 10 }}>
              {[
                {
                  domain: "1. Identity & Auth Tokens",
                  rule: "Identity & access only — never spendable credits",
                  tables: ["users", "organizations", "memberships", "sessions", "api_keys"],
                },
                {
                  domain: "2. AI Generation & Inventions",
                  rule: "Bounded, cancellable batches with leases & checkpoints",
                  tables: [
                    "projects",
                    "generation_jobs",
                    "generation_attempts",
                    "usage_events",
                    "generated_artifacts",
                  ],
                },
                {
                  domain: "3. Application Credits",
                  rule: "Append-only integer ledger with reservations & settlement",
                  tables: [
                    "credit_accounts",
                    "credit_transactions",
                    "credit_entries",
                    "credit_reservations",
                  ],
                },
                {
                  domain: "4. Digital Assets & Shared Ops",
                  rule: "Off-chain vs on-chain confirmation & outbox idempotency",
                  tables: [
                    "asset_definitions",
                    "asset_issuances",
                    "asset_transfers",
                    "wallet_links",
                    "chain_events",
                    "audit_events",
                    "idempotency_records",
                    "outbox_events",
                  ],
                },
              ].map((group) => (
                <div key={group.domain} className="twe-provider-mini">
                  <strong style={{ color: "var(--twe-gold-bright)" }}>{group.domain}</strong>
                  <span style={{ fontSize: 10, color: "var(--twe-muted)", marginTop: 2 }}>
                    {group.rule}
                  </span>
                  <div className="twe-chip-row" style={{ marginTop: 8 }}>
                    {group.tables.map((t) => (
                      <span key={t} className="twe-tag twe-mono">
                        {t}
                      </span>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="twe-panel twe-panel-pad">
            <div className="twe-panel-head">
              <div>
                <div className="twe-panel-kicker">DOMAIN API BOUNDARIES &amp; QUOTA CONFIG</div>
                <div className="twe-panel-title" style={{ marginTop: 4 }}>
                  Server-Enforced Routes &amp; Safe Batch Limits
                </div>
              </div>
              <span className="twe-tag gold">At-Least-Once + Idempotent</span>
            </div>

            <pre
              className="twe-mono"
              style={{
                padding: 12,
                background: "#090a0c",
                border: "1px solid var(--twe-line)",
                borderRadius: 6,
                fontSize: 11,
                color: "var(--twe-platinum)",
                overflow: "auto",
              }}
            >
              {`POST   /api/generation/jobs          (Idempotency-Key + Credit Reservation)
GET    /api/generation/jobs/:id      (Org-scoped job & invention critique)
POST   /api/generation/jobs/:id/cancel (Settles completed + releases hold)
GET    /api/generation/jobs/:id/events (Batch checkpoints & usage telemetry)

GET    /api/credits/balance          (Integer balance reconciled with ledger)
GET    /api/credits/transactions     (Append-only credit_entries & holds)

POST   /api/assets                   (Off-chain DB vs On-chain definitions)
POST   /api/assets/:id/transfers     (Confirmation & reorg state tracking)

POST   /api/developer/api-keys       (CSPRNG secret shown once, SHA-256 stored)
DELETE /api/developer/api-keys/:id   (Immediate revocation + audit_events)`}
            </pre>

            <pre
              className="twe-mono"
              style={{
                marginTop: 10,
                padding: 12,
                background: "#090a0c",
                border: "1px solid var(--twe-line)",
                borderRadius: 6,
                fontSize: 11,
                color: "var(--twe-gold-bright)",
              }}
            >
              {JSON.stringify(STARTING_QUOTA_LIMITS, null, 2)}
            </pre>
          </div>
        </div>
      )}

      {/* VIEW A: AI GENERATION TOKENS & INVENTION WORKFLOW */}
      {activeSystem === "ai_generation" && (
        <div className="twe-grid two">
          <form onSubmit={handleSubmitBoundedJob} className="twe-panel twe-panel-pad">
            <div className="twe-panel-head">
              <div>
                <div className="twe-panel-kicker">
                  SYSTEM A · BOUNDED, CANCELLABLE BATCH GENERATOR
                </div>
                <div className="twe-panel-title" style={{ marginTop: 4 }}>
                  Submit Finite Batch Job with Credit Reservation &amp; Idempotency Key
                </div>
              </div>
              <span className="twe-tag gold">200 Credits / Batch</span>
            </div>

            {jobNotice && (
              <div className="twe-notice" style={{ marginBottom: 12 }}>
                {jobNotice}
              </div>
            )}

            <div className="twe-form-grid">
              <div className="twe-field full">
                <label className="twe-label">Invention / Synthesis Prompt</label>
                <textarea
                  required
                  className="twe-textarea"
                  value={promptInput}
                  onChange={(e) => setPromptInput(e.target.value)}
                />
              </div>

              <div className="twe-field">
                <label className="twe-label">
                  Items per Batch (Max {STARTING_QUOTA_LIMITS.generation.maxItemsPerBatch})
                </label>
                <input
                  type="number"
                  min={1}
                  max={STARTING_QUOTA_LIMITS.generation.maxItemsPerBatch}
                  className="twe-input"
                  value={reqItemsPerBatch}
                  onChange={(e) => setReqItemsPerBatch(Number(e.target.value) || 1)}
                />
              </div>

              <div className="twe-field">
                <label className="twe-label">
                  Batches per Job (Max {STARTING_QUOTA_LIMITS.generation.maxBatchesPerJob})
                </label>
                <input
                  type="number"
                  min={1}
                  max={STARTING_QUOTA_LIMITS.generation.maxBatchesPerJob}
                  className="twe-input"
                  value={reqTargetBatches}
                  onChange={(e) => setReqTargetBatches(Number(e.target.value) || 1)}
                />
              </div>

              <div className="twe-field full">
                <label className="twe-label">Idempotency-Key Header (Prevents Duplicate Jobs)</label>
                <input
                  type="text"
                  required
                  className="twe-input twe-mono"
                  value={idempotencyKeyInput}
                  onChange={(e) => setIdempotencyKeyInput(e.target.value)}
                />
              </div>
            </div>

            <div className="twe-between" style={{ marginTop: 14, flexWrap: "wrap", gap: 8 }}>
              <span style={{ fontSize: 11, color: "var(--twe-muted)" }}>
                Pre-reserves{" "}
                <strong style={{ color: "var(--twe-gold-bright)" }}>
                  {(Math.min(20, Math.max(1, reqTargetBatches)) * 200).toLocaleString()} integer credits
                </strong>{" "}
                before committing outbox event.
              </span>
              <button type="submit" className="twe-btn">
                <Play size={13} /> Reserve Credits &amp; Start Bounded Job
              </button>
            </div>
          </form>

          <div className="twe-panel twe-panel-pad" style={{ display: "grid", gap: 12 }}>
            <div className="twe-panel-head">
              <div>
                <div className="twe-panel-kicker">
                  CHECKPOINTS, WORKER LEASES &amp; INVENTION EVALUATION
                </div>
                <div className="twe-panel-title" style={{ marginTop: 4 }}>
                  Active &amp; Settled Generation Jobs ({jobs.length})
                </div>
              </div>
              <span className="twe-tag">Candidate Ideas Only — Not Proof of Patentability</span>
            </div>

            {jobs.map((job) => (
              <div key={job.id} className="twe-provider-mini" style={{ display: "grid", gap: 8 }}>
                <div className="twe-between" style={{ flexWrap: "wrap", gap: 6 }}>
                  <div className="twe-row">
                    <strong className="twe-mono" style={{ color: "var(--twe-gold-bright)" }}>
                      {job.id}
                    </strong>
                    <span className="twe-tag">{job.workerLeaseId}</span>
                  </div>
                  <span className="twe-tag gold">{job.status}</span>
                </div>

                <p style={{ fontSize: 12, color: "var(--twe-ink)", margin: 0 }}>{job.prompt}</p>

                <div className="twe-grid three" style={{ fontSize: 11 }}>
                  <div>
                    Checkpoint:{" "}
                    <strong>
                      {job.completedBatches} / {job.targetBatches} batches
                    </strong>
                  </div>
                  <div>
                    Credits Settled:{" "}
                    <strong style={{ color: "var(--twe-gold-bright)" }}>
                      {job.consumedCredits} / {job.reservedCredits}
                    </strong>
                  </div>
                  <div>
                    AI Text Tokens: <strong className="twe-mono">{job.aiTokensUsed}</strong>
                  </div>
                </div>

                {/* 4-Stage Invention Workflow Evaluation */}
                <div
                  style={{
                    padding: 10,
                    background: "#090a0c",
                    border: "1px solid var(--twe-line)",
                    borderRadius: 6,
                    fontSize: 11,
                    display: "grid",
                    gap: 4,
                  }}
                >
                  <div>
                    <strong style={{ color: "var(--twe-gold-bright)" }}>1. Candidate Idea:</strong>{" "}
                    {job.inventionEvaluation.candidateIdea}
                  </div>
                  <div>
                    <strong style={{ color: "var(--twe-platinum)" }}>2. Critique:</strong>{" "}
                    {job.inventionEvaluation.critique}
                  </div>
                  <div>
                    <strong style={{ color: "var(--twe-emerald)" }}>
                      3. Identified Assumptions:
                    </strong>{" "}
                    {job.inventionEvaluation.assumptions.join(" | ")}
                  </div>
                  <div>
                    <strong style={{ color: "#7db2ff" }}>4. Proposed Verification Tests:</strong>{" "}
                    {job.inventionEvaluation.proposedTests.join(" | ")}
                  </div>
                </div>

                {job.status === "RUNNING_BATCH" && (
                  <div className="twe-row" style={{ justifyContent: "flex-end" }}>
                    <button
                      type="button"
                      className="twe-btn secondary"
                      onClick={() => handleAdvanceBatch(job.id)}
                    >
                      <RefreshCw size={12} /> Process Next Checkpoint Batch
                    </button>
                    <button
                      type="button"
                      className="twe-btn ghost"
                      onClick={() => handleCancelJobAndReleaseCredits(job)}
                    >
                      <PauseCircle size={12} /> Cancel &amp; Release Unused Credits
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* VIEW B: AUTHENTICATION TOKENS & SCOPED API KEYS */}
      {activeSystem === "auth_tokens" && (
        <div className="twe-grid two">
          <div className="twe-panel twe-panel-pad" style={{ display: "grid", gap: 12 }}>
            <div className="twe-panel-head">
              <div>
                <div className="twe-panel-kicker">
                  SYSTEM B · IDENTITY &amp; SCOPED API KEYS (NON-SPENDABLE)
                </div>
                <div className="twe-panel-title" style={{ marginTop: 4 }}>
                  CSPRNG Opaque API Keys (Displayed Once, Stored as SHA-256 Hash)
                </div>
              </div>
              <span className="twe-tag gold">Org: org_twe_sovereign_01</span>
            </div>

            <form onSubmit={handleCreateOpaqueApiKey} className="twe-row" style={{ gap: 8 }}>
              <input
                type="text"
                required
                className="twe-input"
                placeholder="Key label (e.g., Worker Node Signer)"
                value={newKeyName}
                onChange={(e) => setNewKeyName(e.target.value)}
              />
              <button type="submit" className="twe-btn" style={{ flexShrink: 0 }}>
                <Plus size={13} /> Generate Scoped Key
              </button>
            </form>

            {oneTimeSecretBanner && (
              <div
                className="twe-status-banner"
                style={{ justifyContent: "space-between", alignItems: "center" }}
              >
                <div>
                  <strong>Copy your secret now — it will never be shown again:</strong>
                  <p className="twe-mono" style={{ color: "var(--twe-gold-bright)" }}>
                    {oneTimeSecretBanner}
                  </p>
                </div>
                <button
                  type="button"
                  className="twe-btn secondary"
                  onClick={() => {
                    navigator.clipboard.writeText(oneTimeSecretBanner);
                    setCopiedSecret(true);
                    setTimeout(() => setCopiedSecret(false), 1500);
                  }}
                >
                  {copiedSecret ? <Check size={12} /> : <Copy size={12} />}
                  <span>{copiedSecret ? "Copied" : "Copy"}</span>
                </button>
              </div>
            )}

            <div className="twe-table-wrap">
              <table className="twe-table">
                <thead>
                  <tr>
                    <th>Key Name</th>
                    <th>Prefix</th>
                    <th>Stored Verification Hash (SHA-256)</th>
                    <th>Status</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {apiKeys.map((k) => (
                    <tr key={k.id}>
                      <td>
                        <div className="twe-asset-name">{k.name}</div>
                        <div className="twe-asset-symbol">{k.scopes.join(", ")}</div>
                      </td>
                      <td className="twe-mono">{k.keyPrefix}…</td>
                      <td className="twe-mono" style={{ fontSize: 10, color: "var(--twe-muted)" }}>
                        {k.sha256VerificationHash.slice(0, 26)}…
                      </td>
                      <td>
                        <span className={`twe-tag ${k.status === "ACTIVE" ? "gold" : ""}`}>
                          {k.status}
                        </span>
                      </td>
                      <td>
                        {k.status === "ACTIVE" && (
                          <button
                            type="button"
                            className="twe-btn ghost"
                            onClick={() => handleRevokeApiKey(k.id)}
                          >
                            <Trash2 size={12} /> Revoke
                          </button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="twe-panel twe-panel-pad">
            <div className="twe-panel-head">
              <div>
                <div className="twe-panel-kicker">SECURITY AUDIT TRAIL (audit_events)</div>
                <div className="twe-panel-title" style={{ marginTop: 4 }}>
                  Organization Isolation &amp; Key Lifecycle Log
                </div>
              </div>
              <ShieldCheck size={16} color="var(--twe-gold)" />
            </div>

            <div style={{ display: "grid", gap: 8 }}>
              {auditEvents.map((ev) => (
                <div key={ev.id} className="twe-provider-mini">
                  <div className="twe-between">
                    <strong className="twe-mono" style={{ color: "var(--twe-gold-bright)" }}>
                      {ev.action}
                    </strong>
                    <span className="twe-tag">{ev.orgId}</span>
                  </div>
                  <div style={{ fontSize: 11, color: "var(--twe-muted)", marginTop: 4 }}>
                    Actor: {ev.actor} · Target: <span className="twe-mono">{ev.targetId}</span> ·{" "}
                    {ev.timestamp}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* VIEW C: DIGITAL ASSETS & CRYPTOCURRENCY TOKENS */}
      {activeSystem === "digital_assets" && (
        <div className="twe-panel twe-panel-pad">
          <div className="twe-panel-head">
            <div>
              <div className="twe-panel-kicker">
                SYSTEM C · OFF-CHAIN DB RECORDS VS. ON-CHAIN BLOCKCHAIN FINALITY
              </div>
              <div className="twe-panel-title" style={{ marginTop: 4 }}>
                Transfer Confirmation &amp; Reorganization Reconciliation Matrix
              </div>
            </div>
            <span className="twe-tag gold">Submission != Final Ownership</span>
          </div>

          <div className="twe-table-wrap">
            <table className="twe-table">
              <thead>
                <tr>
                  <th>Transfer ID</th>
                  <th>Asset</th>
                  <th>Ledger Domain</th>
                  <th>Exact Quantity (String/BigInt)</th>
                  <th>Confirmations</th>
                  <th>Finality Status</th>
                  <th>Reconcile</th>
                </tr>
              </thead>
              <tbody>
                {assetTransfers.map((trf) => (
                  <tr key={trf.id}>
                    <td className="twe-mono">{trf.id}</td>
                    <td>
                      <div className="twe-asset-name">{trf.assetSymbol}</div>
                      <div className="twe-asset-symbol">
                        {trf.fromAccount.slice(0, 10)}… → {trf.toAccount.slice(0, 10)}…
                      </div>
                    </td>
                    <td>
                      <span className="twe-tag">{trf.ledgerDomain}</span>
                    </td>
                    <td className="twe-mono" style={{ color: "var(--twe-gold-bright)" }}>
                      {trf.quantityExactString}
                    </td>
                    <td className="twe-mono">
                      {trf.confirmations} / {trf.requiredConfirmations} blocks
                    </td>
                    <td>
                      <span
                        className={`twe-tag ${
                          trf.finalityStatus === "FINALIZED_OWNERSHIP" ? "gold" : ""
                        }`}
                      >
                        {trf.finalityStatus}
                      </span>
                    </td>
                    <td>
                      {trf.finalityStatus !== "FINALIZED_OWNERSHIP" && (
                        <button
                          type="button"
                          className="twe-btn secondary"
                          onClick={() => handleConfirmBlock(trf.id)}
                        >
                          +3 Block Confirmations
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* VIEW D: APPLICATION CREDITS (APPEND-ONLY INTEGER LEDGER) */}
      {activeSystem === "app_credits" && (
        <div className="twe-grid two">
          <div className="twe-panel twe-panel-pad">
            <div className="twe-panel-head" style={{ flexWrap: "wrap", gap: 8 }}>
              <div>
                <div className="twe-panel-kicker">
                  SYSTEM D · APPEND-ONLY INTEGER LEDGER (credit_entries)
                </div>
                <div className="twe-panel-title" style={{ marginTop: 4 }}>
                  Reconciled Balance: {creditLedgerSummary.reconciledIntegerBalance.toLocaleString()}{" "}
                  Units
                </div>
              </div>
              <div className="twe-row">
                <button
                  type="button"
                  className="twe-btn secondary"
                  onClick={() => handleGrantCredits(5000, "GRANT")}
                >
                  <Plus size={12} /> +5,000 Credit Grant
                </button>
                <button
                  type="button"
                  className="twe-btn ghost"
                  onClick={() => handleGrantCredits(1000, "REFUND_ADJUSTMENT")}
                >
                  +1,000 Refund Entry
                </button>
              </div>
            </div>

            <div className="twe-table-wrap">
              <table className="twe-table">
                <thead>
                  <tr>
                    <th>Entry ID</th>
                    <th>Type</th>
                    <th>Integer Delta</th>
                    <th>Rationale / Job Link</th>
                  </tr>
                </thead>
                <tbody>
                  {creditEntries.map((entry) => (
                    <tr key={entry.id}>
                      <td className="twe-mono">{entry.id}</td>
                      <td>
                        <span className="twe-tag">{entry.entryType}</span>
                      </td>
                      <td
                        className="twe-mono"
                        style={{
                          color:
                            entry.deltaUnits >= 0
                              ? "var(--twe-emerald)"
                              : "var(--twe-gold-bright)",
                          fontWeight: 600,
                        }}
                      >
                        {entry.deltaUnits >= 0 ? `+${entry.deltaUnits}` : entry.deltaUnits}
                      </td>
                      <td style={{ color: "var(--twe-muted)" }}>{entry.note}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="twe-panel twe-panel-pad">
            <div className="twe-panel-head">
              <div>
                <div className="twe-panel-kicker">CREDIT RESERVATIONS (credit_reservations)</div>
                <div className="twe-panel-title" style={{ marginTop: 4 }}>
                  Pre-Job Holds, Actual Settlement &amp; Unused Releases
                </div>
              </div>
              <span className="twe-tag gold">
                <CheckCircle2 size={11} /> Reconciled
              </span>
            </div>

            <div style={{ display: "grid", gap: 10 }}>
              {creditReservations.map((res) => (
                <div key={res.id} className="twe-provider-mini">
                  <div className="twe-between">
                    <strong className="twe-mono">
                      {res.id} (Job: {res.jobId})
                    </strong>
                    <span className="twe-tag gold">{res.status}</span>
                  </div>
                  <div className="twe-grid three" style={{ marginTop: 8, fontSize: 11 }}>
                    <div>
                      Reserved Hold: <strong>{res.reservedUnits}</strong>
                    </div>
                    <div>
                      Settled Usage:{" "}
                      <strong style={{ color: "var(--twe-gold-bright)" }}>
                        {res.settledUnits}
                      </strong>
                    </div>
                    <div>
                      Released Back:{" "}
                      <strong style={{ color: "var(--twe-emerald)" }}>{res.releasedUnits}</strong>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

