  const { data: accessKeys } = trpc.twe.accessKeys.list.useQuery();
  const { data: barriers } = trpc.twe.informationBarriers.list.useQuery();

  const compileMutation = trpc.twe.solidityCompiler.compile.useMutation({
    onSuccess: () => {
      void utils.twe.solidityCompiler.logs.invalidate();
    },
  });

