function Eyebrow({ children }: { children: React.ReactNode }) {
  return <div className="twe-eyebrow">{children}</div>;
}

function PageHeading({
  page,
}: {
  page: { eyebrow: string; title: string; subtitle: string };
}) {
  return (
    <div className="twe-page-heading">
      <div>
        <Eyebrow>{page.eyebrow}</Eyebrow>
        <h1 className="twe-title">{page.title}</h1>
        <p className="twe-subtitle">{page.subtitle}</p>
      </div>
    </div>
  );
}

function Metric({
  icon: Icon,
  label,
  value,
  caption,
}: {
  icon: typeof Gem;
  label: string;
  value: string;
  caption: string;
}) {
