}

export interface TWEWorkspaceProps {
  tokens?: TokenRecord[];
  onSelectToken?: (token: TokenRecord) => void;
  onTradeToken?: (token: TokenRecord, mode: "swap" | "sell") => void;
  onNavigateToClassicTab?: (tabId: string) => void;
}

export function TWEWorkspace({
  tokens = [],
  onSelectToken = () => {},
  onTradeToken = () => {},
  onNavigateToClassicTab,
}: TWEWorkspaceProps = {}) {
  const auth = useAuth();
  const [active, setActive] = useState<WorkspaceKey>("overview");
  const [mobileOpen, setMobileOpen] = useState(false);
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState<number>(5);
  const activePage = pageCopy[active];
  const groups = Array.from(new Set(navigation.map((item) => item.group)));
  const navigate = (key: WorkspaceKey) => {
    setActive(key);
    setMobileOpen(false);
  };

  const renderWorkspace = () => {
    switch (active) {
      case "overview":
        return (
          <Overview
            authenticated={auth.isAuthenticated}
            onNavigate={navigate}
            page={page}
            pageSize={pageSize}
            onPageChange={setPage}
            onPageSizeChange={(nextSize) => {
              setPageSize(nextSize);
              setPage(0);
            }}
          />
        );
      case "four_token_systems":
        return <FourTokenSystemsPlatform />;
      case "atlas":
        return (
          <AssetWorkspace
            authenticated={auth.isAuthenticated}
            title="Token Atlas"
            kinds={[
              "token",
              "commodity_reference",
              "currency_reference",
              "other",
            ]}
          />
        );
      case "foundry":
        return (
          <AssetWorkspace
            authenticated={auth.isAuthenticated}
            title="Token Foundry"
            kinds={["token"]}
            createKind="token"
          />
        );
      case "vault":
        return (
          <AssetWorkspace
            authenticated={auth.isAuthenticated}
            title="Asset Vault"
          />
        );
      case "nft":
        return (
          <div style={{ display: "grid", gap: 16 }}>
            <AssetWorkspace
              authenticated={auth.isAuthenticated}
              title="NFT Studio"
              kinds={["nft_collection", "nft_item"]}
              createKind="nft_collection"
            />
            <CmdtxNftLayerValuationCodex />
          </div>
        );
      case "cmdtx_codex":
        return (
          <div style={{ display: "grid", gap: 16 }}>
            <CmdtxNftLayerValuationCodex />
            <TweAtsCompilerBarriersRebateHub />
          </div>
        );
      case "companies":
        return <CompanyWorkspace authenticated={auth.isAuthenticated} />;
      case "sources_studio":
        return (
          <ReferenceStudio
            isDarkTheme={true}
            onOpenProjectArchive={() => navigate("project_archive")}
          />
        );
      case "project_archive":
        return (
          <div style={{ display: "grid", gap: 16 }}>
            <ProjectArchive
              isDarkTheme={true}
              onOpenSourcesStudio={() => navigate("sources_studio")}
            />
            <TweCompleteMasterArchiveDownloadHub tokens={tokens} />
          </div>
        );
      case "portfolio":
        return (
          <AssetWorkspace
            authenticated={auth.isAuthenticated}
            title="Portfolio & Watchlist"
            watchlistOnly
          />
        );
      default:
        return (
          <FeatureHub
            section={active}
            integrations={undefined}
            tokens={tokens}
            onSelectToken={onSelectToken}
            onTradeToken={onTradeToken}
            onNavigateToClassicTab={onNavigateToClassicTab}
          />
        );
    }
  };

  const triggerHeaderOneClickDownload = () => {
    const downloadBlob = (filename: string, text: string, mime: string) => {
      const blob = new Blob([text], { type: `${mime};charset=utf-8` });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    };

    downloadBlob(
      "TWE_SESSION_ARCHIVE.md",
      generateTweSessionArchiveMarkdown(),
      "text/markdown"
    );
    setTimeout(() => {
      downloadBlob(
        "TWE_IMPLEMENTATION_PLAN_EXTRACT.md",
        generateTweImplementationPlanExtractMarkdown(),
        "text/markdown"
      );
    }, 150);
    setTimeout(() => {
      downloadBlob(
        "TWE_Complete_Workspace_Bundle.json",
        JSON.stringify(
          {
            exportedAt: new Date().toISOString(),
            workspaceLinks: TWE_WORKSPACE_LINKS,
            indexedSourceFiles: TWE_INDEXED_SOURCE_FILES,
            promptLedger: TWE_USER_PROMPT_HISTORY,
          },
          null,
          2
        ),
        "application/json"
      );
    }, 300);
  };

  return (
    <div className="twe-shell">
      <div
        className={`twe-mobile-overlay ${mobileOpen ? "open" : ""}`}
        onClick={() => setMobileOpen(false)}
      />
      <aside className={`twe-sidebar ${mobileOpen ? "open" : ""}`}>
        <div>
          <div className="twe-brand">
            <span className="twe-mark">
              <img src="/twe-mark.svg" alt="" aria-hidden="true" />
            </span>
            <div>
              <div className="twe-brand-name">
                TOKEN WORLD
                <br />
                EXCHANGE
              </div>
              <div className="twe-brand-sub">TWE · ASSET WORKSPACE</div>
            </div>
          </div>
          {groups.map((group) => (
            <div key={group}>
              <div className="twe-nav-label">{group}</div>
              <nav className="twe-nav" aria-label={group}>
                {navigation
                  .filter((item) => item.group === group)
                  .map(({ key, label, icon: Icon }) => (
                    <button
                      key={key}
                      className={`twe-nav-item ${active === key ? "active" : ""}`}
                      onClick={() => navigate(key)}
                    >
                      <span className="twe-nav-icon">
                        <Icon size={15} />
                      </span>
                      <span>{label}</span>
                    </button>
                  ))}
              </nav>
            </div>
          ))}
        </div>
        <div className="twe-side-bottom">
          <div className="twe-provider-mini">
            <strong>System status</strong>
            <span>
              <i className="twe-status-dot" /> Catalog workspace ready
            </span>
            <span>
              <i className="twe-status-dot" /> Live providers disconnected
            </span>
          </div>
          <div className="twe-brand-sub" style={{ padding: "0 10px" }}>
            PROVENANCE BEFORE PERFORMANCE
          </div>
        </div>
      </aside>
      <main className="twe-main">
        <header className="twe-topbar">
          <div className="twe-row">
            <button
              className="twe-mobile-menu"
              aria-label="Open navigation"
              onClick={() => setMobileOpen(true)}
            >
              <Menu size={17} />
            </button>
            <span className="twe-crumb">
              TWE / {activePage.eyebrow.split(" · ")[0]}
            </span>
          </div>
          <div className="twe-top-actions">
            <button
              type="button"
              className="twe-btn"
              onClick={triggerHeaderOneClickDownload}
              title="Download .MD + .JSON Archive Bundle via browser-local Blob stream"
            >
              <Download size={13} /> ⚡ 1-Click Download All TWE Codes
            </button>
            <div className="twe-connection-pill">
              <i className="twe-status-dot" /> Exchange provider not connected
            </div>
            {auth.loading ? (
              <span className="twe-user-pill">Checking account…</span>
            ) : auth.isAuthenticated ? (
              <div className="twe-user-pill">
                <span className="twe-user-avatar">
                  <Gem size={13} />
                </span>
                <span>{auth.user?.name || auth.user?.email || "Account"}</span>
                <button
                  className="twe-btn ghost"
                  onClick={() => void auth.logout()}
                >
                  Sign out
                </button>
              </div>
            ) : (
              <button
                className="twe-btn secondary"
                onClick={() => startLogin()}
              >
                <LockKeyhole size={13} /> Sign in
              </button>
            )}
          </div>
        </header>
        <div className="twe-content">
          <PageHeading page={activePage} />
          {renderWorkspace()}
        </div>
      </main>
    </div>
  );
}

