  // Tab 1: 193 UN Member States State & Interactive World Map Filter State
  const [jurisdictions, setJurisdictions] = useState<UnMemberJurisdiction[]>(
    INITIAL_193_UN_JURISDICTIONS
  );
  const [tierFilter, setTierFilter] = useState<"ALL" | GlobalRegulatoryTier>("ALL");
  const [selectedContinent, setSelectedContinent] = useState<"ALL" | WorldContinentId>("ALL");
  const [selectedRegulatoryBlocks, setSelectedRegulatoryBlocks] = useState<
    Array<"Americas" | "EMEA" | "APAC" | "LATAM">
  >(["Americas", "EMEA", "APAC", "LATAM"]);
  const [selectedCountryIso, setSelectedCountryIso] = useState<string | null>(null);
  const [countrySearch, setCountrySearch] = useState<string>("");
  const [simulatedComplianceIso, setSimulatedComplianceIso] = useState<string>("US");
