interface TweOfficialFilingsPatentsWhitepapersHubProps {
  tokens?: TokenRecord[];
  tweEnvConfig?: TweEnvironmentKeyBundle;
}

/**
 * Native CRC-32 + Binary PKZIP Archive Builder for packaging all TWE Official Filings,
 * Patents, and Whitepapers into a single verifiable .zip download.
 */
function buildPkZipFromDocuments(files: { name: string; content: string }[]): Blob {
  const crcTable = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
      c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    }
    crcTable[n] = c >>> 0;
  }

  const crc32 = (bytes: Uint8Array): number => {
    let c = 0xffffffff;
    for (let i = 0; i < bytes.length; i++) {
      c = crcTable[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
    }
    return (c ^ 0xffffffff) >>> 0;
  };

  const encoder = new TextEncoder();
  const localParts: Uint8Array[] = [];
  const centralParts: Uint8Array[] = [];
  let offset = 0;

  for (const file of files) {
    const nameBytes = encoder.encode(file.name);
    const dataBytes = encoder.encode(file.content);
    const crc = crc32(dataBytes);

    // Local file header (30 bytes + filename)
    const localHeader = new Uint8Array(30 + nameBytes.length);
    const lv = new DataView(localHeader.buffer);
    lv.setUint32(0, 0x04034b50, true); // PK\x03\x04
    lv.setUint16(4, 20, true); // version needed
    lv.setUint16(6, 0, true); // flags
    lv.setUint16(8, 0, true); // compression (0 = store)
    lv.setUint16(10, 0, true); // mod time
    lv.setUint16(12, 0, true); // mod date
    lv.setUint32(14, crc, true);
    lv.setUint32(18, dataBytes.length, true);
    lv.setUint32(22, dataBytes.length, true);
    lv.setUint16(26, nameBytes.length, true);
    lv.setUint16(28, 0, true);
    localHeader.set(nameBytes, 30);

    localParts.push(localHeader, dataBytes);

    // Central directory header (46 bytes + filename)
    const centralHeader = new Uint8Array(46 + nameBytes.length);
    const cv = new DataView(centralHeader.buffer);
    cv.setUint32(0, 0x02014b50, true); // PK\x01\x02
    cv.setUint16(4, 20, true);
    cv.setUint16(6, 20, true);
    cv.setUint16(8, 0, true);
    cv.setUint16(10, 0, true);
    cv.setUint16(12, 0, true);
    cv.setUint16(14, 0, true);
    cv.setUint32(16, crc, true);
    cv.setUint32(20, dataBytes.length, true);
    cv.setUint32(24, dataBytes.length, true);
    cv.setUint16(28, nameBytes.length, true);
    cv.setUint16(30, 0, true);
    cv.setUint16(32, 0, true);
    cv.setUint16(34, 0, true);
    cv.setUint16(36, 0, true);
    cv.setUint32(38, 0, true);
    cv.setUint32(42, offset, true);
    centralHeader.set(nameBytes, 46);

    centralParts.push(centralHeader);
    offset += localHeader.length + dataBytes.length;
  }

  const centralSize = centralParts.reduce((acc, arr) => acc + arr.length, 0);
  const eocd = new Uint8Array(22);
  const ev = new DataView(eocd.buffer);
  ev.setUint32(0, 0x06054b50, true); // PK\x05\x06
  ev.setUint16(4, 0, true);
  ev.setUint16(6, 0, true);
  ev.setUint16(8, files.length, true);
  ev.setUint16(10, files.length, true);
  ev.setUint32(12, centralSize, true);
  ev.setUint32(16, offset, true);
  ev.setUint16(20, 0, true);

  return new Blob([...localParts, ...centralParts, eocd], { type: "application/zip" });
}

export const TweOfficialFilingsPatentsWhitepapersHub: React.FC<
  TweOfficialFilingsPatentsWhitepapersHubProps
> = ({ tokens = [], tweEnvConfig }) => {
  const [documents, setDocuments] = useState<TweOfficialDocumentRecord[]>(TWE_OFFICIAL_ARCHIVES);
  const [selectedCategory, setSelectedCategory] = useState<"ALL" | TweArchiveCategory>("ALL");
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [selectedDocId, setSelectedDocId] = useState<string>(TWE_OFFICIAL_ARCHIVES[0].id);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [isGeneratorOpen, setIsGeneratorOpen] = useState<boolean>(false);
  const [statusNotice, setStatusNotice] = useState<string>("");

  // Custom Document Generator State
  const [genCategory, setGenCategory] = useState<TweArchiveCategory>("SEC_FILING");
  const [genTitle, setGenTitle] = useState<string>(
    "SEC Form ATS Supplemental Amendment — Tokenized RWA & Institutional Equity Tranche"
  );
  const [genTicker, setGenTicker] = useState<string>("TWE");
  const [genOfferingOrScope, setGenOfferingOrScope] = useState<string>(
    "$100,000,000.00 USD Institutional Dual-Listed Allocation & Atomic T+0 DvP Clearing"
  );
  const [genTechnicalSummary, setGenTechnicalSummary] = useState<string>(
    "Establishes continuous 24/7 Price-Time Priority Central Limit Order Book matching with ERC-3643 on-chain identity verification, SEC Rule 15c3-5 pre-trade risk collars (±30% price band, $10M cap), and zero-variance DTCC FAST Participant #9450 master ledger synchronization under the sole principal authority of Mauro Lomibao Dar III."
  );

  const filteredDocuments = useMemo(() => {
    return documents.filter((doc) => {
      const matchesCat = selectedCategory === "ALL" || doc.category === selectedCategory;
      const q = searchQuery.trim().toLowerCase();
      if (!q) return matchesCat;
      return (
        matchesCat &&
        (doc.title.toLowerCase().includes(q) ||
          doc.docNumber.toLowerCase().includes(q) ||
          doc.filingTypeOrCode.toLowerCase().includes(q) ||
          doc.executiveSummary.toLowerCase().includes(q) ||
          doc.creatorAttribution.toLowerCase().includes(q) ||
          doc.accessionOrApplicationNo.toLowerCase().includes(q))
      );
    });
  }, [documents, selectedCategory, searchQuery]);

  const activeDocument = useMemo(() => {
    return (
      documents.find((d) => d.id === selectedDocId) ||
      filteredDocuments[0] ||
      documents[0]
    );
  }, [documents, selectedDocId, filteredDocuments]);

  const categoryCounts = useMemo(() => {
    return {
      ALL: documents.length,
      SEC_FILING: documents.filter((d) => d.category === "SEC_FILING").length,
      PATENT_SPECIFICATION: documents.filter((d) => d.category === "PATENT_SPECIFICATION").length,
      PUBLISHED_WHITEPAPER: documents.filter((d) => d.category === "PUBLISHED_WHITEPAPER").length,
      CORPORATE_GOVERNANCE: documents.filter((d) => d.category === "CORPORATE_GOVERNANCE").length,
    };
  }, [documents]);

  const handleCopyText = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2500);
  };

  const handleDownloadSingleDoc = (doc: TweOfficialDocumentRecord) => {
    downloadDocumentFile(doc.filename, doc.fullText, "text/plain;charset=utf-8");
    setStatusNotice(`Downloaded official document: ${doc.filename}`);
    setTimeout(() => setStatusNotice(""), 4000);
  };

  const handleDownloadJsonPacket = (doc: TweOfficialDocumentRecord) => {
    const packet = {
      schema: "TWE-OFFICIAL-ARCHIVE-V1",
      generatedAt: new Date().toISOString(),
      attribution: TWE_CREATOR_ATTRIBUTION,
      document: doc,
    };
    downloadDocumentFile(
      `${doc.docNumber}_${doc.id}.json`,
      JSON.stringify(packet, null, 2),
      "application/json"
    );
    setStatusNotice(`Exported EDGAR/WIPO structured JSON packet for ${doc.docNumber}`);
    setTimeout(() => setStatusNotice(""), 4000);
  };

  const handleDownloadAllZipArchive = () => {
    const files: { name: string; content: string }[] = documents.map((doc) => ({
      name: `TWE_Official_Archives/${doc.category}/${doc.filename}`,
      content: doc.fullText,
    }));

