                      className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-mono bg-cyan-500/20 hover:bg-cyan-500/30 text-cyan-200 border border-cyan-500/40 cursor-pointer"
                    >
                      <FileCheck className="w-3.5 h-3.5" />
                      JSON Packet
                    </button>
                  </div>
                </div>

                <h3 className="text-lg font-extrabold text-white">
                  {activeDocument.title}
                </h3>
                <p className="text-xs text-slate-300">{activeDocument.subtitle}</p>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 pt-2 border-t border-white/10 text-[11px] font-mono">
                  <div>
                    <span className="text-slate-400">Authority / Venue: </span>
                    <span className="text-white">{activeDocument.authorityOrVenue}</span>
                  </div>
                  <div>
                    <span className="text-slate-400">Creator / Principal: </span>
                    <span className="text-amber-300 font-bold">
                      {activeDocument.creatorAttribution}
                    </span>
                  </div>
                  <div>
                    <span className="text-slate-400">Accession / Patent No.: </span>
                    <span className="text-emerald-300">
                      {activeDocument.accessionOrApplicationNo}
                    </span>
                  </div>
                  <div>
                    <span className="text-slate-400">Classification / CUSIP: </span>
                    <span className="text-cyan-300">
                      {activeDocument.cusipOrClassification}
                    </span>
                  </div>
                </div>

                <div className="pt-1 flex items-center gap-2 text-[10px] font-mono text-slate-400">
                  <Key className="w-3.5 h-3.5 text-amber-400 shrink-0" />
                  <span className="truncate">
                    SHA-256 Cryptographic Seal: {activeDocument.sha256Seal}
                  </span>
                </div>
              </div>

              {/* Key Highlights */}
              <div className="p-4 rounded-xl bg-[#131829] border border-white/10">
                <div className="text-xs font-mono font-bold uppercase text-amber-300 mb-2">
                  Key Statutory, Patent & Technical Highlights
                </div>
                <ul className="space-y-1.5 text-xs text-slate-200">
                  {activeDocument.keyHighlights.map((item, idx) => (
                    <li key={idx} className="flex items-start gap-2">
                      <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 shrink-0 mt-0.5" />
                      <span>{item}</span>
                    </li>
                  ))}
                </ul>
              </div>

              {/* Structured Sections */}
              <div className="space-y-3">
                {activeDocument.sections.map((sec, idx) => (
                  <div
                    key={idx}
                    className="p-4 rounded-xl bg-black/40 border border-white/10 space-y-1.5"
                  >
                    <h4 className="text-xs font-mono font-bold uppercase text-cyan-300">
                      {sec.heading}
                    </h4>
                    <pre className="text-xs font-mono text-slate-200 whitespace-pre-wrap leading-relaxed">
                      {sec.body}
                    </pre>
                  </div>
                ))}
              </div>

              {/* Complete Verbatim Statutory / Patent / Whitepaper Text */}
              <div className="p-4 rounded-xl bg-black/70 border border-amber-500/30 space-y-2">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-mono font-bold uppercase text-amber-300">
                    Complete Official Verbatim Document ({activeDocument.filename})
                  </span>
                  <span className="text-[10px] font-mono text-emerald-400">
                    Digitally Signed: /s/ Mauro Lomibao Dar III
                  </span>
                </div>
                <pre className="text-[11px] font-mono text-slate-200 whitespace-pre-wrap leading-relaxed max-h-96 overflow-y-auto p-3 rounded-lg bg-[#07090f] border border-white/5">
                  {activeDocument.fullText}
                </pre>
              </div>
            </div>
          </div>
        )}
      </div>
    </section>
  );
};

