export const TWE_AUTH_STORAGE_KEY = "twe_authenticated_session_v1";
export const TWE_AUTH_EVENT = "twe-auth-state-change";

export interface TweAuthUser {
  id: number;
  name: string;
  email: string;
  metadataRef: string;
  sovereignUuid: string;
}

export const DEFAULT_TWE_USER: TweAuthUser = {
  id: 1,
  name: "Mauro Dar (Mauro Lomibao Dar III)",
  email: "maurodar08@gmail.com",
  metadataRef: "TAURUS-1987-05-06",
  sovereignUuid: "af230af8-bf63-4308-968a-9962ed14e565",
};

export function startLogin(): void {
  if (typeof window !== "undefined") {
    try {
      window.localStorage.setItem(TWE_AUTH_STORAGE_KEY, "true");
    } catch {
      // ignore storage errors
    }
    window.dispatchEvent(
      new CustomEvent(TWE_AUTH_EVENT, { detail: { isAuthenticated: true } })
    );
  }
}

export function stopLoginSession(): void {
  if (typeof window !== "undefined") {
    try {
      window.localStorage.setItem(TWE_AUTH_STORAGE_KEY, "false");
    } catch {
      // ignore storage errors
    }
    window.dispatchEvent(
      new CustomEvent(TWE_AUTH_EVENT, { detail: { isAuthenticated: false } })
    );
  }
}

