function loadStoredAssets(): TweAssetRecord[] {
  if (typeof window === "undefined") return INITIAL_TWE_ASSETS;
  try {
    const raw = window.localStorage.getItem(TWE_ASSETS_STORAGE_KEY);
    if (!raw) return INITIAL_TWE_ASSETS;
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed) && parsed.length > 0) {
      return parsed;
    }
  } catch {
    // ignore storage parse error
  }
  return INITIAL_TWE_ASSETS;
}

function saveStoredAssets(items: TweAssetRecord[]): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(TWE_ASSETS_STORAGE_KEY, JSON.stringify(items));
  } catch {
    // ignore quota error
  }
}

