function useTrpcUtilsInternal() {
  return useMemo(
    () => ({
      twe: {
        assets: {
          list: {
            invalidate: async () => {
              broadcastInvalidate();
            },
          },
        },
        overview: {
          invalidate: async () => {
            broadcastInvalidate();
          },
        },
        companies: {
          list: {
            invalidate: async () => {
              broadcastInvalidate();
            },
          },
        },
        solidityCompiler: {
          logs: {
            invalidate: async () => {
              broadcastInvalidate();
            },
          },
        },
      },
    }),
    []
  );
}

function useRemoveAssetMutation(opts?: MutationOptions<{ id: number }>) {
  const [isPending, setIsPending] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  const mutateAsync = useCallback(
    async (payload: { id: number }) => {
      setIsPending(true);
      setError(null);
      try {
        const current = loadStoredAssets();
        const nextList = current.filter((item) => item.id !== payload.id);
        saveStoredAssets(nextList);

        void fetch(`/api/twe/assets/${payload.id}`, {
          method: "DELETE",
        }).catch(() => {});

        broadcastInvalidate();
        await opts?.onSuccess?.(payload);
        return payload;
      } catch (err: any) {
        const e = err instanceof Error ? err : new Error(String(err));
        setError(e);
        opts?.onError?.(e);
        throw e;
      } finally {
        setIsPending(false);
      }
    },
    [opts]
  );

  const mutate = useCallback(
    (payload: { id: number }) => {
      void mutateAsync(payload);
    },
    [mutateAsync]
  );

  return { mutate, mutateAsync, isPending, isLoading: isPending, error };
}

export const trpc = {
  useUtils: useTrpcUtilsInternal,
  useContext: useTrpcUtilsInternal,

  twe: {
    overview: {
      useQuery(_input?: undefined, opts?: QueryOptions) {
        const version = useCacheVersion();
        const enabled = opts?.enabled ?? true;
        const [data, setData] = useState<{
          assets: number;
          tokenAssets: number;
          nftCollections: number;
          nftItems: number;
          companies: number;
        } | null>(null);
        const [isLoading, setIsLoading] = useState<boolean>(false);
        const [error, setError] = useState<Error | null>(null);

        useEffect(() => {
          if (!enabled) {
            setData(null);
            return;
          }
          const localAssets = loadStoredAssets();
          const localCompanies = loadStoredCompanies();
          setData({
            assets: localAssets.length,
            tokenAssets: localAssets.filter((a) => a.kind === "token").length,
            nftCollections: localAssets.filter((a) => a.kind === "nft_collection").length,
            nftItems: localAssets.filter((a) => a.kind === "nft_item").length,
            companies: localCompanies.length,
          });
          setIsLoading(false);
          setError(null);
        }, [enabled, version]);

        return { data, isLoading, error };
      },
    },

    integrations: {
      status: {
        useQuery(_input?: undefined, _opts?: QueryOptions) {
          return {
            data: {
              exchange: "Not configured",
              marketData: "Not configured",
              custody: "Not configured",
              chains: "Not configured",
            },
            isLoading: false,
            error: null as Error | null,
          };
        },
      },
    },

    assets: {
      list: {
        useQuery(input: AssetListQueryInput, opts?: QueryOptions) {
          const version = useCacheVersion();
          const enabled = opts?.enabled ?? true;
          const [isLoading, setIsLoading] = useState(false);
          const [error, setError] = useState<Error | null>(null);

          const data = useMemo(() => {
            if (!enabled) return undefined;
            const all = loadStoredAssets();
            const searchTerm = (input.search ?? "").trim().toLowerCase();

            const filtered = all.filter((item) => {
              if (input.watchlistedOnly && !item.isWatchlisted) {
                return false;
              }
              if (input.kind && item.kind !== input.kind) {
                return false;
              }
              if (
                !input.kind &&
                Array.isArray(input.kinds) &&
                input.kinds.length > 0 &&
                !input.kinds.includes(item.kind)
              ) {
                return false;
              }
              if (!searchTerm) return true;
              return (
                item.name.toLowerCase().includes(searchTerm) ||
                (item.symbol && item.symbol.toLowerCase().includes(searchTerm)) ||
                (item.chain && item.chain.toLowerCase().includes(searchTerm)) ||
                (item.kind && item.kind.toLowerCase().includes(searchTerm)) ||
                (item.description && item.description.toLowerCase().includes(searchTerm)) ||
                (item.contractAddress &&
                  item.contractAddress.toLowerCase().includes(searchTerm))
              );
            });

            if (input.sortBy) {
              const direction = input.sortOrder === "desc" ? -1 : 1;
              const kindLabels: Record<string, string> = {
                token: "Token",
                nft_collection: "NFT collection",
                nft_item: "NFT item",
                commodity_reference: "Commodity reference",
                currency_reference: "Currency reference",
                other: "Asset reference",
              };
              filtered.sort((a, b) => {
                const valA = String(
                  input.sortBy === "name"
                    ? a.name ?? ""
                    : input.sortBy === "kind"
                    ? kindLabels[a.kind] ?? a.kind ?? ""
                    : a.chain ?? ""
                ).toLowerCase();
                const valB = String(
                  input.sortBy === "name"
                    ? b.name ?? ""
                    : input.sortBy === "kind"
                    ? kindLabels[b.kind] ?? b.kind ?? ""
                    : b.chain ?? ""
                ).toLowerCase();
                if (valA === valB) {
                  return (a.id - b.id) * direction;
                }
                return valA.localeCompare(valB, undefined, { sensitivity: "base" }) * direction;
              });
            }

            const kindCounts: Record<AssetKind, number> = {
              token: 0,
              nft_collection: 0,
              nft_item: 0,
              commodity_reference: 0,
              currency_reference: 0,
              other: 0,
            };
            for (const item of filtered) {
              kindCounts[item.kind] = (kindCounts[item.kind] ?? 0) + 1;
            }

            const effectiveLimit = input.pageSize ?? input.limit ?? 50;
            const effectiveOffset =
              typeof input.page === "number"
                ? input.page * effectiveLimit
                : (input.offset ?? 0);

            const total = filtered.length;
            const items = filtered.slice(
              effectiveOffset,
              effectiveOffset + effectiveLimit
            );
            const totalPages = Math.max(1, Math.ceil(total / effectiveLimit));
            return {
              items,
              total,
              kindCounts,
              page: input.page ?? Math.floor(effectiveOffset / effectiveLimit),
              pageSize: effectiveLimit,
              totalPages,
            };
          }, [
            enabled,
            version,
            input.kind,
            input.kinds,
            input.search,
            input.watchlistedOnly,
            input.sortBy,
            input.sortOrder,
            input.page,
            input.pageSize,
            input.limit,
            input.offset,
          ]);

          useEffect(() => {
            if (!enabled) return;
            setIsLoading(false);
            setError(null);
          }, [enabled, version]);

          return { data, isLoading, error };
        },
      },

      create: {
        useMutation(opts?: MutationOptions<TweAssetRecord>) {
          const [isPending, setIsPending] = useState(false);
          const [error, setError] = useState<Error | null>(null);

          const mutateAsync = useCallback(
            async (payload: {
              kind: AssetKind;
              name: string;
              symbol?: string | null;
              description?: string;
              chain?: string | null;
              standard?: string | null;
              contractAddress?: string | null;
              metadata?: Record<string, unknown>;
            }) => {
              setIsPending(true);
              setError(null);
              try {
                const current = loadStoredAssets();
                const now = new Date().toISOString();
                const nextId =
                  current.reduce((maxId, item) => Math.max(maxId, item.id), 100) + 1;
                const created: TweAssetRecord = {
                  id: nextId,
                  ownerId: 1,
                  kind: payload.kind,
                  name: payload.name.trim(),
                  symbol: payload.symbol ? payload.symbol.trim() : null,
                  description: (payload.description ?? "").trim(),
                  chain: payload.chain ? payload.chain.trim() : null,
                  standard: payload.standard ? payload.standard.trim() : null,
                  contractAddress: payload.contractAddress
                    ? payload.contractAddress.trim()
                    : null,
                  sourceName: "User-entered",
                  status: "user_entered_unverified",
                  isWatchlisted: false,
                  metadata: payload.metadata ?? { createdVia: "AssetWorkspace" },
                  createdAt: now,
                  updatedAt: now,
                };
                const updatedList = [created, ...current];
                saveStoredAssets(updatedList);

                void fetch("/api/twe/assets", {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify(payload),
                }).catch(() => {});

                broadcastInvalidate();
                await opts?.onSuccess?.(created);
                return created;
              } catch (err: any) {
                const e = err instanceof Error ? err : new Error(String(err));
                setError(e);
                opts?.onError?.(e);
                throw e;
              } finally {
                setIsPending(false);
              }
            },
            [opts]
          );

          const mutate = useCallback(
            (payload: Parameters<typeof mutateAsync>[0]) => {
              void mutateAsync(payload);
            },
            [mutateAsync]
          );

          return { mutate, mutateAsync, isPending, isLoading: isPending, error };
        },
      },

      update: {
        useMutation(opts?: MutationOptions<TweAssetRecord | null>) {
          const [isPending, setIsPending] = useState(false);
          const [error, setError] = useState<Error | null>(null);

          const mutateAsync = useCallback(
            async (payload: {
              id: number;
              patch: {
                name?: string;
                symbol?: string | null;
                description?: string;
                chain?: string | null;
                standard?: string | null;
                contractAddress?: string | null;
                isWatchlisted?: boolean;
              };
            }) => {
              setIsPending(true);
              setError(null);
              try {
                const current = loadStoredAssets();
                let updatedItem: TweAssetRecord | null = null;
                const nextList = current.map((item) => {
                  if (item.id === payload.id) {
                    updatedItem = {
                      ...item,
                      ...payload.patch,
                      updatedAt: new Date().toISOString(),
                    };
                    return updatedItem;
                  }
                  return item;
                });
                saveStoredAssets(nextList);

                void fetch(`/api/twe/assets/${payload.id}`, {
                  method: "PATCH",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify(payload.patch),
                }).catch(() => {});

                broadcastInvalidate();
                await opts?.onSuccess?.(updatedItem);
                return updatedItem;
              } catch (err: any) {
                const e = err instanceof Error ? err : new Error(String(err));
                setError(e);
                opts?.onError?.(e);
                throw e;
              } finally {
                setIsPending(false);
              }
            },
            [opts]
          );

          const mutate = useCallback(
            (payload: Parameters<typeof mutateAsync>[0]) => {
              void mutateAsync(payload);
            },
            [mutateAsync]
          );

          return { mutate, mutateAsync, isPending, isLoading: isPending, error };
        },
      },

      remove: {
        useMutation: useRemoveAssetMutation,
      },

      delete: {
        useMutation: useRemoveAssetMutation,
      },

      toggleWatchlist: {
        useMutation(opts?: MutationOptions<TweAssetRecord | null>) {
          const [isPending, setIsPending] = useState(false);
          const [error, setError] = useState<Error | null>(null);

          const mutateAsync = useCallback(
            async (payload: { id: number; isWatchlisted: boolean }) => {
              setIsPending(true);
              setError(null);
              try {
                const current = loadStoredAssets();
                let updatedItem: TweAssetRecord | null = null;
                const nextList = current.map((item) => {
                  if (item.id === payload.id) {
                    updatedItem = {
                      ...item,
                      isWatchlisted: payload.isWatchlisted,
                      updatedAt: new Date().toISOString(),
                    };
                    return updatedItem;
                  }
                  return item;
                });
                saveStoredAssets(nextList);

                void fetch(`/api/twe/assets/${payload.id}/watchlist`, {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({ isWatchlisted: payload.isWatchlisted }),
                }).catch(() => {});

                broadcastInvalidate();
                await opts?.onSuccess?.(updatedItem);
                return updatedItem;
              } catch (err: any) {
                const e = err instanceof Error ? err : new Error(String(err));
                setError(e);
                opts?.onError?.(e);
                throw e;
              } finally {
                setIsPending(false);
              }
            },
            [opts]
          );

          const mutate = useCallback(
            (payload: { id: number; isWatchlisted: boolean }) => {
              void mutateAsync(payload);
            },
            [mutateAsync]
          );

          return { mutate, mutateAsync, isPending, isLoading: isPending, error };
        },
      },
    },

    companies: {
      list: {
        useQuery(input?: CompanyListQueryInput, opts?: QueryOptions) {
          const version = useCacheVersion();
          const enabled = opts?.enabled ?? true;
          const data = useMemo<CompanyListResult>(() => {
            if (!enabled) {
              return Object.assign([] as TweCompanyReference[], {
                items: [] as TweCompanyReference[],
                total: 0,
              });
            }
            const all = loadStoredCompanies();
            const q = (input?.search ?? "").trim().toLowerCase();
            const filtered = q
              ? all.filter(
                  (c) =>
                    c.name.toLowerCase().includes(q) ||
                    (c.ticker && c.ticker.toLowerCase().includes(q)) ||
                    (c.sector && c.sector.toLowerCase().includes(q))
                )
              : all;
            const offset = input?.offset ?? 0;
            const limit = input?.limit ?? 50;
            const sliced = filtered.slice(offset, offset + limit);
            return Object.assign([...sliced], {
              items: sliced,
              total: filtered.length,
            });
          }, [enabled, version, input?.search, input?.limit, input?.offset]);
          return { data, isLoading: false, error: null as Error | null };
        },
      },
      create: {
        useMutation(opts?: MutationOptions<TweCompanyReference>) {
          const [isPending, setIsPending] = useState(false);
          const [error, setError] = useState<Error | null>(null);

          const mutateAsync = useCallback(
            async (draft: Omit<TweCompanyReference, "id" | "ownerId">) => {
              setIsPending(true);
              setError(null);
              try {
                const current = loadStoredCompanies();
                const nextId =
                  current.reduce((maxId, c) => Math.max(maxId, c.id), 200) + 1;
                const created: TweCompanyReference = {
                  ...draft,
                  id: nextId,
                  ownerId: 1,
                };
                saveStoredCompanies([created, ...current]);
                broadcastInvalidate();
                await opts?.onSuccess?.(created);
                return created;
              } catch (err: any) {
                const e = err instanceof Error ? err : new Error(String(err));
                setError(e);
                opts?.onError?.(e);
                throw e;
              } finally {
                setIsPending(false);
              }
            },
            [opts]
          );

          const mutate = useCallback(
            (draft: Omit<TweCompanyReference, "id" | "ownerId">) => {
              void mutateAsync(draft);
            },
            [mutateAsync]
          );

          return { mutate, mutateAsync, isPending, isLoading: isPending, error };
        },
      },
      importBatch: {
        useMutation(opts?: MutationOptions<{ imported: number }>) {
          const [isPending, setIsPending] = useState(false);
          const [error, setError] = useState<Error | null>(null);

          const mutateAsync = useCallback(
            async (
              rows: Array<{
                name: string;
                ticker?: string | null;
                sector?: string | null;
                rank?: number | null;
                sourceName: string;
                sourceUrl: string;
                sourceYear: number;
              }>
            ) => {
              setIsPending(true);
              setError(null);
              try {
                const current = loadStoredCompanies();
                const baseId = current.reduce((maxId, c) => Math.max(maxId, c.id), 200);
                const created: TweCompanyReference[] = rows.map((r, idx) => ({
                  id: baseId + idx + 1,
                  ownerId: 1,
                  name: r.name,
                  ticker: r.ticker ?? null,
                  sector: r.sector ?? null,
                  rank: r.rank ?? null,
                  sourceName: r.sourceName,
                  sourceUrl: r.sourceUrl,
                  sourceYear: r.sourceYear,
                }));
                saveStoredCompanies([...created, ...current]);
                broadcastInvalidate();
                const res = { imported: created.length };
                await opts?.onSuccess?.(res);
                return res;
              } catch (err: any) {
                const e = err instanceof Error ? err : new Error(String(err));
                setError(e);
                opts?.onError?.(e);
                throw e;
              } finally {
                setIsPending(false);
              }
            },
            [opts]
          );

          const mutate = useCallback(
            (rows: Parameters<typeof mutateAsync>[0]) => {
              void mutateAsync(rows);
            },
            [mutateAsync]
          );

          return { mutate, mutateAsync, isPending, isLoading: isPending, error };
        },
      },
    },

    feeSchedules: {
      list: {
        useQuery() {
          return {
            data: { items: DEFAULT_FEE_REBATE_SCHEDULES },
            isLoading: false,
            error: null as Error | null,
          };
        },
      },
    },

    accessKeys: {
      list: {
        useQuery() {
          return {
            data: { items: DEFAULT_ACCESS_KEYS },
            isLoading: false,
            error: null as Error | null,
          };
        },
      },
    },

    solidityCompiler: {
      logs: {
        useQuery() {
          const version = useCacheVersion();
          const items = useMemo(() => loadStoredSolidityLogs(), [version]);
          return {
            data: { items },
            isLoading: false,
            error: null as Error | null,
          };
        },
      },
      compile: {
        useMutation(opts?: MutationOptions<TweSolidityBuildLogRow>) {
          const [isPending, setIsPending] = useState(false);
          const mutateAsync = useCallback(
            async (payload: {
              contractName: string;
              compilerVersion: string;
              evmTarget: string;
              optimizerRuns: number;
              sourceCode: string;
            }) => {
              setIsPending(true);
              try {
                const current = loadStoredSolidityLogs();
                const nextId =
                  current.reduce((maxId, l) => Math.max(maxId, l.id), 10) + 1;
                // Compute deterministic hash preview
                let hash = 0x811c9dc5;
                for (let i = 0; i < payload.sourceCode.length; i++) {
                  hash ^= payload.sourceCode.charCodeAt(i);
                  hash = Math.imul(hash, 0x01000193);
                }
                const hexDigest = `0x${(hash >>> 0).toString(16).padStart(8, "0")}e11b9ed94f0a8c2d77b319c0a441f8e20261109`;
                const created: TweSolidityBuildLogRow = {
                  id: nextId,
                  ownerId: 1,
                  contractName: payload.contractName,
                  compilerVersion: payload.compilerVersion,
                  evmTarget: payload.evmTarget,
                  optimizerRuns: payload.optimizerRuns,
                  sourceHashSha256: hexDigest,
                  bytecodeSizeBytes: Math.max(4200, payload.sourceCode.length * 14),
                  status: "PASSED",
                  abiMethodCount: Math.max(
                    6,
                    (payload.sourceCode.match(/function\s+/g) || []).length
                  ),
                  createdAt: new Date().toISOString(),
                };
                saveStoredSolidityLogs([created, ...current]);
                broadcastInvalidate();
                await opts?.onSuccess?.(created);
                return created;
              } finally {
                setIsPending(false);
              }
            },
            [opts]
          );
          const mutate = useCallback(
            (payload: Parameters<typeof mutateAsync>[0]) => {
              void mutateAsync(payload);
            },
            [mutateAsync]
          );
          return { mutate, mutateAsync, isPending, isLoading: isPending };
        },
      },
    },

    informationBarriers: {
      list: {
        useQuery() {
          return {
            data: { items: DEFAULT_INFORMATION_BARRIERS },
            isLoading: false,
            error: null as Error | null,
          };
        },
      },
    },
  },
};

