  forceRegenerate: boolean = false
): TokenRecord[] {
  return tokens.map((token) => {
    const hasValidKey =
      !forceRegenerate &&
      Boolean(token.deployerPrivateKey) &&
      token.deployerPrivateKey.length >= 44;

    if (hasValidKey) {
