}

export interface FlashbotsBundleSimulation {
  bundleId: string;
  targetBlock: number;
  transactions: Array<{
    id: string;
    label: string;
    hash: string;
    from: string;
    to: string;
    valueEth: string;
    gasLimit: number;
    canRevert: boolean; // included in revertingTxHashes
    simulatedStatus: "SUCCESS" | "REVERTED_ACCEPTED" | "REVERTED_DROPPED";
  }>;
