    if (useRealIfAvailable && eth) {
      try {
        let provider = eth;
        if (walletId === "coinbase" && win.coinbaseWalletExtension) {
          provider = win.coinbaseWalletExtension;
        } else if (walletId === "trust" && win.trustwallet) {
          provider = win.trustwallet;
